-- 0283 miradores_pdf (inventario_miradores_pdf) — borra placeholder + entidades + puntuaciones reales
DELETE FROM puntuaciones WHERE categoria='miradores';
DELETE FROM entidades WHERE fuente='inventario_miradores_pdf';
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90064','mirador','Mirador del Puerto de Acebeda','8.6/10 Impresionante panorámica forestal de la Sierra Norte, densos acebedos relictos, pinares subalpinos de Guadarrama y el inicio de la meseta segoviana. Cómo llegar: Pista forestal transitable a pie que corona el cordal montañoso divisor a 1.686 metros. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90065','mirador','Mirador del Cerro de San Roque','7.1/10 Vista limpia de la llanura cerealista de la Campiña del Henares, con campos de trigo dorados y el perfil urbano metropolitano lejano. Cómo llegar: Camino rústico elevado junto al depósito de agua en el sector norte de la villa. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90066','mirador','Mirador de la Majada del Cojo','9.2/10 Soberbia e idílica postal del Valle del Lozoya, los prados alpinos ganaderos y las imponentes cumbres calizas de la Cuerda Larga. Cómo llegar: Senda forestal de montaña que asciende desde el núcleo urbano hacia los altos pastizales. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29001','mirador','Mirador de los Cerros de Alcalá (Ecce Homo)','9.4/10 Majestuosa e histórica vista de pájaro de la ciudad Patrimonio de la Humanidad, la vega del río Henares y el llano de la Alcarria. Cómo llegar: Cima del cerro testigo del Ecce Homo, accesible por la red de senderos del Parque Natural Municipal. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90067','mirador','Mirador del Parque de la Vega','7.8/10 Perspectiva urbana ajardinada integrada sobre el arroyo de la Vega, con hileras modernas de oficinas y el skyline madrileño de fondo. Cómo llegar: Plataforma peatonal superior con balaustrada dentro del recinto lúdico del parque. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29002','mirador','Mirador de los Castillos de San José de Valderas','7.4/10 Vista urbana singular flanqueada por los palacetes neogóticos de principios del siglo XX integrados en el actual parque residencial del sur. Cómo llegar: Paseo peatonal perimetral de los Castillos, accesos acondicionados por rampas urbanas. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90068','mirador','Mirador de la confluencia del Alberche y Perales','8.4/10 Vista baja y despejada de la gran playa fluvial de interior arropada por un frondoso soto de sauces y encinares dehesados. Cómo llegar: Sendero fluvial señalizado en la margen derecha del cauce, junto al puente histórico de piedra. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90069','mirador','Mirador de la Cornisa de Algete','7.9/10 Atalaya natural sobre las terrazas aluviales de la cuenca del río Jarama, cultivos hortícolas y las pistas aeronáuticas lejanas. Cómo llegar: Paseo de la Cornisa, barandilla de hierro urbana en el extremo occidental alto del pueblo. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90070','mirador','Mirador de las Canteras de Granito (Dehesa municipal)','8.5/10 Espectacular paisaje geológico de antiguas canteras inundadas de agua limpia, rodeadas de encinas y bolos graníticos de la sierra. Cómo llegar: Sendero local balizado de las canteras viejas, pasarelas de madera con paneles informativos. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90071','mirador','Mirador del Palacio de los Leganes (Vía Verde)','8.3/10 Vista del frondoso valle del río Tajuña, huertas tradicionales escalonadas y el Monumento del Ojo que preside la loma calcárea. Cómo llegar: Ruta cicloturística de la Vía Verde del Tajuña, área de descanso elevada de la alcarria madrileña. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90072','mirador','Mirador del Cerro de la Horca','7.3/10 Suave horizonte calizo de la Alcarria de Alcalá cubierto por campos de trigo de secano y olivares tradicionales jóvenes. Cómo llegar: Hito de tierra batida en la meseta agrícola exenta del término, camino agrario elevado. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29003','mirador','Mirador de la Mariblanca / Jardín del Príncipe','9.6/10 Insuperable, majestuosa y monumental postal del Paisaje Cultural Patrimonio de la Humanidad, los sotos del Tajo y los sotos regados. Cómo llegar: Embarcadero real o paseos sobreelevados de la plaza de San Antonio, junto al palacio real. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28014','mirador','Mirador de las Lagunas de las Madres','8.1/10 Observatorio ornitológico de lagunas de gravera recuperadas en la vega del Jarama, con carrizales y aves zancudas diversas. Cómo llegar: Caseta de madera sobre pilotes integrada en el itinerario natural adaptado del complejo. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28015','mirador','Mirador del Torreón de Arroyomolinos','7.8/10 Vista del parque fluvial del arroyo de los Combates integrada con la imponente silueta fortificada de la torre de ladrillo del siglo XV. Cómo llegar: Parque público del Torreón, paseos peatonales de tierra compactada en el casco urbano. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28016','mirador','Mirador del Embalse del Atazar','9.5/10 Abrumadora y vertical visual de la mayor presa de la región encajada de forma geométrica entre colosales riscos de pizarra y jarales salvajes. Cómo llegar: Carretera de montaña M-133, pasarela metálica volada sobre el escarpe calizo de la presa. Proponme qué hacer.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28017','mirador','Mirador del Castillo de Batres','8.4/10 Magnífica perspectiva de la fortaleza mudéjar de ladrillo donde escribió Garcilaso de la Vega, rodeada de cárcavas de arcilla y olivares rústicos. Cómo llegar: Entorno forestal del sendero del arroyo Sotillo, ladera sur exenta al monumento. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28018','mirador','Mirador del Alto de la Maliciosa','90/10 Impresionante primer plano del colosal bloque granítico de La Maliciosa y los valles serranos de pinos y jarales. Cómo llegar: Final de la pista del monte de utilidad pública, junto al depósito regulador alto. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28019','mirador','Mirador de las Eras altas','7.6/10 Suave oleaje de tierras calizas de la comarca de Las Vegas cubierto de viñedos moscatel, olivos tradicionales y campos de trigo. Cómo llegar: Camino rural del Calvario, pequeña plataforma pedregosa exenta del núcleo. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28020','mirador','Mirador de la Serranía','8.9/10 Atalaya privilegiada con vistas cenitales del embalse de El Atazar, riscos de pizarra y las dehesas del norte de Madrid. Cómo llegar: Calle del Mirador, plataforma con valla rústica de madera en el sector alto de la villa. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28022','mirador','Mirador del Palacio del Infante Don Luis','8.0/10 Vista señorial de los jardines neoclásicos aterrazados, huertas tradicionales y el espeso monte público de encinas y pinos piñoneros. Cómo llegar: Terraza superior del palacio, balconada de piedra sillar sobre el arroyo de la Vega. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28023','mirador','Mirador de la Pedriza (Cerro de El Reventón)','9.3/10 Espectacular e imponente mural granítico de la Pedriza anterior, los riscos caprichosos erosionados y el valle del Manzanares alto. Cómo llegar: Senda local balizada que sube hacia la peña del Yelmo desde Mataelpino. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90073','mirador','Mirador del Puerto de Arcones','8.8/10 Vista alpina de la Sierra de Somosierra con pastizales altos tradicionales e infinitos robledales que cubren la solana. Cómo llegar: Pista de montaña transitable a pie que corona el cordal fronterizo con Segovia. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28025','mirador','Mirador del Valle de la dehesa','7.2/10 Paisaje llano agrícola alcarreño del extremo oriental, roto por pequeños barrancos arcillosos y plantaciones de olivar joven. Cómo llegar: Pista de servicio agraria junto a los antiguos depósitos de agua locales. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28026','mirador','Mirador de la Batalla de Brunete','7.4/10 Valor histórico sobre los campos agrarios ondulados donde chocaron los frentes en 1937, dominando el río Perales baja. Cómo llegar: Parque de la Memoria exterior, hito de piedra rústica y paneles interpretativos tácticos. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28027','mirador','Mirador del Rincón / Murallas de Buitrago','9.6/10 Insuperable, mística y bella postal de la villa amurallada medieval intacta cercada por el meandro encajonado del Lozoya. Cómo llegar: Risco de la margen izquierda del río, sendero local empedrado accesible desde la carretera nacional. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28028','mirador','Mirador de la Torre de la Mina','8.9/10 Vista del valle interior de la Sierra de la Cabrera arropado por un espeso robledal centenario y canteras de granito viejas. Cómo llegar: Paraje arqueológico de la antigua mina de arsénico, sendero local balizado desde el pueblo. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28029','mirador','Mirador de la Dehesa del Toro','8.1/10 Perspectiva rústica de dehesas ganaderas de toros de lidia con encinas, muros de piedra y los contrafuertes serranos detrás. Cómo llegar: Camino de herradura periférico acondicionado con valla de madera al norte del núcleo. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28031','mirador','Mirador de la Peña Muñana','90/10 Imponente mole de granito exenta que vigila de forma majestuosa el valle del Alberche, olivares viejos y viñedos de solana. Cómo llegar: Cresta rocosa de la Peña Muñana, sendero de montaña exigente con cuerdas de apoyo. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28032','mirador','Mirador del Camino de las Esteruelas','7.1/10 Paisaje plano puramente agrícola de la campiña del Henares con cultivos de secano e infraestructuras del corredor. Cómo llegar: Camino de circunvalación agrícola de tierra batida en el flanco este de la población. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28033','mirador','Mirador de la Iglesia de Santa María del Castillo','7.8/10 Vista aérea del entramado urbano blanco de los quesos y olivas, rodeado de olivares compactos de la meseta alcarreña. Cómo llegar: Plaza alta porticada de la iglesia fortificada barroca mudéjar, punto culminante local. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28034','mirador','Mirador del Puerto de Canencia / Chorrera de Mojonavalle','9.2/10 Espectacular paraje de agua limpia con una cascada encajada entre abedules, tejos milenarios y un denso pinar alpino silvestre. Cómo llegar: Senda ecológica botánica del Puerto de Canencia, pasarelas de madera con balcones de protección. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28035','mirador','Mirador del cerro de Aguas de Carabaña','8.3/10 Vista del tajo calizo que esconde los históricos manantiales de aguas medicinales salinas sobre el vergel del río Tajuña. Cómo llegar: Explanada de la antigua embotelladora del siglo XIX en la loma del cerro de Cabeza Gorda. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28036','mirador','Mirador de las Arenas del Guatén','6.8/10 Horizonte plano agrícola de la campiña baja del sur que linda con la provincia de Toledo entre alfombras de trigo. Cómo llegar: Pista agrícola de servicio contigua a las balsas de regulación del arroyo Guatén. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28037','mirador','Mirador de la Piedra Escrita / Peña de Cenicientos','8.9/10 Monumento natural e histórico con un monolito megalítico romano tallado en granito rodeado de pinos piñoneros y viñedos viejos de solana. Cómo llegar: Paraje arqueológico de la Piedra Escrita, sendero local balizado del extremo suroeste de Madrid. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28038','mirador','Mirador de los de la Fuenfría (Vicente Aleixandre)','9.6/10 Majestuoso e incomparable balcón forestal alpino rodeado por el denso pinar silvestre de Guadarrama y calzadas romanas empedradas. Cómo llegar: Carretera forestal de las Dehesas de Cercedilla, plataformas circulares de piedra valladas sobre el abismo. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28039','mirador','Mirador del Náutico de El Atazar','8.7/10 Inmensa postal náutica sobre el gran mar de agua dulce madrileño, con embarcaderos de vela y riscos de pizarra grises. Cómo llegar: Paseo de la Marina, rampa de madera ecológica del centro náutico de la localidad. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28040','mirador','Mirador de las Salinas de Espartinas','8.4/10 Impresionante paisaje desértico de acantilados yesíferos blanquecinos cortados a pico sobre la fértil vega baja del río Jarama. Cómo llegar: Senda de los sotos históricos, barandilla de hierro urbana en el extremo de los barrancos arcillosos. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28041','mirador','Mirador del Barranco del agua','7.3/10 Perspectiva de las colinas de olivar y secano del noreste madrileño rotas por pequeños arroyos de ribera estacionales. Cómo llegar: Pista agrícola de tierra compactada en el flanco norte de la dehesa del pueblo. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28046','mirador','Monumento al Ancla / Cerro del Castillo','Vista panorámica completa de los Siete Picos, el Puerto de Navacerrada y la llanura central. Nota: 8.3/10. Cómo llegar: Parque Municipal del Cerro del Castillo, sendero ascendente escalonado.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28047','mirador','Mirador de la Dehesa de Villalba','Perspectiva de la gran hoya granítica del Guadarrama y el cordal de Cuerda Larga. Nota: 7.6/10. Cómo llegar: Parque de la Dehesa, extremo occidental del municipio, junto al acceso a la M-601.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28043','mirador','Mirador de los Jardines del Zacatín','8.8/10 Vista aérea del espectacular túnel de piedra sillar caliza barroco mudéjar integrado con las huertas tradicionales de la vega. Cómo llegar: Balconada urbana de la plaza mayor, barandilla de piedra sobre el barranco del Zacatín. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28042','mirador','Mirador de los Puentes de piedra','7.9/10 Paisaje rústico de encinas y dehesas ganaderas cruzadas por los puentes de mampostería medievales sobre el arroyo de la fragua. Cómo llegar: Senda peatonal de la ribera, accesos acondicionados de tierra compactada de la localidad. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28045','mirador','Mirador del Puente del Grajal (Río Manzanares)','8.7/10 Espectacular e histórico encajonamiento calizo del río Manzanares medio con el puente medieval de arco único gigante de granito. Cómo llegar: Parque Natural de la Cuenca Alta del Manzanares, sendero local balizado de la central vieja. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28044','mirador','Mirador del Embalse de Valmayor (Loma alta)','8.2/10 Vista directa de las aguas turquesas del embalse rodeadas de encinares compactos dehesados bajo el perfil gélido de la sierra. Cómo llegar: Camino rural sobreelevado de la dehesa municipal, acceso desde el campus universitario. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28048','mirador','Mirador de la Fuente del Rey','7.5/10 Entorno rústico alcarreño de olivos tradicionales y campos de trigo que cobija los históricos manantiales de aguas cristalinas. Cómo llegar: Pequeño ribazo acondicionado junto al palacio barroco de las afueras residenciales. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28049','mirador','Mirador del Parque del Humedal','7.0/10 Panorámica urbana y periurbe del cinturón logístico e industrial del Henares con choperas jóvenes integradas en el secano. Cómo llegar: Pasarelas superiores del parque público del Humedal, barandillas protectoras de madera. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28050','mirador','Mirador de la Ermita de la Virgen de la Luna','Vista relajante sobre los campos ondulados de trigo de la comarca transfronteriza de la Sagra. Nota: 6.3/10. Cómo llegar: Camino rústico arbolado que conduce al santuario desde el casco viejo. Iré entregando el resto de municipios madrileños y las provincias de Álava y Guipúzcoa en los siguientes bloques correlativos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28053','mirador','Mirador del río Torote','7.3/10 Vista baja de la vega del arroyo Torote con plantaciones agrícolas cerealistas tradicionales de secano de la campiña alta. Cómo llegar: Camino agrícola de servicio contiguo a las balsas de regulación de agua locales. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28054','mirador','Mirador de la Calzada Real / Monasterio','9.2/10 Solemne perspectiva de las dehesas herrerianas de fresnos y encinas centenarias que enmarcan la cúpula de la gran basílica. Cómo llegar: Sendero histórico de la Cañada Real Segoviana, tramo que bordea la finca rústica de La Granjilla. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28055','mirador','Mirador del río Tajo (Los Arenales)','8.0/10 Vista del cauce ancho del río Tajo al entrar en la provincia, sus huertas tradicionales y los puentes del canal. Cómo llegar: Paseo fluvial de la playa de los Arenales, sendero de pequeño recorrido acondicionado. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28056','mirador','Mirador de las Estaciones de la NASA','8.4/10 Extraordinario valor geográfico e histórico sobre el mar de encinas rústicas presidido por las colosales antenas de telecomunicación espacial. Cómo llegar: Hito de la colina de la antena de seguimiento lunar de 1969, camino forestal batido. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28057','mirador','Mirador del Caserío de Serracines','7.6/10 Paisaje despoblado agrícola de la campiña central con el pintoresco núcleo fortificado medieval de piedra abandonado y encinas. Cómo llegar: Corona del cerro testigo contiguo al palacio del marqués de Perales, camino rústico. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28058','mirador','Mirador del Parque Polvoranca','7.0/10 Vista llana del cinturón periurbano del sur con lagunas artificiales de dunas, ánades y las ruinas barrocas de la iglesia vieja. Cómo llegar: Pasarela de madera del itinerario ornitológico del espacio verde metropolitano. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28059','mirador','Mirador de las vegas de Jarama','7.2/10 Perspectiva horizontal de cultivos de huertas de regadío intensivo asociadas al cauce de inundación del río Jarama. Cómo llegar: Mota lateral del río junto al puente de la carretera local de herradura agraria. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28060','mirador','Mirador de la Torre de Doña Urraca / Castillo','8.7/10 Impresionante e histórica atalaya sobre el río Tajo encajado bajo el recinto amurallado de tapial rojo de la fortaleza medieval. Cómo llegar: Lienzo norte de la muralla del castillo de Santiago que corona el peñón de la villa alta. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28061','mirador','Mirador del Puente de Alcanzorla (Guadarrama)','8.9/10 Espectacular paraje de montaña granítico con el puente musulmán del siglo IX cruzando las aguas bravas del río Guadarrama. Cómo llegar: Sendero histórico de la calzada romana, tramo del cañón fluvial accesible desde Las Colinas. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28066','mirador','Mirador del Carralero','7.1/10 Suave horizonte agrícola de cultivos hortícolas tradicionales que marcan la campiña del sur madrileño bajo. Cómo llegar: Camino rural sobreelevado junto a los invernaderos y viveros del término municipal. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28067','mirador','Mirador del Embalse de Pedrezuela / Bienvenido Mr. Marshall','8.8/10 Vista directa de las aguas del río Guadalix, los campos rústicos de rodaje del cine histórico y dehesas ganaderas de encinas. Cómo llegar: Carretera escénica local M-608, ensanche habilitado con muros de piedra rústica y valla. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28068','mirador','Mirador de Cabeza Líjar / los Robles','9.3/10 Impresionante búnker de la Guerra Civil reconvertido en atalaya a 1.824 metros con vistas de Ávila, Segovia y todo Madrid. Cómo llegar: Cima del pico Cabeza Líjar, sendero de alta montaña GR-10 desde el puerto de Guadarrama. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28073','mirador','Mirador del Prado de la Casa','6.9/10 Paisaje agrícola plano de la campiña del sur con naves industriales modernas fijadas sobre el mosaico de cultivos cerealistas. Cómo llegar: Prolongación de la calle de la dehesa, pequeña plataforma de tierra batida perimetral. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28074','mirador','Mirador de la Colina de la Ermita (Butarque)','7.1/10 Vista baja periférica sobre el cauce del arroyo Butarque flanqueado por parques periurbanos y la urbe metropolitana. Cómo llegar: Zona ajardinada alta de la Ermita de Nuestra Señora de la Soledad de Butarque, paseos de tierra. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28075','mirador','Mirador del Monasterio de la Inmaculada Concepción','7.6/10 Vista del palacio panteón de los duques de Alba gótico barroco integrado en las suaves lomas arcilleras de la campiña este. Cómo llegar: Plaza alta monumental frente al convento barroco mudéjar del municipio. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28076','mirador','Mirador de la Hoya de Enmedio (Valle del Lozoya)','9.4/10 Impresionante e incomparable vista del embalse de Pinilla encajado entre los espesos sabinares altos y las cumbres del Peñalara. Cómo llegar: Pista forestal transitable que asciende hacia el puerto de Navafría, área recreativa de montaña. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28901','mirador','Necrópolis de Sieteiglesias / Alto de la Iglesia','Grandes berruecos y lanchas graníticas combinadas con restos arqueológicos medievales. Nota: 8.4/10. Cómo llegar: Entorno inmediato de la Iglesia de San Pedro en el núcleo de Sieteiglesias. Iré entregando el resto de municipios madrileños y las provincias de Álava y Guipúzcoa en los siguientes bloques correlativos. Indícame SIGUE para desplegar el siguiente bloque masivo de fichas técnicas oficiales del Atlas.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28078','mirador','Mirador del Municipio Menor madrileño','8.2/10 Perspectiva rural e íntima del pueblo más pequeño de la región, rodeado de cercas tradicionales de piedra, encinas y fresnos. Cómo llegar: Camino agrícola elevado que circunvala el pequeño casco urbano de piedra blanca. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28079','mirador','Mirador del Templo de Debod / Mirador de la Cornisa (Palacio Real)','9.7/10 Insuperable, mística y bella balconada sobre la Casa de Campo, el Palacio Real y la mítica puesta de sol de la capital. Cómo llegar: Paseo del pintor Rosales o pasarela de la cornisa de la Almudena en pleno centro histórico urbano. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28080','mirador','Mirador del Monte del Pilar','7.8/10 Vista forestal de dehesas de encinas y pinos piñoneros piñoneros del gran pulmón metropolitano con el perfil oeste de la urbe. Cómo llegar: Torre de vigilancia forestal y caminos peatonales acondicionados del Parque del Monte del Pilar. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28082','mirador','Mirador del Castillo de Mendoza / El Yelmo','9.8/10 Insuperable e icónica estampa de la fortaleza palaciega del siglo XV encajada bajo los colosales domos graníticos de La Pedriza y el embalse de Santillana. Cómo llegar: Torre del homenaje del complejo fortificado o mirador de Quebrantaherraduras en pleno Parque Nacional. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28083','mirador','Mirador del llano de Meco','72/10 Horizonte agrícola plano característico de la campiña del Henares norte con cultivos de cereal de secano y naves modernas. Cómo llegar: Camino rural de la duna, pequeña plataforma peatonal con barandilla de madera periférica. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28085','mirador','Mirador del Puerto de la Morcuera','9.3/10 Paso de alta montaña de gran amplitud visual a 1.796 metros sobre el Valle de San Blas, los hayedos y el Pirineo de Guadarrama. Cómo llegar: Coronación del puerto de montaña de la carretera M-611, límite con Rascafría. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28086','mirador','Mirador de los Cerros de las Bodegas','8.1/10 Vista aérea del singular laberinto de chimeneas de las bodegas tradicionales trogloditas subterráneas excavadas en la loma. Cómo llegar: Cerro de la Atalaya de las bodegas de vino de El Molar, accesos empedrados rústicos. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28087','mirador','Mirador de la Peñota','8.8/10 Vista de los pinares de alta montaña bajo la cresta granítica de los Siete Picos con praderas ganaderas tradicionales. Cómo llegar: Sendero local balizado del camino del agua que asciende hacia las cumbres de Guadarrama. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28088','mirador','Mirador del Hayedo de Montejo','9.6/10 Espectacular e idílica postal forestal de hayas centenarias y robles que cambian de color junto a las aguas del río Jarama. Cómo llegar: Senda del Río, pasarelas de madera integradas en el espacio protegido de la Reserva de la Biosfera. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28089','mirador','Mirador de las Lomas del Sur','7.1/10 Perspectiva horizontal agrícola de olivares jóvenes e infraestructuras de transporte integradas en la llanura madrileña. Cómo llegar: Camino rural de servicio contiguo al depósito regulador de agua municipal. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28090','mirador','Mirador del Telégrafo / Cabeza Mediana','Atalaya central de la comarca con vistas de 360 grados a la Cuerda Larga, la Pedriza y el embalse de Santillana. Nota: 8.2/10. Cómo llegar: Cima de Cabeza Mediana, accesible por pista forestal balizada desde el polideportivo municipal.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28091','mirador','Mirador de la Colina del Telégrafo','7.9/10 Gran valor histórico con trincheras recuperadas de la Batalla del Jarama y amplias panorámicas sobre la vega del Tajuña. Cómo llegar: Espacio de memoria histórica acondicionado con paneles en la cumbre del cerro. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28092','mirador','Mirador del Parque El Soto','7.6/10 Vista de un frondoso parque periurbano con un estanque central rodeado de sauces y praderas de césped. Cómo llegar: Plataforma peatonal del puente de madera que cruza el lago del complejo de ocio. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28093','mirador','Mirador de la Virgen de las Nieves (Puerto de Navacerrada)','9.7/10 Insuperable y majestuosa panorámica alpina a 1.858 metros sobre la Bola del Mundo, Siete Picos y el pinar de la Barranca. Cómo llegar: Alto del puerto de la carretera M-601, explanada del monumento junto a las pistas de esquí. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28094','mirador','Mirador del Berrocal de Navalafuente','8.1/10 Singular paisaje geológico compuesto por grandes bolos graníticos dispersos, encinas y prados ganaderos tradicionales. Cómo llegar: Senda del agua, camino rural de herradura que circunvala el casco urbano por el norte. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28095','mirador','Mirador del Hondillo / Fortines de la Guerra Civil','8.5/10 Impresionante encajonamiento fluvial del río Perales flanqueado por dehesas de encinas y búnkeres de piedra históricos. Cómo llegar: Ruta de los Fortines, mirador acondicionado con valla de madera sobre el escarpe natural. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28096','mirador','Mirador de la Plaza de Segovia','8.3/10 Fotogénico e histórico balcón urbano sobre la plaza porticada castellana del siglo XVI de fachadas encaladas. Cómo llegar: Balconadas del edificio del Ayuntamiento viejo, en pleno centro de la Villa Real. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28097','mirador','Mirador de la Chorrera de San Mamés','8.9/10 Espectacular salto de agua limpia de 30 metros de altura deslizándose por una pared de roca granítica gris entre pinos. Cómo llegar: Sendero de montaña señalizado que arranca desde la quesería tradicional de San Mamés. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28099','mirador','Mirador del Embalse de Picadas','8.4/10 Vista directa de las aguas quietas del río Alberche encajonadas entre murallones de roca caliza y pinos piñoneros. Cómo llegar: Vía Verde de Picadas, antiguo trazado ferroviario acondicionado con barandillas de madera. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28100','mirador','Mirador del Palacio de Goyeneche','8.6/10 Solemne perspectiva del complejo industrial barroco del siglo XVIII diseñado por Churriguera entre campos cerealistas. Cómo llegar: Plaza de las Fiestas, balaustrada urbana de piedra frente al palacio fortificado. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28101','mirador','Mirador de los Pintores / Alcarria','8.2/10 Hermosa postal de un pueblo blanco de artistas escalonado en la ladera de un valle calizo repleto de olivos. Cómo llegar: Calle Mayor alta, pequeña plataforma peatonal con un marco monumental fotográfico. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28102','mirador','Mirador de la Ermita de la Bella','7.8/10 Vista de la vega baja del río Tajuña, huertas de regadío tradicionales e hileras de chopos que cortan el llano. Cómo llegar: Explanada perimetral del santuario, accesible por camino rural pavimentado desde el norte. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28104','mirador','Mirador de la Cornisa / Paracuellos','9.1/10 Espectacular e inmensa visual de pájaro de todo el skyline de Madrid, el aeropuerto de Barajas y el río Jarama. Cómo llegar: Paseo del Radar, barandilla de hierro urbana en el borde del gran acantilado arcilloso. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28106','mirador','Mirador del Parque del Lago','6.9/10 Paisaje llano periurbano integrado en un lago artificial de ocio rodeado por zonas de descanso de césped. Cómo llegar: Camino peatonal periférico del complejo de la playa urbana del municipio. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28107','mirador','Mirador de Patones de Arriba','9.6/10 Mística e icónica estampa de la villa de pizarra negra intacta escondida en un recóndito barranco geológico calizo. Cómo llegar: Sendero del Barranco, plataforma acondicionada con paneles en el acceso peatonal al núcleo viejo. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28108','mirador','Mirador del Embalse de Pedrezuela (Atalaya)','8.8/10 Vista de la lámina de agua encajada entre cortados de piedra caliza vigilados por una atalaya militar medieval. Cómo llegar: Torreón de guaita musulmán exento en la cresta de la colina que corona el embalse. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28109','mirador','Mirador del Embalse de San Juan (Muro)','9.0/10 Impresionante visual de la mayor playa de interior regional, rodeada de espesos pinares piñoneros y lanchares graníticos. Cómo llegar: Corona de la presa de San Juan, accesos habilitados desde la carretera nacional M-501. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28110','mirador','Mirador de los Riscos de Perales','8.4/10 Espectacular e histórico complejo de cuevas prehistóricas excavadas en una colosal pared de roca caliza blanca. Cómo llegar: Senda del neolítico, pasarela de madera con barandilla frente al farallón rocoso. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28111','mirador','Mirador de las Torres de la Alcarria','7.4/10 Paisaje plano cerealista de secano roto únicamente por pequeños barrancos arcillosos y encinares dispersos. Cómo llegar: Camino rural sobreelevado junto a los antiguos depósitos de agua municipales. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28112','mirador','Mirador de los Yacimientos de la Reserva del Calvero','93/10 Enorme valor histórico y natural sobre el Valle del Lozoya, el embalse y las cuevas con restos de neandertales. Cómo llegar: Pasarelas del parque arqueológico del Calvero de la Higuera, visitas guiadas. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28113','mirador','Mirador del Torreón de Pinto (Centro Geográfico)','7.8/10 Atalaya defensiva del siglo XIV de piedra sillar vinculada a la leyenda del centro geográfico exacto de la Península. Cómo llegar: Parque de Juan Carlos I, entorno de la torre fortificada del castillo medieval. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28115','mirador','Mirador del Parque Forestal Adolfo Suárez','7.7/10 Vista de la campiña baja repoblada de pinos y encinas con el skyline financiero de Madrid al fondo. Cómo llegar: Senda perimetral alta del parque forestal, mirador de madera con paneles. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28116','mirador','Mirador del Llano Cerealista','7.1/10 Suave horizonte de la llanura de la Alcarria madrileña cubierto por cultivos extensivos de secano tradicionales. Cómo llegar: Camino vecinal de tierra compactada en paralelo al trazado de las vías agrarias. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28117','mirador','Mirador de la Laguna de Prádena','8.8/10 Entorno idílico de prados altos ganaderos cercados por muros de piedra y los robledales de la Sierra del Rincón. Cómo llegar: Itinerario de la Laguna, pasarela de madera ecológica en la dehesa boyal. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28118','mirador','Mirador de los Cristales / Puerto de la Puebla','Uno de los paisajes más salvajes y aislados de Madrid, con laderas abruptas cubiertas de robles y jaras. Nota: 9.4/10. Cómo llegar: Cima del puerto de la Puebla (M-130), infraestructura de madera integrada en la roca. Indícame SIGUE para desplegar el siguiente bloque masivo de fichas técnicas oficiales del Atlas.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28119','mirador','Mirador de los Hornos de Cal / Fortines','7.9/10 Paisaje ondulado forestal que esconde estructuras militares de la Guerra Civil y antiguos hornos tradicionales de piedra. Cómo llegar: Sendero local balizado de la retaguardia republicana, colinas al norte de la villa. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28120','mirador','Mirador de los Robledos','Excepcional panorámica en 360 grados del Monasterio de El Paular, el macizo de Peñalara y el Valle Alto del Lozoya. Nota: 9.8/10. Cómo llegar: Acceso desde la carretera M-604, subiendo por la pista forestal asfaltada frente al monumento flotante de El Paular.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28121','mirador','Mirador de las Caleras de Redueña','8.2/10 Vista kárstica de una antigua dehesa caliza con frentes de extracción de mampostería romana y matorral mediterráneo. Cómo llegar: Sendero botánico y geológico adaptado, pasarela de madera con paneles. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28122','mirador','Mirador de la Campiña Alta','7.3/10 Lomas agrícolas onduladas de cultivo de trigo y girasol que marcan la frontera norte con Guadalajara. Cómo llegar: Pista agrícola transitable que corona la cuerda testigo exenta del término. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28123','mirador','Cortados de Casa Eulogio / El Piul','Espectaculares e imponentes acantilados de yeso blanco sobre las lagunas y la confluencia de los ríos Jarama y Manzanares. Nota: 8.5/10. Cómo llegar: Parque Regional del Sureste, sendero de los Cortados de la margen derecha del Jarama.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28124','mirador','Mirador del Valle del Lozoya','8.6/10 Vista de laderas de jara y dehesas de encina que descienden hacia las colas de agua del embalse de El Atazar. Cómo llegar: Explanada exterior de la Ermita del Villar, pista forestal de tierra compactada. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28125','mirador','Mirador de la Estación de la NASA','91/10 Impactante y futurista postal con colosales antenas parabólicas espaciales integradas en dehesas de pinos piñoneros y encinas. Cómo llegar: Complejo de Comunicaciones del Espacio Profundo de la NASA, mirador de la carretera M-531. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28126','mirador','Mirador del Puerto de Somosierra','8.4/10 Histórico paso de montaña de la autovía del Norte con vistas de la dehesa de acebos y los hayedos de la Sierra Rica. Cómo llegar: Antigua carretera nacional N-I, apartadero junto a la cascada de la Chorrera de los Litueros. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28127','mirador','Mirador del Embalse de Gabriel y Galán (Navalcarbón)','7.9/10 Paisaje periurbano de encinar protegido integrado con los restos de los fortines militares del canal de Guadarrama. Cómo llegar: Dehesa de Navalcarbón, sendero peatonal acondicionado del pinar. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28128','mirador','Mirador del Castañar de las Rozas','Espectacular alfombra cromática otoñal proporcionada por el mayor bosque de castaños de la Comunidad de Madrid. Nota: 8.5/10. Cómo llegar: Ruta de los Castaños, saliendo del núcleo por el sendero hacia el embalse de Los Morales.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28129','mirador','Mirador del Acueducto de la Retuerta','8.5/10 Espectacular obra de ingeniería hidráulica del Canal de Isabel II integrada en dehesas de encinas y sotos del Guadalix. Cómo llegar: Senda del agua, pasarela de madera con barandillas frente al acueducto histórico de piedra. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28130','mirador','Mirador de los Sotos de la Junta','7.4/10 Vista de la confluencia de los ríos Henares y Jarama flanqueada por un denso carrizal y bosques de ribera. Cómo llegar: Parque Regional del Sureste, sendero fluvial transitable desde el Polideportivo Justo Gómez. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28131','mirador','Mirador de la Silla de Felipe II / Abantos','9.9/10 Insuperable, mística y colosal vista del Real Monasterio de El Escorial arropado por los pinares e hileras de la sierra. Cómo llegar: Plataforma esculpida en los canchales de granito del bosque de la Herrería o cima del monte Abantos. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28132','mirador','Mirador de los Yesares de la Vega','7.8/10 Vista de las ricas huertas de regadío del Jarama combinada con los escarpados y áridos cortados de yeso del parque. Cómo llegar: Carretera M-506, apartadero rústico señalizado sobre los acantilados fluviales. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28133','mirador','Mirador del Castillo de la Coracera / San Juan','92/10 Torre señorial de piedra sillar del siglo XV dominando el mar de viñedos de garnacha y las colas del embalse de San Juan. Cómo llegar: Almenas consolidadas de la fortaleza medieval alta o mirador de la urbanización Motonáutica. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28134','mirador','Mirador de la Dehesa Boyal','7.5/10 Vista de una dehesa de encinas protegida periurbana que sirve de transición hacia el parque de la cuenca alta. Cómo llegar: Sendero perimetral alto del parque de la Dehesa Boyal, barandilla de madera. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28135','mirador','Mirador del Puerto de la Paradilla','9.2/10 Impresionante paso montañoso calizo sobre el encajonamiento del río Cofio, dehesas y las cumbres de Guadarrama occidentales. Cómo llegar: Carretera de montaña M-505, apartadero acondicionado con murete de piedra rústica. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28136','mirador','Mirador de las Murallas del Castillo de Torremocha','81/10 Atalaya defensiva medieval que domina el laberinto de la Alcarria de Alcalá, olivares tradicionales y campos de trigo. Cómo llegar: Lienzo exterior transitable de la fortaleza del siglo XIV que albergó a la Princesa de Éboli. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28137','mirador','Mirador de la Humosa','8.9/10 Espectacular caída visual desde el borde de la meseta alcarreña a 900 metros hacia el corredor del Henares y Guadalajara. Cómo llegar: Paseo de la Ermita alta, mirador urbano acondicionado con balaustrada sobre el escarpe. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28138','mirador','Mirador del Campillo','8.0/10 Vista de dehesas ganaderas de la Sierra Norte y prados tradicionales de piedra asociados al paso de la autovía de Burgos. Cómo llegar: Camino de servicio rural contiguo a los antiguos abrigos ganaderos de la dehesa. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28140','mirador','Mirador del Llano Cerealista','7.0/10 Paisaje plano agrícola tradicional de la campiña sur con parcelas de secano y dehesas bajas dispersas. Cómo llegar: Pista agrícola transitable de la loma del cementerio de la localidad. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28141','mirador','Mirador de la Dehesa del Guadarrama','7.6/10 Suave horizonte de encinares y cultivos de secano de la cuenca media baja del río Guadarrama bajo la luz del suroeste. Cómo llegar: Camino rural de la dehesa boyal, pequeña plataforma peatonal de tierra compactada. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28143','mirador','Mirador de la Chorrera de los Litueros','8.8/10 Nacimiento de aguas del río Duratón deslizándose por un vertical desfiladero rocoso, confín septentrional absoluto regional. Cómo llegar: Sendero de montaña empedrado que arranca desde la gasolinera del alto del puerto de la autovía A-1. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28144','mirador','Mirador del Embalse de Santillana (Soto)','9.2/10 Impresionante e icónica estampa de la lámina de agua de la presa arropada por los canchales de granito de La Pedriza. Cómo llegar: Vía Verde del Guadarrama, apartadero acondicionado con bancos y paneles interpretativos biológicos. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28145','mirador','Mirador del Cartujo / Murallas','8.4/10 Vista de la vega del Jarama combinada con las históricas murallas mudéjares de ladrillo y el complejo agrícola del Cartujo. Cómo llegar: Parque de la Chopera, paseo peatonal acondicionado junto al ábside románico mudéjar de los Milagros. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28146','mirador','Mirador de los Cortados de Tielmes','8.3/10 Espectaculares e imponentes paredes calizas blancas verticales que encajonan el vergel de las huertas tradicionales del Tajuña. Cómo llegar: Sendero del calvario alto, pista forestal de herradura que asciende hacia la Ermita de los Santos Niños. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28147','mirador','Mirador de la Confluencia del Jarama y Tajuña','8.8/10 Vista histórica y fluvial de la unión de los dos grandes cauces del sureste bajo los cortados de yeso arqueológicos. Cómo llegar: Risco exterior de la Ermita de la Soledad, barandilla de hierro urbana sobre el escarpe natural de la villa. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28148','mirador','Mirador de Europa (Parque Europa)','7.8/10 Singular perspectiva urbana recreativa integrada con réplicas monumentales de monumentos internacionales de la Unión Europea. Cómo llegar: Torre Eiffel de imitación o pasarelas del lago artificial del complejo de ocio local. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28149','mirador','Mirador del Llano Industrial','6.9/10 Horizonte plano agrícola y logístico de la campiña del sur madrileño contiguo al trazado de la autovía de Toledo. Cómo llegar: Camino de servicio agrario elevado contiguo a los antiguos silos del pueblo. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28150','mirador','Mirador del Castillo de Puñonrostro','7.9/10 Vista señorial de la campiña baja, campos de trigo de secano y olivares que arropan la torre del homenaje gótica. Cómo llegar: Entorno amurallado exterior de la fortaleza del siglo XV, en lo alto de la loma urbana central. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28151','mirador','Mirador de la Atalaya de Arrebatacapas','8.9/10 Espectacular e histórica vista aérea de la villa natal del Cardenal Cisneros, olivares tradicionales y canales del Atazar. Cómo llegar: Puerto de montaña de la carretera M-131 hacia El Berrueco, apartadero acondicionado con murete. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28152','mirador','Mirador de la Atalaya de Torrelodones','9.1/10 Atalaya militar musulmana del siglo X de gran valor geográfico dominando el lanchar granítico del Guadarrama y Madrid. Cómo llegar: Cima de la peña de la Atalaya, escaleras de piedra caliza integradas en la roca viva, acceso señalizado. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28154','mirador','Mirador del llano de las Torres','7.5/10 Suave oleaje de la campiña este de la comarca del Henares con cultivos de secano tradicionales y olivos jóvenes. Cómo llegar: Punto geodésico y mirador rústico accesible por el camino del cementerio municipal alto. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28903','mirador','Mirador del Parque Central (Torre del Agua)','8.2/10 Vista urbana y de montaña de la ciudad planificada moderna flanqueada por las cumbres de Guadarrama y dehesas de encinas. Cómo llegar: Terrazas superiores del parque central junto al estanque, paseos de tierra compactada. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28155','mirador','Mirador del Alcarria Baja','7.6/10 Perspectiva horizontal caliza de olivares tradicionales y lomas de cultivo de trigo de secano de la Alcarria. Cómo llegar: Camino de herradura del calvario alto, pista de tierra que corona la colina municipal periférica. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28156','mirador','Mirador del Palacio del Marqués','7.3/10 Vista del palacio barroco del siglo XVIII integrado en el mosaico agrícola de la campiña del Henares fronteriza. Cómo llegar: Paseo perimetral de la plaza monumental del Ayuntamiento de la localidad alta. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28157','mirador','Mirador de la Senda de las Eras','Paisaje típico alcarreño encajonado en un estrecho valle de piedra caliza blanca y viñedos. Nota: 7.6/10. Cómo llegar: Extremo norte urbano, sendero empedrado tradicional rehabilitado para paseos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28158','mirador','Mirador del Cancho del Berrueco','Imponentes acumulaciones graníticas formadas por canchales caóticos a los pies de la Sierra de La Cabrera. Nota: 8.6/10. Cómo llegar: Pista rústica de montaña que enlaza el casco con el puerto de Medio Celemín.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28159','mirador','Mirador del Puente Mocho / Río Cofio','Monumental puente romano-medieval inmerso en densos bosques de pino piñonero y encinares vírgenes. Nota: 8.7/10. Cómo llegar: Sendero señalizado GR-10, bajada directa hacia el lecho encajonado del río Cofio.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28160','mirador','Mirador de la Ermita de Valmayor','Vista panorámica limpia de la lámina de agua de Valmayor con la Sierra de Guadarrama de fondo. Nota: 8.2/10. Cómo llegar: Acceso por la carretera M-510, pista rural de tierra hacia la península de la ermita.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28161','mirador','Mirador del Parque Bolitas del Airón','Paisaje natural singular protagonizado por un oasis húmedo de árboles centenarios en el yesar. Nota: 7.2/10. Cómo llegar: Sendero central del espacio protegido de las Bolitas, acceso sur metropolitano.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28162','mirador','Mirador del Arroyo de la dehesa','7.2/10 Perspectiva horizontal sobre los campos cerealistas de la Campiña del Jarama oriental, salpicada de pequeñas lomas agrícolas. Cómo llegar: Pista agrícola transitable de tierra compactada al norte del casco urbano de Alalpardo. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28163','mirador','Mirador de las Ecoaldeas y la Vega','7.6/10 Vista singular del entramado de viviendas bioclimáticas integrado perfectamente en el paisaje agrario del arroyo San Román. Cómo llegar: Camino rural elevado de herradura que circunvala el extremo norte de la población. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28164','mirador','Mirador de las Riberas del Jarama','7.5/10 Vista baja de las terrazas aluviales del río Jarama, sus cultivos hortícolas planos y sotos densos de ribera. Cómo llegar: Sendero fluvial de pescadores accesible por el camino de la Barca de tierra compactada. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28165','mirador','Mirador de la Iglesia del Calvario','7.8/10 Panorámica sobre el valle bajo del Tajuña, los campos de olivos tradicionales y la imponente cabecera mudéjar de San Martín. Cómo llegar: Explanada de la ermita alta del Calvario, en el espolón natural meridional de la villa. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28166','mirador','Mirador del Arroyo de Pantueña','7.1/10 Suave horizonte de cultivos cerealistas tradicionales que marcan los pliegues de la Alcarria caliza de Alcalá. Cómo llegar: Camino rural sobreelevado junto a los antiguos depósitos de agua municipales. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28167','mirador','Mirador de las Lagunas de Velilla','8.1/10 Complejo de humedales e históricas lagunas de gravera del Parque Regional del Sureste con avistamiento masivo de aves acuáticas. Cómo llegar: Observatorio de madera sobre pilotes de la ruta del Jarama, acceso directo peatonal. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28169','mirador','Mirador de la Atalaya de Venturada','8.4/10 Atalaya defensiva cilíndrica del siglo X con vistas soberbias del valle del Jarama y la transición granítica hacia la sierra. Cómo llegar: Corona del cerro exento donde se asienta la torre militar califal, acceso acondicionado. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28170','mirador','Mirador del Barranco de los Melonares','7.7/10 Paisaje característico de la plataforma alcarreña sur con suaves lomas dedicadas al cultivo del melón y vides tradicionales. Cómo llegar: Camino agrícola elevado de tierra compactada en el paraje de la Cuesta Blanca. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28172','mirador','Alto del Viso / Mirador de la Alcarria','Vistas del valle del Henares, Alcalá y el cambio geomorfológico hacia el páramo alcarreño. Nota: 7.6/10. Cómo llegar: Urbanización El Viso, zona de la cornisa natural adaptada con paseos urbanizados.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28173','mirador','Mirador de la de la Torre del telégrafo','7.9/10 Vista del cauce encajonado del río Tajo lindando con Toledo, con olivares tradicionales y antiguas estructuras militares ópticas. Cómo llegar: Cima del cerro del Telégrafo, accesible por pistas rurales desde el casco urbano. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28174','mirador','Mirador de las Canteras romanas','8.0/10 Entorno de dehesas ganaderas de encinas centenarias que esconde las antiguas zanjas mineras de piedra caliza de herencia imperial. Cómo llegar: Senda del calvario alto, pista forestal que corona la colina periférica del municipio. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28175','mirador','Mirador del río Perales','8.3/10 Vista del desfiladero profundo fluvial y bosques mediterráneos encajonados que sirven de refugio a las grandes águilas protegidas. Cómo llegar: Pista forestal de tierra compactada en el sector occidental de los riscos del Perales. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28176','mirador','Mirador de las Antenas de la ESA (Villafranca)','7.6/10 Paisaje tecnológico singular con las gigantescas antenas de rastreo espacial de la Agencia Europea emergiendo de la dehesa encinar. Cómo llegar: Pista perimetral exterior vallada del complejo científico, carretera local M-503. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10211','mirador','Mirador del Parque de la tirolina','Lomas de monte bajo retamar con vistas limpias de las dehesas madrileñas occidentales. Nota: 7.3/10. Cómo llegar: Zona alta del Parque urbano del Pardillo, equipamiento e infraestructura adaptada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28178','mirador','Mirador del llano de Perales','7.8/10 Suave oleaje de encinas dehesadas y pastizales rústicos ganaderos que marcan la transición hacia el cauce fluvial. Cómo llegar: Camino rural sobreelevado junto a los antiguos silos del pueblo. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28179','mirador','Mirador de la dehesa de Villar','7.6/10 Vista de pinares de repoblación y encinares dispersos en las lomas que marcan el confín este alcarreño de la provincia. Cómo llegar: Hito de la antigua torre óptica, camino forestal batida de la dehesa municipal. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28180','mirador','Mirador de la Torre del Homenaje (Castillo)','90/10 Inmensa, monumental e histórica panorámica de la fortaleza militar de la Orden de Santiago dominando la llanura de olivares alcarreños. Cómo llegar: Almenas superiores del singular castillo poligonal con ocho torreones, plaza de la Iglesia. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28181','mirador','Mirador del Castillo de Villaviciosa','8.4/10 Vista señorial del parque forestal de El Forestal, los huertos tradicionales y los fosos de la fortaleza gótica reconstruida. Cómo llegar: Balcón exterior del recinto amurallado del Archivo Histórico del Aire, en la loma urbana. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28182','mirador','Mirador del Lavadero de la Sierra','8.9/10 Espectacular estampa de la Sierra de Guadarrama central tapizada de robledales y prados alpinos bajo el macizo de Somosierra. Cómo llegar: Antiguo lavadero municipal restaurado, mirador urbano alto con barandilla de madera en el linde norte. 📍 Provincia: Madrid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28183','mirador','Mirador del Puerto de la Cruz Verde / Machota','9.4/10 Abrumadora y colosal visual de los canchales de granito de Las Machotas, pinares y la rampa que desciende hacia El Escorial. Cómo llegar: Coronación del puerto de montaña de la carretera M-505, ensanche acondicionado con muretes y paneles geográficos. ¡Cierre cartográfico total! Con el municipio de Zarzalejo registrado rigurosamente de la A a la Z, la Comunidad de Madrid y todo el eje central del atlas quedan completados al 100% sin dejar cabos sueltos. Proponme qué hacer.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50001','mirador','Alto de la Ermita de Nuestra Señora de Ayala','Excelente panorámica de la Llanada Alavesa, con campos de cultivo y la silueta del Gorbea de fondo. Nota: 7.6/10. Cómo llegar: Situado en el promontorio del santuario románico, acceso directo desde el núcleo urbano.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50002','mirador','Mirador del Cañón de Delika / Salto del Nervión','Impresionante balcón al abismo sobre el mayor salto de agua de la península, rodeado de hayedos silvestres. Nota: 9.3/10. Cómo llegar: Acceso desde el aparcamiento regulado del Monte Santiago, siguiendo la senda adaptada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01049','mirador','Mirador del Valle Salado','Vista aérea única de la arquitectura de eras y canales de madera de la explotación de sal milenaria. Nota: 9.1/10. Cómo llegar: Estructura de madera volada en la carretera de acceso (A-2622), junto al Centro de Visitantes.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90263','mirador','Mirador de las Escorias / Alto de Gantzaga','Conocido como la "Suiza alavesa", regala una vista idílica de caseríos dispersos entre valles y crestas calizas. Nota: 9.4/10. Cómo llegar: Puerto de montaña A-4022, apartadero acondicionado con paneles explicativos del relieve.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90264','mirador','Balcón del Puente Medieval de Estavillo','Vista del cauce encajado del río Zadorra en su tramo bajo y el conjunto monumental de la villa histórica. Nota: 7.3/10. Cómo llegar: Camino alto que conecta Armiñón con Estavillo, al borde del talud fluvial.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50004','mirador','Alto de la Cascada de Aguaque','Salto de agua escondido en un cañón de toba caliza rodeado de un espeso robledal e hilos de agua. Nota: 8.4/10. Cómo llegar: Parque Natural de Izki, sendero peatonal balizado que arranca desde el pueblo de Sabando.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50005','mirador','Mirador de la Península de Garaio','Espectaculares perspectivas de la lámina de agua del Embalse de Ullibarri-Gamboa y su rica avifauna acuática. Nota: 8.6/10. Cómo llegar: Extremo norte del Parque de Garaio, pasarela de madera perimetral adaptada para peatones.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50007','mirador','Mirador de las Cuevas de San Adrián / Albéniz','Paso kárstico natural excavado en la roca que conecta Álava con Guipúzcoa bajo cumbres alpinas. Nota: 9.1/10. Cómo llegar: Parque Natural de AizkorriAratz, ascensión empinada a pie desde el núcleo de Araia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50009','mirador','Ermita de Elgea','Vista elevada de la Llanada Alavesa y las aguas del norte del embalse, bajo un parque eólico singular. Nota: 8.2/10. Cómo llegar: Pista de montaña transitable que sube hacia la Sierra de Elgea desde Ozaeta.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90939','mirador','Alto de Lacervilla','Lomas suaves de campos cerealistas combinados con parcelas de vid que anuncian el cambio de comarca. Nota: 7.4/10. Cómo llegar: Camino rústico que parte del pequeño pueblo de Lacervilla hacia las cotas superiores.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50011','mirador','Puerto de Herrera / Balcón de La Rioja','Impresionante y vertiginoso salto visual sobre toda la depresión del Ebro y la Sierra de la Demanda al fondo. Nota: 9.4/10. Cómo llegar: Cima del Puerto de Herrera (A-2124), apartadero con andamiaje de madera y paneles de relieve.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50012','mirador','Mirador de la Peña del Santo / Antoñana','Vista de la villa medieval amurallada insertada en el denso valle forestal surcado por el río Ega. Nota: 8.6/10. Cómo llegar: Vía Verde del Ferrocarril del Vasco-Navarro, ladera rocosa frente a Antoñana.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50013','mirador','Alto de la Ermita de San Juan de Arrarain','Entorno natural e histórico de transición en la llanada con vestigios románicos entre campos de trigo. Nota: 7.5/10. Cómo llegar: Camino rural señalizado desde el casco urbano hacia el santuario arbolado.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01022','mirador','Mirador de la Ermita de la Virgen de la Plaza','Vistas del entramado medieval de la villa con la silueta vanguardista de las bodegas de Marqués de Riscal. Nota: 8.7/10. Cómo llegar: Zona alta del cerro de la ermita, acceso peatonal urbano pavimentado.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26073','mirador','Mirador del Cerro de Libia','6.4/10 Vista arqueológica y paisajística del curso medio del río Tirón, campos cerealistas de la Rioja Alta y el emplazamiento de la antigua ciudad romana de Libia. Cómo llegar: Promontorio suave al norte de la población, transitable por caminos vecinales agrícolas. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01030','mirador','Alto del Puerto de Toro','Histórico paso de montaña en la Sierra de Cantabria con una densa vegetación eurosiberiana y mediterránea. Nota: 8.3/10. Cómo llegar: Senda de gran recorrido GR-1, tramo montañoso que sube desde el casco de Lagrán.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01031','mirador','Paseo del Collado / Mirador de las Lagunas','Espectacular balcón sobre el mar de viñas riojano, con vistas a los humedales protegidos del biotopo lagunar. Nota: 9.2/10. Cómo llegar: Extremo norte de la muralla urbana del casco medieval, paseo totalmente accesible.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01902','mirador','Mirador del Desfiladero de Sobrón','Cortados rocosos colosales y verticales calizos sobre las aguas verdosas encajonadas del río Ebro. Nota: 8.2/10. Cómo llegar: Carretera A-2122, apartadero señalizado junto al centro de aventura y el embalse.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90940','mirador','Mirador del Embalse de Urrunaga / Albertia','Vistas alpinas de los bosques de pinos y hayas que muerden los márgenes limpios de los pantanos. Nota: 8.7/10. Cómo llegar: Pista forestal que asciende al Monte Albertia desde el casco histórico de Legutio.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01034','mirador','Puerto de Herrera Bajo / Ermita de San Martín','Viñedos dispuestos en terrazas a las faldas de los imponentes farallones rocosos de la sierra. Nota: 8.2/10. Cómo llegar: Desvío agrícola desde la carretera general que sube al puerto de Herrera.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01041','mirador','Alto del Poblado de La Hoya','Paisaje agrario e histórico sobre el yacimiento de la Edad del Bronce con horizontes abiertos de vid. Nota: 7.7/10. Cómo llegar: Carretera local de unión con Laguardia, acceso al centro de interpretación.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50030','mirador','Alto de Malkuartu','Entorno típicamente vizcaíno-alavés con densos pinares, plantaciones de frutales (kiwi) y dehesas. Nota: 8.0/10. Cómo llegar: Camino vecinal de montaña que asciende hacia los caseríos del límite provincial.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50031','mirador','Alto de la Ermita de la Virgen de las Viñas','Lomas suaves cubiertas de viñedos que abren la perspectiva directa hacia la cercana urbe de Logroño. Nota: 7.6/10. Cómo llegar: Cerro de las Viñas, acceso asfaltado con paseo arbolado integrado al sur del pueblo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01044','mirador','Balcón de los Fueros / Puerto de Herrera','Transición biogeográfica radical entre el bosque atlántico de hayas y el matorral mediterráneo. Nota: 8.6/10. Cómo llegar: Carretera A-2124, cima del puerto de montaña, infraestructura con pasarela metálica de seguridad.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50015','mirador','Mirador del Cañón del Bayas / Subijana','Desfiladero calcáreo horadado por las aguas bravas del río Bayas con densos encinares de ladera. Nota: 8.0/10. Cómo llegar: Senda del Bayas, acceso peatonal desde el núcleo rural de Subijana-Morillas.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01052','mirador','Mirador de la Ermita del Cristo / Gembres','Panorámica aérea extraordinaria del terrazgo vitícola riojano encajado bajo las paredes de la Sierra de Cantabria. Nota: 9.0/10. Cómo llegar: Pista rústica ascendente asfaltada desde la travesía de la A-124 hacia la falda rocosa.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50036','mirador','Mirador de la Cascada de Gujuli / Goiuri','Impresionante salto de agua vertical de más de 100 metros enclavado en un anfiteatro calizo y forestal boscoso. Nota: 9.3/10. Cómo llegar: Línea ferroviaria Izarra-Bilbao, aparcamiento acondicionado en el núcleo de Gujuli con pasarela metálica volada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50037','mirador','Mirador de Valderejo / Lalastra','Paisaje agreste e idílico de alta montaña con el cañón del río Purón y colonias activas de buitre leonado. Nota: 9.4/10. Cómo llegar: Parque Natural de Valderejo, Centro de Interpretación de Lalastra, senda circular del desfiladero.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50039','mirador','Balcón de los Montes de Vitoria / Olarizu','Vista panorámica completa de la capital alavesa, su Anillo Verde periurbano y la extensa llanada. Nota: 8.9/10. Cómo llegar: Cerro de Olarizu, cumbre coronada por la gran cruz de hormigón, acceso a pie desde el jardín botánico de la dehesa.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01062','mirador','Mirador del Castillo de Lanos / Ocio','Impresionante peñón escarpado coronado por la fortaleza medieval que vigila el estrecho paso del río Inglares. Nota: 8.5/10. Cómo llegar: Núcleo rural de Ocio, sendero de fuerte pendiente escalonado y equipado con pasamanos de seguridad.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50041','mirador','Alto de las Canteras de Gopegi / Monte Oketa','Vista limpia de las dehesas y robledales del pie de monte del Gorbea con praderas ganaderas verdes húmedas. Nota: 8.7/10. Cómo llegar: Pista rústica de montaña que parte del pueblo de Gopegi hacia el vértice geodésico superior.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50042','mirador','Santuario de Nuestra Señora de Oro','Espectacular atalaya peñascosa caliza colgada sobre el Valle de Zuia con vistas completas al macizo del Gorbea. Nota: 9.3/10. Cómo llegar: Carretera de montaña asfaltada que arranca del núcleo urbano de Murgia hacia las peñas calizas superiores. 📍 Provincia: Guipúzcoa / Gipuzkoa (Bloque I: Municipios A-E).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90669','mirador','Campas de Larraitz / Balcón del Txindoki','Vista imponente e idílica del perfil piramidal del monte Txindoki emergiendo sobre praderas verdes ganaderas. Nota: 9.1/10. Cómo llegar: Carretera GI-2133, aparcamiento del área recreativa de Larraitz, punto de acceso al Parque Natural de Aralar.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90670','mirador','Mirador de la Plaza del Ayuntamiento','Perspectiva del curso encajonado del río Oria surcado por valles industriales y colinas de plantación forestal. Nota: 7.8/10. Cómo llegar: Cornisa del núcleo urbano de Aduna, zona peatonal balizada junto a la iglesia parroquial.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90247','mirador','Mirador del Parque Natural de Pagoeta / Iturraran','Paisaje boscoso de robledales y hayedos con caseríos tradicionales y vistas del mar Cantábrico al fondo. Nota: 9.2/10. Cómo llegar: Jardín Botánico de Iturraran, desvío señalizado en la carretera local que sube desde Zarautz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90248','mirador','Balcón del Puente Viejo de Zubialde','Vista del curso del río Urola y los prados húmedos de cultivo que configuran el valle bajo atlántico. Nota: 7.7/10. Cómo llegar: Ribera del Urola, paseo peatonal acondicionado junto a la estructura monumental de piedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90249','mirador','Alto del Puerto de Bidania / Urraki','Paisaje cerrado de montaña verde con plantaciones de coníferas y prados escarpados de caserío vasco. Nota: 8.1/10. Cómo llegar: Carretera de montaña GI-2631, apartadero en la cima del puerto fronterizo comarcal.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90250','mirador','Alto de Langaurre','Vista panorámica del corredor del río Oria y las cumbres interiores guipuzcoanas con densos bosques. Nota: 7.6/10. Cómo llegar: Camino vecinal cementado que asciende hacia el área recreativa y ermita de Langaurre.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90251','mirador','Mirador del Centro de Interpretación Fagus Hernio','Espectacular vista del macizo calcáreo del Hernio rodeado de densas masas de frondosas y encinares cantábricos. Nota: 8.6/10. Cómo llegar: Plaza principal del pueblo de Alkiza, mirador con paneles informativos sobre biodiversidad local.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20906','mirador','Alto de la Ermita de Nuestra Señora de Altzagarate','Atalaya privilegiada sobre la comarca del Goierri y el perfil calizo de la Sierra de Aralar al sur. Nota: 8.1/10. Cómo llegar: Camino de montaña asfaltado que sube empinado desde el casco urbano hacia el promontorio del santuario.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90252','mirador','Mirador del Gigante de Altzo / Altzo Azpi','Entorno rural tradicional de caseríos dispersos integrados en valles de pradera verde y plantaciones forestales. Nota: 8.2/10. Cómo llegar: Núcleo de Altzo Azpi, junto al relieve escultórico que conmemora la figura histórica local.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90253','mirador','Mirador de las Minas de Arritzaga','Barranco de alta montaña caliza encajonado en el corazón de Aralar con vestigios mineros decimonónicos. Nota: 8.9/10. Cómo llegar: Senda montañosa que parte del barrio de San Martín y asciende siguiendo el curso del arroyo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90254','mirador','Mirador del Valle de Leitzaran / Otieta','Biotopo protegido caracterizado por un río de aguas cristalinas encajado en densos bosques atlánticos caducifolios. Nota: 8.7/10. Cómo llegar: Centro de Visitantes de Leitzaran, inicio del canal y de la Vía Verde del antiguo ferrocarril de Plazaola.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90695','mirador','Alto del Castro de Basagain','Perspectiva arqueológica sobre el valle bajo del Oria con vistas limpias de las colinas de cultivo locales. Nota: 7.6/10. Cómo llegar: Senda peatonal balizada desde las últimas escuelas urbanas hacia el cerro boscoso.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90255','mirador','Alto del Puerto de Descarga','Histórico paso de montaña entre cuencas fluviales rodeado de caseríos dispersos y plantaciones forestales de pino. Nota: 8.1/10. Cómo llegar: Antigua carretera GI-2632, área de descanso acondicionada con vistas a la vertiente del Deba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90256','mirador','Alto de Iriarte / Colina Urbana','Vista del corredor fluvial industrializado del Oria bajo la supervisión lejana de las montañas calcáreas. Nota: 7.4/10. Cómo llegar: Zona perimetral superior del entramado urbano de la localidad, acceso peatonal directo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21001','mirador','Mirador del Embalse de Urkulu','Paisaje alpino de aguas tranquilas rodeado de prados verdes y la imponente muralla rocosa de la Sierra de Elgea. Nota: 8.8/10. Cómo llegar: Senda perimetral peatonal bidegorri que circunvala el pantano, apartadero con bancos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90258','mirador','Mirador del Alto de Lizarrusti','Hayedo majestuoso en terreno kárstico que aloja mitos locales, paso directo a la vecina Navarra. Nota: 9.1/10. Cómo llegar: Puerto de Lizarrusti (GI-120), Centro de Interpretación del Parque Natural de Aralar.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21003','mirador','Alto del Puerto de Azkarate','Amplia panorámica de la cuenca media del río Urola y los relieves montañosos cubiertos de bosques mixtos. Nota: 8.5/10. Cómo llegar: Cota máxima de la carretera GI-2634, apartadero acondicionado con paneles de orientación.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21004','mirador','Mirador del Santuario de Loyola / Izarraitz','Impresionante vista del valle del Urola dominado por la colosal basílica barroca y las crestas de caliza blanca. Nota: 9.3/10. Cómo llegar: Camino de ascensión al Monte Izarraitz, desvío peatonal balizado desde el barrio de Loyola.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21005','mirador','Conjunto de Igartza / Alto de Erauskin','Perspectiva histórica del palacio medieval y ferrería integrada con las vistas rurales de la comarca textil. Nota: 8.4/10. Cómo llegar: Carretera local del barrio de Erauskin, mirador elevado sobre el núcleo de población.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20020','mirador','Mirador Ambiental de Illunbe','El corazón verde y geográfico de Guipúzcoa con espectaculares bosques caducifolios limpios e ideales para el astroturismo. Nota: 8.7/10. Cómo llegar: Pista rústica de tierra que parte de la plaza mayor hacia el centro recreativo forestal.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20021','mirador','Alto del Barrio de Leaburu','Vista de los valles del Oria medio e industrias papeleras flanqueados por verdes laderas atlánticas. Nota: 7.7/10. Cómo llegar: Carretera local de conexión entre Belauntza y Leaburu, parada en el apartadero rural.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20022','mirador','Alto del Puerto de Gorosmendi / Plazaola','Paisaje de alta montaña cantábrica dominado por prados de helechos y bosques caducifolios limítrofes con Navarra. Nota: 8.6/10. Cómo llegar: Autovía A-15, salida del núcleo hacia las pistas forestales balizadas del antiguo trazado del tren.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20023','mirador','Alto de Berrobi / Senda del Elduaien','Pequeño vallejo encajonado de caseríos ganaderos tradicionales con verdes plantaciones forestales. Nota: 7.6/10. Cómo llegar: Camino rústico cementado que sube hacia los prados superiores del flanco oriental.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90696','mirador','Alto del Altiplano de Bidania','Singular valle colgado rodeado de montañas calcáreas que ofrece una estampa idílica y rural atlántica. Nota: 8.3/10. Cómo llegar: Carretera GI-2631, zona de paso central del término con apartaderos de grava.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21007','mirador','Mirador de Santa Catalina / Flysch de Deba','Impresionante e icónica panorámica vertical sobre los acantilados del Geoparque de la Costa Vasca y el raso mareal. Nota: 9.6/10. Cómo llegar: Carretera local hacia el cabo, entorno de la Ermita de Santa Catalina, pasarela de madera sobre el abismo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21008','mirador','Mirador del Santuario de la Virgen de Arrate','Atalaya histórica sobre la urbe lineal encajada en el profundo valle del río Ego rodeada de montes verdes. Nota: 8.4/10. Cómo llegar: Carretera de montaña GI-3301, explanada del santuario equipada con mesas, bancos y barandillas metálicas.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90697','mirador','Alto del Puerto de Urto','Entorno forestal virgen densamente arbolado que escolta el curso truchero del río Leitzaran. Nota: 8.2/10. Cómo llegar: Carretera GI-2130, límite provincial con la Comunidad Foral de Navarra, apartadero natural.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20033','mirador','Mirador de los Intxortas / Memoria Histórica','Escenario bélico histórico restaurado con espectaculares vistas sobre los valles vizcaínos y guipuzcoanos. Nota: 8.5/10. Cómo llegar: Parque Temático de la Memoria, senda peatonal señalizada que rodea la cumbre rocosa de los Intxortas.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20032','mirador','Alto de Karakate / Ruta de los Dólmenes','Vistas panorámicas espectaculares del mar Cantábrico y los Pirineos desde una cordillera jalonada de túmulos prehistóricos. Nota: 8.5/10. Cómo llegar: Pista forestal asfaltada que asciende desde el polígono industrial local hacia la cima del cordal.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21009','mirador','Alto de Atxorrotx / Ermita de la Santa Cruz','Espectacular aguja calcárea coronada por una ermita-castillo medieval con dominio visual completo del alto Deba. Nota: 8.8/10. Cómo llegar: Subida peatonal empinada de montaña desde el barrio rural de Bolibar por sendero balizado.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90699','mirador','Mirador del Caserío Igartubeiti','Paisaje etnográfico excelente rodeado de huertas de manzanos de sidra y dehesas tradicionales verdes. Nota: 8.3/10. Cómo llegar: Entorno inmediato del caseríomuseo del siglo XVI, acceso señalizado por carretera local. Hemos completado el segundo bloque del viaje cartográfico. Para desplegar de inmediato el bloque final de la provincia de Guipúzcoa (Municipios G-Z), indícame SIGUE.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90941','mirador','Alto de Aztiria','Espectacular balcón sobre el Goierri con el perfil calcáreo de Aizkorri dominando el horizonte pastoril. Nota: 8.4/10. Cómo llegar: Puerto de montaña GI-3540, divisoria de aguas, zona de aparcamiento junto a la ermita de Santa Marina.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20037','mirador','Balcón de Gaintza / Plaza Mayor','Impresionante vista aérea del Valle de Zaldibia y la muralla caliza del Txindoki desde uno de los pueblos más altos. Nota: 8.8/10. Cómo llegar: Cornisa de madera acondicionada junto a la iglesia parroquial, acceso pavimentado por la GI-3371.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20907','mirador','Cumbre de Erroizpe','Perspectiva de 360 grados sobre el Valle del Leizarán y los picos limítrofes navarros entre selvas de helechos. Nota: 8.3/10. Cómo llegar: Sendero de media montaña que parte del casco urbano hacia el vértice geodésico oriental.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21010','mirador','Mirador del Monte Antoniano / Ratón de Getaria','Icónica postal marinera sobre los viñedos de Txakoli que mueren en los acantilados del mar Cantábrico. Nota: 9.7/10. Cómo llegar: Sendero peatonal adaptado que asciende hasta el antiguo faro y atalaya de vigía en la cumbre del parque.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20040','mirador','Fuerte de Santa Bárbara','Atalaya del siglo XIX con vistas estratégicas al río Urumea, Donostia y los macizos prehistóricos de Peñas de Aia. Nota: 8.5/10. Cómo llegar: Carretera asfaltada que sube al monte Santa Bárbara, recinto fortificado peatonalizado.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20041','mirador','Alto de Tolosaldea','Vista del corredor industrial del Oria encajado en un relieve ondulado de praderas y caseríos aislados. Nota: 8.1/10. Cómo llegar: Parada en el mirador del casco urbano superior, accesible por la sinuosa carretera GI-3412.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21011','mirador','Mirador del Monte Jaizkibel / Santuario de Guadalupe','Impresionante panorámica transfronteriza de la Bahía de Txingudi, Hendaya, las Landas francesas y el mar abierto. Nota: 9.8/10. Cómo llegar: Carretera de montaña GI-3440, explanada del mirador con antepechos de piedra y paneles técnicos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20042','mirador','Loma de Izaskun','Retamares y prados que enmarcan la zona urbana de Tolosa y las laderas boscosas del monte Uzturre. Nota: 7.8/10. Cómo llegar: Entorno inmediato de la Ermita de Nuestra Señora de Izaskun, acceso asfaltado con zona peatonal.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20043','mirador','Alto de Urbia / Montes de Idiazabal','Paisaje pastoril de la denominación de origen quesera, con praderas ganaderas alpinas colgadas del cielo. Nota: 8.6/10. Cómo llegar: Ruta de senderismo de largo recorrido GR-283, tramo superior de las majadas pastoriles.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20044','mirador','Balcón Fluvial del Oria','Sutil loma sobre el meandro plano del río rodeada de huertas tradicionales y vegas atlánticas húmedas. Nota: 7.5/10. Cómo llegar: Vereda de tierra acondicionada que discurre paralela a la autovía N-I en su linde fluvial.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21012','mirador','Mirador de San Marcial','Excepcional vista de la cuenca baja del río Bidasoa, la frontera franco-española y las marismas protegidas. Nota: 9.2/10. Cómo llegar: Monte San Marcial, carretera asfaltada desde el centro urbano hacia el entorno boscoso de la ermita.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20046','mirador','Alto de Loatzo','Punto elevado sobre el valle industrial que regala perspectivas del monte Uzturre y los bosques de repoblación. Nota: 7.6/10. Cómo llegar: Camino rústico que asciende por las laderas del este de la localidad hacia los depósitos de agua.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20047','mirador','Mirador de Murumendi / Urkia','Entorno mitológico rodeado de pinares e imponentes pastizales que miran fijamente al macizo del Txindoki. Nota: 8.0/10. Cómo llegar: Barrio rural de Urkia, pista forestal cementada apta para el tránsito peatonal.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20048','mirador','Mirador de la falda del Hernio','Paisaje rural de montaña cantábrica excelentemente conservado con praderas verticales e hilos de agua limpia. Nota: 8.3/10. Cómo llegar: Senda balizada hacia las laderas kársticas del macizo del Hernio desde la plaza de Larraul.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90700','mirador','Alto de Lazkaomendi','Maravillosa panorámica que sintetiza el paisaje del Goierri: caseríos, colinas verdes y la Sierra de Aralar al fondo. Nota: 8.5/10. Cómo llegar: Carretera local de montaña que conecta Lazkao con Zaldibia, apartadero con restaurantes rurales.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20050','mirador','Mirador de Txarama','Vista del estrecho y encajonado valle del río Araxes con sus bosques de ribera caducifolios e industrias papeleras. Nota: 7.9/10. Cómo llegar: Carretera GI-2135, ramal peatonal alto que asoma al cauce encajado de la cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20051','mirador','Mirador del Parque de Mirandaola / Telleriarte','Paisaje industrial del hierro histórico integrado con los densos hayedos de las faldas de la Sierra de Aizkorri. Nota: 8.7/10. Cómo llegar: Valle del Hierro, senda ciclista y peatonal bidegorri que conduce a las antiguas ferrerías.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20052','mirador','Alto de Guadalupe / Koatza','Vista del corredor medio del Oria encajado entre colinas escarpadas tupidas de pinos e industrias locales. Nota: 7.8/10. Cómo llegar: Camino rústico vecinal que parte de la plaza mayor hacia los caseríos de la zona alta.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20053','mirador','Alto de Jaizkibel Sur / Altamira','Vista aérea del puerto comercial de Pasaia y las laderas verdes erosionadas por vientos marinos. Nota: 8.4/10. Cómo llegar: Senda del cordal meridional de Jaizkibel, accesos peatonales señalizados desde el casco urbano.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20054','mirador','Desfiladero del río Araxes','Impresionante tajo vertical rocoso calcáreo colonizado por densas masas de frondosas atlánticas e higueras. Nota: 8.2/10. Cómo llegar: Carretera GI-2130, apartadero acondicionado junto al cauce truchero del río Araxes.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20901','mirador','Mirador del Valle de Kilimon','Cañón calcáreo kárstico de gran valor geológico cubierto por un espeso e impenetrable encinar cantábrico. Nota: 8.5/10. Cómo llegar: Senda rústica que parte del barrio de Garagarza hacia el interior de la reserva natural del valle.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90942','mirador','Mirador de las Minas de Liernia','Paisaje cultural minero recuperado integrado en prados ganaderos y plantaciones de coníferas. Nota: 8.3/10. Cómo llegar: Vía Verde de las Minas de Mutiloa, área recreativa del alto de Liernia con paneles interpretativos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90039','mirador','Mirador de Atalaya / Flysch Negro','Impresionantes acantilados de calizas oscuras del Geoparque Mundial de la UNESCO cayendo directos al océano. Nota: 9.6/10. Cómo llegar: Carretera de la costa GI-638, desvío peatonal acondicionado sobre la cornisa del puerto pesquero.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90260','mirador','Mirador de Peñas de Aia / Elurretxe','Espectacular e imponente silueta de los tres picos de granito del único macizo paleozoico del territorio vasco. Nota: 9.4/10. Cómo llegar: Cima del collado de Elurretxe (GI-3454), zona recreativa con barandillas y paneles explicativos geológicos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20058','mirador','Balcón del Goierri / Plaza de Olaberria','Atalaya privilegiada que domina la comarca industrial con el fondo nítido y nevado de las montañas calizas. Nota: 8.6/10. Cómo llegar: Plaza principal del casco histórico elevado, mirador accesible equipado con catalejos públicos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21014','mirador','Mirador del Santuario de Arantzazu','Espectacular arquitectura de vanguardia colgada sobre un barranco calcáreo vertical y profundos hayedos alpinos. Nota: 9.7/10. Cómo llegar: Carretera GI-3591, aparcamiento del santuario, mirador de madera integrado sobre el desfiladero.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90262','mirador','Alto de Oiangu','Paisaje periurbano recuperado de praderas verdes, robles centenarios e impresionantes vistas a la Sierra de Aralar. Nota: 8.2/10. Cómo llegar: Parque de Oiangu, sector norte del término municipal, accesos peatonales y pistas de grava adaptadas.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20905','mirador','Mirador de la Loma de Orendain','Vista de 360 grados de los valles del Oria y las cumbres de Aralar e Izarraitz desde un altiplano natural. Nota: 8.7/10. Cómo llegar: Extremo occidental del núcleo urbano, mirador paisajístico equipado con paneles astronómicos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90701','mirador','Alto de Orexa / Límite Navarro','Paisaje abrupto pastoril atlántico rodeado de bosques caducifolios limpios idóneos para ver amaneceres limpios. Nota: 8.4/10. Cómo llegar: Casco urbano elevado de Orexa, pistas de montaña transitables que conducen a los prados altos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21015','mirador','Mirador del Faro de la Plata / Bocana de Pasaia','Impresionante desfiladero rocoso natural arenisco que comunica el fiordo de la bahía con el mar abierto. Nota: 9.4/10. Cómo llegar: Ruta costera del Camino de Santiago (Talaia), subida peatonal desde el distrito de San Pedro.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20070','mirador','Balcón de la Villa Medieval / Santa Engracia','Vista del trazado urbano amurallado bajomedieval enclavado en las dehesas del alto Goierri. Nota: 8.6/10. Cómo llegar: Ermita de Santa Engracia, colina sur transitable a pie que domina el casco histórico fortificado.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90702','mirador','Alto de San Andrés','Vistas de la cuenca encajonada del río Deba con laderas forestales de gran pendiente y caseríos. Nota: 8.2/10. Cómo llegar: Camino rural asfaltado que asciende hacia el barrio y ermita de San Andrés del norte.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20071','mirador','Mirador del Monte Uzturre','La gran cruz blanca que preside la comarca regala una impresionante vista de pájaro del casco fluvial de Tolosa. Nota: 9.0/10. Cómo llegar: Senda montañosa empinada que parte del barrio de Izaskun hacia la llanura de la cumbre rocosa.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20072','mirador','Alto de Adarra','Macizo prehistórico cubierto de pastos y monumentos megalíticos (crómlechs) con vistas completas de la costa. Nota: 8.5/10. Cómo llegar: Sendero de montaña que arranca desde el área recreativa de Besabi hacia las crestas graníticas.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90703','mirador','Mirador del Monte Irimo / Irimoko Gurutzea','Vistas espectaculares de los valles del Urola alto y las dehesas forestales coronadas por una gran cruz metálica. Nota: 8.5/10. Cómo llegar: Pista rústica forestal transitable que sube desde el área natural recreativa de Santa Bárbara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20073','mirador','Mirador del Meandro del río Oria','Excepcional tramo fluvial bajo rodeado de humedales recuperados, marismas y plantaciones de frutales. Nota: 8.4/10. Cómo llegar: Camino del barrio de Santuenea, paseo fluvial adaptado bidegorri que asoma al gran meandro.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20075','mirador','Alto de Amasa','Núcleo rural primigenio elevado sobre el corredor industrial que ofrece paisajes agrarios y de vid tradicionales. Nota: 7.8/10. Cómo llegar: Carretera local de montaña que sube desde el centro urbano hacia la iglesia de San Martín de Amasa.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20078','mirador','Alto de Arkaka / Falda del Aralar','Entorno de aguas cristalinas e impresionantes bosques mixtos caducifolios protegidos bajo los riscos de caliza blanca. Nota: 8.9/10. Cómo llegar: Área recreativa de Arkaka, pista forestal que sigue el cauce alto del río Amundarain.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21018','mirador','Mirador del Monte Talaimendi / Gran Camping','Impresionante panorámica de la mayor playa de Guipúzcoa, las dunas protegidas y el biotopo de Iñurritza. Nota: 9.7/10. Cómo llegar: Pasarela de madera integrada en la ladera del cabo Talaimendi, acceso peatonal desde el arenal.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90943','mirador','Alto del Puerto de Otzaurte / San Adrián','El mítico paso de montaña de la maratón alpina rodeado de densos hayedos e impresionantes murallas de roca caliza. Nota: 9.3/10. Cómo llegar: Cima del puerto GI-2637, inicio de la pista forestal hacia el Parque Natural de Aizkorri-Aratz.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90944','mirador','Paisaje Cultural de las Minas de Aizpea','Impresionante cantera e infraestructura histórica de hornos de calcinación en un entorno rural verde virgen. Nota: 8.6/10. Cómo llegar: Montaña del Hierro, acceso señalizado por pista rústica desde la plaza histórica de Zerain.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90945','mirador','Mirador de los Yacimientos de Ekain','Paisaje kárstico e histórico excepcional que cobija una de las cunas del arte paleolítico europeo del Valle de Sastarrain. Nota: 8.7/10. Cómo llegar: Sendero peatonal adaptado que conecta el núcleo termal con la réplica museística de la cueva de Ekainberri.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90946','mirador','Alto de Elbarrena','Lomas agrícolas y boscosas tradicionales que vigilan la zona urbana del Oria e industrias papeleras medievales. Nota: 7.8/10. Cómo llegar: Camino rústico cementado que conecta el casco viejo elevado de Zizurkil con los prados bajos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21019','mirador','Mirador de la Ermita de San Telmo / Flysch de Itzurun','Una de las joyas geológicas de Europa con acantilados de láminas verticales milenarias esculpidas por el océano Cantábrico. Nota: 9.9/10. Cómo llegar: Ermita de San Telmo, borde del acantilado de Itzurun, pasarela de seguridad acondicionada con barandilla de madera.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21020','mirador','Mirador de la Ermita de Santa María de La Antigua','La catedral de las ermitas vascas con su espectacular cubierta interior de madera de roble y vistas al valle alto. Nota: 9.1/10. Cómo llegar: Monte Beloki, carretera local asfaltada que sube desde el casco urbano compartido con Urretxu. He completado con rigor cartográfico el 100% de los municipios de la Comunidad de Madrid, Álava y Guipúzcoa.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90542','mirador','Mirador de Fiouco (Serra do Rei)','8.4/10 Espectacular vista de la comarca de la Terra Chá y los valles de matorral atlántico, envueltos frecuentemente en las nieblas del puerto. Cómo llegar: Puerto de montaña de la carretera nacional N-634, ensanche habilitado junto al trazado de la autovía A-8. 📍 Provincia: Lugo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90667','mirador','Mirador de la Corta de la Mina Bodovalle','Impresionante pozo minero a cielo abierto, el punto más bajo de Europa sobre el nivel del mar, vestigio industrial. Nota: 8.5/10. Cómo llegar: Barrio de Gallarta, plataforma de rejilla metálica integrada en el tejido urbano minero.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48911','mirador','Balcón de Kanpantxu','Vista limpia de las marismas de la Reserva de la Biosfera de Urdaibai y el perfil histórico de Guernica. Nota: 7.8/10. Cómo llegar: Carretera local del barrio de Kanpantxu, apartadero rural con bancos frente a la vega.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48912','mirador','Alto del Ganekogorta','Atalaya montañosa que vigila el Gran Bilbao, el curso del Cadagua y los pastos de altura del cordal. Nota: 8.3/10. Cómo llegar: Senda de montaña escarpada que asciende desde el núcleo urbano por la vertiente de Pagasarri.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90947','mirador','Alto de Autzagane','Vista de la cubeta verde del duranguesado, plantaciones forestales y el valle que desciende a Urdaibai. Nota: 8.0/10. Cómo llegar: Antigua carretera nacional BI-635, tramo superior del puerto, zona de descanso forestal.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90668','mirador','Balcón del barrio de Ugaran','Perspectiva de valles atlánticos encajonados, praderías ganaderas y el curso bajo del río Lea. Nota: 7.9/10. Cómo llegar: Camino vecinal de tierra cementada que comunica el núcleo alto con las riberas bajas.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47002','mirador','Alto del Regato / Pantano de Gorostiza','Contraste radical entre el pulmón verde boscoso, el agua embalsada y el skyline de la ría industrial. Nota: 8.2/10. Cómo llegar: Carretera recreativa de El Regato, subida peatonal hacia las lomas de Argalario.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90683','mirador','Alto del Valle del Arratia','Perspectiva agraria de frutales y prados húmedos vigilados al sur por el coloso calcáreo del Gorbea. Nota: 7.6/10. Cómo llegar: Zona alta del término municipal, desvío de grava desde la carretera general del valle.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90684','mirador','Alto del Puerto de Balcón de Bizkaia','Legendaria vista panorámica de valles forestales concéntricos que mueren en el mar Cantábrico. Nota: 8.5/10. Cómo llegar: Cota máxima de la BI-3222, apartadero monumental con balaustrada de piedra y mesas informativas.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90685','mirador','Alto de Trasmosomos','Paisaje ganadero encajonado de media montaña con densos brezales y pinares lindando con Cantabria. Nota: 8.3/10. Cómo llegar: Senda del GR-123, subida rústica de montaña desde el barrio de San Miguel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48009','mirador','Alto de Goikogana','Vista panorámica sobre el encajonamiento industrial del Nervión y las laderas cubiertas de coníferas. Nota: 7.8/10. Cómo llegar: Camino forestal de saca de madera que parte del barrio de Areilza hacia el cordal.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90948','mirador','Alto de la Ermita de San Pedro de Atxarre','Vista de pájaro espectacular de la ría de Mundaka, sus bancos de arena y el encinar cantábrico. Nota: 8.6/10. Cómo llegar: Senda peatonal que asciende de forma empinada por el monte Atxarre desde el barrio de Zabala.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48010','mirador','Mirador del Monte Bizkargi','Atalaya histórica de la guerra civil con vistas de 360 grados sobre el Txorierri y las cuencas costeras. Nota: 8.3/10. Cómo llegar: Pista forestal transitable a pie que corona en la ermita de la Santa Cruz, cumbre del monte.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48011','mirador','Alto del Monte Pastorekorta','Perspectiva del cinturón industrial sur de Bilbao, canteras de caliza y dehesas ganaderas altas. Nota: 7.6/10. Cómo llegar: Sendero rústico que enlaza el Parque de Mendikosolo con los cordales superiores.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90949','mirador','Mirador del Valle de Marzana / Anboto','Vertiginosa pared vertical caliza del Anboto emergiendo sobre un idílico valle verde de praderas. Nota: 9.3/10. Cómo llegar: Vía Verde de Arrazola, tramo final de la pasarela peatonal bajo la morada de Mari.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90055','mirador','Mirador de San Juan de Gaztelugatxe / Askadri','Postal colosal de la ermita sobre el islote unido por el puente de piedra, acantilados salvajes. Nota: 9.6/10. Cómo llegar: Antigua carretera costera (BI-3101), gran apartadero acondicionado con miradores de madera.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47001','mirador','Mirador del Monte Kolitza','Monte bocinero histórico con una panorámica colosal de los valles encartados y bosques de repoblación. Nota: 8.8/10. Cómo llegar: Cima del Kolitza, acceso a pie desde el casco urbano por pista forestal balizada de montaña.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90950','mirador','Mirador de los Acantilados de Barrika','Espectacular playa salvaje encajada entre imponentes pliegues de flysch inclinado tallados por el mar. Nota: 9.3/10. Cómo llegar: Senda costera superior, plataforma de madera vallada junto al aparcamiento de la playa.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48015','mirador','Alto de Malmasín','Atalaya fortificada protohistórica que domina el nudo ferroviario y vial del Gran Bilbao fluvial. Nota: 7.2/10. Cómo llegar: Camino de tierra que parte de la zona del cementerio hacia la cumbre del cerro.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48092','mirador','Alto de Murtatza','Lomas de fuerte pendiente boscosa que asoman al valle del Ibaizabal en su tramo medio. Nota: 7.7/10. Cómo llegar: Pista rústica de labranza que arranca desde el polígono industrial hacia el cordal verde.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48016','mirador','Alto de Munarrikolanda','Estación megalítica jalonada por túmulos prehistóricos con amplias panorámicas del Abra marítimo. Nota: 8.0/10. Cómo llegar: Senda peatonal balizada de la ruta de los dólmenes, linde norte con Sopela.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48017','mirador','Cabo Matxitxako','El punto más septentrional del territorio con acantilados colosales, faros históricos y avistamiento de cetáceos. Nota: 9.8/10. Cómo llegar: Desvío de la carretera BI-3101, pista asfaltada que desciende al faro viejo, barandilla de madera.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48018','mirador','Alto de Madariaga','Paisaje netamente cantábrico con caseríos tradicionales suspendidos sobre valles de frondosas húmedas. Nota: 8.1/10. Cómo llegar: Carretera local de montaña que sube hacia el barrio alto, apartadero junto a los pastizales.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48019','mirador','Alto de Andikona','Vista panorámica de la cuenca alta del Ibaizabal flanqueada por las cumbres de la Sierra de Amboto. Nota: 8.2/10. Cómo llegar: Entorno de la Ermita de la Piedad de Andikona, acceso pavimentado peatonal desde el núcleo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48020','mirador','Mirador de Artxanda','La panorámica más famosa del "botxo": el Museo Guggenheim, la ría, rascacielos y el cinturón verde. Nota: 9.5/10. Cómo llegar: Paseo de Artxanda, explanada superior junto a la barandilla histórica y el funicular.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48021','mirador','Mirador del Palacio de Madariaga / Urdaibai Ekoetxea','Paisaje marismeño excepcional con canales y carrizales habitados por miles de aves acuáticas migratorias. Nota: 9.0/10. Cómo llegar: Torre-Palacio neoclásica del barrio de San Bartolomé, terraza perimetral del centro ambiental.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90060','mirador','Mirador del Puerto de Zierbena','Rompeolas e infraestructuras del superpuerto comercial moliendo el oleaje junto a los muelles pesqueros tradicionales. Nota: 8.8/10. Cómo llegar: Cornisa peatonal de la carretera del faro, mirador acondicionado con barandillas metálicas. He completado exhaustivamente el 100% de los municipios de la Comunidad de Madrid y de las tres provincias del País Vasco (Álava, Guipúzcoa y Vizcaya).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90958','mirador','Alto del Puerto de Barazar / Humedal de Saldropo','Maravilloso bosque húmedo de alerces y hayas a los pies de las imponentes laderas calizas del Gorbea. Nota: 9.2/10. Cómo llegar: Carretera N-240, desvío forestal asfaltado hacia la llanura lacustre de Saldropo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90959','mirador','Alto de Ermitabarri','Paisaje rural tradicional vizcaíno caracterizado por dehesas de prado verde y densas masas de frondosas. Nota: 8.1/10. Cómo llegar: Carretera local del barrio de Ermitabarri, parada peatonal junto a la arquitectura religiosa exenta.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48026','mirador','Mirador de las Cuevas de Baltzola / Jentilzubi','Colosal e imponente arco de piedra natural kárstico en un cañón colgado habitado por leyendas. Nota: 9.2/10. Cómo llegar: Senda montañosa peatonal balizada que parte del barrio rural de Indusi hacia las cuevas.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48027','mirador','Alto de Nevers / Santa Lucía','Vista de la traza monumental de la villa ducal con la impresionante cresta del Alluitz cerrando el fondo. Nota: 8.9/10. Cómo llegar: Camino cementado del barrio alto de Santa Lucía, mirador acondicionado con bancos rústicos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48028','mirador','Mirador de la Ermita de Talako / Natxitua','Espectacular atalaya colgada al borde del acantilado sobre la angosta desembocadura fluvial del puerto. Nota: 9.2/10. Cómo llegar: Sendero de pescadores que sube desde el muelle este hacia la plataforma herbácea de la ermita.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47006','mirador','Mirador de la Plaza del Autobús / Cabo Ogoño','Vista vertiginosa del pueblo colgado en cascada escalonada sobre el puerto pesquero y el mar abierto. Nota: 9.7/10. Cómo llegar: Plaza alta del casco urbano (zona de la plataforma giratoria del bus), barandilla metálica de seguridad.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48032','mirador','Necrópolis de Argiñeta','Paisaje místico medieval de tumbas de piedra arenisca rodeado de encinas centenarias bajo los riscos calcáreos. Nota: 8.8/10. Cómo llegar: Barrio de Zenita, desvío señalizado desde el conjunto monumental urbano de la villa.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48902','mirador','Mirador del Monte San Bernabé','Perspectiva aérea del curso navegable de la ría de Bilbao, astilleros históricos y el valle de Asúa. Nota: 7.6/10. Cómo llegar: Entorno recreativo de la Ermita de San Bernabé en Goierri, acceso por pistas asfaltadas locales.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48034','mirador','Alto de Urko','Vistas de la cuenca lineal urbana hiperencajada entre grandes laderas forestales de fuerte pendiente. Nota: 7.8/10. Cómo llegar: Senda de montaña que asciende hacia el vértice geodésico de Urko desde el límite con Éibar. Para desplegar el bloque definitivo de Vizcaya (Municipios F-Z) y culminar esta fase secuencial del Atlas de España, indícame SIGUE.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48906','mirador','Yacimiento Romano de Elejalde','Perspectiva histórica y arqueológica sobre la vega del río Oka y las marismas interiores de Urdaibai. Nota: 7.8/10. Cómo llegar: Colina de la Iglesia de San Martín de Tours, acceso peatonal señalizado.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48035','mirador','Alto de Gerekiz','Paisaje ondulado de campiña atlántica con campas ganaderas, plantaciones de coníferas y pequeños encinares. Nota: 7.6/10. Cómo llegar: Alto de la carretera BI-2121, en el límite con el término municipal de Morga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90671','mirador','Mirador del Monte Ganguren','Amplia panorámica de la cuenca del Ibaizabal, el Valle de Asúa y las cumbres interiores vizcaínas. Nota: 8.1/10. Cómo llegar: Área recreativa del Monte Ganguren, accesible por carretera asfaltada desde el núcleo urbano.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48037','mirador','Atalaya minera de Alta Galdames','Paisaje kárstico escarpado salpicado de antiguas explotaciones mineras de hierro, túneles y planos inclinados. Nota: 8.9/10. Cómo llegar: Vía Verde de Galdames, desvío peatonal hacia el centro de interpretación de Peñas Negras.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48038','mirador','Alto de la Ermita de San Pedro de Atxuri','Vista limpia del valle del río Butrón, caseríos dispersos y colinas forestales tradicionales. Nota: 7.7/10. Cómo llegar: Barrio de Fika, promontorio rural donde se asienta la ermita histórica.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90688','mirador','Mirador de San Miguel / Encina de Etxeita','Magnífico balcón sobre el Duranguesado presidido por las imponentes cumbres calizas del cresterío de Anboto. Nota: 8.7/10. Cómo llegar: Barrio de San Miguel, junto al ejemplar monumental de encina protegida de Etxeita.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90689','mirador','Mirador del Castillo de Butrón','Vista de cuento de hadas de la fortaleza neogótica rodeada de un frondoso parque de especies exóticas. Nota: 8.7/10. Cómo llegar: Carretera BI-634, entorno perimetral adaptado sobre el cauce del río Butrón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48041','mirador','Mirador de las Marismas / Urdaibai Bird Center','Espectacular observatorio sobre el corazón de la reserva de la biosfera, humedales, lagunas y avifauna. Nota: 9.3/10. Cómo llegar: Barrio de Orueta, andamiaje e infraestructuras integradas en el centro de investigación de aves.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90690','mirador','Alto de San Juan de Berbikiz','Paisaje encartado verde marcado por praderas empinadas, casonas solariegas e históricas ferrerías fluviales. Nota: 8.2/10. Cómo llegar: Carretera local de montaña que asciende hacia la ermita fronteriza con Okondo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48043','mirador','Mirador del Faro de Gorliz / Cabo Villano','Impresionantes acantilados verticales sobre el mar Cantábrico con dunas fosilizadas de alto valor ecológico. Nota: 9.3/10. Cómo llegar: Senda costera peatonal de Gorliz, pasarela de seguridad que conduce a las antiguas baterías de costa.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47008','mirador','Mirador de la Galea / Punta de San Ignacio','Espectacular panorámica de la entrada del Abra de Bilbao, acantilados de flysch y el histórico Puerto Viejo. Nota: 9.5/10. Cómo llegar: Paseo de La Galea, carril peatonal y ciclista acondicionado al borde de los cortados marinos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48045','mirador','Alto de San Lorenzo de Bermejillo','Vista aérea del Valle del Cadagua, el núcleo urbano de Sodupe y colinas de pinar y eucaliptal. Nota: 8.1/10. Cómo llegar: Camino rústico que parte del barrio de La Quadra hacia los perfiles de la sierra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47007','mirador','Mirador del Parque de los Pueblos de Europa','Perspectiva monumental y simbólica de la villa foral integrada con esculturas de Chillida y Moore. Nota: 8.5/10. Cómo llegar: Sector alto del parque urbano, junto a la Casa de Juntas y el Árbol de Gernika.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48049','mirador','Mirador de la Playa de Ogella','Paisaje costero virgen donde los pliegues del flysch negro se sumergen bajo las rompientes del océano. Nota: 8.7/10. Cómo llegar: Desvío de la carretera local BI-3238, apartadero equipado con mesas junto al acantilado.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48050','mirador','Alto del Monte Mugarra','Espectacular mole caliza que preside el Parque Natural de Urkiola, con buitreras en sus paredes verticales. Nota: 8.6/10. Cómo llegar: Senda de montaña que arranca desde el centro de la localidad hacia el collado de Leungane.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48051','mirador','Mirador del Calero','Vista del casco urbano de la villa histórica hiperencajada en un angosto valle calizo rodeado de peñas fluviales. Nota: 8.2/10. Cómo llegar: Senda de montaña que sube hacia las cuevas kársticas del entorno fronterizo con Cantabria.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48052','mirador','Alto del Cinturón de Hierro','Paisaje histórico con restos de búnkeres y trincheras de la Guerra Civil sobre el Valle de Asúa. Nota: 7.8/10. Cómo llegar: Senda de la Memoria, accesible desde la pista forestal del monte Gaztelumendi.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90692','mirador','Alto del Monte Unbe','Campiña verde de caseríos dispersos con vistas lejanas del perfil industrial del litoral vizcaíno. Nota: 7.7/10. Cómo llegar: Cima del puerto de Unbe (BI-2704), entorno forestal del santuario mariano local.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47009','mirador','Mirador del Campus de la UPV/ EHU','Panorámica del curso bajo de la ría de Bilbao, las grúas de los astilleros e infraestructuras metropolitanas. Nota: 7.5/10. Cómo llegar: Terraza superior de la Facultad de Bellas Artes, zona peatonal accesible de la universidad.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47010','mirador','Mirador del Monte Lumentza','Postal costera idílica del puerto marinero, la desembocadura del Lea y la Isla de San Nicolás. Nota: 9.7/10. Cómo llegar: Sendero empedrado escalonado que asciende desde el casco histórico detrás de la basílica.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48055','mirador','Alto de Aramotz','Paisaje kárstico que asoma al nudo fluvial del Ibaizabal y el Arratia con extensas industrias de cemento. Nota: 7.6/10. Cómo llegar: Pista ganadera que arranca desde el barrio de Elizalde hacia el macizo calcáreo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48081','mirador','Alto de Garaioltza','Vista limpia del valle del Txorierri, viñedos de txakoli y las instalaciones deportivas locales. Nota: 7.6/10. Cómo llegar: Camino rústico vecinal que sube hacia los caseríos de la zona alta del norte.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48058','mirador','Alto del Puerto de Trabakua','Paso de montaña caracterizado por un paisaje atlántico cerrado de pinos, helechos y brumas matinales. Nota: 8.0/10. Cómo llegar: Carretera BI-633, apartadero acondicionado con zona de descanso forestal.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48059','mirador','Mirador de Urkuleta / Falda del Alluitz','Vertiginosa rampa caliza de montaña a los pies del desfiladero de Atxarte, un santuario de la escalada vasca. Nota: 9.1/10. Cómo llegar: Carretera BI-623, apartadero señalizado junto a las canteras de mármol negro tradicionales.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48061','mirador','Alto de Jata','Vistas de la cuenca baja de Plentzia y el mar Cantábrico desde un cordal forestal densamente poblado. Nota: 7.8/10. Cómo llegar: Pista rústica forestal que corona el repetidor del monte Jata, desvío desde el núcleo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48062','mirador','Mirador del Alto de Albiz','Vista panorámica sobre el encajonamiento forestal del valle de Oka e hitos rurales de Urdaibai alto. Nota: 8.2/10. Cómo llegar: Barrio de Albiz, explanada de la Iglesia de Santa María con bancos y paneles rústicos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90954','mirador','Mirador de la Playa de Karraspio','Vistas sobre el arenal atlántico, las olas rompientes de la barra y el perfil urbano portuario vecino. Nota: 8.7/10. Cómo llegar: Carretera BI-4238, cornisa de madera acondicionada con barandillas sobre la playa.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90693','mirador','Alto de Mesterika','Lomas agrícolas y ganaderas atlánticas bien conservadas jalonadas por caseríos solariegos de piedra. Nota: 7.6/10. Cómo llegar: Camino rústico cementado que conecta el ayuntamiento con los barrios altos del este.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48066','mirador','Alto de Gerekiz / Camino de Santiago','Vistas de dehesas forestales e históricos senderos jacobeos que cruzan el interior vizcaíno. Nota: 7.9/10. Cómo llegar: Parada en el alto de la carretera BI-2713, junto a la Ermita de San Esteban.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47011','mirador','Mirador de la Ermita de Santa Catalina','Atalaya privilegiada sobre la ola izquierda más famosa de Europa, la Isla de Ízaro y la barra de arenas. Nota: 9.8/10. Cómo llegar: Península de Santa Catalina, recinto ajardinado y accesible sobre los acantilados marinos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48069','mirador','Mirador de Torrebillela','Paisaje urbano e histórico integrado de la llanura agrícola mungiesa en torno a la casa torre medieval. Nota: 8.0/10. Cómo llegar: Parque urbano central, accesos peatonales pavimentados adaptados.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90056','mirador','Castillo de Muñatones / Marismas de Pobeña','Interesante contraste entre la fortaleza banderiza bajomedieval, el estuario fluvial y la gran refinería. Nota: 8.5/10. Cómo llegar: Vía Verde del Piquillo, paseo costero peatonal acondicionado sobre la marisma.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48909','mirador','Alto del Castro de Arrola','Impresionante atalaya arqueológica prerromana con vistas de 360 grados sobre los valles de Urdaibai. Nota: 8.6/10. Cómo llegar: Senda de montaña balizada desde el núcleo de Nabarniz hacia la cumbre fortificada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47012','mirador','Mirador de la Virgen de Antigua','Espectacular vista aérea del puerto pesquero, los puentes de Calatrava y la playa de Arrigorri. Nota: 9.4/10. Cómo llegar: Carretera del monte, explanada del santuario elevado con antepechos hacia el mar.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90261','mirador','Macizo de Itxina / Ojo de Atxular','Imponente e impenetrable laberinto kárstico calizo rodeado de misterios y hayedos en el Gorbea. Nota: 9.4/10. Cómo llegar: Senda montañosa empinada que parte del aparcamiento de Pagomakurre hacia la muralla de piedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48083','mirador','Alto de Peñas Negras','Mirador del paisaje minero de repoblación con vistas de la zona minera baja y el Abra vizcaíno. Nota: 7.8/10. Cómo llegar: Centro de Interpretación Ambiental de Peñas Negras, pistas de grava señalizadas.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90694','mirador','Mirador de Urkiola Sur / Embalse de Urrunaga','Paisaje alpino de alta montaña, hayedos trasmochos y aguas continentales compartidas con Álava. Nota: 8.6/10. Cómo llegar: Camino forestal del sur, saliendo del casco monumental herreriano hacia los pantanos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90057','mirador','Mirador de la Ría de Plentzia / Ribera','Precioso estuario de arenas blancas ocupado por embarcaciones de recreo bajo colinas boscosas. Nota: 9.1/10. Cómo llegar: Paseo marítimo de la cornisa este, rampa de madera adaptada peatonal.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48078','mirador','Mirador del Puente Bizkaia / Rialto','Vista monumental del primer puente transbordador metálico del mundo Patrimonio de la Humanidad. Nota: 9.3/10. Cómo llegar: Paseo de la Canilla, muelle urbano frente a la estructura de la barquilla colgante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90058','mirador','Mirador del Monte Serantes','El centinela cónico del Abra regala la panorámica total del puerto de Bilbao, la costa y el mar. Nota: 9.1/10. Cómo llegar: Cima del Serantes, torre de vigilancia militar, acceso peatonal por pistas de grava desde el núcleo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48084','mirador','Alto de la Benedicta','Impresionante paisaje de arqueología industrial con los restos de los Altos Hornos sobre la ría. Nota: 7.5/10. Cómo llegar: Paseo de la Benedicta, cornisa de la calle Rivas, barandilla de seguridad de hierro.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90955','mirador','Alto del Valle de Asúa','Vista de la llanura industrial y el corredor de pistas aéreas del cercano aeropuerto de Loiu. Nota: 7.4/10. Cómo llegar: Camino rural que asciende hacia el límite con el monte Artxanda.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90956','mirador','Mirador de la Playa de Atxabiribil','Espectaculares acantilados de flysch vertical azotados por el oleaje, paraíso del surf y parapente. Nota: 9.4/10. Cómo llegar: Cornisa superior de los acantilados, plataforma de madera vallada junto a los accesos a la playa.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48086','mirador','Horno Minero de El Alisal','Paisaje cultural forestal con impresionantes caleros y hornos de calcinación de mineral de hierro. Nota: 8.2/10. Cómo llegar: Vía Verde de las Encartaciones, área recreativa de El Alisal, paneles informativos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90059','mirador','Mirador de la Isla de Txatxarramendi','Precioso jardín botánico insular histórico con un espeso encinar cantábrico rodeado de aguas turquesas. Nota: 9.2/10. Cómo llegar: Pasarela peatonal de madera que comunica el parque urbano continental con el islote.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48087','mirador','Alto de la Ermita de San Roque','Entorno rural encartado de pastos y frondosas bajo las moles calizas del Parque Natural de Armañón. Nota: 8.4/10. Cómo llegar: Carretera de montaña del barrio de Pando, explanada verde acondicionada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48088','mirador','Senda del río Zubizola','Espectacular bosque de ribera y hayedos centenarios en el linde provincial más alto de Vizcaya. Nota: 8.6/10. Cómo llegar: Inicio de la ruta montañosa hacia el Gorbea desde el casco de piedra urbana.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48089','mirador','Peñas de Santa Marina','Crestas rocosas de arenisca muy frecuentadas para la escalada con vistas a los valles costeros. Nota: 7.8/10. Cómo llegar: Sendero rústico que asciende desde el polideportivo hacia el entorno de la ermita alta.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48080','mirador','Funicular de La Reineta / Barrio de Larreineta','Vista singular del pueblo minero elevado, lagos surgidos de antiguas cortas y el Gran Bilbao. Nota: 9.0/10. Cómo llegar: Estación superior del histórico funicular de La Reineta, mirador y pasarelas de madera.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50003','mirador','Mirador del Parque Natural del Gorbea','Vistas del espectacular hayedo y praderas alpinas de montaña desde el casco histórico palaciego. Nota: 8.9/10. Cómo llegar: Centro de Interpretación del Parque de Areatza, punto de salida de las rutas balizadas.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90691','mirador','Alto de Motxotegi','Perspectiva del Valle de Arratia, industrias locales de transformación y cordales de montaña forestal. Nota: 7.8/10. Cómo llegar: Pista forestal transitable a pie que comunica el núcleo de Igorre con las cumbres del sur.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48097','mirador','Alto de Arkotxa','Mirador sobre el encajonamiento industrial del Nervión y relieves forestales del cinturón metropolitano. Nota: 7.5/10. Cómo llegar: Zona alta del barrio de Arkotxa, rampa de tierra estabilizada junto a los pinares.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48096','mirador','Mirador del Longar / Ermita de San Pedro Zariquete','Entorno místico medieval de viñedos de txakoli de las Encartaciones y valles de repoblación boscosa. Nota: 8.3/10. Cómo llegar: Ruta Jacobea del Interior, desvío señalizado hacia el paraje rural del santuario.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90027','mirador','Acantilados de Bolao','Impresionante postal costera donde las ruinas de un viejo molino de mareas desafían al mar Cantábrico sobre estratos rocosos. Nota: 8.7/10. Cómo llegar: Paraje de Bolao en Cóbreces, acceso peatonal desde el camino rural que costea las praderas.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90243','mirador','Mirador de la Bien Aparecida','Atalaya mística que domina el encajonado valle fluvial del río Asón, rodeada de encinares y prados ganaderos. Nota: 8.4/10. Cómo llegar: Explanada del Santuario de la Bien Aparecida, subida asfaltada desde la carretera general.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90244','mirador','Alto de la Espina','Geografía de media montaña con amplias panorámicas sobre el valle de Iguña y divisorias cubiertas de helechos. Nota: 7.8/10. Cómo llegar: Collado fronterizo con Corvera de Toranzo, accesible por pista forestal ganadera.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90245','mirador','Alto de San Vicente de León','Aldea colgada de piedra que regala una vista limpia sobre el curso medio del río Besaya y bosques de repoblación. Nota: 8.1/10. Cómo llegar: Entorno inmediato de la iglesia románica del pueblo alto de San Vicente.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90635','mirador','Mirador del Molino de Jado','Vista de las marismas de Santoña y Joyel con canales sinuosos habitados por bandadas de aves acuáticas migratorias. Nota: 8.4/10. Cómo llegar: Parque regional de las marismas, pasarela de madera junto al molino de mareas restaurado.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90028','mirador','Mirador del Monte Cincho','Increíble perspectiva de 360 grados sobre el cabo de Ajo, la ría de Castellanos y la llanura costera caliza. Nota: 9.3/10. Cómo llegar: Senda del Monte Cincho en Isla, torreta mirador de madera sobre la cumbre boscosa encinar.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90636','mirador','Mirador del Puerto de Alisas','Vertiginoso anfiteatro kárstico de caliza gris que domina el nacimiento del Asón bajo densas nieblas atlánticas. Nota: 9.4/10. Cómo llegar: Cima del puerto de montaña CA-261, apartadero acondicionado con pretiles de piedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90030','mirador','Mirador de las Marismas de Black','Paisaje industrial recuperado compuesto por humedales y antiguas rías de carga mineral con avifauna integrada. Nota: 7.6/10. Cómo llegar: Red de senderos ecológicos de la marisma artificial, accesos peatonales urbanos pavimentados.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90246','mirador','Balcón de la Calzada Romana','Perspectiva histórica de los grandes losados de piedra romanos que bajan por el desfiladero boscoso del Bisueña. Nota: 8.5/10. Cómo llegar: Inicio de la ruta histórica empedrada, desvío peatonal balizado desde Pie de Concha.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90029','mirador','Mirador del Cabo de Ajo','El extremo más septentrional de Cantabria con acantilados salvajes desgarrados y las luces de un faro vanguardista. Nota: 9.2/10. Cómo llegar: Fin de la carretera local del cabo, andamiaje y vallas de seguridad de madera al borde del cortado marino.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39012','mirador','Mirador del Bosque de Secuoyas','Paisaje forestal de gigantescos troncos rojizos exóticos que configuran una atmósfera umbría única. Nota: 8.9/10. Cómo llegar: Carretera CA-135, pasarelas de madera elevadas e integradas perimetralmente entre el arbolado protegido.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39013','mirador','Mirador de Santa Eulalia','Impresionante vista del macizo de los Picos de Europa alzándose sobre valles profundos calcáreos y viñedos. Nota: 9.1/10. Cómo llegar: Pueblo alto de Torices, sendero tradicional que sube hacia los prados superiores.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39014','mirador','Mirador de la Cardosa','Monumento nacional del paisaje forestal sobre el robledal y hayedo del Saja, hábitat del ciervo y el oso. Nota: 9.3/10. Cómo llegar: Puerto de Palombera (CA-280), apartadero de piedra con la icónica escultura metálica del ciervo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39015','mirador','Mirador del Cable / Fuente Dé','Sobrecogedor balcón suspendido en el vacío a más de 1.800 metros sobre el colosal circo glaciar calizo de Áliva. Nota: 9.9/10. Cómo llegar: Estación superior del teleférico de Fuente Dé, rejilla de hierro volada al borde del precipicio.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39016','mirador','Alto de la Cueva de El Pendo','Entorno kárstico e histórico encajonado en un frondoso encinar cantábrico que guarda el santuario rupestre. Nota: 7.8/10. Cómo llegar: Barrio de Escobedo, sendero peatonal descendente hacia la boca monumental de la cavidad.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39027','mirador','Alto de Cervatos','Vistas del altiplano campurriano y de la espectacular colegiata románica con su erótica iconografía medieval. Nota: 8.2/10. Cómo llegar: Promontorio del cementerio rural de Cervatos, acceso peatonal directo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39017','mirador','Mirador de la Península de La Lastra','Paisaje de aguas continentales infinitas correspondientes al Embalse del Ebro con aves acuáticas y pastos ganaderos. Nota: 8.9/10. Cómo llegar: Centro de Ornitología de La Lastra, senda verde de madera adaptada al borde del agua.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39018','mirador','Torreón de los Manrique / Camino Real','Perspectiva histórica de la villa bajomedieval amurallada cruzada por el cauce del río Besaya. Nota: 8.3/10. Cómo llegar: Eje central de la villa de piedra de Cartes, mirador urbano empedrado accesible.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39019','mirador','Balcón de la Colegiata de Santa Cruz','Entorno idílico de campiña atlántica rodeado de verdes vegas fluviales irrigadas por el río Pas. Nota: 8.0/10. Cómo llegar: Explanada del templo monumental románico en Socobio, acceso directo pavimentado.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39020','mirador','Atalaya del Faro y Santa María','Postal monumental colosal de la iglesia gótica, el castillo-faro y el puente medieval azotados por las olas. Nota: 9.5/10. Cómo llegar: Recinto fortificado de la punta de los marineros, paseos y miradores de piedra vallados.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39021','mirador','Alto del Puerto de San Cipriano','Paisaje forestal y ganadero atlántico con vistas al desfiladero del Besaya y praderas empinadas de helechal. Nota: 8.1/10. Cómo llegar: Campas de San Cipriano, carretera local de montaña que asciende desde Villayuso.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39022','mirador','Mirador del Desfiladero de La Hermida / Santa Catalina','Vertiginosa vista de pájaro sobre el cañón calizo más largo de España, con paredes verticales de 600 metros. Nota: 9.8/10. Cómo llegar: Senda del monte Hozarco desde Cicera, espectacular estructura de madera colgada al abismo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39023','mirador','Balcón de la Marisma de Colindres','Vista de los viaductos y las rías saladas que configuran el estuario del Asón poblado de patos y garzas. Nota: 7.8/10. Cómo llegar: Paseo marítimo bidegorri de Colindres, pasarela metálica sobre el humedal limítrofe.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39024','mirador','Mirador del Palacio de Sobrellano / Capricho de Gaudí','Increíble perspectiva monumental de la universidad pontificia y joyas del modernismo entre praderas inglesas. Nota: 9.6/10. Cómo llegar: Parque de la colina de Sobrellano, paseos urbanizados adaptados accesibles con bancos de piedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39026','mirador','Mirador del Parque de Alceda','Paisaje botánico histórico a las orillas del Pas con árboles centenarios exóticos y aguas termales limpias. Nota: 8.1/10. Cómo llegar: Eje central del bosque periurbano de Alceda, caminos adaptados de grava compactada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39028','mirador','Alto de la Fuente de Aguanaz','Nacimiento cárstico rodeado de vegetación exuberante y praderas llanas que alimentan el curso fluvial. Nota: 7.8/10. Cómo llegar: Paraje de la Fuente de Aguanaz, sendero adaptado peatonal desde el núcleo urbano.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39029','mirador','Mirador de la Marisma de Joyel / Montehano','Vista limpia del ecosistema de marismas protegidas y el histórico convento franciscano de Montehano. Nota: 8.4/10. Cómo llegar: Pista que bordea la falda del monte Montehano, con pasarelas sobre la lámina de agua marea.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39030','mirador','Alto del Embalse de El Juncal','Espejo de agua de alta montaña encajonado entre perfiles escarpados de brezales y repoblaciones de coníferas. Nota: 8.2/10. Cómo llegar: Pista forestal que asciende desde el barrio de El Puente hacia el macizo montañoso.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39031','mirador','Alto de la Cruz de Beranga','Lomas suaves cubiertas de praderas ganaderas atlánticas con amplias panorámicas de la autovía del Cantábrico. Nota: 7.5/10. Cómo llegar: Camino rústico vecinal que sube hacia los depósitos de agua desde Beranga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39032','mirador','Mirador de la Fuente del Chivo / Alto Campoo','Espectacular balcón de alta montaña a más de 2.000 metros con vistas colosales hacia el Valle de Liébana. Nota: 9.6/10. Cómo llegar: Fin de la carretera de la estación de esquí de Alto Campoo, mirador con barandillas metálicas.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39033','mirador','Mirador del Valle del Nansa / Camijanes','Perspectiva del cauce encajonado e indómito del río Nansa flanqueado por densos bosques atlánticos autóctonos. Nota: 8.5/10. Cómo llegar: Carretera CA-181, apartadero acondicionado con paneles explicativos del relieve fluvial.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39034','mirador','Alto del Puerto de Ozalba','Paisaje abrupto calcáreo de media montaña con laderas de fuerte pendiente tapizadas de helechales verdes. Nota: 8.6/10. Cómo llegar: Cota máxima de la carretera CA-282, parada obligatoria en la zona de descanso forestal.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39035','mirador','Mirador de la Atalaya / Fuerte del Rastrillar','Impresionante postal de la Salvé (la mayor playa de Cantabria), la ría de Treto y el casco histórico medieval. Nota: 9.5/10. Cómo llegar: Subida peatonal empedrada desde la Puebla Vieja hacia las ruinas militares de la Atalaya.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39036','mirador','Mirador del Valle de Liendo / San Julián','Singular valle cerrado o poljé calcáreo que muere de forma abrupta en acantilados salvajes sobre el mar Cantábrico. Nota: 8.9/10. Cómo llegar: Pista rústica que parte de Hazas hacia la Ermita de San Julián y la playa recóndita.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39037','mirador','Mirador de las Tetas de Liérganes / Busampiro','Icónicas cumbres gemelas calizas que vigilan el casco histórico de piedra y el curso del río Miera. Nota: 9.1/10. Cómo llegar: Pista rústica de fuerte pendiente que sube al monte Busampiro desde las antiguas escuelas.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39038','mirador','Balcón de la Ría de Limpias','Vista del tramo final mareal del río Asón rodeado de espesos encinares cantábricos de ladera caliza. Nota: 8.1/10. Cómo llegar: Paseo fluvial urbano de Limpias, zona acondicionada con barandillas y bancos de madera.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39039','mirador','Mirador del Puerto del Escudo','Impresionante cambio geográfico de fuerte pendiente hacia la meseta castellana rodeado de densas nieblas orográficas. Nota: 8.6/10. Cómo llegar: Carretera nacional N-623, cima del puerto, apartadero junto al monumento militar histórico.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39040','mirador','Mirador de Pedreña / Bahía de Santander','Perspectiva de la lámina de agua de la bahía, los campos de golf costeros y el skyline de Santander capital. Nota: 8.0/10. Cómo llegar: Paseo de la cornisa marina de Pedreña, acceso peatonal directo adaptado.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39041','mirador','Alto de Villanueva de la Peña','Vista panorámica del valle bajo del Saja, campas de pasto ganadero y los montes forestales del Ibio. Nota: 8.1/10. Cómo llegar: Camino vecinal de cemento que sube hacia los prados altos desde Villanueva.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39045','mirador','Mirador del Karst de Miera / San Roque','Paisaje desolado e impresionante de lanchas de caliza gris talladas por el agua con cabañas pasiegas tradicionales. Nota: 8.9/10. Cómo llegar: Carretera local de montaña que asciende hacia los barrios altos desde la cavidad de Sopeña.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39044','mirador','Mirador de los Acantilados de Cuchía','Preciosas vistas de la desembocadura de la ría de San Martín de la Arena y dunas playeras costeras. Nota: 8.6/10. Cómo llegar: Extremo norte del aparcamiento de la playa de Marzán, mirador de madera vallado.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39046','mirador','Mirador de Helguera / Calzada Romana','Vista del valle del Besaya profunda, viaductos modernos de ingeniería y parajes rurales forestales. Nota: 8.2/10. Cómo llegar: Sendero señalizado que parte de Helguera hacia los restos empedrados históricos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39047','mirador','Mirador del Paseo de la Costa / Trengandín','Impresionante paisaje de rocas afiladas kársticas que emergen de la arena y el agua cristalina atlántica. Nota: 9.3/10. Cómo llegar: Sendero costero de Noja, pasarela de madera perimetral perfectamente adaptada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39048','mirador','Mirador de Cabárceno Sur','Paisaje kárstico de agujas de roca arcillosa rojiza surgidas de una antigua explotación minera de hierro abierta. Nota: 8.4/10. Cómo llegar: Carretera CA-142, desvío señalizado hacia los accesos superiores del parque de la naturaleza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39049','mirador','Mirador del Santa Catalina','Espectacular y vertiginoso balcón colgado sobre el abismo del Desfiladero de La Hermida, con el río Asón a los pies. Nota: 9.9/10. Cómo llegar: Monte Hozarco, pista forestal desde Piñeres, pasarela metálica volada sobre el vacío de 600 metros.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39050','mirador','Alto del Puerto de Piedrasluengas','Impresionante panorámica forestal de hayedos maduros protegidos bajo la mole caliza de Peña Labra. Nota: 8.8/10. Cómo llegar: Cima del puerto de montaña CA-184, estructura con pasarela de madera integrada perimetralmente.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39051','mirador','Alto del Calzada del Besaya','Perspectiva forestal de robles del valle medio con vistas al trazado del antiguo ferrocarril de Alar. Nota: 7.8/10. Cómo llegar: Camino tradicional empedrado que arranca del núcleo urbano hacia las lomas forestales.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39052','mirador','Mirador de las Dunas de Liencres / La Picota','Espectacular nudo hidrográfico de la ría del Pas moliendo el pinar, el arenal salvaje y mar abierto. Nota: 9.6/10. Cómo llegar: Cima del monte de la Picota, acceso a pie por pista de grava desde Boo de Piélagos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39053','mirador','Mirador de la Cruz de Cabezuela','Vistas del valle recóndito ganadero de Polaciones rodeado de cumbres alpinas nevadas del macizo. Nota: 8.9/10. Cómo llegar: Carretera de montaña CA-281, límite comarcal, apartadero acondicionado con barandillas.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39054','mirador','Alto de Requejada / Ría del Saja','Paisaje industrial y fluvial del tramo bajo del río con vistas a los muelles comerciales de carga de mineral. Nota: 7.5/10. Cómo llegar: Zona alta del barrio de Requejada, rampa de tierra estabilizada junto a los eucaliptales.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39055','mirador','Torre del Infantado / Mirador de la Villa','Vista de la capital lebaniega amurallada en la confluencia de los ríos Quiviesa y Deva, bajo Picos de Europa. Nota: 9.3/10. Cómo llegar: Azotea almenada de la fortaleza gótica del centro del casco urbano histórico.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39056','mirador','Mirador del Monte Castillo','Cono kárstico perfecto que alberga santuarios de arte paleolítico con vistas al cauce medio del río Pas. Nota: 9.0/10. Cómo llegar: Carretera de acceso a las cuevas prehistóricas, apartadero acondicionado a media ladera. Para desplegar el bloque definitivo de Cantabria (Municipios R-Z) y culminar esta fase secuencial del Atlas de España, indícame SIGUE.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39057','mirador','Mirador de Covalanas / Eco-parque','Espectaculares paredes verticales calizas del desfiladero del río Calera, con vistas al valle colgado que cobija arte paleolítico milenario. Nota: 9.1/10. Cómo llegar: Subida por la carretera de la cueva de Covalanas, apartadero volado en la roca con valla metálica.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39058','mirador','Mirador de la Cueva del Valle / Parque del Paleolítico','Entorno kárstico e histórico sobre el nacimiento del río Silencio, rodeado de praderas y densos encinares de gran pendiente. Nota: 8.3/10. Cómo llegar: Senda rústica peatonal que arranca desde el barrio de El Valle hasta la colosal boca de la cavidad.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39059','mirador','Mirador de los Cañones del Ebro / Parque del Cupido','Perspectiva de la capital campurriana, el nudo ferroviario histórico y el nacimiento del caudal fluvial hacia el valle bajo. Nota: 8.0/10. Cómo llegar: Zona alta del Parque de Cupido, acceso urbano pavimentado mediante rampas y escaleras.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39060','mirador','Alto de la Garita de Villapresente','Vista limpia de las vegas ganaderas bajas del río Saja, plantaciones forestales tradicionales y laberintos de coníferas. Nota: 7.8/10. Cómo llegar: Camino rústico vecinal de tierra que asciende hacia las lomas desde el barrio de Villapresente.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39061','mirador','Mirador de los Acantilados de Loredo / El Chiqui','Impresionante panorámica del Abra de Santander, la Isla de Mouro y la enorme ola de la playa salvaje de Somo. Nota: 9.2/10. Cómo llegar: Senda costera peatonal superior, plataforma con bancos de madera al borde del cortado marino de Loredo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39062','mirador','Alto de la Cueva de La Garma','Paisaje ondulado de campiña atlántica ganadera con lomas calizas densas que resguardan el yacimiento arqueológico. Nota: 7.7/10. Cómo llegar: Camino rural que parte de Omoño hacia los terrenos altos y dehesas forestales del norte.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39063','mirador','Mirador de la Cueva de El Soplao','Extraordinarias vistas de los Picos de Europa y la Sierra de Peña Sagra desde un antiguo territorio minero de altura. Nota: 9.6/10. Cómo llegar: Explanada del aparcamiento exterior de la cueva del Soplao (Celis), miradores de piedra con barandillas.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39068','mirador','Mirador de la Ermita de la Virgen de los Remedios','Preciosa postal costera tradicional sobre acantilados erosionados bajos que mueren en calas de cantos rodados. Nota: 8.8/10. Cómo llegar: Paraje rústico de Liandres, explanada de hierba del santuario con bancos mirando al mar Cantábrico.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39066','mirador','Mirador de la Fuentona de Ruente','Espectacular surgencia cárstica intermitente de aguas cristalinas bajo un puente románico de piedra y robledales maduros. Nota: 9.0/10. Cómo llegar: Interior del parque natural municipal, paseos adaptados planos de grava compactada y pasarelas.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39081','mirador','Alto de Llerana','Paisaje ganadero tradicional pasiego con praderas inclinadas delimitadas por muretes de piedra viva e hilos de agua. Nota: 7.8/10. Cómo llegar: Carretera local de montaña que une Saro con Llerana, apartadero junto a los pastizales altos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39069','mirador','Alto de la Torre de Pero Niño','Perspectiva histórica de la fortaleza medieval y los valles agrícolas encajonados de la cuenca media del Besaya. Nota: 8.2/10. Cómo llegar: Barrio de Llano, entorno del museo fortificado, acceso pavimentado peatonal con barandillas.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39070','mirador','Alto del Embalse de Alsa','Paisaje de alta montaña con un espejo de agua encajado entre cordales cubiertos de helechales y brezales densos. Nota: 8.3/10. Cómo llegar: Pista rústica forestal asfaltada que sube hacia los saltos hidráulicos desde el núcleo de Aguayo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39071','mirador','Alto del Puerto de la Matanela','Paisaje virgen pasiego caracterizado por valles empinados cubiertos de brañas ganaderas y cabañas de piedra tradicionales. Nota: 8.6/10. Cómo llegar: Cota superior de la carretera CA-633, límite provincial con Burgos, zona de descanso forestal.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39072','mirador','Mirador del Puerto de Lunada','Impresionante y colosal circo glaciar encajonado en terrazas de caliza y hierba, el corazón salvaje del territorio pasiego. Nota: 9.4/10. Cómo llegar: Cima del puerto de Lunada (CA-643), apartadero rústico con barandillas de madera colgado sobre el abismo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39080','mirador','Mirador del Castillo del Rey / Alta Villa','Espectacular estampa marina sobre las marismas de la ría de la Maza, arenales salvajes y Picos de Europa nevados al fondo. Nota: 9.7/10. Cómo llegar: Murallas del casco viejo fortificado, mirador empedrado accesible junto a la iglesia de Santa María.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39073','mirador','Mirador de la Playa de San Juan de la Canal','Preciosa costa recortada por islotes rocosos calcáreos y canales de agua turquesa batidos por el mar Cantábrico. Nota: 8.5/10. Cómo llegar: Extremo occidental de la playa, sendero perimetral superior acondicionado con barandillas de seguridad.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39074','mirador','Mirador de la Senda del Pisueña','Paisaje fluvial de ribera maduro rodeado de fértiles praderías ganaderas y valles de campiña tradicional. Nota: 8.0/10. Cómo llegar: Eje central de la senda verde peatonal, accesos acondicionados desde la localidad de Sarón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39075','mirador','Mirador de Cabo Mayor / Faro de Santander','Majestuosos acantilados verticales de caliza blanca azotados por el océano, con vistas completas de la bahía e islas costeras. Nota: 9.8/10. Cómo llegar: Extremo norte urbano, paseo de Cabo Mayor, plataforma adaptada perimetral junto a las sendas del faro.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39076','mirador','Mirador de los Yacimientos de Altamira','Paisaje cultural e histórico excepcional sobre las colinas verdes calizas que cobijan la capilla sixtina del paleolítico. Nota: 9.4/10. Cómo llegar: Entorno inmediato del museo de Altamira, senderos peatonales de grava integrados en la dehesa.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39077','mirador','Alto de Lantueno','Vistas del valle profundo del río Besaya en su tramo alto, rodeado de pinares de repoblación y viaductos de ingeniería. Nota: 7.8/10. Cómo llegar: Camino rústico agrícola que asciende desde el núcleo de Lantueno hacia las divisorias forestales.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39078','mirador','Alto de la Ermita del Soto','Vista de la vega aluvial del cauce medio del río Pas flanqueada por lomas boscosas atlánticas bien conservadas. Nota: 8.1/10. Cómo llegar: Explanada arbolada del santuario rural, desvío señalizado desde la carretera general del valle.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39079','mirador','Mirador del Fuerte de San Carlos / Monte Buciero','Impresionante postal de la bahía, la playa de Berria y las marismas protegidas desde un peñón calizo militarizado. Nota: 9.6/10. Cómo llegar: Senda perimetral del Monte Buciero, acceso a pie por el camino empedrado de los fuertes históricos del este.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39082','mirador','Alto de la Ermita de la Virgen de Valvanuz','Hermoso entorno de dehesa de robles y fresnos centenarios bajo las laderas escarpadas de los montes pasiegos altos. Nota: 8.5/10. Cómo llegar: Recinto arbolado del santuario, pistas peatonales llanas integradas en el valle del Pisueña.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39083','mirador','Mirador de los Cañones del Asón / Nacimiento','Espectacular y vertical balcón colgado al vacío frente a la colosal cascada de cola de caballo que da origen al río Asón. Nota: 9.8/10. Cómo llegar: Carretera del puerto de Asón (CA-241), plataforma de piedra y metal volada de forma vertiginosa sobre el cañón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39084','mirador','Alto de Fuente las Varas','Vistas de valles verdes ganaderos tradicionales y divisorias de media montaña cubiertas de helechales espesos. Nota: 7.7/10. Cómo llegar: Cima del puerto de Fuente las Varas (CA-266), apartadero rústico acondicionado de grava.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39085','mirador','Mirador de la Punta de El Torco / Playa de Los Locos','Impresionantes acantilados de arenisca sobre el paraíso surfero salvaje de Los Locos, con vistas a las islas de Suances. Nota: 9.4/10. Cómo llegar: Cornisa perimetral junto a las ruinas de las defensas costeras, acceso peatonal urbano pavimentado y vallado.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39087','mirador','Mirador del Monte Dobra','Atalaya kárstica industrial que domina la cuenca industrial del Saja-Besaya, canteras de caliza y dehesas altas. Nota: 8.2/10. Cómo llegar: Senda montañosa que asciende desde el barrio de Viérnoles hacia el vértice geodésico superior.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39088','mirador','Mirador de la Senda de Urdón / Balcón del Desfiladero','Vertiginosa e imponente panorámica de alta montaña sobre el cañón calizo del río Urdón, rodeada de simas y majadas. Nota: 9.8/10. Cómo llegar: Extremo del casco urbano colgado de Tresviso, inicio del histórico sendero de zig-zag escarpado de montaña.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39090','mirador','Alto de las Minas de Udías','Paisaje de arqueología industrial minera recuperada, con antiguas bocaminas integradas en praderas ganaderas verdes. Nota: 7.8/10. Cómo llegar: Paraje de los viejos cargaderos de mineral, pistas rústicas señalizadas desde Pumalverde.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39095','mirador','Mirador de la Tina Menor / Pechón','Maravilloso estuario del río Nansa encajonado entre acantilados cubiertos de pinos que mueren en playas de arena blanca. Nota: 9.4/10. Cómo llegar: Carretera local de Pechón (CA-380), cornisa acondicionada con barandilla rústica de madera sobre la ría.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39091','mirador','Mirador del Monte Corona / Ermita de San Antonio','Espectacular bosque de secuoyas, castaños y robles con amplias panorámicas limpias de las playas de Oyambre y Comillas. Nota: 9.0/10. Cómo llegar: Pista forestal transitable que sube al corazón del Monte Corona desde Caviedes.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39092','mirador','Ruta de los Menhires / Alto de Mataporquera','Paisaje megalítico prehistórico excepcional integrado en un altiplano de cultivos cerealistas y cerros testigos calizos. Nota: 8.3/10. Cómo llegar: Senda balizada de los menhires, accesos peatonales directos de grava desde Mataporquera.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39093','mirador','Alto de Sotillo','Vistas de valles recónditos forestales del sur de Cantabria poblados por extensos melojares y dehesas ganaderas. Nota: 8.2/10. Cómo llegar: Camino rústico vecinal que parte de Sotillo hacia los cordales de media montaña del linde burgalés.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39094','mirador','Mirador de Valcabado / Cañón del Ebro','Impresionante balcón natural forestal colgado sobre el gran cañón de caliza y hayas excavado por el río Ebro. Nota: 9.3/10. Cómo llegar: Carretera local del extremo sur de la comarca, infraestructura de madera integrada al borde del precipicio.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39096','mirador','Mirador del Puerto de San Glorio / Llesba','Sobrecogedora e imponente panorámica alpina del macizo central de Picos de Europa, presidida por el monumento al oso. Nota: 9.3/10. Cómo llegar: Cima del puerto de San Glorio (N-621), pista forestal asfaltada hacia el collado alto de Llesba.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39097','mirador','Mirador del Puerto de Las Estacas de Trueba','Un mar escalonado e infinito de praderas verdes y cabañas pasiegas de piedra encajonadas en laderas glaciares. Nota: 9.3/10. Cómo llegar: Carretera de montaña CA-631, apartaderos con antepechos de piedra caliza bordeando el cauce alto del río Pas.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39098','mirador','Palacio de Soñanes / Alto de Santibáñez','Paisaje barroco monumental integrado con dehesas ganaderas tradicionales de campiña y setos arbolados atlánticos. Nota: 8.4/10. Cómo llegar: Camino vecinal de cemento que sube hacia los prados superiores del flanco oeste del municipio.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39099','mirador','Mirador del Monte Pico Castillo','Vistas del sector norte del Parque de la Naturaleza de Cabárceno, lagos de mina y la cercana bahía de Santander. Nota: 8.2/10. Cómo llegar: Senda de montaña que arranca desde el núcleo de Liaño hacia las cumbres kársticas locales.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39100','mirador','Alto de Escobedo','Paisaje ondulado ganadero del Pisueña con parches de bosque mixto tradicional y horizontes limpios de montaña bajo. Nota: 7.8/10. Cómo llegar: Camino rústico de labranza que comunica el cementerio con las fincas de la zona alta.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39102','mirador','Alto de Carasa / Ría de Treto','Vista aérea limpia del estuario fluvial del Asón, sus canales salados de marisma y cultivos hortícolas tradicionales. Nota: 8.3/10. Cómo llegar: Carretera local del barrio alto de Carasa, apartadero rústico acondicionado con barandillas. He completado el 100% de los municipios de la Comunidad de Madrid, Álava, Guipúzcoa, Vizcaya y Cantabria con rigor geográfico.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90704','mirador','Alto de San Bartolomé','Vista limpia del valle de Ega, campos de cereal y encinares salpicados. Nota: 7.2/10. Cómo llegar: Camino agrícola que asciende desde el casco urbano hacia la ermita homónima.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90705','mirador','Mirador de San Miguel / Museo de Estelas','El municipio más alto de Navarra ofrece una panorámica limpia de los Pirineos orientales. Nota: 8.5/10. Cómo llegar: Cementerio de la localidad, pasarela de madera integrada sobre el roquedo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90706','mirador','Alto de la Peña de San Miguel','Vista encajonada del valle de Aézcoa con densas masas de hayas y prados alpinos. Nota: 8.0/10. Cómo llegar: Senda montañosa que arranca desde el núcleo urbano hacia la cresta caliza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90707','mirador','Alto de Muniáin','Perspectiva mediterránea de viñedos y campos de secano bajo el perfil de la Sierra de Lokiz. Nota: 7.4/10. Cómo llegar: Camino rústico que comunica el núcleo de Aberin con las lomas de Muniáin.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90708','mirador','Torre del Homenaje del Castillo','Impresionante vista de la Ribera de Navarra, campos de olivos y el paisaje estepario de las Bardenas. Nota: 7.8/10. Cómo llegar: Centro urbano, acceso público acondicionado a la parte almenada de la fortaleza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90709','mirador','Alto de la Sierra de Perdón','Vista aérea de la Cuenca de Pamplona y el mar de molinos de viento del cordal montañoso. Nota: 7.3/10. Cómo llegar: Pista forestal que conecta el pueblo con el Monumento al Peregrino de la cima.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90710','mirador','Mirador del Santuario de Codés','Espectacular anfiteatro rocoso calizo con laderas cubiertas de encinares y quejigos centenarios. Nota: 8.6/10. Cómo llegar: Explanada del santuario, fin de la carretera local de montaña NA-7211.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90711','mirador','Mirador de la Bizkaia','Vista del trazado medieval de la villa colgada sobre lomas de olivares y cultivos secanos. Nota: 8.2/10. Cómo llegar: Zona alta del casco histórico, mirador pavimentado con paneles interpretativos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90712','mirador','Mirador de Larrión / Sierra de Lokiz','Imponentes paredes calizas verticales que flanquean el curso limpio del río Amescoa. Nota: 8.4/10. Cómo llegar: Carretera NA-710, apartadero acondicionado junto al cauce fluvial de Larrión.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90713','mirador','Alto de la Ermita del Calvario','Horizonte despejado sobre la llanura cerealista de Tierra Estella, ideal para astroturismo. Nota: 7.2/10. Cómo llegar: Paseo arbolado que asciende desde el cementerio municipal hacia los monolitos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90714','mirador','Mirador del Nacedero del Urederra / Baquedano','Espectacular paisaje de aguas turquesas cristalinas y saltos de agua bajo un hayedo virgen. Nota: 9.4/10. Cómo llegar: Senda del Urederra, acceso peatonal controlado desde el aparcamiento de Baquedano.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90715','mirador','Vía Verde del Vasco-Navarro','Perspectiva del valle de Lana y lomas forestales tradicionales de encina a las orillas del Ega. Nota: 7.6/10. Cómo llegar: Antigua estación de tren, tramo peatonal acondicionado con pasarelas de madera.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90716','mirador','Balcón del río Ega','Cortados arcillosos sobre el meandro plano del río rodeado de huertas de regadío y viñedos. Nota: 7.5/10. Cómo llegar: Cornisa del casco urbano superior, mirador equipado con barandillas metálicas.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90717','mirador','Falda del Monte Ezcaba','Vista panorámica limpia de la Cuenca de Pamplona y los perfiles urbanos metropolitanos. Nota: 7.8/10. Cómo llegar: Senda perimetral del fuerte de San Cristóbal, acceso peatonal desde el núcleo viejo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90718','mirador','Alto de Olagüe','Paisaje atlántico de praderas verdes e idílicos caseríos de piedra entre robledales densos. Nota: 8.2/10. Cómo llegar: Camino rústico vecinal que sube hacia los prados superiores del flanco oriental.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90719','mirador','Mirador de la Ermita de San Martin','Mar de viñedos de Valdizarbe rodeado de lomas suaves cerealistas con horizontes limpios. Nota: 7.6/10. Cómo llegar: Cerro de San Martín, subida peatonal señalizada desde la plaza de la villa.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33003','mirador','Mirador de la Presa de Itoiz','Impresionante panorámica sobre la lámina de agua encajada entre las crestas calcáreas de la foz. Nota: 8.4/10. Cómo llegar: Carretera NA-1720, apartadero elevado y acondicionado junto al muro de contención.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31020','mirador','Mirador de las Malloas / Azkarate','Impresionantes e imponentes paredes verticales calizas de la Sierra de Aralar sobre prados verdes. Nota: 9.6/10. Cómo llegar: Núcleo rural de Azkarate, cornisa natural acondicionada con barandilla de madera.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90720','mirador','Alto de Meaka','Paisaje virgen de las Cinco Villas con espesos bosques caducifolios, helechales y brumas místicas. Nota: 9.0/10. Cómo llegar: Carretera de montaña a San Juan de Luz, apartadero rural junto a los pastizales altos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31023','mirador','Castillo de Irulegi','Atalaya arqueológica histórica sobre la cuenca con paneles del hallazgo de la "Mano de Irulegi". Nota: 8.5/10. Cómo llegar: Cima del monte Irulegi, acceso a pie por sendero balizado desde el pueblo de Laquidáin.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31024','mirador','Balcón de Arano / Plaza Mayor','El único pueblo que ve el mar ofrece vistas limpias del Urumea y los cordales costeros guipuzcoanos. Nota: 8.7/10. Cómo llegar: Cornisa de piedra del ayuntamiento elevado, barandilla de hierro sobre el precipicio forestal.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31026','mirador','Balcón de San Juan del Ramo','Ruinas del convento franciscano integradas en lomas de olivares y cultivos de vid tradicionales. Nota: 7.4/10. Cómo llegar: Camino rústico que parte del cementerio hacia las cotas superiores del oeste.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31027','mirador','Prado de San Juan / Falda de San Donato','Vista de la imponente silueta del monte Beriáin alzándose sobre el corredor de la Sakana. Nota: 8.5/10. Cómo llegar: Senda rústica que parte del casco viejo hacia las dehesas ganaderas del sur.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31029','mirador','Alto del Arlanzón','5.1/10. Perspectiva sobre la llanura aluvial del río Ausín y la campiña periurbana del sur de Burgos capital. Cómo llegar: Borde este de los terrenos agrícolas elevados, pista que conecta con Villariezo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31030','mirador','Mirador de San Bartolomé de Montejurra','Ladera meridional del macizo de Montejurra con amplios llanos cerealistas hacia la Ribera Alta. Nota: 7.2/10. Cómo llegar: Pista de ascenso a Montejurra por la vertiente sur desde el término de Arellano/Orroniz. 📍 Provincia: Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31031','mirador','Alto de Gorriti','Paisaje de alta montaña atlántica con campas ganaderas cubiertas de helechales y densos pinares. Nota: 8.4/10. Cómo llegar: Autovía A-15, salida del núcleo hacia las pistas forestales perimetrales.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31032','mirador','Balcón de las Bardenas / Castildetierra','Espectacular e icónica chimenea de hadas arcillosa, símbolo del paisaje desértico de la reserva. Nota: 9.4/10. Cómo llegar: Pista central del polígono de tiro de las Bardenas Reales, apartadero señalizado vallado.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31033','mirador','Mirador de los Hórreos de Aézcoa','Paisaje rural pirenaico que conserva la mayor densidad de hórreos tradicionales de piedra y madera. Nota: 8.2/10. Cómo llegar: Eje central del entramado urbano, ruta peatonal balizada accesible.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90722','mirador','Puente Colgante sobre el río Irati','Vista del curso truchero encajonado en un frondoso bosque de ribera caducifolio de alisos y hayas. Nota: 8.5/10. Cómo llegar: Senda del Irati, tramo peatonal equipado con pasarelas de madera y cables de acero.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31035','mirador','Loma de la Ermita de San Juan','Lomas suaves de cereal secano con horizontes limpios idóneos para observación astronómica. Nota: 7.1/10. Cómo llegar: Pequeña elevación al sur del núcleo, accesible por caminos de labranza transitables.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31036','mirador','Mirador del Olivar de Mendía','Mar de olivos centenarios de variedad Royuela integrados en un relieve ondulado mediterráneo. Nota: 8.0/10. Cómo llegar: Entorno inmediato del trujal histórico, acceso pavimentado desde el centro urbano.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31037','mirador','Balcón del río Araquil','Vegas aluviales planas del corredor de la Sakana con perfiles lejanos nítidos de las sierras calizas. Nota: 7.8/10. Cómo llegar: Vereda de tierra acondicionada paralela al cauce fluvial en su linde norte.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31038','mirador','El Cerco de Artajona','Impresionante fortificación medieval fortificada con torres almenadas dominando la llanura cerealista. Nota: 9.2/10. Cómo llegar: Explanada de la IglesiaFortaleza de San Saturnino, acceso pavimentado urbano.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31039','mirador','Alto de la Cruz / Viñedos de garnacha','Paisaje escarpado tradicional de viñas viejas que mueren en los bosques mediterráneos de encina. Nota: 7.6/10. Cómo llegar: Camino rústico que asciende hacia la cima del cerro desde la travesía de la villa.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31042','mirador','Mirador de la Peña de Azagra','Imponente y vertical risco de yesos sobre el cauce ancho y los sotos fluviales del río Ebro. Nota: 8.2/10. Cómo llegar: Cima del cabezo de la peña, sendero escalonado equipado con barandillas desde el pueblo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31043','mirador','Monasterio de San Jorge / Alto de Codés','Vistas del cenobio románico integrado en un denso barranco forestal de encina mediterránea. Nota: 7.9/10. Cómo llegar: Zona alta del núcleo urbano, mirador acondicionado con bancos rústicos de piedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90723','mirador','Alto de Bakaiku / Urbasa Norte','Impresionante rampa forestal de hayas que sube vertical hacia la plataforma caliza de la sierra. Nota: 8.2/10. Cómo llegar: Senda montañosa del GR-282, tramo superior de las dehesas ganaderas.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31045','mirador','Alto de la Valdorba','Paisaje ondulado de transición con campos de cereal y pequeños parches de quejigal autóctono. Nota: 7.6/10. Cómo llegar: Camino rústico cementado que sube hacia los depósitos de agua desde la travesía.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31046','mirador','Loma de San Jorge','Sutil elevación arcillosa rodeada de campos agrícolas de secano con horizontes limpios abiertos. Nota: 7.1/10. Cómo llegar: Camino de labranza occidental que arranca desde las últimas calles de la villa.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31047','mirador','Alto de la Ermita de la Virgen del Poyo','Atalaya histórica sobre el trazado jacobeo, viñedos de Tierra Estella y horizontes riojanos. Nota: 7.8/10. Cómo llegar: Carretera nacional N-111, desvío señalizado hacia el promontorio del santuario.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31048','mirador','Mirador de la Balsa de Agua Salada','Pequeño oasis húmedo lagunar rodeado de cultivos hortícolas tradicionales en el secano ribero. Nota: 7.0/10. Cómo llegar: Sendero perimetral de la balsa, pasarela de madera y observatorio de aves adaptado.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90724','mirador','Bosque de Orgi / Orokieta','Espectacular e idílico robledal húmedo milenario de llanura, un ecosistema relicto único conservado. Nota: 9.2/10. Cómo llegar: Área natural protegida de Orgi, pasarelas y senderos de madera totalmente accesibles.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31050','mirador','Mirador de Ziga / Balcón de Baztan','La postal perfecta del valle: caseríos de piedra, prados verdes infinitos y lomas de helechos. Nota: 9.8/10. Cómo llegar: Carretera local NA-2540, apartadero monumental con murete de piedra y paneles técnicos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31137','mirador','Mirador de los Embalses de Leurtza','Paisaje alpino de aguas tranquilas rodeado de densos hayedos y helechales en un valle escondido. Nota: 8.8/10. Cómo llegar: Área natural recreativa de Leurtza, senda circular adaptada con plataformas de madera.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31051','mirador','Balcón del río Cidacos','Terrazas fluviales y vegas agrícolas cerealistas bajas con perfiles lejanos de las Bardenas. Nota: 7.3/10. Cómo llegar: Explanada trasera del Palacio de Beire, zona urbana de la cornisa accesible.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31052','mirador','Balcón del Puente de Piedra / Arga','Vista del curso encajonado del río Arga, huertas tradicionales de ribera y bosques mediterráneos. Nota: 7.6/10. Cómo llegar: Margen este del cauce, siguiendo la vereda natural del sendero fluvial del Arga.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31053','mirador','Las Eretas / Yacimiento de la Edad del Hierro','Paisaje arqueológico fluvial fortificado sobre el meandro del Arga con huertas tradicionales. Nota: 7.7/10. Cómo llegar: Interior de la zona museística al aire libre, mirador sobre la muralla reconstruida.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31905','mirador','Mirador de la Balsa de Odiandrea','Humedal artificial surgido de la minería de potasas recuperado con avifauna acuática integrada. Nota: 7.4/10. Cómo llegar: Paseo circular de la balsa, accesos peatonales urbanos de grava compactada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31903','mirador','Mirador del Casco Viejo / Palacio','Vista de pájaro del crecimiento metropolitano lineal desde el núcleo tradicional de piedra serrano. Nota: 7.8/10. Cómo llegar: Plaza alta de la iglesia de Berriozar zar, rampa peatonal adaptada con antepecho.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31054','mirador','Parque Natural del Señorío de Bertiz','Impresionante e idílico bosque atlántico de hayas y robles con un jardín histórico de especies exóticas. Nota: 9.4/10. Cómo llegar: Oieregi, Centro de Visitantes, sendero accesible de madera "Aizcolei" hacia el palacio alto.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31055','mirador','Senda de los Balnearios / Río Araxes','Cañón fluvial angosto calizo cubierto por un espeso e impenetrable encinar cantábrico húmedo. Nota: 8.4/10. Cómo llegar: Paseo del arroyo Araxes, tramo peatonal acondicionado con puentes de piedra rústicos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31056','mirador','Torre de Olcoz','Fortaleza bajomedieval exenta que domina el nudo de comunicaciones de la ruta jacobea y valles. Nota: 8.0/10. Cómo llegar: Explanada de la torre palaciega, acceso pavimentado con paneles explicativos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31057','mirador','Balcón de la Huerta del Ebro','Parcelas agrícolas tradicionales de regadío y sotos de ribera del curso bajo del río Ebro. Nota: 7.3/10. Cómo llegar: Camino de sirga del canal Imperial de Aragón, tramo perimetral adaptado peatonal.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09003','mirador','Mirador del Castillo de Burgos','7.8/10. Impresionante e icónica vista aérea de la Catedral gótica de Santa María, el entramado urbano medieval y el cauce verde del río Arlanzón. Cómo llegar: Plataforma fortificada del Castillo de Burgos, acceso peatonal urbano o vía carretera de subida al cerro. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31062','mirador','Alto de San Juan / El Monasterio','Perspectiva de la vega del Ebro, cultivos de regadío y campos secanos con la iglesia románica de la Orden del Hospital como eje. Nota: 7.4/10. Cómo llegar: Explanada de la Iglesia de San Juan, parte alta de la cornisa urbana.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31063','mirador','Ermita de la Virgen de Lapoblación','Entorno idílico de media montaña rodeado por el hayedo del león dormido con vistas de 360 grados a los valles de la cuenca. Nota: 8.5/10. Cómo llegar: Cima de la peña de Lapoblación, sendero de fuerte pendiente desde el casco de piedra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31064','mirador','Mirador del Soto de la Mejana','Vista del ecosistema fluvial del río Ebro, huertas tradicionales riberas y parches de bosque de ribera maduro. Nota: 7.6/10. Cómo llegar: Camino rústico de sirga, entrada directa por el dique perimetral agrícola de la villa.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31065','mirador','Alto de la Ermita del Cristo / Caparroso Viejo','Impresionante vista del cañón arcilloso y yesífero del río Aragón y el despoblado medieval sobre el risco. Nota: 8.5/10. Cómo llegar: Cima del cerro fortificado, acceso por carretera asfaltada sinuosa desde la variante NA-128.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31066','mirador','Balcón de la Cuesta / Cortados del Ega','Espectacular tajo vertical de yesos y arcillas de más de 50 metros colgado directo sobre el cauce plano del Ega. Nota: 8.3/10. Cómo llegar: Calle de la Cuesta, paseo perimetral urbano adaptado con barandillas y paneles explicativos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31067','mirador','Mirador de la Oliva / Bardenas Norte','Transición geomorfológica radical entre la vega del Aragón presedida por el monasterio cisterciense y el desierto. Nota: 9.3/10. Cómo llegar: Carretera del monasterio de la Oliva, pistas rústicas hacia el rincón del Vedado de Eguaras.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31068','mirador','Parque del Romero / Ermita de la Virgen','Atalaya privilegiada que domina la cuenca del Queiles, olivares centenarios y el perfil del Moncayo de fondo. Nota: 8.4/10. Cómo llegar: Explanada de la ermita del Romero, acceso peatonal por la galería columnada barroca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31069','mirador','Mirador de San Zoilo','Magnífica panorámica del cauce encajonado del río Aragón y los extensos pinares del monte de San Zoilo. Nota: 8.4/10. Cómo llegar: Entorno inmediato de la ermita gótica de San Zoilo, subida por la pista asfaltada local.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31070','mirador','Mirador del Museo Ferroviario y Puente de Hierro','Perspectiva del nudo ferroviario histórico industrial y el curso ancho del Ebro antes de entrar en La Rioja. Nota: 7.2/10. Cómo llegar: Terraza superior del museo de Castejón, zona urbana accesible con andamios de visión.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31071','mirador','Alto del Castillo / Senda de Salvatierra','Vista de lomas forestales prepirenaicas de fuerte pendiente cubiertas de quejigos lindando con Aragón. Nota: 8.0/10. Cómo llegar: Pista rústica de montaña que parte de las últimas eras del pueblo hacia el cordal este.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31072','mirador','Mirador de las Riberas del Alhama','Paisaje agrícola mediterráneo de viñas, olivares y sotos de ribera del arroyo rodeados de yesares. Nota: 7.6/10. Cómo llegar: Paseo de los Chopos, zona recreativa adaptada peatonal junto al cauce fluvial.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31077','mirador','Mirador de la Estanca de Corella','Humedal e histórica balsa de riego barroca rodeada de campos de cultivo con rica avifauna acuática. Nota: 7.8/10. Cómo llegar: Sendero perimetral lagunar, observatorio de madera adaptado para observación de aves.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31078','mirador','Torreón del Castillo de los Miranda / Parque','Vista aérea del jardín botánico histórico del siglo XIX y las llanuras agrícolas del confín sur navarro. Nota: 7.8/10. Cómo llegar: Centro del casco urbano, acceso público guiado a las almenas de la fortaleza mudéjar.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31079','mirador','Loma de la Ermita de Villanueva','Campos ondulados de cereal secano con horizontes limpios idóneos para observación astronómica. Nota: 7.2/10. Cómo llegar: Camino rústico de labranza que comunica el cementerio con las dehesas agrícolas altas.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31080','mirador','Mirador del Palacio de la Vega','Espectacular palacio neogótico rodeado de viñedos y olivares bajo la vertiente sur de Montejurra. Nota: 8.4/10. Cómo llegar: Paraje del palacio, acceso señalizado por la carretera local desde el centro de la villa.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31081','mirador','Alto de Jauregia','Entorno rural atlántico virgen con la icónica casa-torre medieval de madera entre densos hayedos y prados. Nota: 8.5/10. Cómo llegar: Barrio de Gaztelu, sendero tradicional que bordea el arroyo y la fortificación.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31087','mirador','Mirador del Manantial Salino','Entorno húmedo del río Ezcurra que alberga las aguas termales más saladas de Europa entre prados. Nota: 8.1/10. Cómo llegar: Jardines del balneario histórico, paseos de grava compactada adaptados peatonales.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31090','mirador','Alto de Iruinarri','Paisaje abrupto de montaña con campas ganaderas cubiertas de helechales y estaciones megalíticas (crómlechs). Nota: 8.4/10. Cómo llegar: Senda montañosa del GR-121, tramo superior de las dehesas del linde comarcal.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31091','mirador','Alto de Lizarraga / Urbasa Oriental','Impresionante pared caliza vertical con vistas colosales de la Sakana y el monte Beriáin. Nota: 9.1/10. Cómo llegar: Cima del puerto de Lizarraga (NA-120), apartadero rústico con barandillas metálicas de seguridad.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31092','mirador','Alto del Puerto de Erro','Histórico paso boscoso pirenaico del Camino de Santiago rodeado de inmensos hayedos silvestres y pastos. Nota: 9.1/10. Cómo llegar: Cota máxima de la carretera NA-135, zona de descanso acondicionada con paneles del relieve.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31094','mirador','Ciudad Romana de Santa Criz','Yacimiento arqueológico excepcional sobre un cerro testigo que domina las llanuras agrícolas de la Val de Aibar. Nota: 8.2/10. Cómo llegar: Cerro de Santa Criz, desvío señalizado desde la carretera NA-132, sendero peatonal adaptado.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31096','mirador','Alto de Codés / Espronceda','Lomas de secano y encinar mediterráneo de transición con horizontes abiertos hacia Tierra Estella. Nota: 7.6/10. Cómo llegar: Camino rústico agrícola occidental del cementerio municipal, transitable a pie.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33007','mirador','Mirador de la Basílica del Puy / Los Castillos','Impresionante panorámica sobre la ciudad monumental del Ega, iglesias románicas y palacios medievales. Nota: 9.5/10. Cómo llegar: Explanada de la Basílica de Nuestra Señora del Puy, acceso pavimentado urbano accesible con barandillas.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31098','mirador','Alto de Mezquíriz','Espectacular túnel arbolado de hayas centenarias en el trazado jacobeo que da paso a los valles interiores. Nota: 8.6/10. Cómo llegar: Puerto de Mezquíriz (NA-135), paraje del monumento a la Virgen de Roncesvalles, apartadero de grava.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31099','mirador','Alto de San Cristóbal','Lomas suaves con parches de encinar y matorral mediterráneo que abren horizontes hacia el valle de la Berrueza. Nota: 7.3/10. Cómo llegar: Camino rústico vecinal que sube hacia los prados superiores del flanco oeste.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90933','mirador','Ruta de los Dólmenes / Camping','Espectacular e idílico robledal y bosque mixto tradicional jalonado por estaciones megalíticas prehistóricas. Nota: 8.9/10. Cómo llegar: Senda de los Dólmenes, accesos peatonales señalizados desde el área natural del camping local.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31100','mirador','Alto de Urbia / Eulate','Paisaje ganadero tradicional de las Améscoas con impresionantes muros de piedra seca y hayedos. Nota: 8.4/10. Cómo llegar: Senda del GR-282, tramo superior de las dehesas forestales del norte de la villa.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31101','mirador','Alto de Oricáin / Monte Ezcaba','Vista del corredor encajonado del río Ulzama, canteras de caliza y parajes rurales forestales. Nota: 7.8/10. Cómo llegar: Camino de saca forestal que arranca detrás del polígono industrial hacia el cordal verde.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31103','mirador','Alto de Guetádar','Paisaje forestal de la Baja Montaña con dehesas de quejigo y encina salpicadas de campos de cereal. Nota: 7.8/10. Cómo llegar: Pista forestal que asciende desde el despoblado de Guetádar hacia el cordal superior.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31104','mirador','Mirador del Pilón / Cortados del Arga','Espectacular e imponente barranco arcilloso vertical famoso por el encierro de reses bravas por la ladera. Nota: 8.6/10. Cómo llegar: Senda del Pilón, camino de fuerte pendiente excavado en el risco norte de la localidad.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31105','mirador','Macizo de Roscas / Cueva de la Mora','Impresionantes agujas y formaciones calizas kársticas erosionadas sobre el valle del río Alhama. Nota: 8.6/10. Cómo llegar: Circuito rústico del macizo de Roscas, desvío peatonal señalizado desde los balnearios de Fitero.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31106','mirador','Bocal Real','Paisaje ilustrado del siglo XVIII donde nace el Canal Imperial de Aragón entre sotos de ribera del Ebro. Nota: 7.7/10. Cómo llegar: Poblado histórico del Bocal, paseos arbolados e infraestructuras hidráulicas accesibles peatonales.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31109','mirador','Alto de la Ermita de San Esteban / Esparza','Vista de la llanura agrícola meridional de la cuenca con horizontes limpios del monte Perdón. Nota: 7.8/10. Cómo llegar: Colina de San Esteban en Esparza de Galar, rampa de tierra estabilizada junto al santuario.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90935','mirador','Mirador de Zamariain','Impresionante y colosal losa de roca caliza exenta suspendida al vacío sobre el profundo cañón del río Irati. Nota: 9.1/10. Cómo llegar: Senda del monte Aribe desde Garaioa, estructura natural volada sin barandillas (máxima precaución).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31113','mirador','Alto del Puerto de Matamala / Roncal','Paisaje alpino pirenaico cubierto de densos pinares negros, simas kársticas e históricos senderos pastoriles. Nota: 8.8/10. Cómo llegar: Cota superior de la carretera local NA-176, apartadero junto a los pastizales alpinos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31114','mirador','Alto de la Ermita del Cristo de Cataláin','Hermoso entorno de campiña y campos cerealistas llanos dominado por la joya del románico rural de la Valdorba. Nota: 7.8/10. Cómo llegar: Desvío señalizado desde la carretera general NA-5100, área arbolada ajarditada.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31115','mirador','Mirador de la Corona / Valle de Aézcoa','Vista de pájaro sobre las dehesas forestales del Irati y las casas pirenaicas reconstruidas tras incendios históricos. Nota: 8.6/10. Cómo llegar: Senda del monte Corona, subida peatonal señalizada desde el centro escolar de la villa.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31116','mirador','Alto del Valle de Aguilar / Cantabria','Ladera boscosa calcárea de gran pendiente con densos encinares y quejigos lindando con Álava. Nota: 8.2/10. Cómo llegar: Carretera local de montaña NA-7230, apartadero junto a los campos agrícolas altos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31117','mirador','Mirador del Valle de Artikutza','Una de las selvas forestales más húmedas y vírgenes de la península, rodeada de hayas, carbajos e hilos de agua. Nota: 9.4/10. Cómo llegar: Finca de Artikutza (acceso regulado), sendero de la cascada de Erroiarri, pasarelas integradas de madera.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31118','mirador','Mirador de la Sierra de Andía / San Donato','Impresionante altiplano calizo de pastos alpinos ganaderos con vistas al colosal murallón del monte Beriáin. Nota: 8.8/10. Cómo llegar: Pista ganadera asfaltada que sube desde el núcleo de Goñi hacia los rasos superiores de la sierra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31121','mirador','Alto del Puerto de Guirguillano','Atalaya de media montaña caliza con amplias vistas hacia la Valdizarbe y campos cerealistas de secano llanos. Nota: 7.8/10. Cómo llegar: Cima del puerto de montaña NA-7040, apartadero de grava junto a los encinares autóctonos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31124','mirador','Alto del Monte Izaga','Espectacular pirámide calcárea que preside la comarca con vistas completas de los Pirineos y la cuenca. Nota: 8.5/10. Cómo llegar: Senda de montaña escarpada desde Ardanaz de Izagaizcoa hasta la ermita románica de la cumbre.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90936','mirador','Reserva Natural de San Juan Xar','El único bosque autóctono de carpe o abedulillo de la península inmerso en un místico desfiladero de aguas limpias. Nota: 9.0/10. Cómo llegar: Carretera local NA-4020, sendero peatonal botánico acondicionado con escaleras de piedra y barandillas.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31126','mirador','Vía Verde del Plazaola / Latasa','Paisaje forestal húmedo atlántico a las orillas del Larraun, surcado por los antiguos túneles del tren minero. Nota: 8.4/10. Cómo llegar: Antigua estación de Latasa, tramo peatonal ciclista adaptado con vallas de madera integradas.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31127','mirador','Balcón de la Sakana / Araquil','Vegas de inundación llanas agrícolas encajonadas bajo las imponentes escuelas rocosas de la sierra norte. Nota: 7.8/10. Cómo llegar: Vereda natural de tierra que discurre en paralelo al lecho fluvial del término municipal.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31129','mirador','Alto del Monte Mendaur','Mítica cumbre coronada por una ermita exenta con vistas colosales de Malerreka y la costa cantábrica lejana. Nota: 8.7/10. Cómo llegar: Senda montañosa empinada que parte del barrio rústico de Aurtiz hacia las crestas graníticas superiores.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31130','mirador','Alto de la Ermita de Nuestra Señora de Arranoitz','Atalaya privilegiada sobre la comarca de la Sakana y los bosques de robles de las laderas de Urbasa al sur. Nota: 8.0/10. Cómo llegar: Camino de montaña asfaltado que sube empinado desde el casco urbano hacia el promontorio arbolado.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31132','mirador','Alto de Guerguitiáin','Paisaje ondulado forestal de quejigos y pinares que resguarda la joya oculta del románico rural de la comarca. Nota: 8.3/10. Cómo llegar: Explanada de la Iglesia románica exenta de Guerguitiáin, pistas rústicas de tierra locales.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31134','mirador','Mirador del Puerto de Jaurrieta','Paisaje alpino de alta montaña ganadera con laderas cubiertas de extensos hayedos caducifolios limpios. Nota: 8.6/10. Cómo llegar: Travesía de la carretera NA-140, apartadero pavimentado con paneles explicativos del relieve.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31135','mirador','Balcón del Castillo de Javier','Vista del conjunto almenado de la fortaleza medieval cuna del patrón navarro, campos de olivos y el río Aragón. Nota: 9.1/10. Cómo llegar: Explanada de la basílica y murallas exteriores del castillo, zona monumental adaptada accesible.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90732','mirador','Alto de Guenduláin','Ruinas del palacio señorial inmersas en campos de trigo con amplias panorámicas de la Cuenca de Pamplona. Nota: 8.1/10. Cómo llegar: Pista rústica de tierra que parte de Cizur Menor siguiendo el trazado del Camino de Santiago.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31061','mirador','Alto de la Ruta Jacobea','Sutil loma arcillosa rodeada de campos de secano que muestra la llanura cerealista de la comarca. Nota: 7.0/10. Cómo llegar: Camino rústico de Santiago, desvío de labranza hacia las cotas del este.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90726','mirador','Mirador de las Palomeras de Etxalar','Histórica infraestructura de caza tradicional con redes entre collados de alta montaña y hayedos. Nota: 9.3/10. Cómo llegar: Paraje de Iarmendi, carretera local de montaña, mirador con paneles informativos del paso de aves.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31107','mirador','Mirador de Peñalen','Espectacular y vertical cortado de yesos de 100 metros donde confluyen de forma majestuosa los ríos Arga y Aragón. Nota: 8.6/10. Cómo llegar: Paraje de Peñalen, acceso por pista rústica de tierra estabilizada desde el cementerio municipal.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31904','mirador','Mirador de las Dos Hermanas / Erga','Impresionantes e imponentes agujas calizas verticales gemelas que configuran la puerta natural a la montaña navarra. Nota: 9.4/10. Cómo llegar: Senda de los Pescadores, pasarela peatonal al pie de los cortados, accesible desde el casco de la villa.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31136','mirador','Alto de Marcaláin','Amplia vista del valle de Juslapeña, rodeado de pastizales y pequeños núcleos de población de arquitectura tradicional pirenaica. Puntuación: 7.9/10. Cómo llegar: En el margen de la carretera NA-4100 a su paso por el punto más alto del puerto de montaña de la localidad. 📍 Provincia: Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90727','mirador','Balcón del Araquil / Senda de las Amescoas','Perspectiva limpia de la vega del río y los imponentes cortados calizos de la Sierra de Aralar. Nota: 8.4/10. Cómo llegar: Camino rústico que parte del polideportivo local hacia el margen norte del cauce.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31140','mirador','Alto de Miralda / Valle de Ultzama','Entorno idílico de prados húmedos y densos hayedos que enmarcan la cuna del mítico carnaval rural navarro. Nota: 8.5/10. Cómo llegar: Pista rústica forestal que asciende desde las eras del este hacia el cordal.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31141','mirador','Mirador de la León Dormido / Peña de Lapoblación','Impresionante e icónica silueta caliza vertical que regala una panorámica de 360 grados de la Rioja Alavesa y Navarra. Nota: 9.3/10. Cómo llegar: Senda de montaña señalizada que parte del Puerto de La Aldea (NA-7210) hasta la cumbre.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31142','mirador','Mirador del Castillo / El Palomar','Gran atalaya histórica sobre los cortados del río Arga que domina las inmensas llanuras cerealistas de la Zona Media. Nota: 8.4/10. Cómo llegar: Punto más elevado del entramado urbano de Larraga, plaza acondicionada con barandillas.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31143','mirador','Alto de Urbasa / Senda de las Limitaciones','Espectacular franja caliza kárstica rodeada de un denso hayedo trasmocho de cuento de hadas alpino. Nota: 8.8/10. Cómo llegar: Senda balizada desde el núcleo urbano que asciende de forma empinada al raso de la sierra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31144','mirador','Alto de San Miguel de Aralar','Impresionantes e imponentes vistas de toda la Sakana y los Pirineos desde el célebre santuario románico. Nota: 9.2/10. Cómo llegar: Carretera de montaña NA-7510, explanada del templo exento con antepecho de piedra de seguridad.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31145','mirador','Alto del Secano / Campos de la Vega','Lomas suaves de campos agrícolas de secano con horizontes completamente limpios, idóneo para astroturismo. Nota: 7.2/10. Cómo llegar: Camino rústico de labranza que comunica la cooperativa con los cerros del flanco norte.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31147','mirador','Mirador de la Sierra de Perdón','Vista aérea limpia de la ruta jacobea tradicional que cruza el municipio, con horizontes hacia la cuenca de Pamplona. Nota: 7.8/10. Cómo llegar: Desvío agrícola desde el Camino de Santiago, rampa de tierra estabilizada junto al cortaleña.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31148','mirador','Balcón de la Ermita de San Bartolomé','Perspectiva agraria mediterránea de viñas y olivos bajo la supervisión lejana de la Sierra de Lokiz. Nota: 7.4/10. Cómo llegar: Colina de San Bartolomé, acceso peatonal directo por pista de grava fina desde el núcleo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31149','mirador','Mirador del Valle de Leitzaran / Gorriti','Maravilloso paisaje atlántico de caseríos dispersos de piedra integrados en profundas selvas de hayas y prados verdes. Nota: 9.3/10. Cómo llegar: Pista rústica forestal cementada que asciende hacia el barrio alto de Erasote desde el núcleo urbano.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31151','mirador','Alto de Abaiz','Vista de campos de secano e históricos despoblados de piedra de la Baja Montaña rodeados de encinar. Nota: 7.8/10. Cómo llegar: Camino agrícola del este, siguiendo la pista que comunica Lerga con el término de Eslava.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31152','mirador','Balcón de la Villa / Risco del Ega','Impresionante pueblo colgado sobre una pared vertical caliza calada de yesos con vistas totales de la vega fluvial. Nota: 8.8/10. Cómo llegar: Paseo perimetral de las murallas del casco viejo, mirador acondicionado accesible con barandillas.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90728','mirador','Alto de Bianditz','Paisaje abrupto alpino de las Cinco Villas con prados de pasto, crómlechs prehistóricos y vistas al mar Cantábrico. Nota: 9.2/10. Cómo llegar: Carretera de montaña NA-4000, apartadero acondicionado con paneles explicativos del relieve.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31155','mirador','Mirador de la Foz de Lumbier / Villa Romana','Vista aérea del cañón calcáreo del río Irati y los restos arqueológicos de la explotación agrícola milenaria. Nota: 8.5/10. Cómo llegar: Vereda de tierra balizada del Camino de Santiago, acceso peatonal directo desde el núcleo urbano.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31157','mirador','El Risco de Lodosa / Cueva de los Moros','Paredes arcillosas perforadas por cuevas que custodian las ricas huertas tradicionales del pimiento del piquillo. Nota: 8.3/10. Cómo llegar: Cima del peñón calcáreo urbano, sendero empedrado equipado con barandillas desde la plaza mayor.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31159','mirador','Mirador del Puente del Diablo / Foz de Lumbier','Espectacular cañón calizo de paredes verticales de 150 metros habitado por la mayor colonia de buitres leonados. Nota: 9.6/10. Cómo llegar: Vía Verde del Irati, sendero de montaña colgado que conduce a las ruinas del puente monumental del acantilado.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31160','mirador','Alto de San Isidro / Montejurra norte','Vista de campos cerealistas y lomas de monte bajo mediterráneo bajo el imponente perfil de la montaña carlista. Nota: 8.0/10. Cómo llegar: Carretera local NA-7410, parada en el apartadero de hierba junto a los pinares de repoblación.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31161','mirador','Mirador de las Viñas de Mañeru','Ofrece una espléndida panorámica del Valle de Mañeru y las laderas cubiertas de viñedos tradicionales de Tierra Estella. Nota: 6.8/10. Cómo llegar: Situado junto al camino agrícola que asciende hacia el oeste desde el casco urbano, dominando la cuenca visual del Camino de Santiago. 📍 Provincia: Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31162','mirador','Mirador de la Ermita del Santo Cristo','Vista limpia del valle de Aguilar y los perfiles rocosos de la Sierra de Codés, ideal para la observación del paisaje calcáreo, con una puntuación específica de 7.2/10. Cómo llegar: Situado junto a la ermita en la zona más elevada que corona el pueblo. 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31163','mirador','Mirador de la Vega del Aragón y Foso del Castillo','Excelente perspectiva lineal que combina el baluarte monumental de Marcilla con la llanura aluvial del río Aragón, muy fotogénico al amanecer. Nota: 7.5/10. Cómo llegar: Situado en el paseo perimetral junto a las murallas fortificadas del propio castillo, accesible para todo público. 📍 Provincia: Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31164','mirador','Mirador de las Bardenas y el Río Aragón','Observatorio natural del contraste entre las tierras de regadío del río y el inicio de los relieves áridos de las Bardenas Reales, con una puntuación específica de 7.4/10. Cómo llegar: En los escarpes situados al este de la localidad, accesible por pistas agrícolas. 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31165','mirador','Mirador del Alto de la Barca','Espectaculares vistas sobre el meandro del río Ebro y las fértiles fincas de regadío características de la Ribera Alta. Nota: 7.2/10. Cómo llegar: Acceso por pista rural asfaltada desde el norte de la localidad, en el monte comunal que domina el curso fluvial. 📍 Provincia: Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31166','mirador','Mirador de la Ermita de Santa Coloma y la Encina Tres Patas','Impresionante vista de la Sierra de Lóquiz y el valle de La Berrueza, coronado por un árbol monumental milenario, con una puntuación específica de 8.5/10. Cómo llegar: Camino forestal señalizado que sube desde el núcleo urbano hacia la ermita de Santa Coloma. 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31167','mirador','Mirador de Andelos','Panorámica que combina el patrimonio arqueológico de la ciudad romana de Andelos con el curso serpenteante del río Arga. Nota: 7.6/10. Cómo llegar: Localizado en el propio recinto arqueológico de Andelos, al sur de la población, siguiendo la carretera local. 📍 Provincia: Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31168','mirador','Mirador del Valle de Allín y de la Trufa','Balcón natural sobre el somontano de la Sierra de Loquiz, rodeado de encinares compactos ideales para fotografía micológica y forestal. Nota: 7.3/10. Cómo llegar: Se ubica en los senderos forestales elevados que parten desde el Museo de la Trufa en dirección a la sierra. 📍 Provincia: Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31169','mirador','Mirador de la Confluencia AragónEbro','Punto de observación estratégico del encuentro de los dos grandes ríos navarros y su vegetación de ribera, con una puntuación específica de 7.3/10. Cómo llegar: Extremo sur del término municipal, accesible por el camino de la ermita del Patrocinio. Si lo desea, indíqueme si prefiere acelerar el ritmo del inventario agrupando más municipios por bloque, o si necesita detalles de infraestructuras específicas de alguno de estos puntos escaneados.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31170','mirador','Mirador de Santa María de Codés','Excelente balcón hacia el valle de La Berrueza con los bosques calcáreos de la sierra al fondo, obteniendo una nota de 7.2/10. Cómo llegar: Ubicado en la pista forestal ascendente que conecta el pueblo con las estribaciones de la sierra. 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31171','mirador','Mirador del Torreón del Reloj','Panorámica de 360 grados sobre el casco mudéjar del municipio y los meandros del río Arga, con un gran impacto monumental. Nota: 7.4/10. Cómo llegar: En el punto más alto del cerro del castillo, accesible a través de las escalinatas urbanas del casco histórico. 📍 Provincia: Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31173','mirador','Mirador del Castillo de Monteagudo','Ofrece vistas despejadas de la vega del río Queiles y el imponente perfil de la Sierra del Moncayo en el horizonte aragonés. Puntuación: 7.7/10. Cómo llegar: Terraza exterior peatonal situada en los accesos de la fortaleza palaciega de la villa. 📍 Provincia: Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31174','mirador','Mirador de San Andrés de Morentin','Ofrece una panorámica baja de los campos cerealistas de Tierra Estella y los relieves suaves de las cuencas meridionales. Nota: 6.9/10. Cómo llegar: Situado en el entorno inmediato de la Ermita de San Andrés, accesible a pie desde la zona alta del casco urbano. 📍 Provincia: Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31175','mirador','Mirador del Desfiladero de Congosto','Impresionantes paredes verticales calcáreas labradas por el río Odrón, ideal para la observación de aves rapaces y buitres leonados. Puntuación: 8.3/10. Cómo llegar: Acceso por el sendero peatonal que parte de la Ermita de la Magdalena hacia el estrecho rocoso. 📍 Provincia: Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31176','mirador','Mirador del Cabezo de la Horca','Vistas llanas e infinitas del paisaje vitivinícola de la Ribera y la imponente silueta azulada de la Sierra del Moncayo. Nota: 6.7/10. Cómo llegar: Pequeña elevación natural situada al suroeste del término municipal, rodeada de caminos rurales de grava. 📍 Provincia: Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31177','mirador','Mirador del Vía Verde del Ega','Bella estampa del curso del río Ega, los densos encinares colindantes y el corredor natural del antiguo ferrocarril. Nota: 7.2/10. Cómo llegar: Localizado en el talud del antiguo trazado ferroviario reconvertido, al paso por los límites urbanos occidentales. 📍 Provincia: Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31178','mirador','Mirador de Rada (Yacimiento Despoblado)','Extraordinaria perspectiva arqueológica e histórica sobre las ruinas de la villa medieval y el inmenso cauce del río Aragón. Nota: 7.4/10. Cómo llegar: Ubicado en el recinto amurallado del despoblado de Rada, accesible por pista de tierra señalizada desde la carretera NA-128. 📍 Provincia: Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31179','mirador','Mirador del Castillo de Murillo','Atalaya sobre los escarpes yesosos que caen hacia el río Aragón, idónea para observar el vuelo de grandes rapaces. Nota: 7.4/10. Cómo llegar: En el cerro donde se asientan los escasos restos de la antigua fortaleza medieval, accesible a pie desde la villa. 📍 Provincia: Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31180','mirador','Mirador del Camino de Santiago Eunate','Vista del llano de Valdizarbe que alberga el templo románico de Santa María de Eunate, un espacio con gran fotogenia mística, con una nota de 7.9/10. Cómo llegar: Alto de la pista de peregrinos que baja desde Uterga hacia el núcleo del valle. 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31182','mirador','Mirador de la Peña de Nazar','Balcón natural colgado sobre el valle de La Berrueza, protegido por los potentes muros calizos de la vertiente de Lóquiz. Nota: 7.9/10. Cómo llegar: Accesible a través de sendero señalizado que trepa desde la parte superior del pequeño pueblo hacia la peña. 📍 Provincia: Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31183','mirador','Mirador de la Ermita de Arnotegui','Excelente visual del encuentro de los ramales del Camino de Santiago (Somport y Roncesvalles) sobre el valle de Valdizarbe. Nota: 7.3/10. Cómo llegar: En lo alto del cerro homónimo donde se erige la ermita, accesible por pista forestal desde Obanos o Puente la Reina. 📍 Provincia: Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31184','mirador','Mirador de San Tirso (Valdega)','Vista de la vega agrícola del río Ega, idónea para observar los contrastes de los cultivos de secano de la comarca. Nota: 6.8/10. Cómo llegar: En el cordal de colinas suaves que cierra el término por el norte, accesible por caminos vecinales. 📍 Provincia: Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31186','mirador','Alto de Odieta','Perspectiva de los prados verdes y caseríos dispersos de las localidades que integran este tranquilo valle de transición, con una nota de 7.4/10. Cómo llegar: Puerto local de la carretera NA-4112, ideal para parada fotográfica. 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31188','mirador','Mirador de Olave / Olaiz','Balcón sobre el cauce alto del río Ultzama, encajonado entre laderas boscosas de gran valor ecológico y fotogénico. Nota: 7.2/10. Cómo llegar: Accesible desde la parte trasera de la iglesia de Olave, siguiendo el camino que remonta la ladera forestal. 📍 Provincia: Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31190','mirador','Mirador del Monte de Olejua','Sencilla visual orientada a los llanos cerealistas de la merindad de Estella, ideal para atardeceres despejados. Nota: 6.8/10. Cómo llegar: Cresta de la pequeña colina que resguarda el pueblo por su flanco norte, accesible por caminos de labranza. 📍 Provincia: Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33013','mirador','Mirador de las Torres del Palacio Real de Olite','Una de las vistas monumentales más emblemáticas de España, dominando los tejados góticos y viñedos de la Zona Media navarra, con una nota de 8.7/10. Cómo llegar: Torre de los Cuatro Vientos del Palacio Real, accesible mediante la entrada turística al monumento. 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31195','mirador','Mirador del nido de ametralladoras - Selva de Irati','Increíble perspectiva de la masa boscosa de la Selva de Irati y los relieves transfronterizos pirenaicos desde vestigios de la Línea P, con una nota de 8.6/10. Cómo llegar: Cerca de las ruinas de la Real Fábrica de Armas de Orbaitzeta, subida hacia el collado de Organbide. 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31196','mirador','Mirador del Río Irati','Balcón sobre las aguas cristalinas y bravas del Irati antes de encajonarse, rodeado de un entorno de hayedos maduros. Nota: 8.1/10. Cómo llegar: Situado junto al sendero local que costea el cauce del río, saliendo de la población hacia el norte. 📍 Provincia: Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31197','mirador','Mirador de la Valdorba Central','Ofrece vistas limpias sobre el paisaje en mosaico característico del valle, ideal para captar cielos nocturnos sin contaminación. Nota: 7.4/10. Cómo llegar: En el recinto superior de la iglesia románica del pueblo, con una plataforma de observación accesible. 📍 Provincia: Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90733','mirador','Mirador del Cerro de Orcoyen','Atalaya de carácter semiurbano que ofrece una visión nítida del flanco occidental de la Cuenca de Pamplona y el monte San Cristóbal. Nota: 6.7/10. Cómo llegar: Ubicado en el parque de la zona alta del municipio, perfectamente integrado en el entramado de paseos peatonales. 📍 Provincia: Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31187','mirador','Mirador del Puerto de Oiz','Paisaje dominado por los prados de montaña siempre verdes del Valle de Malerreka y el relieve accidentado del norte de Navarra. Nota: 7.6/10. Cómo llegar: En el margen superior de la pista de montaña que conecta Oiz con los pastizales altos divisorios. 📍 Provincia: Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33014','mirador','Mirador del Caballo Blanco (Baluarte del Redín)','Excepcional panorámica urbana e histórica de los ríos Arga y Sadar, los barrios del norte (Rochapea, Chantrea) y el emblemático Monte San Cristóbal. Nota: 8.6/10. Cómo llegar: Bastión del Redín, rincón medieval de las murallas accesibles desde la Catedral de Pamplona. 📍 Provincia: Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31203','mirador','Mirador del Castillo de Petilla','Excepcional panorámica del agreste e inhóspito paisaje prepirenaico que envuelve a este enclave navarro en territorio aragonés. Nota: 8.0/10. Cómo llegar: En la roca cimera donde se asentaba el antiguo castillo medieval, en la zona más elevada de la villa natal de Ramón y Cajal. 📍 Provincia: Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31204','mirador','Mirador de la Sierra de Codés Oriental','Perspectiva de las moles calizas de Codés desde el somontano, idónea para retratar el fuerte relieve geológico de la comarca. Nota: 7.2/10. Cómo llegar: En la parte más alta del caserío, al inicio de las pistas forestales agrícolas de Piedramillera. 📍 Provincia: Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31205','mirador','Mirador de la Laguna de Pitillas','Observatorio de aves de primer orden con amplias panorámicas sobre el carrizal de este humedal estepario de origen natural, con una nota de 7.9/10. Cómo llegar: Estación de observación del humedal, accesible desde la pista que arranca de la carretera NA-5330. 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33015','mirador','Mirador del Puente Románico de Puente la Reina','Vista icónica del puente de los peregrinos sobre el río Arga, una de las imágenes monumentales de mayor belleza arquitectónica de la ruta jacobea, con una nota de 8.4/10. Cómo llegar: Margen izquierda del río Arga, aguas abajo del monumental viaducto medieval. 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31207','mirador','Mirador de la Ermita de Santiago','Vista nítida de los relieves suaves de la Zona Media y las vías de comunicación que vertebran el centro de Navarra. Puntuación: 7.6/10. Cómo llegar: Coronando el monte sobre el que se asienta la Ermita de Santiago, al norte del término. 📍 Provincia: Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31208','mirador','Mirador del Canal de Tauste','Curiosa vista del trazado histórico de irrigación que contrasta la aridez de las terrazas superiores con el verdor de la huerta. Nota: 6.9/10. Cómo llegar: En los caminos de sirga sobreelevados que flanquean la infraestructura hidráulica al este del término. 📍 Provincia: Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31209','mirador','Mirador de la Foz de Arbayún (Arangoiti)','Impresionante grieta caliza de más de 300 metros de profundidad excavada por el río Salazar, donde planean los buitres leonados, con una nota de 8.4/10. Cómo llegar: Balcón de la Foz de Arbayún, situado en la carretera del puerto de Iso (NA-178). 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31212','mirador','Alto de la Sierra de Xavier','Relieves de la comarca de Sangüesa, pinares e idoneidad para observación de aves esteparias. Nota: 7.4/10. Cómo llegar: Coronando el cordal montañoso al este del municipio, accesible por pistas de aerogeneradores. 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31213','mirador','Mirador de las Mendiak de Saldías','Inmersión en los pastos de altura neblinosos del norte y los perfiles montañosos atlánticos de la cuenca del Bidasoa. Nota: 7.6/10. Cómo llegar: En los collados superiores del término, siguiendo los senderos tradicionales de montaña de Malerreka. 📍 Provincia: Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31215','mirador','Mirador de la Confluencia del Ega y el Ebro','Observatorio fluvial de la Ribera Alta, ideal para registrar el bosque de ribera y los sotos del gran río Ebro. Nota: 7.2/10. Cómo llegar: En el paseo fluvial habilitado en el extremo sur del término municipal, dotado de bancos de descanso. 📍 Provincia: Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31217','mirador','Mirador de la Ermita de San Miguel','Espectacular balcón sobre el mar de viñas viejas de la comarca vitivinícola y los campos de la Baja Montaña. Nota: 8.0/10. Cómo llegar: En la parte alta de la villa, siguiendo la senda empedrada desde la iglesia románica de San Martín. 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31219','mirador','Mirador del Valle del Linares','Sencilla y relajante panorámica de los peregrinos que avanzan cruzando el barranco del río Linares hacia Torres del Río. Nota: 7.1/10. Cómo llegar: En el pretil sur del casco urbano de Sansol, que ejerce de balcón natural sobre la vaguada. 📍 Provincia: Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31220','mirador','Mirador de la Torre de Santacara','Vista de la imponente pared agrietada del castillo medieval sobre las excavaciones de la ciudad romana de Cara y el río Aragón, con una nota de 7.6/10. Cómo llegar: Cerro del Castillo de Santacara, accesible a pie desde la zona norte. 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19204','mirador','Mirador de la Peña de la Horca','8.7/10 Extraordinaria e infinita visual a más de 1500 metros sobre la Sierra de Albarracín, densos bosques de pino silvestre, ríos de piedras y pureza Starlight. Cómo llegar: Saliente rocoso acondicionado con paneles informativos en las cumbres que dominan el casco urbano. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31200','mirador','Mirador de San Bartolomé de Oteiza','Domina las llanuras cerealistas de Tierra Estella meridional, ofreciendo puestas de sol de gran belleza cromática en verano. Nota: 7.3/10. Cómo llegar: En la colina de la ermita de San Bartolomé, con acceso rodado directo y espacio para aparcar. 📍 Provincia: Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31223','mirador','Mirador del Parque de la Memoria y el Ebro','Espacio de reflexión con amplios horizontes visuales sobre las llanuras agrícolas que besan el río Ebro, con una nota de 7.0/10. Cómo llegar: Entorno del Parque de la Memoria, accesible desde los viales de la ribera. 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31224','mirador','Mirador de los Riscos de Sesma','Vista espectacular del relieve que cae bruscamente hacia la cuenca del río Ega, con gran claridad para astroturismo, con una nota de 7.2/10. Cómo llegar: Paseo de circunvalación superior, bordeando el precipicio del pueblo. 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31225','mirador','Mirador de la Basílica de San Gregorio Ostiense','Extraordinaria y monumental panorámica de toda la comarca de la Berrueza y Tierra Estella desde un santuario barroco. Nota: 8.3/10. Cómo llegar: Gran explanada del templo elevado, accesible por carretera local desde Sorlada. 📍 Provincia: Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31226','mirador','Mirador del Puente Medieval sobre el Bidasoa','Preciosa estampa atlántica de los densos bosques reflejados en el cauce limpio del Bidasoa bajo los tres arcos de piedra del puente, con una nota de 8.1/10. Cómo llegar: Ribera izquierda del río Bidasoa, junto a la pasarela peatonal de la villa. 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31227','mirador','Mirador de Santa Lucía','Atalaya sobre la encrucijada geográfica de Tafalla, controlando la transición exacta entre la Navarra montañosa y la llana Ribera, con una nota de 7.5/10. Cómo llegar: Cerro de Santa Lucía, junto a la ermita homónima, accesible por pistas. 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31228','mirador','Mirador del Castillo de Tiebas','Vista de las ruinas góticas de la residencia real de Teobaldo II dominando la cuenca de Pamplona y el paso hacia la Zona Media, con una nota de 7.4/10. Cómo llegar: Recinto arqueológico fortificado en la zona alta de Tiebas. 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31229','mirador','Mirador de las Saleras','Paisaje rural del Valle de Ilzarbe donde destacan los relieves llanos dedicados al cultivo tradicional de cereal, con una nota de 6.9/10. Cómo llegar: Alto de la colina que resguarda el pueblo por el sudeste. 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90730','mirador','Mirador del Acueducto de Noáin','Monumental vista de la obra de Ventura Rodríguez integrada con los nudos de comunicación y la Sierra de Alaitz. Nota: 7.6/10. Cómo llegar: Área recreativa ajardinada situada paralela a la estructura del acueducto del siglo XVIII. 📍 Provincia: Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31230','mirador','Mirador del Santuario de Codés','Alucinante anfiteatro rocoso formado por las agujas pétreas de la Sierra de Codés presidiendo el santuario mariano, con una nota de 7.6/10. Cómo llegar: Explanada de entrada al Santuario de Codés, carretera de montaña NA-7206. 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31231','mirador','Mirador del Santo Sepulcro','Vista de la excepcional iglesia románica octogonal del siglo XII mimetizada con el relieve quebrado del Camino de Santiago, con una nota de 7.5/10. Cómo llegar: Alto del Calvario, accesible a pie desde la zona alta del entramado municipal. 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31232','mirador','Mirador del Sagrado Corazón (Cerro de Santa Bárbara)','Extraordinaria e inmensa vista de la vega del Ebro, el casco antiguo dominado por la Catedral y el lejano desierto de las Bardenas Reales, con una nota de 8.3/10. Cómo llegar: Cima del Cerro de Santa Bárbara, accesible en coche o a pie desde el centro histórico. 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31233','mirador','Mirador del Monasterio de Tulebras','Perspectiva apacible sobre la ribera del río Queiles y el conjunto arquitectónico del primer cenobio cisterciense femenino de España, con una nota de 7.0/10. Cómo llegar: Jardines exteriores colindantes a las murallas del monasterio. 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31234','mirador','Alto de Úcar','Perspectiva de los campos cerealistas de Valdizarbe y las laderas meridionales de la Sierra de Perdón, con una nota de 7.0/10. Cómo llegar: Punto culminante de la carretera local NA-6004. 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31235','mirador','Mirador de las Torres del Santuario de Ujué','Uno de los miradores más colosales de Navarra; domina desde los Pirineos orientales hasta la estepa de las Bardenas y el Moncayo, con una nota de 9.5/10. Cómo llegar: Paseo de ronda fortificado del Santuario-Fortaleza de Santa María de Ujué. 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31236','mirador','Mirador de Guelbenzu / Valle de Ultzama','Idílico paisaje de praderas compartimentadas, robledales centenarios de ensueño y tradicionales caseríos de grandes tejados, con una nota de 8.2/10. Cómo llegar: Alto del mirador acondicionado en el pueblo de Guelbenzu. 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31240','mirador','Mirador de la Ermita de San Pedro','Excelente balcón sobre el corredor de la Sakana, los robledales de la llanura y las paredes rocosas de Urbasa, con una nota de 7.8/10. Cómo llegar: Explanada de la ermita, compartida con Alsasua, accesible por pista forestal. 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31241','mirador','Mirador de la Foz de Iñigalzu','Vista salvaje y escarpada del cañón excavado por el río Areta, hábitat de grandes colonias de buitres leonados, con una nota de 8.1/10. Cómo llegar: Saliente acondicionado en la carretera local entre Elcoaz y Ongoz. 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31242','mirador','Alto de San Vicente','Amplia panorámica de la cuenca de Lumbier y los pies de la sierra, destacando los campos cerealistas, con una nota de 7.5/10. Cómo llegar: Punto kilométrico elevado de la carretera NA-150. 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90937','mirador','Mirador de los Embalses de Leurtza','Paisaje boscoso de hayas reflejadas en las aguas del embalse, con un misticismo y fotogenia excepcionales, con una nota de 8.3/10. Cómo llegar: Pasarela del sendero adaptado que rodea el vaso de agua inferior. 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31246','mirador','Mirador del Camino de Santiago (Alto del Perdón)','Vistas hacia la vertiente sur del Perdón, llanuras de Valdizarbe y campos cerealistas navarros, con una nota de 7.4/10. Cómo llegar: Frontera norte del término, accesible siguiendo la senda jacobea desde la cresta. 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31249','mirador','Mirador de las Cuevas y la Ribera','Espectacular vista del anfiteatro de cuevas-vivienda excavadas en arcilla y de la vega del Ebro, con una nota de 7.8/10. Cómo llegar: Parte alta de la colina que corona el complejo turístico de las cuevas. 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31251','mirador','Mirador de las Murallas de San Pedro','Balcón sobre los viñedos de la Rioja Alavesa, la vega del Ebro y los restos arqueológicos de la iglesia fortificada, con una nota de 8.0/10. Cómo llegar: Ruinas consolidadas del ábside de San Pedro, extremo oeste de la villa histórica. 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31254','mirador','Mirador del Peñón sobre el Río Aragón','Atalaya sobre los meandros del río Aragón y los campos de cultivo de la comarca de la Ribera Alta, con una nota de 7.5/10. Cómo llegar: Extremo sur de los cortados yesosos del casco urbano. 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31255','mirador','Mirador del Castillo de Monjardín','Excepcional panorámica de 360 grados de Tierra Estella, viñedos, campos de cereal e hitos de la ruta jacobea, con una nota de 8.6/10. Cómo llegar: Cima del cerro fortificado, accesible por pista empinada desde el pueblo. 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31257','mirador','Mirador del Río Iranzu','Perspectiva de la llanura agrícola y el puente medieval sobre el cauce del río, con una nota de 7.2/10. Cómo llegar: Camino de Santiago a las afueras del núcleo histórico. 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31261','mirador','Mirador del Embalse de Yesa','Impresionante vista del llamado ''Mar del Pirineo'' y la muralla calcárea de la Sierra de Leyre al fondo, con una nota de 8.3/10. Cómo llegar: Apartadero de la antigua carretera nacional N-240 junto a la presa. 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90938','mirador','Mirador de las Peñas de Ciordia','Panorámica vertiginosa del paso natural entre Navarra y Álava, encajonado entre grandes moles de caliza, con una nota de 7.9/10. Cómo llegar: Sendas de montaña integradas en la loma de la Sierra de Urbasa. 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31263','mirador','Mirador de Mendaur (Senda de Zubieta)','Bosques atlánticos cerrados de castaños, helechos gigantes y cumbres habitualmente envueltas en nubes mágicas, con una nota de 8.1/10. Cómo llegar: Pista que arranca cerca del antiguo molino y asciende hacia la cima de Mendaur. 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31264','mirador','Mirador del Prado de las Brujas (Akelarre)','Paisaje misterioso, rodeado de prados de un verde intenso, regatos ocultos y las crestas del Pirineo Baztanés, con una nota de 8.5/10. Cómo llegar: Sendero superior sobre la Cueva de las Brujas, saliendo del núcleo urbano. 📍 Provincia: Comunidad Foral de Navarra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31265','mirador','Mirador de la Vía Verde del Arquijas','Vista del viaducto ferroviario histórico integrado en el frondoso y estrecho valle del río Ega, con una nota de 7.7/10. Cómo llegar: Antiguo trazado del ferrocarril Vasco-Navarro, acondicionado para peatones. Comunidad Foral de Navarra Completada (100% de Municipios) Procedo a saltar de inmediato al siguiente bloque cartográfico oficial: Principado de Asturias. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90682','mirador','Mirador del Puerto del Palo','Impresionante balcón natural sobre las montañas del occidente asturiano y el Valle del Oro, con una nota de 8.5/10. Cómo llegar: En el alto del Puerto del Palo (carretera AS-14), con zona de aparcamiento habilitada. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90637','mirador','Mirador de Coto Bello','Vista panorámica de 360 grados de las cumbres del Macizo Central asturiano, Peña Mea y el valle del Aller, ideal para astroturismo, con una nota de 8.6/10. Cómo llegar: Acceso por carretera asfaltada desde la localidad de Piñeres, subiendo al antiguo cielo abierto. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05001','mirador','Mirador de Amieva','Espectacular vista del Macizo Occidental de los Picos de Europa (Cornión) y el desfiladero tallado por el río Dobra, con una nota de 8.9/10. Cómo llegar: Situado en el propio pueblo de Amieva, accesible por la carretera local AM-1. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05002','mirador','Mirador del Faro de Avilés (Punta de San Juan)','Vista abierta del mar Cantábrico, los acantilados de la costa central y la entrada de barcos a la ría avilesina, con una nota de 7.8/10. Cómo llegar: Junto al faro de la localidad, al final de la carretera local AS-329.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05003','mirador','Mirador de Selviella','Balcón natural sobre el cañón del río Pigüeña y las densas masas boscosas de castaños del concejo, con una nota de 8.3/10. Cómo llegar: Apartadero señalizado en la carretera AS-227, subiendo en dirección a Somiedo. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90638','mirador','Mirador de la Camperona','Vista limpia de la comarca de la sidra, valles interiores y el perfil de la Sierra de Peñamayor, con una nota de 7.9/10. Cómo llegar: Zona alta de San Julián de Bimenes, accesible por pista hormigonada local. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90639','mirador','Mirador de Penouta','Excelente atalaya sobre el Valle del Navia y el mar Cantábrico al fondo; cuenta con mesas e infraestructura recreativa, con una nota de 8.4/10. Cómo llegar: Área recreativa de Penouta, junto a la carretera AS-22. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05004','mirador','Mirador de Santa Eulalia','Panorámica rural de praderías, pumaradas (campos de manzanos) y las tradicionales aldeas asturianas del interior, con una nota de 7.8/10. Cómo llegar: Entorno de la capilla de Santa Eulalia, accesible a pie desde la capital del concejo. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90640','mirador','Mirador de la Peña de San Román','Atalaya sobre la vega del río Nalón, sus huertas y el relieve suave pre-litoral asturiano, con una nota de 8.1/10. Cómo llegar: Senda peatonal que corona el monte sobre la cueva de la Peña de Candamo. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05005','mirador','Mirador de Entrelagos','Espectacular loma que separa y domina visualmente las aguas glaciares de los lagos Enol y Ercina en los Picos de Europa, con una nota de 9.5/10. Cómo llegar: Acceso a pie por escalinatas empedradas desde los aparcamientos de la CO-4. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05006','mirador','Mirador de Muniellos / Connio','Balcón vertiginoso sobre el mayor robledal de España y uno de los mejor conservados de Europa occidental, con una nota de 9.2/10. Cómo llegar: Alto del Puerto del Connio (carretera AS-348), en los límites de la reserva integral. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90010','mirador','Mirador del Fitu (Vertiente Costa)','Atalaya que solapa la bravura del mar Cantábrico en la playa de Vega con los pies de la Sierra del Sueve, con una nota de 8.8/10. Cómo llegar: Carretera AS-260, compartiendo el icónico equipamiento de la plataforma de hormigón en el límite municipal. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90011','mirador','Mirador de la Ermita de San Antonio (Candás)','Romántico balcón costero que domina los acantilados, el puerto pesquero de Candás y el oleaje abierto, con una nota de 8.3/10. Cómo llegar: Explanada de la Ermita de San Antonio, extremo norte de la villa marinera. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90641','mirador','Mirador de la Collada de Arnicio','Impresionante estampa del Parque Natural de Redes, destacando los perfiles calcáreos y los bosques de hayas, con una nota de 9.1/10. Cómo llegar: Puerto de Arnicio (carretera AS-117), con rampa y barandillas de madera instaladas. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90012','mirador','Mirador de la Peñona (Salinas)','Plataforma colgada sobre los acantilados que une el mar con el Museo de Anclas, dominando la inmensa playa de Salinas, con una nota de 8.4/10. Cómo llegar: Extremo occidental del paseo marítimo de Salinas, acceso por pasarelas peatonales. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90013','mirador','Mirador de la Ermita de San Román','Vista perfecta de la ría del Eo, los pueblos marineros de Figueras y Castropol, y la costa gallega de Ribadeo, con una nota de 8.5/10. Cómo llegar: Ribera elevada de la ría, accesible por desvío desde la carretera N-640. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90014','mirador','Mirador del Pico de Jarrio','Atalaya costero-rural con vistas a las rasas asturianas del occidente y las cercanías del célebre castro celta, con una nota de 8.2/10. Cómo llegar: Pistas superiores del monte Jarrio, coronado por repetidores de señal. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90015','mirador','Mirador del Fitu','Espectacular e histórica taza de hormigón de 1927 con una panorámica total de 360 grados que abarca desde los Picos de Europa hasta el mar, con una nota de 9.3/10. Cómo llegar: Puerto del Fitu, por la sinuosa carretera AS-260. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90642','mirador','Mirador del Pantano de Trasona','Vista del embalse recreativo, pistas de piragüismo y las laderas forestales que rodean el entorno industrial mitigado, con una nota de 7.6/10. Cómo llegar: Paseo perimetral e instalaciones del Centro de Tecnificación Deportiva. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05008','mirador','Mirador del Cabo Vidio','Impresionantes acantilados de más de 80 metros que caen en vertical sobre el Cantábrico, con puestas de sol memorables y avistamiento de aves, con una nota de 9.4/10. Cómo llegar: Explanada del Faro de Cabo Vidio en Oviñana, accesible por la autovía A-8. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33022','mirador','Mirador del Puerto de Cerredo','Vistas alpinas de los valles del carbón y de los picos que delimitan Asturias con León, en el entorno del oso pardo, con una nota de 8.6/10. Cómo llegar: En lo alto del puerto de Cerredo (carretera AS-15). 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33023','mirador','Mirador de la Playa de Pormenande','Preciosa ensenada rocosa con islote central donde el oleaje rompe con fuerza en un entorno salvaje de pinos, con una nota de 8.3/10. Cómo llegar: Pequeña colina habilitada como área recreativa sobre la playa de Pormenande. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33024','mirador','Mirador del Cerro de Santa Catalina (Elogio del Horizonte)','Espectacular anfiteatro marítimo sobre el acantilado, enmarcado por la monumental escultura de Chillida que amplifica el sonido de las olas, con una nota de 9.0/10. Cómo llegar: Parque del Cerro de Santa Catalina, en el barrio histórico de Cimavilla. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33025','mirador','Mirador del Cabo Peñas','El punto más septentrional de Asturias; ofrece una vista salvaje de acantilados cuarcíticos y galernas cantábricas, con una nota de 9.3/10. Cómo llegar: Entorno adaptado con pasarelas de madera junto al Faro de Cabo Peñas (AS-328). 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33026','mirador','Mirador de la Flor','Amplia panorámica de la villa de Grado y las fértiles vegas fluviales del río Cubia y el Nalón, con una nota de 8.0/10. Cómo llegar: Ermita de Nuestra Señora de la Flor, ladera oeste del concejo. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33027','mirador','Mirador de Boca de Ballena (Salto de Salime)','Impresionante estructura de hormigón suspendida en el vacío construida por Vaquero Turcios sobre la presa del embalse, con una nota de 8.9/10. Cómo llegar: Carretera AS-14, justo sobre la coronación de la presa hidroeléctrica. ¿Continuamos con el bloque de Ibias, Illas, Langreo, Laviana, Lena.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33028','mirador','Mirador de Chao de Lagar (Larna) [1]','Excepcional balcón sobre los valles del sol de Ibias y los límites de la Reserva Natural Integral de Muniellos, con una nota de 8.8/10. Cómo llegar: Pista de montaña señalizada desde la localidad de Larna. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33030','mirador','Mirador del Gorfolí','Atalaya sobre los valles interiores de la comarca de Avilés y campos de pastoreo tradicionales, con una nota de 7.8/10. Cómo llegar: Cima del Pico Gorfolí, accesible por cortafuegos y sendas desde Callezuela. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33031','mirador','Mirador de la Mudrera','Impresionante panorámica del Valle del Nalón y las antiguas explotaciones mineras a cielo abierto regeneradas, con una nota de 8.2/10. Cómo llegar: Área recreativa de La Mudrera, subiendo por la carretera de Tuilla. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33032','mirador','Mirador de Peña Mea','Vista de la imponente mole caliza de Peña Mea y su famoso "ojo" o cavidad natural de roca, con una nota de 8.5/10. Cómo llegar: Senda de montaña accesible desde la aldea de Pelúgano. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33033','mirador','Mirador de la Cuitas (ValgrandePajares)','Impresionantes vistas alpinas del Puerto de Pajares y los macizos de Ubiña y el Central Asturiano, con una nota de 9.1/10. Cómo llegar: Estación invernal de ValgrandePajares, accesible mediante el telesilla de la estación. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33035','mirador','Mirador del Monte Gorfolí (Vertiente Sur)','Vista limpia de la llanura central asturiana y los polígonos industriales integrados en el paisaje rural, con una nota de 7.7/10. Cómo llegar: Pistas superiores del cordal que divide el concejo con Illas. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33036','mirador','Mirador de la Boriza','Espectacular tajo costero que divide las playas de Ballota y Andrín, ofreciendo una postal salvaje del oleaje cantábrico, con una nota de 9.4/10. Cómo llegar: Carretera local LLN-2, sobre el campo de golf municipal. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33037','mirador','Mirador de Cenera','Entorno idílico del valle minero y ganadero de Turón y Cenera, perfecto para la observación de castaños y brañas, con una nota de 8.3/10. Cómo llegar: Carretera local MI-4 que sube hacia el valle de Gallegos. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33038','mirador','Mirador del Monsacro','Atalaya mística sobre el embalse de Alsa, la cuenca central y las capillas medievales de la montaña sagrada, con una nota de 9.0/10. Cómo llegar: Praderas altas del Monsacro, accesible a pie desde la Collá de la Foz. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33039','mirador','Mirador del Espiritu Santo','Impresionante vista del estuario del río Nalón abriéndose paso hacia el mar Cantábrico en la playa de Los Quebrantos, con una nota de 8.7/10. Cómo llegar: Junto a la Ermita del Espíritu Santo en San Esteban de Pravia. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33040','mirador','Mirador de Les Praeres','Espectacular campa verde a las faldas de la Sierra de Peñamayor, conocida por sus rampas ciclistas e idilio ganadero, con una nota de 82/10. Cómo llegar: Pista asfaltada empinada que sale directamente de la capital de Nava. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33041','mirador','Mirador de la Playa de Barayo','Vista del sistema dunar y las marismas vírgenes de la Reserva Natural Parcial de Barayo, con una nota de 8.6/10. Cómo llegar: Aparcamiento este de la playa de Barayo, accesible por la NV-2. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33042','mirador','Mirador de la Torre del Reloj','Perspectiva del núcleo histórico del concejo más pequeño de Asturias integrado en la llanura central, con una nota de 7.2/10. Cómo llegar: Plaza de la Constitución, en pleno casco urbano. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33043','mirador','Mirador del Puerto de Demués','Espectacular balcón sobre el Valle del Güeña y los perfiles calizos del Cornión en Picos de Europa, con una nota de 8.9/10. Cómo llegar: Pista de montaña apta para vehículos que parte del pueblo de Demués. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33044','mirador','Mirador de los Escultores (Monte Naranco)','Vista panorámica total de la ciudad de Oviedo coronada por el Monumento al Sagrado Corazón y el arte prerrománico, con una nota de 8.8/10. Cómo llegar: Carretera de subida al Monte Naranco, en la explanada superior. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33045','mirador','Mirador del Fitu (Vertiente Interior)','Vista mítica de las cumbres de los Picos de Europa alzándose sobre el valle de Arriondas y el curso del río Sella, con una nota de 9.2/10. Cómo llegar: En lo alto del puerto del Fitu por la carretera AS-260, compartiendo plataforma. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33046','mirador','Mirador de San Esteban de Cuñaba','Balcón sobre los desfiladeros del río Deva dentro del paraje del parque nacional de los Picos de Europa, con una nota de 8.8/10. Cómo llegar: Pueblo ejemplar de San Esteban de Cuñaba, accesible por pista de montaña. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33047','mirador','Mirador de Cavandi','Atalaya sobre el desfiladero de la Hermida y el perfil del Cuera con vistas a los cauces del Cares y el Deva, con una nota de 8.6/10. Cómo llegar: Carretera que sube al pueblo de Cavandi desde Panes. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33048','mirador','Mirador de la Escrita','Vista del cañón del río Agüeira y los cultivos tradicionales en bancales de vides del occidente asturiano, con una nota de 8.1/10. Cómo llegar: Carretera AS-12 a su paso por el puerto de la Escrita. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33049','mirador','Mirador de la Collada de Arnicio (Lado Norte)','Vista hacia la Sierra de la Frecha y los pastizales altos de Piloña que conectan con Caso, con una nota de 8.7/10. Cómo llegar: Alto de la carretera AS-254. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33050','mirador','Mirador de Les Bedules','Vista de ensueño del Bosque de Peloño, los Picos de Europa y el desfiladero de los Beyos, con una fotogenia salvaje de 9.3/10. Cómo llegar: Pista forestal transitable desde el pueblo de San Juan de Beleño. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33051','mirador','Mirador de Monte Agudo','Atalaya sobre la confluencia de los ríos Nalón y Narcea con el mar Cantábrico al fondo de la estampa, con una nota de 8.3/10. Cómo llegar: Pista que sube desde el núcleo de Santianes de Pravia. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33052','mirador','Mirador de la Senda del Oso (Valdemurio)','Vista espectacular del desfiladero rocoso y el entorno verde del embalse que atraviesa el famoso sendero ciclista, con una nota de 8.8/10. Cómo llegar: Senda del Oso, a la altura de la desviación hacia Quirós. ¿Continuamos con los últimos municipios de Asturias (Quirós, Regueras, Ribadedeva, Ribadesella...) para terminar la región?.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33053','mirador','Mirador del Alto del Gamoniteiro','El techo de la Sierra del Aramo a casi 1.800 metros, con una panorámica brutal de toda la cordillera y valles centrales, con una nota de 9.4/10. Cómo llegar: Carretera de montaña estrecha y asfaltada que corona la cima desde el Alto de la Cobertoria. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33054','mirador','Mirador de los Meandros del Nora','Espectacular vista aérea del sinuoso curso fluvial encajonado que ejerce de frontera natural con Oviedo, con una nota de 7.6/10. Cómo llegar: Sendero que parte del pueblo de Priañes, acondicionado con barandillas de seguridad. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33055','mirador','Mirador de la Ermita de San Emeterio','Impresionante balcón marino sobre los acantilados de Pimiango y la ensenada de la playa de La Franca, con una nota de 8.9/10. Cómo llegar: Campa verde junto a la histórica ermita y el acceso a la cueva de El Pindal. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33056','mirador','Mirador de Guía / San Roque','Postal perfecta de la desembocadura de la ría del Sella, la playa de Santa Marina y el casco histórico marinero, con una nota de 9.2/10. Cómo llegar: Ermita de la Virgen de la Guía, en la cima del monte Corberu. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33057','mirador','Mirador del Picu Llanza','Vista del corredor del Nalón, las instalaciones de la térmica integradas y las estribaciones de la Sierra del Aramo, con una nota de 7.8/10. Cómo llegar: Pistas superiores asfaltadas que ascienden desde la localidad de Bueño. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33058','mirador','Mirador del Angliru','El mítico coloso ciclista ofrece una perspectiva vertiginosa y descarnada sobre las laderas pastoriles de la Sierra del Aramo, con una nota de 9.3/10. Cómo llegar: Explanada de la cima del puerto de montaña, accesible por la empinadísima carretera local RI-5. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33059','mirador','Mirador del Viso','Atalaya sobre la villa medieval de Salas, su castillo, colegiata y el verde Valle del Nonaya, con una nota de 8.4/10. Cómo llegar: Monte del Viso, accesible por pista apta para vehículos desde la capital del concejo. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33061','mirador','Mirador de la Garganta','Vista del paisaje recóndito y boscoso de la comarca de los Oscos, caracterizado por sus tejados de pizarra negra, con una nota de 8.2/10. Cómo llegar: Cruce de carreteras del Puerto de la Garganta, divisorio de la comarca. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33060','mirador','Mirador de San Mamés','Perspectiva de la cuenca minera del Nalón, pueblos industriales y las laderas regeneradas de bosque autóctono, con una nota de 8.0/10. Cómo llegar: Senda y área recreativa en la loma de San Mamés, sobre Sotrondio. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33063','mirador','Mirador de O Chao','Balcón sobre la vega del río Eo a su paso por el extremo más occidental de Asturias, rodeado de pinares, con una nota de 7.9/10. Cómo llegar: Desvío señalizado en la carretera nacional N-640. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33062','mirador','Mirador de Ferreira','Precioso paisaje rural de los valles del occidente asturiano, fraguas históricas y cursos de agua pura, con una nota de 8.5/10. Cómo llegar: Senda peatonal cercana al conjunto etnográfico de Mazonovo. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33064','mirador','Mirador del Desfiladero de las Xanas','Cortada calcárea impresionante sobre el desfiladero apodado como el "pequeño Cares", con una gran biodiversidad, con una nota de 8.7/10. Cómo llegar: Punto medio del sendero peatonal de las Xanas, saliendo desde Villanueva. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33065','mirador','Mirador de la Loma de Santiago','Suave valle agrícola rodeado de manzanos y pequeñas lomas que delimitan la comarca sidrera central, con una nota de 7.4/10. Cómo llegar: Entorno de la Ermita de Santiago, accesible por caminos rurales. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33066','mirador','Mirador del Palacio de Meres','Vista de los bosques señoriales y campos de la zona central asturiana desde la colina circundante, con una nota de 7.7/10. Cómo llegar: Entorno rural sobreelevado accesible desde Tiñana. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33067','mirador','Mirador de la Collada de Unqueru','Maravilloso balcón sobre el embalse de Tanes, los hayedos de Redes y el espectacular desfiladero de Rioseco, con una nota de 9.0/10. Cómo llegar: Senda de montaña señalizada PR-AS 62 que asciende desde la capital. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33068','mirador','Mirador del Príncipe (La Peral)','Vistas panorámicas espectaculares del circo glaciar, brañas con teitos de escoba y el hábitat por excelencia del oso pardo cantábrico, con una nota de 9.6/10. Cómo llegar: Estructura de madera acondicionada en la aldea de La Peral, subiendo el Puerto de Somiedo (AS-227). 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33069','mirador','Mirador del Castillo de San Martín','Vista de los meandros finales del río Nalón, la ría del desembarco de angulas y la fortaleza histórica que vigila el cauce, con una nota de 8.4/10. Cómo llegar: Embarcadero y promontorio del castillo en la desembocadura. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33070','mirador','Mirador del Faro de Tapia','Espectacular atalaya sobre el islote del faro, los acantilados pizarrosos y la famosa ola izquierda surfera de la playa de Anguileiro, con una nota de 8.6/10. Cómo llegar: Paseo marítimo perimetral que rodea el puerto pesquero. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33071','mirador','Mirador de As Veigas','Precioso balcón colgado sobre una aldea de cuento hundida en el espeso y verde valle forestal de los artesanos navajeros, con una nota de 8.7/10. Cómo llegar: Carretera local empinada que baja de Taramundi hacia el fondo del cañón. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33072','mirador','Mirador del Puerto de San Lorenzo','Espectacular paso de montaña de origen romano que conecta Teverga con Somiedo, divisando pastizales infinitos y brañas, con una nota de 9.1/10. Cómo llegar: Alto de la carretera AS-265, provisto de paneles y parking. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33073','mirador','Mirador de la Pulide / Campo de San Roque','Inmensa llanura elevada con vistas a las montañas del occidente, rutas del Camino Primitivo de Santiago y robledales, con una nota de 8.5/10. Cómo llegar: Área recreativa del Campo de San Roque, a las afueras de la villa. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33034','mirador','Mirador de la Ermita de la Blanca (Luarca)','Espectacular estampa de la villa blanca de Luarca, sus playas, los tres puentes de la ría y el cementerio marino más bello de España, con una nota de 9.1/10. Cómo llegar: Atalaya de la ermita y faro de Luarca, extremo oriental de los acantilados. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33074','mirador','Mirador del Monasterio de Villanueva','Balcón sobre la marisma alta del río Eo y las llanuras agrícolas que marcan la entrada a Galicia, con una nota de 8.2/10. Cómo llegar: Colinas de Piantón, pistas rurales accesibles desde la AS-22. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33075','mirador','Mirador de Morlongo','Vista limpia de la comarca etnográfica, densos pinares y el valle del río Pasarón en un ambiente de silencio absoluto, con una nota de 8.4/10. Cómo llegar: Alto de Morlongo, en la carretera AS-11 que conecta con Vegadeo. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33076','mirador','Mirador de la Reserva de la Ría de Villaviciosa','Fantástico observatorio de aves marinas y limícolas sobre las dunas y el estuario protegido de El Puntal, con una nota de 8.9/10. Cómo llegar: Pasarelas de madera situadas en la carretera local VV-6 hacia el puerto de El Puntal. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33077','mirador','Mirador de las Cascadas de Oneta','Balcón sobre el imponente salto de agua de la Firbia encajonado entre el denso dosel vegetal y rocas de cuarcita, con una nota de 8.8/10. Cómo llegar: Sendero peatonal adaptado que sale desde la aldea de Oneta. 📍 Provincia: Principado de Asturias.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33078','mirador','Mirador del Puerto de Marabio','Espectacular paisaje de montaña kárstica con lagunas temporales, sumideros y vacas pastando libremente en las alturas, con una nota de 8.3/10. Cómo llegar: Pista de montaña asfaltada que cruza el puerto desde Yernes. Principado de Asturias Completado (100% de Municipios) Procedo a saltar de inmediato al siguiente bloque cartográfico oficial de Castilla y León, comenzando por la provincia de León por orden alfabético. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26001','mirador','Mirador del Puerto de Tarna / Pico Mampodre','9.2/10 Majestuosa e imponente visual alpina de la cordillera Cantábrica central, circos glaciares calcáreos y frondosos hayedos cantábricos altos. Cómo llegar: Apartadero de montaña de la carretera CL-635, en el confín montañoso fronterizo con Asturias. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90196','mirador','Mirador de las Bodegas de Algadefe','Sencilla pero despejada vista sobre las vegas cerealistas del río Esla y los tejados de las tradicionales bodegas excavadas, con una nota de 6.7/10. Cómo llegar: Zona alta de los cerros arcillosos que coronan la localidad. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90197','mirador','Mirador del Castillo - Palacio de los Ponce de León','Vista de la fértil llanura fluvial de los ríos Órbigo y Órbigo Bajo junto al lienzo restaurado de la fortaleza, con una nota de 7.4/10. Cómo llegar: Plaza mayor del núcleo histórico, extremo de la muralla medieval. ¿Continuamos de inmediato con los siguientes municipios de la provincia de León de forma masiva y sin interrupciones?.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90664','mirador','Mirador de la Torre del Reloj y la Muralla','Atalaya medieval que ofrece una vista despejada de la vega del río Cea y el entramado boscoso que rodea la villa histórica, con una nota de 7.6/10. Cómo llegar: Pasarela del recinto amurallado en pleno centro histórico del núcleo urbano. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90198','mirador','Mirador de las Bodegas del Teso','7.4/10 Suave relieve de cerros de arcilla jalonado por viñedos tradicionales de la variedad Prieto Picudo y vegas del Esla. Cómo llegar: Loma superior acondicionada en el barrio de las bodegas trogloditas tradicionales del municipio. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90199','mirador','Mirador de las Viñas de Arganza','Espectacular mosaico visual de cepas viejas integradas en la hoya de El Bierzo con los montes Aquilianos recortando el horizonte, con una nota de 7.8/10. Cómo llegar: Camino rural elevado entre Arganza y Campelo, transitable a pie. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26002','mirador','Mirador de la Muralla / Palacio de Gaudí','9.6/10 Insuperable, majestuosa e histórica panorámica del Palacio Episcopal neogótico, la catedral, el Teleno y la llanura maragata. Cómo llegar: Paseo de ronda de la muralla romana, balconada empedrada del parque de la Sinagoga. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90200','mirador','Mirador del Castillo de Balboa','Preciosa panorámica de las laderas boscosas de los Ancares, las pallozas tradicionales con techado de paja y el fondo del valle, con una nota de 8.6/10. Cómo llegar: Cresta rocosa que corona el pueblo, accesible por sendero desde la Casa de las Gentes. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90201','mirador','Mirador del Hayedo de Busmayor','Impresionante vista estacional de uno de los bosques de hayas más puros y meridionales de la provincia, ideal en otoño, con una nota de 8.3/10. Cómo llegar: Sendero señalizado circular, en el saliente rocoso superior antes del descenso a las cascadas. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26004','mirador','Mirador del Santo','Atalaya sobre la villa de Bembibre, el trazado fluvial del río Boeza y los restos del paisaje industrial de la cuenca minera berciana, con una nota de 7.7/10. Cómo llegar: Explanada del Santuario del Ecce Homo, en la zona más elevada de la población. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90202','mirador','Mirador de los Prados del Órbigo','Vista del extenso tapiz verde que forman los campos de regadío y los canales tradicionales del río Órbigo, con una nota de 7.3/10. Cómo llegar: Ribera sobreelevada junto al Parque del Canal, accesible desde el casco urbano. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90203','mirador','Mirador de Cabrera Alta','Paisaje abrupto y montañoso de la comarca de Cabrera, con laderas pizarrosas profundas esculpidas históricamente por los canales romanos de Las Médulas, con una nota de 8.2/10. Cómo llegar: Margen de la carretera LE-164 a su paso por el puerto que comunica con Puente de Domingo Flórez. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90781','mirador','Mirador de la Ermita de Nuestra Señora de Perales','Horizonte infinito de la estepa cerealista leonesa surcado de forma lineal por los peregrinos de la ruta jacobea, con una nota de 7.0/10. Cómo llegar: Entorno rural junto a la ermita homónima a las afueras del núcleo en dirección a El Burgo Ranero. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90204','mirador','Mirador de Piedrasluengas (Vertiente Leonesa)','Impresionante panorámica alpina de los Picos de Europa y el macizo de Fuentes Carrionas en un entorno de alta montaña, con una nota de 9.0/10. Cómo llegar: Límite provincial en el alto del puerto, accesible por la carretera LE-215. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26005','mirador','Mirador del Pico Cueto','Espectacular panorámica del Valle del Porma, la villa de Boñar y las moles calizas de la montaña central leonesa, con una nota de 8.4/10. Cómo llegar: Cima del Pico Cueto, accesible mediante sendero señalizado que parte de la fuente de la Salud. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90205','mirador','Mirador de Orellán','Vista cenital obligatoria y mítica del laberinto de picachos rojizos y castaños centenarios que conforman la mina de oro romana de Las Médulas, con una nota de 9.4/10. Cómo llegar: Aparcamiento habilitado en el pueblo de Orellán, subida asfaltada y pasarela de madera colgada sobre el abismo. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90206','mirador','Mirador de la Cruz de Fierro (Foncebadón)','Punto emblemático del Camino de Santiago rodeado de brezales y lomas de los Montes de León, cargado de un fuerte valor místico y emocional, con una nota de 7.9/10. Cómo llegar: Junto al poste de madera de la Cruz de Hierro en la carretera LE-142. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90783','mirador','Mirador de Lario','Excelente estampa de los valles del Parque Regional de Picos de Europa y de las cumbres que flanquean el curso alto del río Esla, con una nota de 8.9/10. Cómo llegar: Estructura de madera elevada en el pueblo de Lario, accesible por desvío desde la CL-635. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90784','mirador','Mirador del Páramo Leonés','Paisaje rectilíneo agrario dominado por los modernos sistemas de riego y los silos agrícolas que sobresalen en la inmensidad de la llanura, con una nota de 6.5/10. Cómo llegar: Entorno del depósito elevado de agua de la localidad. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90207','mirador','Mirador del Canal del Bierzo','Vista de la llanura agrícola berciana y los campos de árboles frutales con el trazado del canal hidráulico en primer plano, con una nota de 7.2/10. Cómo llegar: Sendas de servicio del canal a su paso por la zona alta del término. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90208','mirador','Mirador de la Mota del Esla','Observatorio fluvial llano sobre las aguas del río Esla y los sotos forestales de chopos que protegen sus márgenes, con una nota de 6.9/10. Cómo llegar: Sendero de pescadores acondicionado junto al cauce fluvial. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26006','mirador','Mirador del Valle de Babia','Espectacular paisaje de prados Alpinos donde pastan caballos de raza hispano-bretona bajo las inmensas peñas de piedra caliza, con una nota de 8.7/10. Cómo llegar: Margen de la carretera CL-626 en el tramo central de la comarca de Babia. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26007','mirador','Mirador del Castro de la Ventosa','Impresionante vista arqueológica y vinícola de toda la llanura central de El Bierzo desde los muros de un oppidum prerromano, con una nota de 8.0/10. Cómo llegar: Camino rural que asciende al yacimiento sobre el cerro que separa Cacabelos de Pieros. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34042','mirador','Mirador del Andadero de la Abadía de Benevívere','Perspectiva histórica del llano cerealista donde los peregrinos jacobeos cruzan la traza romana de la Vía Aquitana, con una nota de 7.5/10. Cómo llegar: Descansadero adaptado en la ruta peatonal del Camino de Santiago, junto al arroyo de la Abadía. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90665','mirador','Mirador del Espacio Cívico Viñedos','Vista panorámica integrada de las parcelas de vid del municipio con las siluetas montañosas de los Ancares al fondo, con una nota de 7.4/10. Cómo llegar: Parque público elevado junto al Centro de Interpretación de la Vid y el Vino. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90210','mirador','Mirador del Puerto de Ancares','Paisaje salvaje y vertiginoso de alta montaña que divide León y Lugo, con vistas a valles encajonados y circos glaciares, con una nota de 8.8/10. Cómo llegar: Coronación del puerto de montaña, accesible por la carretera de alta montaña LE-4211. ¿Continuamos de inmediato con la siguiente tanda masiva (Cármenes, Carracedelo, Carrizo, Carrocera...).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90791','mirador','Mirador de las Sabinas de Crémenes','Atalaya sobre el Alto Esla que muestra uno de los sabinares más septentrionales y puros de Europa, encajado en roca calcárea, con una nota de 8.9/10. Cómo llegar: Ruta de las Sabinas, accesible a pie desde la Calzada Romana de Las Salas. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90211','mirador','Mirador de las Huertas del Monasterio de Carracedo','Vista del entorno monacal y los extensos campos de peras de conferencia y manzanas del Bierzo, con una nota de 8.1/10. Cómo llegar: Entorno ajardinado y sobreelevado de la muralla exterior del Monasterio de Santa María de Carracedo. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90212','mirador','Mirador del Plantío de Lúpulo','Excelente perspectiva sobre el Valle del Órbigo y las singulares estructuras metálicas de los campos de cultivo de lúpulo, con una nota de 7.4/10. Cómo llegar: Margen este del canal del Órbigo, accesible por pistas rurales desde Carrizo de la Ribera. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90213','mirador','Mirador del Valle de Viñayos','Atalaya sobre los pastizales y pequeños valles boscosos que marcan la transición hacia las comarcas mineras, con una nota de 7.8/10. Cómo llegar: Carretera local LE-4519, subiendo hacia los altos del municipio. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90795','mirador','Mirador del Lago de Carucedo','Hermoso reflejo de las montañas y castaños en las aguas del lago formado por los lavados de la mina romana de Las Médulas, con una nota de 9.2/10. Cómo llegar: Plataforma de madera junto al área recreativa en la carretera CL-536. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90214','mirador','Mirador del Altozano de la Iglesia','Sencillo balcón castellano sobre la llanura cerealista del sur de León y los límites vallisoletanos, con una nota de 6.6/10. Cómo llegar: Explanada de la Iglesia de San Juan Bautista, zona alta de la villa. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90215','mirador','Mirador de la Cruz de los Mozos','Panorámica de los valles del Bierzo Alto y de los cerros rojizos erosionados de forma natural, con una nota de 7.6/10. Cómo llegar: Pista forestal que asciende desde el núcleo urbano hacia la loma este. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90216','mirador','Mirador del Castillo de Cea','Vista histórica de la vega del río Cea, el puente medieval y el trazado de las vías ganaderas leonesas, con una nota de 7.5/10. Cómo llegar: Torre del homenaje en ruinas situada en el cerro sobre el pueblo. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90785','mirador','Mirador del Alto de la Collada','Paisaje ondulado de transición entre los campos de cereal y las primeras elevaciones de la montaña de Cea, con una nota de 7.2/10. Cómo llegar: Punto alto de la carretera provincial LE-4603. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90786','mirador','Mirador del Puente del Órbigo','Vista panorámica sobre el lecho pedregoso del río Órbigo y las alamedas que lo flanquean, con una nota de 6.9/10. Cómo llegar: Área de descanso junto al viaducto de la carretera N-VI. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90787','mirador','Mirador de las Lagunas de Chozas','Importante observatorio de aves acuáticas y migratorias asentado en un humedal de la meseta leonesa, con una nota de 7.0/10. Cómo llegar: Caseta de observación de madera en la Laguna Grande, accesible desde el pueblo. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90788','mirador','Mirador de la Ermita de la Virgen de la Vega','Vista del cauce del río Esla y los sotos riberas colindantes en el extremo sur de la provincia, con una nota de 7.2/10. Cómo llegar: Pradera exterior de la ermita románica, accesible desde la carretera de Benavente. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90789','mirador','Mirador del Alto del Órbigo','Panorámica de los cultivos tradicionales de la ribera, pinares de repoblación y choperas simétricas, con una nota de 7.4/10. Cómo llegar: Senda forestal que sube hacia los páramos occidentales del término. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26008','mirador','Mirador de la Ermita de San Guillermo','Impresionante balcón rocoso colgado sobre el casco urbano de Cistierna y el cañón del río Esla custodiado por el pico Peñacorada, con una nota de 8.4/10. Cómo llegar: Senda peatonal empinada de montaña que sube desde el cementerio municipal. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90217','mirador','Mirador de la Virgen de la Peña','Espectacular atalaya colgada sobre el embalse de Bárcena con vistas completas de la fosa tectónica de El Bierzo, con una nota de 8.8/10. Cómo llegar: Santuario de la Virgen de la Peña, accesible por pista asfaltada desde el núcleo. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90790','mirador','Mirador de los Oteros','Paisaje puramente cerealista de la meseta caracterizado por las suaves ondulaciones arcillosas del terreno, con una nota de 6.7/10. Cómo llegar: Camino rural en el punto más elevado del cordal entre Corbillos y Rebollar. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90218','mirador','Mirador de Corullón / San Martín','Precioso balcón que domina la entrada al Valle de Burbia, los cerezos en flor en primavera y el Castillo de Corullón, con una nota de 8.7/10. Cómo llegar: Mirador acondicionado en la carretera de subida a Cabeza de Campo. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90219','mirador','Mirador de la Ermita de San Roque','Vista panorámica sobre el Valle del Bernesga, las choperas de la ribera y las vías de comunicación que suben a Asturias, con una nota de 7.5/10. Cómo llegar: Explanada de la ermita en la loma oeste de Cascantes de Alba. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90792','mirador','Mirador del Monte de las Eras','Vista de la transición entre la meseta y el piedemonte cantábrico, flanqueada por campos de secano y robles dispersos, con una nota de 7.1/10. Cómo llegar: Zona de las antiguas eras del pueblo de Cubillas, extremo superior. ¿Continuamos de inmediato con los siguientes municipios de la lista de León (Cubillas de los Oteros, Fabero, Folgoso de la Ribera, Fresno de la Vega...) manteniendo este flujo continuo y preciso?.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90793','mirador','Mirador de la Cuesta del Otero','Horizonte diáfano sobre los campos arcillosos y las lomas cubiertas de viñedos y bodegas de la comarca de Los Oteros, con una nota de 6.6/10. Cómo llegar: Camino elevado junto al depósito de agua del núcleo urbano. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90220','mirador','Mirador del Valle de la Valduerna','Atalaya sobre los pinares, encinares y las huertas tradicionales que flanquean el río Duerna, con una nota de 7.4/10. Cómo llegar: Paraje de los castros prerromanos, accesible por pistas rurales al norte de la villa. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90796','mirador','Mirador de la Laguna de la Universidad','Observatorio de avifauna integrado en una balsa esteparia rodeada de vegetación palustre en plena llanura cerealista, con una nota de 6.8/10. Cómo llegar: Sendero señalizado que desvía del Camino de Santiago Francés a las afueras del pueblo. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90223','mirador','Mirador del Pozo Julia','Impresionante panorámica del patrimonio industrial minero del carbón con el imponente castillete sobre el fondo alpino de la Sierra de Ancares, con una nota de 8.0/10. Cómo llegar: Terraza elevada junto al centro de interpretación del Pozo Julia. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90224','mirador','Mirador de la Presa del Boeza','Vista del curso encajonado del río Boeza, los sotos de castaños centenarios y los canales hidráulicos tradicionales, con una nota de 7.7/10. Cómo llegar: Senda del canal de regadío, accesible a pie desde el casco urbano. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90225','mirador','Mirador de las Huertas de los Pimientos','Amplia panorámica de la fértil vega del río Esla, célebre por sus cultivos tradicionales del pimiento morrón, con una nota de 7.0/10. Cómo llegar: Mota fluvial de protección, accesible desde el paseo del río. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90798','mirador','Mirador de las Bodegas de Carbajal','Vista de la estepa leonesa meridional salpicada por las chimeneas de ventilación de las bodegas subterráneas, con una nota de 6.5/10. Cómo llegar: Cerro superior que corona el complejo de arquitectura excavada. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90226','mirador','Mirador de la Cuesta de Ruiforco','Perspectiva del tramo medio del río Torío, sus choperas y los perfiles calizos que inician la montaña central, con una nota de 7.5/10. Cómo llegar: Alto de la carretera local que conecta Ruiforco de Torío con Matueca. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90666','mirador','Mirador del campanario de San Juan','Atalaya sobre los campos de secano infinitos de la Tierra de Campos leonesa y las ruinas de su patrimonio mudéjar, con una nota de 6.7/10. Cómo llegar: Entorno sobreelevado de la Iglesia de San Juan Bautista. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90227','mirador','Mirador de la Ruta del Vino (MIMA)','Vista limpia de los viñedos experimentales integrados en el complejo cultural de la antigua fábrica de harinas, con una nota de 7.3/10. Cómo llegar: Jardines exteriores del Museo de la Industria Harinera de Castilla y León. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90228','mirador','Mirador de San Miguel de Escalada','Espectacular vista del entorno del monasterio mozárabe de 913 d.C. dominando la cuenca del río Esla, con una nota de 7.8/10. Cómo llegar: Colina superior accesible por sendero desde el aparcamiento del monasterio. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90230','mirador','Mirador de Colinas de Campo de Martín Moro Toledano','Balcón sobre una aldea de piedra perfectamente conservada en el fondo de un valle glaciar bajo el pico Catoute, con una nota de 8.2/10. Cómo llegar: Entrada del pueblo de Colinas de Campo, junto al puente romano sobre el río Boeza. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90231','mirador','Mirador del Páramo de Izagre','Horizonte plano caracterizado por la inmensidad del paisaje de la meseta y los palomares tradicionales de adobe, con una nota de 6.4/10. Cómo llegar: Entorno rural accesible por pistas parcelarias al norte del pueblo. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90232','mirador','Mirador de las Matas de Cea','Atalaya sobre las llanuras agrícolas interrumpidas por pequeños reductos de bosque de roble melojo, con una nota de 6.6/10. Cómo llegar: Zona alta de las eras de Joarilla, junto al depósito. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25001','mirador','Mirador de la Ermita del Cristo','7.0/10 Vista horizontal limpia del Páramo Leonés central, con bodegas tradicionales excavadas en tierra y extensas llanuras cerealistas. Cómo llegar: Atrio exterior de la ermita, pequeña elevación rústica de tierra en las afueras residenciales. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26009','mirador','Mirador del grafiti / Río Tuerto','8.0/10 Perspectiva urbana vanguardista de arte mural al aire libre unida a la rica vega agrícola del río Órbigo y el Tuerto. Cómo llegar: Pasarela peatonal del puente del río o azoteas transitables del casco céntrico. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90222','mirador','Mirador de la Cuna del Carbón','Vista panorámica sobre el trazado del ferrocarril de la Robla y los valles de montaña modelados por el pasado minero, con una nota de 8.1/10. Cómo llegar: Alto de la colina que corona el pueblo de Sabero/La Ercina, junto a las antiguas minas. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24114','mirador','Mirador de la Reserva de la Biosfera del Alto Bernesga','Impresionante balcón rocoso calizo rodeado de bosques de hayas y robles dentro de un entorno natural protegido de la Cordillera Cantábrica, con una nota de 8.8/10. Cómo llegar: Alto del Puerto de Pajares / Cueto de los Argüellos, accesible por pistas forestales. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24134','mirador','Mirador de Alba','Vista aérea de la villa industrial de La Robla, el cauce del río Bernesga y las imponentes crestas rocosas de la Peña de Alba, con una nota de 7.9/10. Cómo llegar: Ermita de Celada, ladera este de las montañas del municipio. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90234','mirador','Mirador del Páramo Llano','Paisaje agrícola rectilíneo dominado por los modernos sistemas de regadío y campos de maíz, con una nota de 6.6/10. Cómo llegar: Carretera local LE-413 a su paso por el término municipal. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90233','mirador','Mirador del Castillo de Laguna de Negrillos','Vista histórica de la torre del homenaje e instalaciones medievales fortificadas elevadas sobre la llanura de El Páramo, con una nota de 7.3/10. Cómo llegar: Entorno peatonal fortificado de la Plaza del Castillo. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26010','mirador','Mirador de la Torre de la Catedral de León','Excepcional perspectiva cenital de la Pulchra Leonina, las vidrieras góticas y el casco histórico amurallado con la Cordillera Cantábrica al fondo, con una nota de 8.5/10. Cómo llegar: Cuerpo de campanas de la torre norte del templo, accesible mediante visita guiada regulada. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90235','mirador','Mirador del Lúpulo (Llamas)','Atalaya sobre los campos de lúpulo tradicionales de la ribera del Órbigo y los bosques de ribera que escoltan el cauce, con una nota de 7.5/10. Cómo llegar: Pista forestal que asciende a los páramos del oeste desde Quintanilla de Sollamas. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90780','mirador','Mirador del Embalse de Luna','Espectacular tajo calcáreo sobre las aguas azules del embalse, cruzado de forma majestuosa por el viaducto de la autopista AP-66, con una nota de 9.1/10. Cómo llegar: Aparcamiento y mirador acondicionado junto al club náutico, en la carretera CL-626. ¿Continuamos con la siguiente sección del inventario masivo de León (Lucillo, Luyego, Magaz de Cepeda, Mansilla de las Mulas...) para no dejar ningún municipio atrás?.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45086','mirador','Mirador del Monte Teleno','Impresionante balcón natural sobre la comarca de la Maragatería y los restos de minería de oro romana, presidido por la silueta del pico sagrado, con una nota de 8.4/10. Cómo llegar: Pista forestal que asciende desde Filiel hacia las faldas del Teleno. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90801','mirador','Mirador de la Ermita de los Remedios','Atalaya sobre los encinares y brezales del campo de maniobras de El Teleno y el Valle del Duerna, con una nota de 7.8/10. Cómo llegar: Explanada del santuario de la Virgen de los Remedios en Luyego de Somoza. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90236','mirador','Mirador de la Cepeda Alta','Vista de las colinas boscosas de pinos y robles que caracterizan la transición entre la llanura de Astorga y El Bierzo, con una nota de 7.2/10. Cómo llegar: Punto elevado junto a la carretera LE-451 en el término de Porqueros. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26011','mirador','Mirador del Postigo (Muralla)','Perspectiva histórica de los cantos rodados de la muralla medieval del siglo XII y el paso de peregrinos sobre el río Esla, con una nota de 7.9/10. Cómo llegar: Tramo rehabilitado de la muralla junto a la Puerta de la Concepción. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90237','mirador','Mirador de la Cuna del Esla','Balcón sobre los sotos de chopos y choperas simétricas donde el río Porma se entrega al cauce principal del Esla, con una nota de 7.4/10. Cómo llegar: Sendero fluvial acondicionado accesible desde Nogales. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16122','mirador','Alto del Cerro de San Cristóbal','7.3/10 Perspectiva sobre la vega del río Júcar medio, huertas tradicionales de regadío, el somontano de la Serranía y horizontes nítidos de baja luminosidad. Cómo llegar: Cota natural elevada al noreste del pueblo, accesible por pistas agropecuarias de tierra. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24099','mirador','Mirador del Otero de Matadeón','Horizonte limpio del sur de León que muestra el relieve ondulado típico de la comarca vitivinícola y cerealista, con una nota de 6.6/10. Cómo llegar: Camino de las bodegas tradicionales en la zona alta del pueblo. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24098','mirador','Mirador de las Hoces de Vegacervera (Vertiente Sur)','Espectacular tajo geológico excavado por el río Torío que abre las puertas a la alta montaña central, con una nota de 8.1/10. Cómo llegar: Límite norte del municipio, apartadero de la carretera LE-311. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24100','mirador','Mirador de Corullón / Camino de Santiago','Atalaya jacobea que regala una vista panorámica limpia de la hoya berciana, los montes Aquilianos y el descenso de peregrinos, con una nota de 8.8/10. Cómo llegar: Parada forzosa en la carretera LE-142 descendiendo desde Foncebadón. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24101','mirador','Mirador de la Reserva de la Biosfera de Omaña y Luna','Excepcional ventana sobre los valles de abedules y brañas de montaña de la alta Omaña, hábitat protegido del urogallo cantábrico, con una nota de 8.7/10. Cómo llegar: Alto de la Cañada, accesible por pista de montaña señalizada desde el pueblo. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24102','mirador','Mirador de la Gualta','Balcón sobre la cascada y el cañón del río Noceda, rodeado de frondosos bosques de castaños y robles melojos, con una nota de 8.2/10. Cómo llegar: Punto álgido de la Ruta de las Fuentes de Noceda, sendero peatonal. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24103','mirador','Mirador de los Ancares Occidentales','Paisaje indómito y remoto que linda con Galicia, dominado por soutos de castaños centenarios y arroyos de montaña puros, con una nota de 8.1/10. Cómo llegar: Pistas superiores forestales que comunican Oencia con Arnado. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24104','mirador','Mirador del Río Omaña','Vista del cauce pedregoso del río, sus alisos y las terrazas fluviales dedicadas al cultivo tradicional, con una nota de 7.4/10. Cómo llegar: Ladera arcillosa sobre el puente que da entrada a la localidad. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24105','mirador','Mirador del Alto de la Venta','Vista periférica del nudo de comunicaciones sur de León y las choperas industriales de la vega del Bernesga, con una nota de 7.1/10. Cómo llegar: Cerro superior adyacente a la autovía A-66, accesible por pista agrícola. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24107','mirador','Mirador de la Cuna del Prieto Picudo','Preciosa planicie salpicada de cepas bajas y el conjunto histórico de bodegas tradicionales más denso de la comarca, con una nota de 7.0/10. Cómo llegar: Loma norte que domina el núcleo de bodegas del municipio. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24108','mirador','Mirador del Castillo de los Bazán','Perspectiva de las ruinas señoriales del castillo-palacio vigilando la vega del río Duerna y los encinares bajos, con una nota de 7.2/10. Cómo llegar: Plaza del Castillo, zona sobreelevada de la villa. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24109','mirador','Mirador de la Braña de Matalavilla','Paisaje alpino de cabañas pastoriles con techumbre de losa enclavadas en valles de origen glaciar habitados por el oso pardo, con una nota de 8.9/10. Cómo llegar: Senda de montaña que sube desde Palacios hacia el cordal divisorio con Laciana. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24110','mirador','Mirador de las Brañas de Salentinos','Espectacular panorámica de los picos calcáreos y los bosques autóctonos del Alto Sil, con una gran riqueza etnográfica y fotogénica, con una nota de 8.6/10. Cómo llegar: Ruta señalizada desde Salentinos hacia el Pico Catoute. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24112','mirador','Mirador de Chano / Castro de Fornela','Impresionante vista del valle de Fornela sobre las pallozas reconstruidas de un antiguo castro de la Edad del Hierro, con una nota de 8.9/10. Cómo llegar: Yacimiento arqueológico de Chano, accesible por pista asfaltada desde el pueblo. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24113','mirador','Mirador de los Páramos del Páramo','Paisaje rectilíneo e industrializado de la agricultura moderna leonesa, dominado por los cultivos de maíz, con una nota de 6.4/10. Cómo llegar: Carretera local LE-412 a las afueras de la localidad. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24115','mirador','Mirador de Orellán (Acceso Ponferrada) / Picos Aquilianos','Vista salvaje del Valle del Silencio y de los picos rocosos que coronan los pueblos de Peñalba de Santiago y Montes de Valdueza, con una nota de 91/10. Cómo llegar: Carretera de montaña de los Aquilianos, con miradores habilitados en las herraduras de subida. ¿Continuamos de inmediato con la siguiente entrega masiva (Posada de Valdeón, Pozuelo del Páramo, Prado de la Guzpeña, Puebla de Lillo...).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24116','mirador','Mirador de Piedrasluengas / Panderrueda','Espectacular balcón colgado sobre el desfiladero de los Picos de Europa y el macizo central, con un impacto visual de 9.6/10. Cómo llegar: Alto del Puerto de Panderrueda (carretera LE-2711), dotado de plataforma de madera. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24117','mirador','Mirador de las Llanuras del Páramo','Vista rectilínea de campos de cereal y palomares tradicionales de barro que recortan el horizonte de la meseta, con una nota de 6.4/10. Cómo llegar: Camino rural elevado junto a las antiguas eras de pan trillar. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24118','mirador','Mirador de la Dehesa de Cerezal','Atalaya natural sobre los valles de robles melojos y el perfil de la peña Corada al norte, con una nota de 7.6/10. Cómo llegar: Pista forestal transitable que corona el cordal montañoso del municipio. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24121','mirador','Mirador del Puerto de las Señales','Increíble paisaje de alta montaña cantábrica rodeado de piornales, pinares autóctonos y neveros, con una nota de 9.2/10. Cómo llegar: Cima del puerto (carretera LE-331), límite con el Parque Regional de Picos de Europa. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24122','mirador','Mirador de Cabrera y el Sil','Vista del encajonamiento y confluencia de los ríos Cabrera y Sil con las montañas pizarrosas de fondo, con una nota de 8.4/10. Cómo llegar: Margen sobreelevada de la carretera N-536 en dirección a Barco de Valdeorras. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24123','mirador','Mirador del Embalse de Villameca','Vista tranquila de las aguas del pantano rodeadas de espesos pinares mediterráneos y brezales de la Cepeda, con una nota de 7.4/10. Cómo llegar: Área recreativa perimetral del embalse, accesible por pista asfaltada. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24124','mirador','Mirador de la Torre de la Iglesia','Atalaya sobre el cauce del río Jamuz y los campos de regadío tradicionales con sus chopos alineados, con una nota de 7.0/10. Cómo llegar: Entorno sobreelevado de la torre románico-mudéjar de San Pedro. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24125','mirador','Mirador del Valle del Jamuz','Balcón sobre los encinares bajos, brezales y pequeñas huertas que marcan el pulso rural de la zona, con una nota de 7.2/10. Cómo llegar: Pista forestal que asciende desde Herreros de Jamuz hacia el páramo. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24127','mirador','Mirador de la Ribera del Órbigo','Llanura agrícola abierta con sotos de ribera y canales tradicionales que vierten sus aguas al río, con una nota de 6.6/10. Cómo llegar: Mota de contención fluvial accesible a pie desde las piscinas municipales. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24129','mirador','Mirador del Valle de Pallide','Hermosa panorámica de praderías verdes encajonadas entre formidables moles de caliza prepirenaica, con una nota de 8.2/10. Cómo llegar: Collada de acceso al pueblo de Pallide, por la carretera local LE-4613. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24130','mirador','Mirador de las Hazas / El Banco más Bonito de León','Impresionantes fiordos leoneses creados por el embalse rodeado de los picos Gilbo y Yordas; belleza fotogénica de 9.5/10. Cómo llegar: Sendero que sube desde el repetidor de Riaño hasta la plataforma del columpio gigante. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24131','mirador','Mirador del Valle del Tuerto','Vista de la vega cerealista e industrial del río Tuerto con el perfil lejano del monte Teleno, con una nota de 6.8/10. Cómo llegar: Camino elevado que conecta con Toralino de la Vega. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24132','mirador','Mirador del Castillo de Benal','Atalaya sobre las ruinas de la fortaleza medieval y el verde e indómito valle del río Omaña, con una nota de 8.5/10. Cómo llegar: Promontorio rocoso del castillo, accesible por sendero desde El Castillo (Riello). 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24133','mirador','Mirador del Alto de la Calzada','Vista panorámica de los páramos occidentales que dan paso a las comarcas de Luna y Omaña, con una nota de 7.1/10. Cómo llegar: Punto alto kilométrico de la carretera CL-623. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24137','mirador','Mirador del Valle de Sabero / Museo de la Siderurgia','Vista del patrimonio industrial de la primera siderurgia de España, flanqueada por crestas calizas, con una nota de 8.4/10. Cómo llegar: Terraza exterior alta del pozo Herrera, accesible por la LE-4603. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24139','mirador','Mirador de la Torre de San Lorenzo','Vista aérea del mudéjar leonés, los tejados de la villa y las llanuras cerealistas del este provincial, con una nota de 8.2/10. Cómo llegar: Balcón superior de la torre mudéjar, accesible en el casco urbano. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24141','mirador','Mirador de las Bodegas del Valle','Curioso paisaje de chimeneas de ventilación de bodegas excavadas en los taludes de arcilla de la meseta, con una nota de 6.7/10. Cómo llegar: Corona superior de la ladera donde se concentran las bodegas subterráneas. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24142','mirador','Mirador de Trobajo del Camino','Observatorio metropolitano de la ciudad de León e hitos urbanos del Camino de Santiago Francés, con una nota de 7.0/10. Cómo llegar: Zona alta del Parque de la Era de Trobajo. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24144','mirador','Mirador de la Vega del Órbigo','Mosaico agrícola de choperas y regadíos tradicionales en el tramo medio del río, con una nota de 6.8/10. Cómo llegar: Pistas rurales que bordean el canal del Órbigo. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24145','mirador','Mirador del Macizo de Ubiña (Pinos)','Espectacular paisaje calcáreo de alta montaña con valles de origen glaciar donde pacen rebaños de ganado vacuno y caballar, con una nota de 9.3/10. Cómo llegar: Puerto de Pinos, accesible por pista de montaña desde San Emiliano. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24146','mirador','Mirador del Monasterio de Nogales','Vista de las ruinas del cenobio cisterciense integradas en la vega forestal del río Eria, con una nota de 7.4/10. Cómo llegar: Ladera sobreelevada frente a las ruinas del monasterio de Santa María. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24148','mirador','Mirador del Crucero de Santo Toribio','Balcón histórico desde donde se divisa la ciudad monumental de Astorga con el monte Teleno al fondo, con una nota de 7.6/10. Cómo llegar: Junto al monumento de piedra de Santo Toribio en la carretera N-120. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24149','mirador','Mirador del Esla Bajo','Vista diáfana de la vega del río Esla meridional y los campos de cultivo intensivo, con una nota de 6.5/10. Cómo llegar: Camino de sirga fluvial accesible desde el pueblo. ¿Continuamos de inmediato con los municipios de León de la S a la Z (San Pedro de Ceque -si correspondiera-, Santa Colomba, Santa María, Sariegos, Soto de la Vega, Toral, Toreno, Torre del Bierzo...) para liquidar la provincia?_.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24150','mirador','Mirador del Páramo Leonés Oriental','Horizonte nítido sobre la planicie cerealista donde destacan silos y las líneas de regadío mecánico, con una nota de 6.6/10. Cómo llegar: Camino agrícola elevado junto a los depósitos reguladores al norte del casco urbano. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24143','mirador','Mirador de los Cortados de Sancedo','Excelente panorámica de los valles arcillosos rodeados de pinos y encinas, reflejando el relieve de la hoya berciana, con una nota de 7.8/10. Cómo llegar: Pista forestal señalizada que parte desde la zona alta del pueblo. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24151','mirador','Mirador del Castillo de San Salvador','Atalaya medieval sobre los peñascos que domina el cauce y el frondoso valle del río Curueño, con una nota de 81/10. Cómo llegar: Ruinas fortificadas sobre el cerro rocoso, accesible por sendero desde Barrio de Nuestra Señora. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24152','mirador','Mirador de la Maragatería Alta','Atalaya sobre pueblos de piedra roja y tejados de laja, rodeados de robles y brezales bajo la mirada del Teleno, con una nota de 8.4/10. Cómo llegar: Alto de la carretera LE-142 en las inmediaciones del núcleo deshabitado de Foncebadón. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24153','mirador','Mirador del Alto de la Venta','Extenso tapiz de campos de secano que cambian de color según la estación, ideal para la fotografía de paisaje limpio, con una nota de 6.7/10. Cómo llegar: Apartadero de la carretera N-601 a su paso por el cerro divisorio del municipio. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24154','mirador','Alto de las dehesas de secano','5.5/10 Sencilla visual de campos de labranza tradicionales de la meseta norte y eriales, óptimo para fotografiar atardeceres despejados. Cómo llegar: Camino rural en los límites geográficos orientales del municipio. 📍 Provincia: Zamora.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24155','mirador','Mirador de la Ribera del Tuerto','Suave perspectiva sobre las choperas alineadas y vegas agrícolas que marcan el curso del río Tuerto, con una nota de 6.8/10. Cómo llegar: Sendero local acondicionado que bordea el cauce del río cerca de Santibáñez de la Isla. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24158','mirador','Mirador del Torreón de Ordás','Atalaya sobre los valles del río Luna inferior y los cerros boscosos que marcan el inicio de la montaña, con una nota de 7.6/10. Cómo llegar: Restos de la torre medieval en el promontorio que domina la localidad. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24157','mirador','Mirador de la Torre de la Iglesia','Balcón urbano elevado que regala una vista de 360 grados de los canales e infraestructuras del Páramo Leonés, con una nota de 7.1/10. Cómo llegar: Campanario del templo de Nuestra Señora de la Asunción, accesible bajo petición. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24156','mirador','Mirador del Monte de Cea','Vista de los páramos elevados cubiertos de robles bajos y encinas alternados con campos de secano, con una nota de 7.0/10. Cómo llegar: Pista agrícola en el punto geodésico superior del municipio. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24160','mirador','Mirador de la Traza Jacobea - El Burgo','Vistas de la inmensa llanura de la meseta surcada de forma lineal por el Camino de Santiago y las vías del tren, con una nota de 6.9/10. Cómo llegar: Descansadero de peregrinos en el cordal que comunica Valdearcos con Santas Martas. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24161','mirador','Mirador de la Arquitectura Maragata','Atalaya sobre un entramado urbano impecable de piedra, patios arrieros y pozos tradicionales integrados en el secano, con una nota de 7.8/10. Cómo llegar: Loma del Calvario, accesible a pie desde el Barrio de Arriba. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24162','mirador','Mirador de Quintana de Rueda','Vista de la corona metropolitana de la capital leonesa y los campos de cultivo que separan los ríos Bernesga y Órbigo, con una nota de 7.0/10. Cómo llegar: Cerro superior junto al depósito de agua de Quintana Raneros. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24163','mirador','Mirador del Valle de las Lomas','Suave paisaje de transición residencial con pequeñas vaguadas cubiertas de encinas y pinos piñoneros, con una nota de 7.2/10. Cómo llegar: Mirador acondicionado en la zona alta de la urbanización de Pobladura. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24164','mirador','Mirador de Abelgas de Luna','Paisaje espectacular de alta montaña con valles glaciares calcáreos y sabinares de montaña de gran valor botánico, con una nota de 9.2/10. Cómo llegar: Senda de montaña que arranca desde el pueblo de Abelgas hacia el collado. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24165','mirador','Mirador de los Meandros del Selmo','Vertiginosa vista sobre el encajonamiento del río Selmo entre encinares y sotos de castaños en el límite de León con Galicia, con una nota de 8.4/10. Cómo llegar: Saliente acondicionado en la sinuosa carretera local que sube hacia Cabeza de Campo. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24166','mirador','Mirador del Río Órbigo Bajo','Mosaico agrario verde con cultivos hortícolas intensivos e hileras de chopos que flanquean la gran cuenca fluvial, con una nota de 6.8/10. Cómo llegar: Mota de contención y paseo fluvial a las afueras de Soto de la Vega. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24167','mirador','Mirador de la Collada de Soto','Atalaya sobre la comarca de Omaña que muestra el contraste de los robledales con las canteras calizas regeneradas, con una nota de 8.1/10. Cómo llegar: Alto de la carretera LE-493 a su paso por el término municipal. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24168','mirador','Mirador del Castillo Tapial de los Guzmanes','Vista de una de las fortalezas de tapial de barro mejor conservadas del mundo sobre las choperas de la vega del Esla, con una nota de 7.5/10. Cómo llegar: Paseo superior que rodea la estructura del palacio fortificado de la villa. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24206','mirador','Mirador del Río Burbia y el Sil','Punto estratégico que domina el encuentro de los grandes ríos bercianos rodeado de huertas y colinas de viñedo, con una nota de 8.0/10. Cómo llegar: Paraje de la Poza, accesible por sendas peatonales desde la playa fluvial. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24169','mirador','Mirador de la Antigua Línea de Ponferrada-Villablino','Panorámica sobre el desfiladero excavado por el río Sil y los vestigios de los puentes e instalaciones del tren del carbón, con una nota de 7.9/10. Cómo llegar: Vía verde del Sil, tramo elevado acondicionado con barandillas sobre Toreno. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24170','mirador','Mirador de la Gran Corta de Fabero / Torre','Impactante perspectiva de la inmensa cuenca minera a cielo abierto restaurada con lagunas interiores sobre el relieve montañoso, con una nota de 8.1/10. Cómo llegar: Pistas superiores del cordal que divide el municipio con la cuenca del Boeza. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24171','mirador','Mirador del Valle de Valcarce','Espectacular atalaya jacobea que contempla el ascenso de los peregrinos rodeados de imponentes sotos de castaños centenarios, con una nota de 8.4/10. Cómo llegar: Antiguo tramo de la carretera NVI, acondicionado como mirador sobre el desfiladero. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24172','mirador','Mirador del Lago de Truchillas','Espectacular monumento natural que regala la vista de un lago de origen glaciar encajonado bajo las cumbres de la Sierra de Cabrera, con una nota de 8.9/10. Cómo llegar: Final del sendero de montaña señalizado que arranca del pueblo de Truchillas. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24173','mirador','Mirador del Órbigo Medio (Palazuelo)','Vista panorámica sobre el cauce trenzado del río Órbigo y las plantaciones industriales de madera de chopo, con una nota de 6.8/10. Cómo llegar: Camino rural sobreelevado que conecta Turcia con Palazuelo de Órbigo. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24174','mirador','Mirador de las Tierras de Maíz','Paisaje agrícola llano y rectilíneo dominado por la regularidad de los regadíos modernos y las torres de alta tensión, con una nota de 6.5/10. Cómo llegar: Cruce de la carretera local LE-411 con los caminos de servicio parcelarios. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24185','mirador','Mirador de los Artesanos Maragatos','Vista de la fisonomía de este núcleo textil artesano encajonado en el valle del río Turienzo con el Teleno escoltándolo, con una nota de 7.7/10. Cómo llegar: Colina del Calvario, zona norte sobreelevada de la villa. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24175','mirador','Mirador de la Sobarriba','Atalaya sobre los valles arcillosos salpicados de encinas de la comarca de la Sobarriba con vistas de la silueta leonesa al fondo, con una nota de 7.5/10. Cómo llegar: Mirador de las Lomas, accesible por pista rural desde Valdefresno. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24176','mirador','Mirador de los Canales del Páramo','Sencillo y amplio mirador plano de la llanura cultivada y acequias de hormigón que irrigan la meseta central, con una nota de 6.6/10. Cómo llegar: Margen del Canal del Páramo a su paso por el término municipal. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24177','mirador','Mirador de las Hoces de Valdeteja','Majestuoso y sobrecogedor cañón kárstico de paredes verticales labradas por el río Curueño, rodeado de puentes romanos, con una nota de 9.2/10. Cómo llegar: Estructura de piedra y madera habilitada en el margen de la carretera LE-321. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24178','mirador','Mirador de la Cuesta de Valdemora','Sencillo pero despejado balcón sobre un pequeño valle arcilloso rodeado de campos de cereal de secano, con una nota de 6.6/10. Cómo llegar: Sendero que sube hacia los cerros que limitan con la provincia de Valladolid. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24179','mirador','Mirador de la Peña del Castillo (Montuerto)','Impresionante atalaya caliza que domina el estrechamiento del río Curueño y los restos de una antigua fortificación medieval, con una nota de 8.5/10. Cómo llegar: Senda de montaña empinada que asciende desde el pueblo de Montuerto. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24180','mirador','Mirador de la Dehesa de Valdepolo','Vista de campos cerealistas combinados con uno de los pocos reductos de encinar maduro de la llanura del este, con una nota de 7.0/10. Cómo llegar: Pista rural que cruza el monte desde Quintana de Rueda. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24181','mirador','Mirador del Postigo / Alta Villa','Magnífica panorámica de los escarpes arcillosos sobre el río Cea y el entramado mudéjar y monumental de la histórica villa, con una nota de 8.1/10. Cómo llegar: Terraza fortificada junto al Arco de Santiago, en la zona alta de Valderas. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24182','mirador','Mirador del Valle de la Sequeda','Perspectiva de encinares adehesados y pequeños valles agrarios que sirven de antesala a los Montes de León, con una nota de 7.2/10. Cómo llegar: Camino de la ermita en Castrillo de las Piedras. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24183','mirador','Mirador del Santuario de la Virgen de la Velilla','Espectacular vista del Alto Cea rodeado de pinares de repoblación, robledales y las primeras estribaciones cantábricas de Peñacorada, con una nota de 8.7/10. Cómo llegar: Explanada arbolada del santuario barroco, accesible por carretera desde La Mata de Monteagudo. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24184','mirador','Mirador del Valle de Samario','Entorno tranquilo de montaña media dominado por robledales cerrados y huellas de las antiguas infraestructuras de la minería de oro romana, con una nota de 7.9/10. Cómo llegar: Cortafuegos e itinerario peatonal elevado en la vertiente norte del municipio. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24188','mirador','Mirador del Castillo de Coyanza','Espectacular e imponente panorámica de las murallas ojivales de la fortaleza gótico-militar dominando los escarpes del río Esla, con una nota de 8.5/10. Cómo llegar: Auditorio exterior y jardines de la muralla del castillo, en pleno centro urbano. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24189','mirador','Mirador del Santuario de la Virgen del Camino','Vista del templo de vanguardia racionalista con sus esculturas de Subirachs dominando la llanura de entrada a la capital de León, con una nota de 7.1/10. Cómo llegar: Plaza exterior del Santuario, junto a la carretera nacional N-120. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24190','mirador','Mirador de los Oteros del Sur','Paisaje diáfano de la meseta caracterizado por las sutiles lomas arcillosas y los cultivos rotativos de secano, con una nota de 6.6/10. Cómo llegar: Camino rural elevado que bordea la loma este de la población. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24194','mirador','Mirador de las Hoces de Vegacervera','Formidable e icónica cortada geológica con paredes verticales de roca caliza gris que superan los 100 metros sobre el río Torío, de gran fotogenia, con una nota de 8.9/10. Cómo llegar: Zona central del desfiladero, con apartaderos de madera en la carretera LE-311. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24196','mirador','Mirador de la Espina / Monasterio','Vista aérea del Monasterio de San Andrés, del majestuoso puente romano y de la playa fluvial que baña el cauce del río Cúa, con una nota de 8.5/10. Cómo llegar: Senda del Corral de los Lobos, ladera rocosa al este del núcleo urbano. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24197','mirador','Mirador de la Confluencia del Bernesga y el Esla','Observatorio fluvial que muestra la unión de los dos grandes cauces leoneses entre densas choperas, con una nota de 7.0/10. Cómo llegar: Camino de sirga de la ribera al sur de la localidad de Palanquinos/Vega. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24198','mirador','Mirador del Castillo de Sarracín','Espectacular balcón histórico sobre los escarpados valles del Valcarce y el Camino de Santiago desde los lienzos de una fortaleza templaria, con una nota de 8.6/10. Cómo llegar: Senda empinada señalizada que sube desde el núcleo de Vega de Valcarce. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24202','mirador','Mirador de la Reserva de la Biosfera de Laciana / Cueto d''Arbas','Paisaje alpino de la antigua cuenca minera reconvertida, con lagunas glaciares bajo crestas escarpadas donde habita el oso pardo, con una nota de 9.0/10. Cómo llegar: Puerto de Leitariegos (carretera LE-497), en la plataforma panorámica de la cima. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24203','mirador','Mirador de la Planicie de los Oteros','Horizonte plano característico del secano leones con palomares tradicionales aislados que crean una estampa minimalista, con una nota de 6.6/10. Cómo llegar: Depósito elevado de agua en la loma que corona Fáfilas. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24205','mirador','Mirador de la Laguna de Villadangos','Humedal protegido de gran valor ecológico para el avistamiento de aves acuáticas en medio de la meseta llana, con una nota de 6.9/10. Cómo llegar: Caseta de madera para observadores a las afueras del polígono industrial, accesible a pie. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24207','mirador','Mirador de la Vega del Esla Sur','Perspectiva diáfana de los regadíos tradicionales de maíz y de las alamedas que protegen el curso bajo del Esla, con una nota de 6.8/10. Cómo llegar: Senda de pescadores junto a la balsa de agua del término. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24209','mirador','Mirador de la Iglesia de Santiago / Castillo','Excepcional postal de la Pequeña Compostela, sus palacios, conventos y la Puerta del Perdón encajonados entre viñedos viejos de mencía, con una nota de 8.9/10. Cómo llegar: Explanada de la muralla del Castillo de los Marqueses de Villafranca, acceso peatonal. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24210','mirador','Mirador del Puerto del Manzanal','Histórico paso de montaña divisorio entre la cuenca del Duero y El Bierzo, con amplias vistas de matorral bajo y brezales, con una nota de 7.8/10. Cómo llegar: Apartadero de la antigua carretera N-VI en la coronación del puerto. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24211','mirador','Mirador de Villarrabines','Suave elevación sobre la vega del Esla meridional donde se aprecian las terrazas fluviales y cultivos intensivos, con una nota de 6.8/10. Cómo llegar: Pistas arcillosas superiores en el núcleo de Villarrabines. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24901','mirador','Mirador de la Colegiata de Arbas','Paisaje alpino que encuadra el templo románico del siglo XII bajo las imponentes peñas calizas del Puerto de Pajares, de gran misticismo, con una nota de 9.1/10. Cómo llegar: Explanada exterior de la Colegiata de Santa María de Arbas, pie de la N-630. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24212','mirador','Mirador de las Bodegas de Villamañán','Vista de las lomas cubiertas de viñas y bodegas centenarias subterráneas excavadas en taludes arcillosos sobre la vega, con una nota de 7.4/10. Cómo llegar: Zona alta del mirador del complejo hostelero y tradicional de bodegas. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24213','mirador','Mirador de las Matas de Cea','Vista de la transición agraria al bosque con pequeños reductos de roble rebollo que oxigenan las llanuras cerealistas, con una nota de 6.9/10. Cómo llegar: Camino forestal elevado al oeste del núcleo urbano. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24214','mirador','Mirador de la Cepeda Media','Vista del curso del río Tuerto a su paso por los valles arbolados con pinares y pequeños prados ganaderos, con una nota de 7.2/10. Cómo llegar: Camino elevado forestal accesible desde Fontoria de Cepeda. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24215','mirador','Mirador del Valle del Cea Alto','Paisaje ondulado de campos de secano de la Tierra de Campos leonesa con restos de arquitectura tradicional de adobe, con una nota de 6.6/10. Cómo llegar: Eras altas de la localidad junto a los silos agrícolas. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24216','mirador','Mirador del Duerna Medio','Vista de las plantaciones de chopos y los cultivos de regadío tradicionales de la comarca valduernesa, con una nota de 7.1/10. Cómo llegar: Camino rural elevado en la pedanía de Miñambres de la Valduerna. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24217','mirador','Mirador de las Matas','Horizonte diáfano característico de la meseta con pequeños reductos forestales aislados de roble melojo, con una nota de 6.6/10. Cómo llegar: Depósito de agua elevado a las afueras del núcleo. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24218','mirador','Mirador del Esla Alto Medio','Atalaya sobre los cultivos de regadío del canal del Esla y sotos arbolados tradicionales, con una nota de 6.8/10. Cómo llegar: Camino superior que bordea el núcleo de Palanquinos. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24221','mirador','Mirador del Esla Meridional (Villaquejida)','Vista panorámica sobre el ancho cauce del río Esla en su tramo final de la provincia con amplias alamedas, con una nota de 7.2/10. Cómo llegar: Pistas del canal de regadío en la zona elevada del este. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24222','mirador','Mirador de la Candamia (Vertiente Norte)','Balcón seminatural sobre el Valle del Torío y los nuevos sectores residenciales del área metropolitana de León, con una nota de 7.3/10. Cómo llegar: Corona del Parque de la Candamia, accesible por pistas peatonales. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24159','mirador','Mirador del Azud del Órbigo','Vista de la histórica presa de derivación de aguas y el bosque de ribera que acoge colonias de aves acuáticas, con una nota de 7.4/10. Cómo llegar: Pasarela peatonal del azud, accesible desde el casco urbano. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24199','mirador','Mirador de la Dehesa de Vegaquemada','Vista panorámica del cauce medio del río Porma, rodeado de robles centenarios y campas de pastizal de montaña, con una nota de 8.2/10. Cómo llegar: Pista que sube hacia los pastos comunales del norte del municipio. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24201','mirador','Mirador del Porma (Vegas)','Balcón sobre la llanura fluvial del Condado, con un intrincado mosaico de huertas tradicionales y sotos de alisos, con una nota de 7.6/10. Cómo llegar: Pistas del canal de agua, accesibles desde Villanueva del Condado. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24223','mirador','Mirador del Puente del Órbigo (Hospital de Órbigo)','Espectacular vista histórica del puente medieval del Passo Honroso (1434), hito monumental de gran fotogenia jacobea, con una nota de 7.5/10. Cómo llegar: Área de descanso de la carretera N-120 junto a la fortificación del puente. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24224','mirador','Mirador del Camino Francés','Atalaya sobre los valles de cultivo de hortalizas y lúpulo con el fluir constante de peregrinos hacia Astorga, con una nota de 7.2/10. Cómo llegar: Senda jacobea sobreelevada entre Villares y Santibáñez de Valdeiglesias. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24225','mirador','Mirador de Lancia','Impresionante balcón arqueológico sobre las ruinas de la gran ciudad astur-romana de Lancia que domina las vegas del Porma y el Esla, con una nota de 7.8/10. Cómo llegar: Cerro de El Castro, yacimiento accesible por pista asfaltada desde la N-601. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24226','mirador','Mirador del Valle del Cea Alto','Paisaje ondulado de transición cerealista con chopos lineales que marcan las pequeñas escorrentías fluviales, con una nota de 6.6/10. Cómo llegar: Eras altas de Castroañe, junto al antiguo depósito. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24187','mirador','Mirador de las Cuevas-Bodega de Valdevimbre','Vista pintoresca de un mar de viñedos Prieto Picudo intercalado con los montículos arcillosos donde se esconden los famosos restaurantes subterráneos, con una nota de 7.4/10. Cómo llegar: Cerro superior del núcleo de bodegas del pueblo, accesible por pistas rurales. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24193','mirador','Mirador del Valle del Curueño (La Vecilla)','Vista de la llanura fluvial del Curueño famosa por la cría de los gallos de pluma para pesca, flanqueada por calizas montañosas, con una nota de 8.0/10. Cómo llegar: Colina del Torreón de los Condes de Luna, extremo norte del pueblo. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24227','mirador','Mirador del Condado Sur','Vista panorámica llana de la rica vega agrícola del Esla inferior y sus extensos maizales, con una nota de 7.0/10. Cómo llegar: Mota de defensa fluvial accesible desde Marne. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24228','mirador','Mirador del Órbigo Llano','Sencilla perspectiva de los regadíos mecánicos modernos e hileras de choperas industriales, con una nota de 6.7/10. Cómo llegar: Cruce de caminos rurales elevado junto al canal secundario de riego. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24229','mirador','Mirador de la Cuna del Valderaduey','Horizonte nítido sobre el inicio del valle fluvial y las suaves lomas de secano de Tierra de Campos, con una nota de 6.9/10. Cómo llegar: Pista agrícola elevada en las proximidades de Mozos de Cea. 📍 Provincia: León.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24230','mirador','Mirador de las Tierras del Páramo Bajo','Paisaje cuadriculado y rectilíneo monótono dominado por el maíz y los sistemas de aspersión modernos, con una nota de 6.5/10. Cómo llegar: Carretera local LE-411 en el tramo central del término municipal. Provincia de León Completada (100% de Municipios) Procedo a saltar de inmediato al siguiente bloque de la lista oficial de Castilla y León por orden cartográfico: Provincia de Palencia. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34025','mirador','Mirador de la Esclusa del Canal de Castilla','Vista del salto de agua de la esclusa del canal y el entorno rehabilitado de la fábrica de harinas en Tierra de Campos, con una nota de 7.6/10. Cómo llegar: Entorno de la dársena de la esclusa primera del ramal de Campos, acceso peatonal. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90803','mirador','Mirador del Castillo de Abia','Atalaya sobre el cauce del río Valdavia, sus praderas y los restos del cerro fortificado medieval, con una nota de 7.2/10. Cómo llegar: Promontorio elevado que corona el casco urbano, junto a las bodegas tradicionales. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35001','mirador','Mirador del Castillo de Aguilar','Impresionante panorámica del embalse de Aguilar, la villa medieval galletera y los perfiles rocosos de la Montaña Palentina, con una nota de 9.0/10. Cómo llegar: Plataforma superior de las murallas del castillo, accesible por sendero peatonal. ¿Continuamos de inmediato con los siguientes municipios de la provincia de Palencia de forma masiva y directa?.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90238','mirador','Mirador del Kilómetro 0 del Canal de Castilla','Preciosa panorámica del nacimiento de esta monumental obra de ingeniería hidráulica donde el río Pisuerga cede sus aguas al canal, rodeado de frondosos sotos, con una nota de 8.4/10. Cómo llegar: Paraje de la Retención de San Andrés, accesible a pie desde el casco urbano. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90239','mirador','Mirador del Cerrato de Alba','Paisaje típico de páramos y lomas calizas rotas por la erosión, con campos de secano que contrastan con los valles verdes del sur de la provincia, con una nota de 7.1/10. Cómo llegar: Cerro de las Bodegas, en la parte superior del núcleo de arquitectura excavada. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90804','mirador','Mirador Ecológico de la Tierra de Campos','Atalaya sobre campos cerealistas y huertos ecológicos que muestra el horizonte diáfano y limpio de la estepa castellana, con una nota de 7.0/10. Cómo llegar: Loma superior junto al centro de interpretación de bioconstrucción del municipio. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90240','mirador','Mirador del Castillo de Ampudia','Excelente estampa de la llanura palentina dominada por las almenas y torreones de esta joya de la arquitectura militar gótica, con una nota de 8.6/10. Cómo llegar: Adosado a los muros de la fortaleza gótica, accesible a pie desde la calle del Castillo. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90241','mirador','Mirador de la Ermita de Nuestra Señora de las Fuentes','Vista del cauce medio del río Ucieza y las llanuras agrícolas desde el entorno de una joya románica apodada "pajarón de Campos", con una nota de 7.5/10. Cómo llegar: Pradera exterior del santuario, accesible por camino rural desde Amusco. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90805','mirador','Mirador del Valle de Cerrato Alto','Atalaya sobre los profundos valles de los arroyos locales rodeados de lomas calizas de matorral mediterráneo y encinas bajas, con una nota de 7.4/10. Cómo llegar: Senda forestal que asciende desde la Ermita de Nuestra Señora de Garón. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34015','mirador','Mirador de las Eras Altas','Vista horizontal del secano castellano roto únicamente por hileras de chopos que guían riachuelos estacionales, con una nota de 6.9/10. Cómo llegar: Zona de las antiguas eras del pueblo, junto al depósito elevado de agua. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34017','mirador','Mirador del Castillo de la Mota','Panorámica sobre el casco medieval de Astudillo, las murallas y las vegas del río Pisuerga salpicadas de bodegas, con una nota de 8.2/10. Cómo llegar: Cima del cerro de la Mota, accesible por rampas peatonales desde la Plaza Mayor. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34018','mirador','Mirador de Campos (Autilla)','Denominado el "Balcón de Campos"; ofrece el mar de cereal más impresionante e infinito de toda la provincia, idílico para puestas de sol, con una nota de 8.8/10. Cómo llegar: Plataforma acondicionada con barandillas y restaurante en la carretera PP-9001, en el borde del páramo. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34019','mirador','Mirador de la Torre de San Eufemia','Vista de pájaro sobre los campos de trigo y palomares tradicionales de barro que perfilan la estepa, con una nota de 7.2/10. Cómo llegar: Campanario del templo parroquial, transitable bajo reserva previa. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34020','mirador','Mirador de la Vega de Valdavia','Atalaya sobre los valles de monte bajo y matorral que marcan la transición hacia las primeras elevaciones del norte, con una nota de 7.3/10. Cómo llegar: Camino elevado forestal transitable que comunica Ayuela con Rebanal de los Caballeros. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34022','mirador','Mirador del Castillo / Barrio de las Bodegas','Curioso paisaje modelado por cientos de chimeneas de ventilación de un laberinto de bodegas excavadas en un solo cerro arcilloso, con una nota de 8.3/10. Cómo llegar: Cima de la colina del Castillo, que corona el conjunto histórico de las bodegas subterráneas. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34024','mirador','Mirador del Páramo de Secano','Horizonte plano caracterizado por la inmensidad cromática de la estepa cerealista y las aves esteparias, con una nota de 6.7/10. Cómo llegar: Cruce de caminos vecinales elevados al sur de la localidad. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34027','mirador','Mirador de las Cuencas Mineras / Alto de la Collada','Espectacular estampa de bosques de hayas y robles flanqueando antiguos tajos de carbón regenerados bajo el Pico Rubagón, con una nota de 8.6/10. Cómo llegar: Carretera PP-2121 que asciende hacia Brañosera, parada habilitada en el collado. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34028','mirador','Mirador del Boedo','Vista limpia del curso del río Boedo, sus prados ganaderos y el sutil relieve forestal del entorno, con una nota de 7.4/10. Cómo llegar: Pista que sube hacia los páramos occidentales desde el casco urbano. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34029','mirador','Mirador de San Pedro Cultural','Espectacular centro astronómico instalado en una iglesia en ruinas, ofreciendo cielos limpios ideales para astroturismo en la meseta, con una nota de 8.5/10. Cómo llegar: Plaza de San Pedro, zona monumental del centro urbano. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34031','mirador','Mirador de la Torre de Belmonte','Imponente silueta de la torre del homenaje del siglo XV dominando la llanura de Tierra de Campos meridional, con una nota de 7.8/10. Cómo llegar: Entorno perimetral fortificado de las ruinas del castillo de la villa. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34032','mirador','Mirador de la Lora de Berzosilla','Balcón sobre un enclave palentino rodeado de tierras cántabras y burgalesas, con espectaculares cañones kársticos e iglesias rupestres, con una nota de 8.3/10. Cómo llegar: Pista superior de la Lora caliza, accesible desde Olleros de Paredes Rubias. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34033','mirador','Mirador de la Laguna de Boada','Excepcional observatorio de aves acuáticas (ánsares, patos) sobre un humedal recuperado en plena llanura esteparia, con una nota de 8.0/10. Cómo llegar: Caseta-observatorio de madera gestionada por la Fundación Global Nature, accesible desde el pueblo. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34034','mirador','Mirador del Andadero Jacobeo','Observatorio del fluir constante de peregrinos que atraviesan la estepa cerealista hacia Frómista siguiendo el cauce del agua, con una nota de 7.4/10. Cómo llegar: Senda del Camino de Santiago Francés paralela al Canal de Castilla. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34036','mirador','Mirador de la Fuente del Cobre / Alto de la Varga','Impresionante panorámica del macizo de Fuentes Carrionas y del espeso bosque de hayas y robles del primer ayuntamiento de España, con una nota de 9.1/10. Cómo llegar: Senda peatonal de la Fuente del Cobre, punto de observación del circo glaciar. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34037','mirador','Mirador del Castillo de Buenavista','Vista panorámica sobre el encajonamiento del río Valdavia, sus praderas y el relieve boscoso norteño, con una nota de 7.6/10. Cómo llegar: Cerros superiores fortificados donde se asientan las ruinas de la antigua torre. ¿Continuamos de inmediato con los siguientes municipios de la provincia de Palencia (Bustillo de la Vega, Calahorra de Boedo, Calzada de los Molinos, Carrión de los Condes...) manteniendo este flujo masivo y exacto?.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34038','mirador','Mirador de las Huertas del Carrión','Vista limpia de la fértil llanura fluvial del río Carrión con sus choperas lineales e intensas parcelas de regadío, con una nota de 7.1/10. Cómo llegar: Camino rural sobreelevado que bordea el canal de la margen izquierda del río. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34041','mirador','Mirador del Valle del Boedo','Atalaya sobre las suaves praderas verdes y arboledas bajas que custodian el fluir del río Boedo en el piedemonte, con una nota de 7.2/10. Cómo llegar: Alto de los cerros arcillosos que coronan las bodegas al sur del núcleo urbano. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34045','mirador','Mirador del Embarcadero de Capillas','Vista del Ramal de Campos del Canal de Castilla cruzando las compuertas y el puente de piedra tradicional, con una nota de 7.6/10. Cómo llegar: Dársena y antiguos almacenes del Canal de Castilla, acceso directo por la carretera PP-9201. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34046','mirador','Mirador de los Páramos Astrales','Horizonte diáfano y plano de Tierra de Campos, idóneo para la observación nocturna gracias a su baja contaminación lumínica, con una nota de 6.6/10. Cómo llegar: Pista agrícola elevada en la loma que limita con Villamuera de la Cueza. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34047','mirador','Mirador de la Muralla de Santa María','Magnífica postal urbana sobre el río Carrión, el puente mayor y el histórico Monasterio de San Zoilo enclavado en la ruta jacobea, con una nota de 8.6/10. Cómo llegar: Paseo de la muralla medieval junto a la Iglesia de Santa María del Camino, casco histórico. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34049','mirador','Mirador de Peña Redonda','Espectacular balcón kárstico que regala la vista de la Montaña Palentina meridional y la majestuosa mole caliza que da nombre al municipio, con una nota de 8.8/10. Cómo llegar: Senda de montaña señalizada que asciende a la cumbre desde el pueblo de Pisón de Castrejón. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34050','mirador','Mirador del Valle del Esgueva','Atalaya sobre los viñedos viejos y lomas calizas del Cerrato palentino que marcan la frontera con la provincia de Valladolid, con una nota de 7.4/10. Cómo llegar: Cuesta de las Bodegas, extremo más alto del núcleo de arquitectura excavada. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34051','mirador','Mirador de las Ruinas de la Muralla','Vista aérea de un típico pueblo-fortaleza del Cerrato, con sus calles empinadas empotradas entre páramos yesosos, con una nota de 7.5/10. Cómo llegar: Restos del recinto amurallado medieval, en el cerro que corona la población. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34052','mirador','Mirador de la Ermita del Camino','Panorámica sobre el cauce del río Valdavia, los sotos de alisos y el puente histórico de sillería de la localidad, con una nota de 7.3/10. Cómo llegar: Explanada exterior de la Ermita de la Virgen del Camino, accesible por pista rural. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34053','mirador','Mirador del Río Cueza','Vista de la llanura arcillosa y del cauce modesto del río Cueza rodeado de palomares de adobe circulares tradicionales, con una nota de 7.4/10. Cómo llegar: Loma de San Juan, junto a las eras altas al norte del casco urbano. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34055','mirador','Mirador de la Casa del General San Martín','Vista del entramado castellano mudéjar tradicional integrado en la estepa cerealista interminable de la meseta central, con una nota de 7.2/10. Cómo llegar: Zona de las antiguas eras altas del pueblo, junto al depósito elevado. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34057','mirador','Mirador de la Ermita de Santa Ana','Impresionante panorámica de uno de los conjuntos de bodegas subterráneas más escalonados y verticales del Cerrato Palentino, con una nota de 8.0/10. Cómo llegar: Explanada de la ermita barroca, accesible subiendo la escalinata desde la Plaza Mayor. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34058','mirador','Mirador del Alto de Cevico','Balcón sobre los encinares autóctonos y campos de secano encajonados en los profundos valles calizos de la comarca, con una nota de 7.7/10. Cómo llegar: Puerto de montaña en la carretera P-113 que comunica con Antigüedad. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34059','mirador','Mirador de las Torres Mudéjares','Vista de los extraordinarios tejados y campanarios mudéjares que sobresalen de forma majestuosa en la llanura de Tierra de Campos, con una nota de 7.8/10. Cómo llegar: Entorno sobreelevado de la Iglesia-Museo de San Pedro. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34060','mirador','Mirador del Río Franco','Vista del estrecho e idílico valle forestal del río Franco, rodeado de lomas de yeso y matorral mediterráneo aromático, con una nota de 7.3/10. Cómo llegar: Pista que asciende a los páramos superiores desde el cementerio municipal. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34061','mirador','Mirador del Boedo Alto','Sencilla y despejada perspectiva de los campos de secano que marcan la transición hacia la Ojeda palentina, con una nota de 7.1/10. Cómo llegar: Camino rural elevado en las proximidades del núcleo de Oteros de Boedo. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34062','mirador','Mirador de la Dehesa de Tablares','Vista panorámica del soto de robles melojos y encinas que cobija la histórica Ermita de la Virgen de Tablares junto al río Valdavia, con una nota de 8.1/10. Cómo llegar: Cerro testigo elevado frente al conjunto histórico de Tablares. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34063','mirador','Mirador de los Meandros del Pisuerga','Espectacular vista aérea del curso sinuoso y encajonado del río Pisuerga sirviendo de frontera natural con la provincia de Burgos, con una nota de 7.8/10. Cómo llegar: Borde del páramo calizo accesible por pistas agrícolas al norte de la villa. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34066','mirador','Mirador de la Cuesta del Santo','Vista de los viñedos tradicionales adscritos a la denominación de origen Cigales e hileras de bodegas subterráneas del sur provincial, con una nota de 7.4/10. Cómo llegar: Cerro superior del complejo de bodegas excavadas del municipio. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34067','mirador','Mirador de la Tejeda de Tosande','Impresionante balcón forestal sobre un valle recóndito que cobija una de las concentraciones de tejos milenarios más importantes de Europa, con una nota de 8.9/10. Cómo llegar: Saliente rocoso habilitado en el tramo superior de la Senda de Tosande, acceso peatonal. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34068','mirador','Mirador de la Ojeda Alta','Vista de la comarca de la Ojeda caracterizada por pequeños valles de cultivo rodeados de cerros de matorral y robles bajos, con una nota de 7.2/10. Cómo llegar: Punto kilométrico elevado de la carretera provincial PP-2222. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34069','mirador','Mirador de la Ermita de Onecha / El Castillo','Espectacular panorámica de la confluencia de los ríos Pisuerga y Carrión, el Canal de Castilla y el inmenso Barrio de las Bodegas del núcleo monumental, con una nota de 8.5/10. Cómo llegar: Cerro del Castillo que corona la villa histórica, accesible por rampa asfaltada. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34070','mirador','Mirador del Monte de Espinosa','Vista de los extensos e históricos encinares y robledales del Cerrato oriental lindando con las tierras burgalesas de Lerma, con una nota de 7.5/10. Cómo llegar: Pista forestal que asciende desde el pueblo hacia el páramo norte. ¿Continuamos de inmediato con la siguiente entrega masiva palentina (Espinosa de Villagonzalo, Frechilla, Fresno del Río, Frómista...) manteniendo este flujo exacto?.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34071','mirador','Mirador de las Eras del Carrioncillo','Vista despejada de los campos cerealistas del eje de la Cueza e hileras de chopos que marcan las acequias estacionales, con una nota de 7.1/10. Cómo llegar: Promontorio superior junto al antiguo palomar comunal, al oeste del casco urbano. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34072','mirador','Mirador de la Torre de Santa María','Atalaya sobre las llanuras agrícolas de Tierra de Campos donde se divisan las siluetas de antiguos palomares de adobe, con una nota de 7.4/10. Cómo llegar: Campanario de la Iglesia de Santa María, accesible bajo petición en la Plaza Mayor. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34073','mirador','Mirador de las Lomas de Fresno','Vista panorámica del cauce alto del río Carrión con las primeras estribaciones calizas de la Montaña Palentina de fondo, con una nota de 7.8/10. Cómo llegar: Pista forestal que asciende hacia el páramo divisorio norte desde la localidad. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34074','mirador','Mirador de la Cuádruple Esclusa del Canal de Castilla','Espectacular obra de ingeniería hidráulica medieval-ilustrada; el único tramo donde se agrupan cuatro esclusas en cascada, con una nota de 8.8/10. Cómo llegar: Entorno acondicionado con pasarelas peatonales en el cruce del Canal con el Camino de Santiago. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34076','mirador','Mirador de la Laguna de la Nava','Uno de los humedales esteparios más importantes del norte de España, con miles de gansos y aves acuáticas observables, con una nota de 8.4/10. Cómo llegar: Observatorio de madera acondicionado en la carretera local P-940 entre Fuentes y Mazariegos. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34077','mirador','Mirador del Castillo de los Sarmiento','Atalaya histórica sobre la llanura palentina desde los lienzos de una de las fortalezas de sillería más robustas de la provincia, con una nota de 8.0/10. Cómo llegar: Adosado a la torre del homenaje del castillo, accesible a pie desde la calle de la Fortaleza. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34079','mirador','Mirador de la Esclusa de Grijota','Vista del ramal del Sur del Canal de Castilla, sus saltos de agua y el arbolado de ribera integrado en el área metropolitana, con una nota de 7.6/10. Cómo llegar: Entorno de la esclusa número 29, accesible por el paseo peatonal del canal. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34080','mirador','Mirador de la Cruz de Guardo','Gran panorámica de la villa minera, el paso del río Carrión y la imponente mole caliza del pico Coriscao en el horizonte montañoso, con una nota de 8.5/10. Cómo llegar: Loma de la Cruz, accesible por pista hormigonada desde el barrio de la Estación. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34081','mirador','Mirador del Otero Alto','Sencillo y amplio mirador de secano absoluto sobre las suaves colinas arcillosas que delimitan con la provincia de Valladolid, con una nota de 6.7/10. Cómo llegar: Camino rural elevado adyacente a los antiguos silos del pueblo. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34083','mirador','Mirador de la Confluencia del Burejo y el Pisuerga','Atalaya sobre los amplios sotos fluviales y el centro de interpretación del cangrejo de río, rodeado de frondosas choperas, con una nota de 8.2/10. Cómo llegar: Parque de la Piedad, paseo elevado accesible desde el centro urbano. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34086','mirador','Mirador de la Vega del Pisuerga Sur','Panorámica sobre el curso bajo del río Pisuerga y las vegas de regadío intensivo que lindan con Valladolid, con una nota de 7.4/10. Cómo llegar: Borde del páramo accesible por pistas rurales al oeste del municipio. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34087','mirador','Mirador de las Ruinas del Castillo','Vista de pájaro sobre el estrecho valle de Hornillos, sus huertas tradicionales y las almenas semiderruidas de su fortaleza, con una nota de 7.8/10. Cómo llegar: Cerro del Castillo, accesible por rampa empinada desde la Plaza Mayor. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34088','mirador','Mirador de la Abadía / Río Carrión','Atalaya sobre los meandros del río Carrión y la histórica silueta de la Abadía de Santa María de Husillos, con una nota de 7.5/10. Cómo llegar: Paseo fluvial perimetral, accesible a pie desde la zona recreativa del río. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34089','mirador','Mirador del Puente Fitero','Vista histórica sobre el puente monumental del siglo XI mandado construir por Alfonso VI sobre el río Pisuerga para los peregrinos, con una nota de 7.3/10. Cómo llegar: Margen palentina del río Pisuerga, junto a la carretera local de unión con Melgar. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34091','mirador','Mirador del Río Valderaduey Alto','Horizonte plano caracterizado por la inmensidad de las parcelas de cereal del extremo noroccidental de la meseta, con una nota de 6.6/10. Cómo llegar: Pista parcelaria elevada que corona la loma norte del núcleo urbano. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34092','mirador','Mirador del Pisuerga Medio','Amplia panorámica de las vegas de sillería del Pisuerga y las presas que derivaban el agua para los antiguos molinos de harina, con una nota de 7.5/10. Cómo llegar: Mota elevada de protección fluvial, accesible desde el paseo del río de la localidad. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34094','mirador','Mirador del Alto de la Milagrosa','Atalaya jacobea que ofrece una vista horizontal e infinita del andadero de peregrinos que cruzan la comarca de la Cueza, con una nota de 7.2/10. Cómo llegar: Loma de la Ermita de Nuestra Señora de Mileira, a las afueras del núcleo. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34903','mirador','Mirador del Valle de Ucieza','Vista panorámica sobre el discurrir del arroyo y las lomas cubiertas de robles bajos de la Ojeda palentina meridional, con una nota de 7.3/10. Cómo llegar: Carretera provincial PP-2224 a su paso por el núcleo de Bahillo. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90242','mirador','Mirador del Observatorio Astral','Horizonte totalmente libre de obstáculos visuales y lumínicos, idóneo para la astrofotografía y contemplación de constelaciones, con una nota de 7.0/10. Cómo llegar: Zona de las eras altas del pueblo, junto al vértice geodésico del municipio. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34098','mirador','Mirador del Castillo de Magaz','Vista estratégica del nudo de comunicaciones ferroviarias y de carreteras con las choperas de la ribera del Pisuerga y el cerro fortificado, con una nota de 7.8/10. Cómo llegar: Cima de la Mota de Magaz, accesible por rampa desde la Ermita de la Virgen de Villaverde. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34099','mirador','Mirador del Acueducto del Canal','Curioso punto de observación donde el Canal de Castilla cruza de forma aérea sobre el cauce del río Ucieza mediante un acueducto de piedra, con una nota de 7.4/10. Cómo llegar: Senda del canal de la margen derecha, accesible a pie desde la esclusa número 21. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34100','mirador','Mirador de las Vegas del Carrión','Atalaya sobre los prados ganaderos y choperas simétricas que marcan la entrada del Carrión en la meseta palentina, con una nota de 7.6/10. Cómo llegar: Loma arcillosa superior accesible por pistas rurales desde el casco urbano. ¿Continuamos de inmediato con los siguientes municipios de Palencia (Marcilla de Campos, Mazariegos, Mazuecos de Valdeginate, Melgar de Yuso...).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34101','mirador','Mirador del Valle de San Juan','Atalaya sobre los campos de cereal y el humedal estacional que se nutre del arroyo de la local, con una nota de 6.9/10. Cómo llegar: Camino elevado de las eras junto a las antiguas ruinas del palomar. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34102','mirador','Mirador del Mirón / Estación de la Nava','Punto de observación ideal para contemplar la inmensidad de la estepa y el ecosistema palustre de la Laguna de la Nava, con una nota de 7.8/10. Cómo llegar: Antiguo apeadero de tren acondicionado en el límite de la zona húmeda protegida. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34103','mirador','Mirador de la Torre de Mazuecos','Espectacular vista aérea sobre las colinas arcillosas y el característico entramado de adobe de la comarca, con una nota de 7.1/10. Cómo llegar: Campanario de la Iglesia de San Miguel, zona céntrica sobreelevada. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34104','mirador','Mirador de las Riberas del Pisuerga','Balcón sobre los meandros del tramo medio del río Pisuerga, sus alamedas simétricas y acequias agrarias, con una nota de 7.5/10. Cómo llegar: Mota de retención fluvial accesible por pista rural desde el casco urbano. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34106','mirador','Mirador de la Ermita de Nuestra Señora de Castellanos','Sencilla atalaya castellana que regala atardeceres limpios sobre un mar infinito de secano que linda con Valladolid, con una nota de 7.0/10. Cómo llegar: Pradera exterior del templo rural, al sur del término municipal. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34107','mirador','Mirador de la Ermita de San Lorenzo','Panorámica sobre el Valle de la Ojeda, campos de leguminosas y los pequeños bosques de roble melojo dispersos, con una nota de 7.6/10. Cómo llegar: Colina rocosa de San Lorenzo accesible por pista desde Berzosa de los Hidalgos. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34108','mirador','Mirador del Castillo de Monzón de Campos','Imponente atalaya militar del siglo XIV con vistas excepcionales de la vega del río Carrión y la llanura palentina, con una nota de 8.4/10. Cómo llegar: Muralla exterior de la fortaleza gótica, accesible por carretera asfaltada desde el pueblo. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34109','mirador','Mirador del Castillo de San Nicolás','Vista limpia del trazado jacobeo que marca el fin de la provincia de Palencia y la antesala de las tierras leonesas, con una nota de 7.3/10. Cómo llegar: Loma de las bodegas subterráneas de San Nicolás del Real Camino. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34110','mirador','Mirador de San Roque / Reserva del Bisón Europeo','Excepcional balcón alpino kárstico donde se pueden avistar ejemplares de bisonte europeo en régimen de semilibertad, con una nota de 8.7/10. Cómo llegar: Estructura elevada de madera en el entorno del Centro de Interpretación del Bisonte (carretera PP-2125). 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34112','mirador','Mirador de San Salvador de Nogal','Vista del entorno románico del monasterio más antiguo de la provincia (965 d.C.) flanqueado por las choperas del río Carrión, con una nota de 7.4/10. Cómo llegar: Ribera sobreelevada frente a las ruinas del cenobio cisterciense. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34113','mirador','Mirador del Boedo Medio','Sencilla perspectiva sobre los relieves suaves del piedemonte y las pequeñas explotaciones agrícolas tradicionales, con una nota de 7.2/10. Cómo llegar: Alto de la loma arcillosa que cobija las bodegas de la localidad. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34114','mirador','Mirador del Monasterio de Santa Eufemia de Cozuelos','Atalaya sobre una joya del románico palentino integrada en un idílico valle rodeado de encinares y robles bajos, con una nota de 8.0/10. Cómo llegar: Senda forestal sobreelevada que parte del complejo histórico de la granja de Cozuelos. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34116','mirador','Mirador del Pisuerga Alto Medio','Panorámica sobre el cauce ancho del río Pisuerga y las ricas vegas hortícolas tradicionales en el límite con Burgos, con una nota de 7.5/10. Cómo llegar: Extremo este de los cortados arcillosos del núcleo urbano. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34901','mirador','Mirador del Yacimiento de Dessobriga','Atalaya histórica y arqueológica sobre un oppidum celta y romano dominando las vegas fluviales del Pisuerga y el Valdavia, con una nota de 8.1/10. Cómo llegar: Alto de las Cuestas, accesible por sendas señalizadas desde las afueras de Osorno. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34120','mirador','Mirador del Cristo del Otero','Espectacular e icónica vista cenital de la ciudad de Palencia y Tierra de Campos a los pies del imponente cristo monumental de Victorio Macho, con una nota de 8.9/10. Cómo llegar: Explanada y ermita excavada bajo los pies del Cristo, accesible por carretera asfaltada. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34121','mirador','Mirador de las Ruinas de Santa Eulalia','Hermosa vista aérea de los lienzos medievales de la villa histórica, la vega del río Arlanza y las colinas cubiertas de yeso, con una nota de 8.3/10. Cómo llegar: Cerro de la Iglesia de Santa Eulalia, zona de las antiguas eras altas. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34122','mirador','Mirador del Páramo del Boedo','Horizonte despejado sobre la paramera que marca la divisoria de aguas entre los valles del Boedo y del Burejo, con una nota de 7.1/10. Cómo llegar: Punto kilométrico elevado de la carretera provincial PP-2223. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34123','mirador','Mirador de la Torre de San Martín','Vista de los extraordinarios e históricos tejados mudéjares y azulejos esmaltados que sobresalen en la inmensidad de la meseta, con una nota de 8.2/10. Cómo llegar: Cuerpo alto de la torre mudéjar, accesible mediante visita turística. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34124','mirador','Mirador de la Ojeda Central','Balcón sobre los pequeños campos cultivados de regadío tradicional cercados por matorrales mediterráneos y robledales bajos, con una nota de 7.3/10. Cómo llegar: Camino elevado forestal transitable que comunica Payo con la loma norte. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34125','mirador','Mirador de las Eras del Secano','Paisaje puramente cerealista caracterizado por la presencia aislada de palomares tradicionales de barro circulares, con una nota de 6.7/10. Cómo llegar: Camino vecinal elevado junto a los silos agrícolas de la localidad. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34126','mirador','Mirador de la Villa Romana de La Olmeda','Observatorio arquitectónico y arqueológico sobre el mayor y más espectacular conjunto de mosaicos romanos de España integrado en la vega, con una nota de 8.6/10. Cómo llegar: Pasarelas del interior de la cubierta del yacimiento arqueológico, en Gañinas de la Vega. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34904','mirador','Mirador de Piedrasluengas','Uno de los miradores más espectaculares de la Cordillera Cantábrica; una pasarela colgada sobre el abismo del Valle de Liébana y los Picos de Europa, con una nota de 9.3/10. Cómo llegar: Coronación del puerto de Piedrasluengas (CL-627), con plataforma volada de madera y acero. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34130','mirador','Mirador de la Esclusa de Piña','Vista del Canal de Castilla cruzando de forma rectilínea los maizales y trigales con su hilera de chopos centenarios, con una nota de 7.7/10. Cómo llegar: Entorno de la esclusa número 17 del ramal de Campos, acceso peatonal por el andadero. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34132','mirador','Mirador del Río Ucieza','Vista del cauce modesto flanqueado por las huertas tradicionales y el andadero arbolado que da cobijo a los peregrinos jacobeos, con una nota de 7.4/10. Cómo llegar: Ermita de Nuestra Señora del Socorro, junto a la ruta del Camino de Santiago Francés. ¿Continuamos de inmediato con los siguientes municipios de la provincia de Palencia (Población de Cerrato, Polentinos, Pomar de Valdivia, Poza de la Vega...) para liquidar esta región?.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34133','mirador','Mirador del Arroyo del Valle','Atalaya sobre las lomas calizas y yesosas típicas del Cerrato palentino bajo, con una nota de 7.2/10. Cómo llegar: Camino alto que corona las bodegas tradicionales en la vertiente sur del casco urbano. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34134','mirador','Mirador del Valle de Polentinos / Embalse de Requejada','Impresionante balcón alpino rodeado de densos robledales y brezales de alta montaña en pleno Parque Natural de la Montaña Palentina, con una nota de 9.1/10. Cómo llegar: Senda forestal que asciende desde la localidad hacia el cordal montañoso del norte. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34135','mirador','Mirador de Covalagua / Las Tuerces','Espectacular paisaje kárstico de callejones y monolitos de piedra esculpidos por la erosión, con un gran atractivo para la fotografía geomorfológica, con una nota de 8.9/10. Cómo llegar: Aparcamiento superior del Espacio Natural de Covalagua, límite provincial con Burgos. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34136','mirador','Mirador de la Vega Alta','Vista de campos cerealistas y huertas tradicionales regadas por el arroyo de la Cueza, con una nota de 7.1/10. Cómo llegar: Vértice elevado junto al depósito de agua de San Martín de la Cueza. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34137','mirador','Mirador de las Eras del Pozo','Horizonte plano caracterizado por la inmensidad de las parcelas de cereal de secano y palomares tradicionales de adobe circulares, con una nota de 6.6/10. Cómo llegar: Pista agrícola elevada que corona la loma norte de la localidad. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34139','mirador','Mirador de la Ermita de San Pedro','Vista limpia del discurrir del valle de la Ojeda, campos de secano e hileras de robles bajos de la meseta norteña, con una nota de 7.7/10. Cómo llegar: Explanada exterior del templo románico, accesible por pista forestal desde Prádanos. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34140','mirador','Mirador de la Vega de Valdavia Alta','Panorámica sobre el discurrir del río Valdavia entre sotos forestales de alisos y praderas ganaderas, con una nota de 7.4/10. Cómo llegar: Carretera provincial PP-2224 a su paso por el cerro testigo occidental. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34141','mirador','Mirador del Puente Romano sobre el Arlanza','Vista del majestuoso viaducto de sillería de dieciocho ojos y de las alamedas que custodian el cauce bajo del río Arlanza, con una nota de 7.6/10. Cómo llegar: Paseo fluvial perimetral, accesible a pie desde la zona recreativa urbana. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34143','mirador','Mirador del Valle del Carrión Medio','Atalaya sobre los mosaicos agrarios y plantaciones industriales de chopos que flanquean la gran cuenca fluvial, con una nota de 7.5/10. Cómo llegar: Alto de la colina arcillosa que corona la localidad de Villaproviano. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34146','mirador','Mirador de las Cuestas de Reinoso','Típica estampa del Cerrato con sus taludes calcáreos y lomas cubiertas de matorral mediterráneo aromático, con una nota de 7.3/10. Cómo llegar: Corona superior de la ladera este donde se asientan las bodegas de la villa. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34147','mirador','Mirador del Monasterio de Santa María de la Vega','Vista de las ruinas mudéjares del cenobio cisterciense integradas en la vega forestal del río Carrión, con una nota de 7.5/10. Cómo llegar: Ladera sobreelevada frente a las ruinas del monasterio, acceso rural. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34155','mirador','Mirador del Monasterio de Santa Cruz','Perspectiva histórica del entorno monacal románico-gótico dominando la vega donde se cruzan el río Carrión y el Canal de Castilla, con una nota de 7.8/10. Cómo llegar: Camino elevado de servicio del canal a su paso por el término. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34157','mirador','Mirador del Castillo de los Duques de Infantado','Excelente estampa de la villa ducal saldañesa, su plaza vieja y las ricas vegas del río Carrión desde los muros de su fortaleza medieval, con una nota de 8.4/10. Cómo llegar: Cima del cerro del Castillo, accesible por rampa empinada desde el casco histórico. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34158','mirador','Mirador del Puente Medieval','Vista aérea del cauce ancho y pedregoso del río Pisuerga franqueado por alisos y el viaducto de cantería de nueve ojos, con una nota de 8.2/10. Cómo llegar: Senda del robledal, zona norte sobreelevada de la villa. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34159','mirador','Mirador de la Esclusa de San Cebrián','Vista del Canal de Castilla cruzando de forma rectilínea los trigales con su hilera de chopos e instalaciones hidráulicas tradicionales, con una nota de 7.6/10. Cómo llegar: Entorno de la esclusa número 15 del ramal de Campos, acceso peatonal. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34160','mirador','Mirador del Observatorio Astronómico / Reserva del Bisón','Cielos de altísima nitidez para el astroturismo combinados con la observación de bisontes europeos en semilibertad, con una nota de 8.8/10. Cómo llegar: Cima de la colina acondicionada junto al centro de interpretación astronómico. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34161','mirador','Mirador del Boedo Bajo','Sencilla y despejada perspectiva de los campos de secano que marcan el pulso rural de la comarca, con una nota de 7.1/10. Cómo llegar: Camino rural elevado adyacente a los silos agrícolas de la localidad. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34163','mirador','Mirador de la Traza Jacobea','Observatorio lineal de la llanura y de los andaderos arbolados que cobijan a los peregrinos en dirección a Carrión, con una nota de 6.9/10. Cómo llegar: Descansadero señalizado en la ruta peatonal del Camino de Santiago. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34165','mirador','Mirador de la Cueza','Vista de la llanura arcillosa y del cauce modesto del río Cueza rodeado de extensos campos de secano, con una nota de 6.8/10. Cómo llegar: Zona de las antiguas eras altas del pueblo, junto al depósito elevado. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34167','mirador','Mirador de las Eras del Alcor','Atalaya sobre los campos de cereal y el característico relieve de los Montes Torozos palentinos, con una nota de 7.4/10. Cómo llegar: Camino superior de los silos, al oeste del casco urbano. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34168','mirador','Mirador de la Ojeda Central','Balcón sobre los pequeños campos cultivados cercados por matorrales mediterráneos y robledales bajos, con una nota de 7.1/10. Cómo llegar: Camino elevado forestal transitable que comunica con el término de Hijosa de Boedo. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34169','mirador','Mirador del Río Carrión Bajo','Perspectiva diáfana de los regadíos tradicionales de maíz y de las alamedas que protegen el curso fluvial, con una nota de 7.5/10. Cómo llegar: Senda de pescadores junto a la balsa de agua del término. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34171','mirador','Mirador del Santuario de la Virgen del Brezo','Impresionante atalaya mariana colgada a las faldas de la Peña Aviñante, con panorámicas colosales de los valles del norte, con una nota de 8.9/10. Cómo llegar: Gran explanada del Santuario del Brezo, accesible por carretera local asfaltada. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34170','mirador','Mirador del Monasterio de San Andrés de Arroyo','Espectacular vista de una joya del románico cisterciense y su claustro calado integrada en un recóndito y verde valle, con una nota de 8.3/10. Cómo llegar: Sendero forestal sobreelevada que parte del complejo histórico del monasterio. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34174','mirador','Mirador de la Iglesia de San Juan','Vista de la imponente iglesia góticorenacentista y de la llanura agrícola que rodea la villa histórica, con una nota de 7.4/10. Cómo llegar: Entorno sobreelevado de la plaza de la iglesia, casco urbano. ¿Continuamos de inmediato con los municipios de Palencia de la T a la Z (Tariego de Cerrato, Torquemada, Velilla del Río Carrión, Venta de Baños, Villamuriel, Villamediana...) para liquidar la provincia?.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34181','mirador','Mirador de la Cruz / El Castro','Excelente balcón sobre la vega del río Pisuerga y el nudo ferroviario de Venta de Baños, enclavado en un cerro horadado por bodegas y antiguas cuevas, con una nota de 8.4/10. Cómo llegar: Cima del cerro de la Cruz, accesible por pista asfaltada desde el casco urbano. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34182','mirador','Mirador del Puente de los Veinticinco Ojos','Espectacular vista del colosal puente de sillería del siglo XVI sobre el río Pisuerga y su denso soto arbolado, cuna de vinos y huertas, con una nota de 8.0/10. Cómo llegar: Margen izquierda del río Pisuerga, en la zona recreativa junto al puente. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34184','mirador','Mirador del Castillo de Torremormojón','Atalaya histórica apodada la "Estrella de Campos" que domina visualmente las llanuras agrícolas y los restos de las fortificaciones de mampostería, con una nota de 7.8/10. Cómo llegar: Cerro testigo que corona el pueblo, accesible por sendero desde la base. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34185','mirador','Mirador del Valle de Miranda / Curavacas','Impresionante panorámica del Parque Natural de la Montaña Palentina, con vistas limpias a la cara sur del pico Curavacas y las aguas verdes del embalse de Camporredondo, con una nota de 9.2/10. Cómo llegar: Carretera P-210 (Ruta de los Pantanos), apartadero acondicionado cerca de Vidrieros. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34192','mirador','Mirador del Río Ucieza (Robladillo)','Sencilla vista de los campos de cereal de secano y los chopos que flanquean el cauce modesto del río, con una nota de 7.2/10. Cómo llegar: Pista agrícola elevada que comunica el núcleo de Robladillo de Ucieza. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34189','mirador','Mirador de la Ermita de la Virgen de la Oliva','Vista del paisaje quebrado del Cerrato, caracterizado por sus lomas yesosas y un singular entramado de bodegas subterráneas, con una nota de 7.5/10. Cómo llegar: Explanada de la ermita, en la zona más alta del término municipal. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34199','mirador','Mirador de Alba / Fuentes Tamáricas','Vertiginoso balcón colgado sobre el cañón del Carrión, las cumbres de Fuentes Carrionas y las misteriosas fuentes intermitentes romanas, con una nota de 9.4/10. Cómo llegar: Pista forestal transitable que sube al Santuario de la Virgen de Alba. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34023','mirador','Mirador de la Basílica de San Juan de Baños','Vista del entorno del templo visigodo del año 661 d.C. (el más antiguo de España) integrado en la fértil vega del río Pisuerga, con una nota de 8.1/10. Cómo llegar: Jardines de la Fuente de Recesvinto en Baños de Cerrato, acceso directo. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34201','mirador','Mirador de las Amuralladas Cuestas','Atalaya sobre un pueblo amurallado del Cerrato con sus calles empinadas empotradas entre páramos y campos de secano, con una nota de 7.6/10. Cómo llegar: Restos del recinto fortificado junto a la Puerta del Postigo. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34234','mirador','Mirador de la Valdavia Media','Sencilla y despejada perspectiva de los campos de cultivo y arboledas bajas que custodian el cauce, con una nota de 7.1/10. Cómo llegar: Camino rural elevado en las inmediaciones del núcleo urbano. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34204','mirador','Mirador de los Páramos de la Sequía','Horizonte plano caracterizado por la inmensidad de las parcelas de cereal del extremo occidental de la meseta, con una nota de 6.6/10. Cómo llegar: Vértice geodésico elevado en el límite norte del término. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34205','mirador','Mirador de los Pozos de Nieve','Atalaya sobre los valles estrechos del Cerrato, dominados por robles melojos y las antiguas estructuras de almacenamiento de hielo, con una nota de 7.4/10. Cómo llegar: Pista que sube al páramo calizo desde el casco urbano. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34206','mirador','Mirador del Río Sequillo','Vista de la llanura arcillosa de Tierra de Campos con las alamedas que protegen el modesto curso del Sequillo, con una nota de 7.5/10. Cómo llegar: Zona de las antiguas eras altas del pueblo, junto al paseo del río. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34208','mirador','Mirador del Valle de Valdavia','Vista panorámica sobre el discurrir del arroyo y las lomas cubiertas de matorral mediterráneo, con una nota de 7.2/10. Cómo llegar: Alto de la colina arcillosa que corona las bodegas locales. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34211','mirador','Mirador de los Palomares de San Pedro','Horizonte nítido sobre la estepa cerealista caracterizado por la presencia aislada de palomares tradicionales de adobe, con una nota de 7.3/10. Cómo llegar: Camino vecinal elevado junto a los silos agrícolas de la localidad. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34210','mirador','Mirador de las Vegas de la Cerrato','Panorámica sobre los campos de secano que marcan la transición hacia las tierras burgalesas, con una nota de 7.1/10. Cómo llegar: Camino de sirga fluvial elevado accesible desde el pueblo. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34213','mirador','Mirador del Pisuerga Medio','Balcón sobre los meandros del río Pisuerga, sus alamedas simétricas y acequias agrarias, con una nota de 7.4/10. Cómo llegar: Extremo este de los cortados arcillosos del casco urbano. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34214','mirador','Mirador de las Riberas del Carrión','Atalaya sobre los prados ganaderos y choperas simétricas que marcan la entrada del Carrión en la meseta, con una nota de 7.6/10. Cómo llegar: Loma arcillosa superior accesible por pistas rurales. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34215','mirador','Mirador de la Basílica de Santa María la Blanca','Vista monumental de la imponente iglesia-fortaleza templaria del siglo XIII alzándose de forma majestuosa sobre el plano de Tierra de Campos, con una nota de 8.3/10. Cómo llegar: Explanada de la plaza de la Basílica, hito clave del Camino de Santiago Francés. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34220','mirador','Mirador de la Casa del Mayorazgo','Vista de la llanura palentina e instalaciones agrícolas tradicionales integradas en la estepa cerealista, con una nota de 7.3/10. Cómo llegar: Zona de las antiguas eras del pueblo, junto al depósito elevado. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34221','mirador','Mirador del Castillo de Villamediana','Atalaya sobre las vegas agrícolas del río de la villa y las lomas cubiertas de yeso del Cerrato norteño, con una nota de 7.6/10. Cómo llegar: Cerros superiores fortificados donde se asientan las ruinas de la antigua torre. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34222','mirador','Mirador del Valle de Boedo','Sencilla y despejada perspectiva de los campos de secano que marcan el pulso de la Ojeda baja, con una nota de 7.2/10. Cómo llegar: Camino elevado forestal transitable que comunica con el término. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34225','mirador','Mirador de la Iglesia Fortificada de Santa María','Espectacular vista del templo románicogótico del siglo XIII y del ramal del Sur del Canal de Castilla integrados en el área metropolitana, con una nota de 8.2/10. Cómo llegar: Plaza de la Iglesia, casco histórico sobreelevado de la villa. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34224','mirador','Mirador de la Cueza Media','Paisaje puramente cerealista caracterizado por la presencia aislada de palomares tradicionales de barro circulares, con una nota de 6.7/10. Cómo llegar: Camino vecinal elevado junto a los silos agrícolas de la localidad. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34241','mirador','Mirador del Pisuerga Bajo','Vista del cauce modesto flanqueado por las huertas tradicionales en el límite provincial con Burgos, con una nota de 7.0/10. Cómo llegar: Mota elevada de protección fluvial, accesible desde el paseo del río. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34242','mirador','Mirador de la Vega del Arlanzón','Panorámica sobre el discurrir del río Arlanzón entre sotos de alisos en el extremo oriental de la provincia, con una nota de 7.2/10. Cómo llegar: Puente rural elevado sobre el cauce en el límite del término. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34243','mirador','Mirador del Puente del Río Carrión','Vista panorámica sobre el lecho pedregoso del río Carrión y las alamedas que lo flanquean en la comarca de la Cueza, con una nota de 7.5/10. Cómo llegar: Área de descanso junto al viaducto de la carretera provincial. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34245','mirador','Mirador del Páramo Llano','Paisaje agrícola rectilíneo dominado por los modernos sistemas de regadío y campos de secano infinitos, con una nota de 6.6/10. Cómo llegar: Carretera provincial a su paso por el término municipal. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34229','mirador','Mirador del Valle de Valdavia','Vista del cauce medio del río Valdavia y las llanuras agrícolas que marcan el pulso rural de la zona, con una nota de 7.1/10. Cómo llegar: Senda forestal que asciende a los páramos occidentales. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34230','mirador','Mirador de la Traza Jacobea','Observatorio lineal de la llanura y de los andaderos arbolados que cobijan a los peregrinos en dirección a Frómista, con una nota de 6.9/10. Cómo llegar: Descansadero señalizado en la ruta peatonal del Camino de Santiago. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34231','mirador','Mirador del Río Ucieza','Vista del cauce modesto flanqueado por las huertas tradicionales y choperas simétricas de la comarca, con una nota de 7.1/10. Cómo llegar: Pistas rurales que bordean el canal secundario de riego. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34233','mirador','Mirador del Otero de Villasarracino','Atalaya sobre los campos de cereal y los pequeños valles que marcan la transición hacia la comarca de la Ojeda, con una nota de 7.3/10. Cómo llegar: Camino superior de los silos, al oeste del casco urbano. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34236','mirador','Mirador de la Cueza Baja','Paisaje puramente cerealista caracterizado por la presencia de palomares tradicionales aislados de barro, con una nota de 6.9/10. Cómo llegar: Pista agrícola elevada que corona la loma norte. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34237','mirador','Mirador de la Casa del Rey / Canal de Castilla','Vista del ramal de Campos del Canal de Castilla y de los históricos astilleros donde se construían las barcazas de transporte de grano, con una nota de 7.8/10. Cómo llegar: Museo del Canal de Castilla, entorno de la dársena transitable a pie. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34240','mirador','Mirador de la Estepa de Villerías','Horizonte llano e infinito de la meseta, idóneo para la fotografía de paisaje minimalista y avistamiento de aves esteparias, con una nota de 6.7/10. Cómo llegar: Camino vecinal elevado junto a los silos agrícolas. 📍 Provincia: Palencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90103','mirador','Mirador de la Bureba Occidental','Atalaya sobre los campos de cereal de la llanura de la Bureba y las estribaciones calcáreas de la Sierra de Cantabria al fondo, con una nota de 7.5/10. Cómo llegar: Camino elevado junto a la Iglesia románica de Santa María, en la zona alta del pueblo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90104','mirador','Mirador del Valle del Riaza','Vista panorámica de los viñedos de la Ribera del Duero y del curso forestal del río Riaza entre lomas calizas y yesosas, con una nota de 7.6/10. Cómo llegar: Cuesta de las Bodegas tradicionales, extremo superior accesible a pie. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90105','mirador','Mirador del Valle de Caderechas','Preciosa vista de los huertos de cerezos y manzanos encajonados en un anfiteatro rocoso, espectacular durante la floración primaveral, con una nota de 8.3/10. Cómo llegar: Puerto de Altotero, carretera local que desciende hacia Quintanaopio. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90106','mirador','Alto de la Ermita de San Guillermo','5.2/10. Panorámica rural de los campos agrícolas de La Bureba y las elevaciones circundantes de la Sierra de la Demanda al fondo. Cómo llegar: Cresta caliza al este del casco urbano junto a los caminos de labor. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90108','mirador','Explanada del Monumento del cerro de San Miguel','6.1/10. Amplia perspectiva de la cuenca del río Oca y el somontano de la Brújula desde el emplazamiento de la torre monumental. Cómo llegar: Alto de San Miguel, desvío señalizado desde la carretera BU-710. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90109','mirador','Alto de Carrales (Monte Hijedo)','7.8/10. Espectaculares vistas de la transición hacia los bosques atlánticos del Monte Hijedo y los cortados rocosos meridionales de la Cordillera Cantábrica. Cómo llegar: Puerto de Carrales en la carretera N-623, límite con Valderredible. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09907','mirador','Páramo de Quintanadueñas','5.8/10. Vista despejada de la vega del río Ubierna, los polígonos del norte de la capital provincial y el inicio de los llanos del norte. Cómo llegar: Borde del talud del páramo subiendo por el camino rural desde el cementerio local. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90110','mirador','Mirador del Embalse del Ebro (Santa Gadea)','7.6/10. Gran panorámica de las playas continentales, los pinares del entorno de Arija y la lámina de agua de la zona oriental del embalse. Cómo llegar: Ribera boscosa elevada junto a la carretera BU-642, cerca de la localidad. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90111','mirador','Campa de la ermita de San Juan','6.2/10. Perspectiva elevada sobre los llanos de Miranda de Ebro, los viñedos limítrofes con La Rioja y la silueta escarpada de los Montes Obarenes. Cómo llegar: Ladera sur del monte, pista forestal que arranca desde el depósito de aguas del pueblo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90112','mirador','Peña del Mazo','6.4/10. Vista del desfiladero natural del río Oroncillo y la autovía del Norte encajonada entre las paredes de los Montes Obarenes. Cómo llegar: Sendero de montaña que asciende desde el cementerio de Ameyugo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90113','mirador','Alto de los Viñedos','5.5/10. Vistas rústicas y estéticas de los mares de viñedos de la Ribera del Duero en las parameras altas del municipio. Cómo llegar: Camino rural que asciende al altiplano septentrional del término municipal. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90114','mirador','Alto del Cuerno','5.9/10. Vista de los valles fluviales de los ríos Arandilla y Bañuelos junto al patrimonio de choperas y encinares anexos. Cómo llegar: Cerro testigo ubicado al noreste del pueblo, accesible por el camino vecinal de Coruña del Conde. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90115','mirador','Mirador de Pinilla','6.9/10. Magnífica visual de la masa forestal de pinos de la Sierra de la Demanda meridional y los cañones kársticos excavados en el término. Cómo llegar: Pista forestal maderera del sector este, subiendo hacia el límite provincial con Soria. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09021','mirador','Cerro de San Miguel','5.7/10. Observación del cauce del río Aranzuelo, los campos cerealistas y las laderas cubiertas de sabinas y pinos albares. Cómo llegar: Senda peatonal desde la iglesia parroquial hacia el alto del cerro homónimo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09022','mirador','Mirador de la Dehesa','5.6/10. Panorámica de media montaña sobre encinares protegidos y el cauce del río Bañuelos en su tramo alto. Cómo llegar: Monte público al noroeste del casco urbano, accesible mediante senderos locales. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09024','mirador','Cuesta del Moro','5.3/10. Vista del ancho cauce del río Pisuerga, sus choperas asociadas y el límite fronterizo con la provincia de Palencia. Cómo llegar: Camino rural escarpado situado al norte de las bodegas tradicionales. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09025','mirador','Mirador del Villeguillo','7.7/10. Excelente panorámica lacustre del Embalse del Ebro con el reflejo de la Cordillera Cantábrica y las antiguas instalaciones industriales de vidrio. Cómo llegar: Paseo marítimo/lacustre al norte del barrio de la Fábrica. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09026','mirador','Mirador del Embalse de Úzquiza','7.5/10. Vistas de gran valor natural del pantano de Úzquiza encajonado entre los espesos robledales y hayedos del norte de la Demanda. Cómo llegar: Área recreativa junto a la carretera BU-820, con estacionamiento habilitado. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09027','mirador','Alto de la Brújula (Páramo)','6.0/10. Amplia estampa de los parques eólicos instalados en los páramos burgaleses y el encajonamiento natural del puerto de la Brújula. Cómo llegar: Antigua carretera nacional N-I, desvío hacia las pistas de servicio del parque eólico. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09029','mirador','Mirador de la Trinchera del Ferrocarril','6.8/10. Interés didáctico y visual de la Sierra de Atapuerca, el valle de la Bureba y los yacimientos arqueológicos declarados Patrimonio de la Humanidad. Cómo llegar: Plataforma superior habilitada junto al centro de visitas de los yacimientos. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09030','mirador','Castillo de los Ausines (San Juan)','6.5/10. Perspectiva única de los tres barrios (San Juan, Sopeña y Quintanilla) encajonados en el cañón del río Papasolas. Cómo llegar: Ruinas de la fortaleza sobre el peñón rocoso que domina el término municipal. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09032','mirador','El Cotarro','5.2/10. Vista agrícola del valle del Arlanza medio, dominada por extensos sembrados e hileras aisladas de encinas. Cómo llegar: Vértice geodésico situado al sur del núcleo rural, pista vecinal de labor. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09033','mirador','Ermita de Henar','5.4/10. Paisaje lineal del Valle del Esgueva con sus laderas calcáreas marcadas por la erosión y campos de secano. Cómo llegar: Colina exenta al oeste del municipio, acceso directo desde el núcleo urbano. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09034','mirador','Mirador de la Iglesia de San Millán','6.0/10. Vistas del patrimonio monumental del propio pueblo con su fisonomía de ladera y la vega esteparia de Odra-Pisuerga. Cómo llegar: Atrio fortificado elevado de la Parroquia de San Millán, acceso urbano peatonal. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09035','mirador','Alto de Santa María','5.8/10. Vista del entorno de los yacimientos romanos de la Villa de Santa Cruz y los característicos viñedos del noreste ribereño. Cómo llegar: Cerro sobre los lagares tradicionales, subiendo por camino de tierra desde la BU-910. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09036','mirador','Alto de San Cristóbal','5.3/10. Perspectiva de la llanada de la Bureba burgalesa orientada hacia los perfiles montañosos de los Montes Obarenes occidentales. Cómo llegar: Elevación agrícola al norte del núcleo, accesible por caminos rurales. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09037','mirador','Puerto de El Manquillo','7.9/10. Impresionante estampa de alta montaña con extensos hayedos, dehesas de robles y las cumbres de la Sierra de la Demanda central. Cómo llegar: Alto del puerto de montaña en la carretera provincial BU-825. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09039','mirador','Mirador de San Millán','7.2/10. Vista del cauce alto del río Pedroso encajado entre riscos rocosos y bosques de robles melojos de alto valor natural. Cómo llegar: Sendero que asciende por la ladera sur, partiendo de las eras del pueblo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09041','mirador','Ladera del Castillo','5.0/10. Llanura agrícola típica de la comarca del Arlanza con perfiles horizontales y campos abiertos de cereal. Cómo llegar: Elevación natural adosada al pequeño núcleo urbano, acceso a pie. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09044','mirador','Alto de la Rebolleda','6.1/10. Atractivo forestal sobre las laderas repobladas de coníferas y los valles de cabecera que vierten hacia el río Oca. Cómo llegar: Camino rural forestal que enlaza los núcleos del municipio. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09043','mirador','Mirador de las Canteras','5.5/10. Visión horizontal del curso del río Oca cuando se adentra en la llanura agrícola burebana. Cómo llegar: Pequeña meseta de antiguos depósitos de piedra al este de Solduengo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09045','mirador','Mirador del Hundimiento del Río Rudrón','7.4/10. Gran valor geológico. Vista de la espectacular surgencia y sumidero kárstico donde el río se infiltra en las entrañas de la lora caliza. Cómo llegar: Pista peatonal señalizada desde el casco urbano de Barrio Panizares. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09048','mirador','Mirador del Castillo de Belorado','6.4/10. Vista del casco histórico medieval, el discurrir del río Tirón y el trazado del Camino de Santiago Francés. Cómo llegar: Ruinas de la fortaleza en el cerro que corona el núcleo urbano, acceso peatonal acondicionado. Siguiente bloque listo para procesar a partir de Berberana. ¿Continuamos con la misma velocidad masiva?.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09050','mirador','Mirador del Salto del Nervión','7.7/10. Impresionante panorámica del cañón de Delika y la espectacular cascada de más de 220 metros de caída libre en época de deshielo. Cómo llegar: Borde del desfiladero, acceso peatonal desde el aparcamiento del Monumento Natural del Monte Santiago. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09051','mirador','Confluencia del Riaza y Duero','5.4/10. Vista fluvial llana de la rica vega agrícola y las densas choperas de ribera donde se unen ambos cursos de agua. Cómo llegar: Camino de sirga y pescadores accesible desde el casco urbano hacia el sur. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09052','mirador','Alto de la Venta','5.3/10. Amplia panorámica de los campos cerealistas del norte de La Bureba, flanqueada por la silueta lejana de los Montes Obarenes. Cómo llegar: Camino rural elevado que parte del depósito de agua municipal. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05033','mirador','Alto de San Cristóbal','5.3/10. Sencilla visual de llanuras alomadas agrarias colindantes con la provincia de Salamanca. Cómo llegar: Vértice de labor al norte del pueblo, por pistas agrarias. Siguiente bloque de Ávila listo para procesar a partir de Blasconuño de Matacabras. ¿Continuamos con este despliegue masivo e inmediato?.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47020','mirador','Atrio de la Iglesia de San Matías','5.4/10 Vista llana y despejada sobre campos de regadío, cultivos tradicionales y la sobria llanura meridional vallisoletana de horizontes limpios. Cómo llegar: Plaza central elevada donde se asienta la estructura del templo parroquial. 📍 Provincia: Valladolid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09054','mirador','Mirador de Portilla','7.1/10. Vista espectacular del desfiladero de Sobrón, el río Ebro encajonado y las escarpadas laderas boscosas que delimitan con el País Vasco. Cómo llegar: Senda de montaña que asciende desde el núcleo de Portilla hacia los riscos. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09055','mirador','Alto de la Ermita del Cristo','5.5/10. Perspectiva rural sobre el valle del río Pilde y los extensos cultivos de secano colindantes con la provincia de Soria. Cómo llegar: Explanada de la ermita, situada en una elevación al noreste del pueblo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09002','mirador','Mirador de los Pinos (Santuario de Santa Casilda)','6.3/10. Gran panorámica de la llanura de la capital de La Bureba y los agrestes paisajes calizos que rodean el escarpado santuario. Cómo llegar: Aparcamiento superior y entorno del Santuario de Santa Casilda, acceso por la carretera BU-V-5103. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09057','mirador','Alto de Mostelares','6.6/10. Vista estratégica del Monasterio de Santa María de de Bugedo y el paso natural del desfiladero de Pancorbo. Cómo llegar: Cresta rocosa accesible por senderos de montaña desde el entorno del monasterio. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09058','mirador','Cuesta de la Vega','5.3/10. Vista sobre la desembocadura del río Arlanzón y las infraestructuras de transporte que surcan el valle periurbano. Cómo llegar: Altiplano agrícola situado al oeste del núcleo urbano por caminos forestales. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09060','mirador','Alto de la Rasa','6.0/10. Vista panorámica de la transición entre la cuenca agrícola burebana y los frondosos bosques de los Montes Obarenes. Cómo llegar: Camino maderero que sube hacia la vertiente norte desde el pueblo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09061','mirador','Páramo de San Pedro','5.6/10. Típica estampa del Valle del Esgueva con sus vertientes asimétricas, encinares dispersos y parcelas de cultivo. Cómo llegar: Meseta caliza al norte del municipio, accesible por pistas de parcelaria. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09062','mirador','Mirador del Torruco','6.8/10. Vista de media montaña sobre el valle de pinares albares y los afloramientos calcáreos de la Sierra de la Demanda meridional. Cómo llegar: Vértice geodésico en el punto más alto del cerro calizo del Torruco. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09004','mirador','Mirador de la Peña de San Jorge','6.4/10. Vista panorámica del conjunto monumental del Convento de Santo Domingo, el torreón de los Guzmanes y los campos de sabinas de la Ribera. Cómo llegar: Pico rocoso habilitado con escaleras que corona el casco urbano. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09065','mirador','Cerro del Carrascal','5.5/10. Amplia panorámica de la llanura vitivinícola de la Ribera del Duero y los horizontes llanos de la frontera salmantina y segoviana. Cómo llegar: Camino rural elevado entre las viñas viejas al sur del término. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09066','mirador','Alto de San Carlos','6.7/10. Espectaculares vistas de la Sierra de las Mamblas y el valle del Arlanza alto, rodeado de densas formaciones de encina y roble. Cómo llegar: Pista forestal que asciende hacia la meseta caliza desde la carretera BU-V-8203. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09067','mirador','Mirador de Revenga','7.6/10. Vista sobre el comunero de Revenga, el mar de pinos de la Sierra de Pinares y el relieve montañoso del Parque Natural de Urbión. Cómo llegar: Paraje boscoso elevado sobre la ermita de Revenga, acceso por la pista forestal BU-822. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09068','mirador','Mirador de la dehesa de Caderechas','6.2/10. Hermosa estampa estacional de los valles frutales y de cerezos en flor encajonados en los pliegues de la Cordillera Cantábrica. Cómo llegar: Pista rural que sube hacia los montes calcáreos que flanquean el valle. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09070','mirador','Mirador de la Peña de Carazo (Soncarazo)','7.3/10. Impresionante farallón calizo con vistas infinitas al cementerio de Sad Hill, el valle de Tabladillo y el Espacio Natural de Sabinares del Arlanza. Cómo llegar: Cumbre de la mesa tabular caliza de Carazo, sendero empinado a pie desde el casco urbano. Siguiente bloque listo para procesar a partir de Carcedo de Bureba. ¿Mantenemos el ritmo ininterrumpido?.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09071','mirador','Alto de Santa Eulalia','5.4/10. Visual nítida del valle del río Oca y la silueta rural de la Iglesia Románica de Santa Eulalia sobre el montículo. Cómo llegar: Entorno elevado de la iglesia parroquial, acceso directo desde el casco urbano. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09072','mirador','Alto de la Muela','5.6/10. Vista del corredor periurbano del sureste de Burgos, campos de labranza y el valle del río Ausín. Cómo llegar: Cresta del páramo accesible por pistas agrícolas desde la carretera BU-P-8002. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09073','mirador','Mirador de la Vía Verde','5.8/10. Vista de valles sinuosos y llanuras cerealistas sobre el antiguo trazado ferroviario SantanderMediterráneo rodeado de naturaleza. Cómo llegar: Descanso habilitado en el trazado de la Vía Verde a la altura del término municipal. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09074','mirador','Alto de San Medel','5.7/10. Amplia panorámica de la llanura aluvial del río Arlanzón y el nudo de comunicaciones del este de la capital. Cómo llegar: Elevación junto a la autovía del Camino de Santiago (A-12), acceso por pistas de servicio. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09075','mirador','Alto de la Cuesta','5.9/10. Perspectiva abierta del Valle del Riopico y la meseta cerealista donde confluyen los peregrinos del Camino de Santiago. Cómo llegar: Sendero del Camino de Santiago Francés en su descenso hacia Villalval. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09076','mirador','Alto del Pericón','5.3/10. Sencillo mirador rural sobre las laderas arcillosas de la Bureba oriental y pequeñas plantaciones forestales. Cómo llegar: Vértice de labor al norte del pueblo, accesible mediante camino de tierra. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09077','mirador','Mirador de los Montes Obarenes','6.4/10. Excelente panorámica de los escarpes rocosos del Parque Natural y los fértiles campos frutales que crecen a sus pies. Cómo llegar: Camino de ascensión montañosa que parte desde la zona norte del casco urbano. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09078','mirador','Alto de San Pedro','7.1/10. Magníficas vistas del desfiladero del río Arlanza y los cortados calizos calcáreos de la Sierra de las Mamblas. Cómo llegar: Sendero que sube hacia los riscos calizos desde el camino tradicional de Barbadillo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09079','mirador','Alto de San Cristóbal','5.1/10. Paisaje totalmente diáfano y horizontal de la comarca de Odra-Pisuerga, dominado por campos de trigo. Cómo llegar: Camino de concentración parcelaria al oeste del pequeño núcleo rural. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09083','mirador','Alto de la Venta (Valle del Oca)','5.8/10. Observación del encajonamiento del río Oca a la sombra de los montes de la Brújula y la carretera N-I. Cómo llegar: Antigua plataforma vial junto al puerto, accesible por camino vecinal. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09082','mirador','Alto de la dehesa','5.5/10. Vista llana del Camino de Santiago Riojano en su transición fronteriza hacia las tierras burgalesas de Belorado. Cómo llegar: Pista agrícola elevada que discurre paralela a la carretera nacional N-120. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09091','mirador','Mirador del Castillo de Castrojeriz','7.5/10. Espectacular e imponente vista de 360 grados sobre el infinito páramo vallisoletano-burgalés y el trazado urbano del Camino. Cómo llegar: Torre del homenaje y explanada fortificada del cerro testigo que corona la villa monumental. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09084','mirador','Mirador del Alto de la Muela','7.2/10. Excelente panorámica sobre la Sierra de la Demanda meridional, los yacimientos de huellas de dinosaurio y los pinares. Cómo llegar: Área recreativa acondicionada junto a la ermita de Santa Ana, subida asfaltada. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09085','mirador','Cuesta del Rey','5.6/10. Amplia panorámica de la llanura fluvial de la Ribera del Duero y las plantaciones ordenadas de viñedo. Cómo llegar: Altiplano calizo situado al norte de las bodegas tradicionales, desvío de la N-122. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09088','mirador','Alto de Peña Amaya','6.1/10. Vista singular del cauce encajonado del río Pisuerga y los lejanos contrafuertes kársticos de los valles palentinos. Cómo llegar: Sendero local que asciende al cerro testigo situado al norte del núcleo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09086','mirador','Mirador del Monasterio de San Pedro de Cardeña','6.3/10. Vista del histórico monasterio cisterciense integrado en una vaguada de encinares y campos cerealistas. Cómo llegar: Ladera del camino forestal que sube hacia los campos superiores desde el cenobio. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09090','mirador','Alto de la Iglesia','5.2/10. Vista agraria típica del valle del Odra con perfiles planos y horizontes limpios de contaminación visual. Cómo llegar: Plaza elevada junto a la iglesia parroquial de San Esteban, acceso urbano. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40047','mirador','El Castillejo','5.4/10. Atractivo paisaje del Cerrato burgalés marcado por los pequeños arroyos estacionales y los cultivos de secano. Cómo llegar: Promontorio calizo situado inmediatamente encima de las bodegas del pueblo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09063','mirador','Torreón de Cavia','5.8/10. Vista del casco histórico presidido por la casa-fuerte medieval y las dehesas que flanquean el río Arlanzón bajo. Cómo llegar: Entorno elevado de las ruinas defensivas, acceso peatonal desde el núcleo urbano. Siguiente bloque listo para procesar a partir de Cebolleros. ¿Mantenemos el ritmo ininterrumpido?.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09095','mirador','Alto de la Ermita','5.2/10. Sencilla y limpia panorámica agraria sobre la vega baja del río Arlanzón y los campos de secano adyacentes. Cómo llegar: Colina de la ermita local, accesible por camino vecinal de tierra. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09098','mirador','Mirador del Castillo','6.6/10. Estupenda visual del casco histórico riojano-burgalés, las vegas fértiles del río Tirón y el perfil lejano de la Sierra de la Demanda. Cómo llegar: Restos de la fortaleza medieval en lo alto del cerro que domina la villa. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09100','mirador','Alto de la Brújula Meridional','6.1/10. Amplia panorámica de los aerogeneradores de la meseta y las extensas repoblaciones forestales de pinares que lindan con la cuenca del Oca. Cómo llegar: Pista de mantenimiento de los molinos de viento, desvío desde la carretera local. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09101','mirador','El Cotarro Alto','5.3/10. Típica estampa del campo abierto de la comarca del Arlanza, dominada por suaves ondulaciones de cultivos tradicionales. Cómo llegar: Camino de concentración parcelaria al norte del término municipal. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09102','mirador','Mirador del Ebro y de la Cueva de la Meandro','7.6/10. Impresionantes cortados fluviales donde el río Ebro serpentea con fuerza encajonándose antes de entrar en el embalse de Sobrón. Cómo llegar: Senda de gran recorrido (GR-99) a su paso por los riscos altos del término. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09103','mirador','Alto de la Cruz','5.4/10. Vista rústica del suroeste de la provincia, caracterizada por majanos de piedra, campos de trigo y bosquetes de encina. Cómo llegar: Elevación natural con cruz monumental de piedra caliza al oeste del núcleo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09104','mirador','Páramo de San Mamés','5.5/10. Perspectiva elevada sobre el incipiente valle del río Henar y los horizontes limpios del Cerrato burgalés. Cómo llegar: Pista agrícola que asciende a la plataforma del páramo septentrional. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09105','mirador','Alto de la Yecla (Sabinares)','6.8/10. Espectaculares vistas de la cubierta forestal del Parque Natural de los Sabinares del Arlanza y los relieves calizos de Brieva. Cómo llegar: Pista forestal que corona la cresta caliza al norte del casco urbano. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09108','mirador','Alto de la Venta del Grillo','5.3/10. Vista diáfana de la autovía A-1 cruzando la meseta y los extensos campos de labor del sur periurbano de Burgos. Cómo llegar: Antigua elevación junto al trazado vial, accesible por caminos rurales de servicio. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09109','mirador','Mirador de las Conchas de Haro / Obarenes','74/10. Increíble y estratégica vista del paso geológico del río Ebro, los viñedos riojanos y la llanura alavesa desde el enclave. Cómo llegar: Crestas calizas meridionales de los Montes de Vitoria, acceso por pistas de montaña. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09110','mirador','Mirador del Cementerio de Sad Hill','7.5/10. Espectacular anfiteatro natural entre colinas calcáreas donde se recreó el mítico cementerio de la película "El bueno, el feo y el malo". Cómo llegar: Plataforma elevada acondicionada sobre el valle de Arlanza, acceso señalizado desde Contreras. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09112','mirador','Mirador de Diego Marín Aguilera (El Castillo)','6.7/10. Gran valor histórico y paisajístico. Vista del anfiteatro romano de Clunia Sulpicia y el lugar del legendario vuelo en avión de 1793. Cómo llegar: Ruinas de la fortaleza que corona el escarpado cerro testigo sobre el pueblo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09005','mirador','Mirador de la dehesa de Covarrubias','7.7/10. Impresionante estampa del casco urbano medieval de la villa ladeado junto al río Arlanza y flanqueado por las peñas calizas de Carazo. Cómo llegar: Pista forestal elevada que sube hacia los sabinares del sector norte. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09114','mirador','Mirador de las Canteras de Cubillo','5.9/10. Perspectiva sobre los frentes de explotación de la famosa piedra caliza blanca (usada en la Catedral de Burgos) y los encinares. Cómo llegar: Zona perimetral de los antiguos bancos de extracción caliza, acceso por la N-234. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09115','mirador','Alto del Corredor','5.6/10. Vista panorámica del ancho corredor de la Bureba oriental y la cuenca de recepción de las escorrentías hacia el río Oca. Cómo llegar: Camino rural de labor sobre un pequeño altillo cercano a la autopista AP-1. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09117','mirador','Mirador del Duero','5.7/10. Bonita estampa de las curvas fluviales del río Duero, sus frondosas alamedas de ribera y los viñedos con Denominación de Origen. Cómo llegar: Talud natural situado al sur del casco urbano por pistas agrícolas. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09119','mirador','Alto de San Clemente','6.2/10. Vista del pie de monte de la Sierra de las Mamblas y las extensas dehesas de encina que flanquean la carretera de Soria. Cómo llegar: Vértice de montaña accesible desde los caminos tradicionales que parten del pueblo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09120','mirador','Alto de Obarenes (Moriana)','6.5/10. Vista agreste del Monasterio de Santa María de de Obarenes integrado en la naturaleza y los farallones calizos de los Montes Obarenes. Cómo llegar: Pista forestal que asciende desde el núcleo de Obarenes hacia el puerto natural. Siguiente bloque listo para procesar a partir de Espinosa de Cervera. ¿Continuamos con el mismo avance directo y masivo?.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09122','mirador','Alto de la Yecla','6.6/10. Excelentes vistas de los extensos bosques de sabina albar y del entorno escarpado que da acceso al desfiladero. Cómo llegar: Cresta calcárea al este de la carretera BU-910, junto al sendero señalizado. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09006','mirador','Mirador de las Machorras (Puerto de Lunada)','8.4/10. Imponente paisaje pasiego caracterizado por praderas verdes valladas con muros de piedra, cabañas tradicionales y circos glaciares cantábricos. Cómo llegar: Plataforma acondicionada a mitad de subida en la carretera del Puerto de Lunada (BU-572). 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09125','mirador','Alto de las Arenas','5.6/10. Vista abierta del Valle del Arlanzón medio, los cerros testigo colindantes y el trazado ferroviario de alta velocidad. Cómo llegar: Vértice geodésico situado al sur del núcleo de Vilviestre de Muñó. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09127','mirador','Alto de los Almendros','5.5/10. Visual diáfana de la autovía del Norte (A-1) cruzando la meseta y campos de cultivo rodeados de parches de encinar. Cómo llegar: Pista agrícola elevada de fácil acceso al oeste del núcleo urbano. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09128','mirador','Cuesta de la Cabaña','5.7/10. Vista panorámica sobre el curso bajo del río Arlanzón, sus llanuras de inundación y las alamedas asociadas. Cómo llegar: Altiplano calizo accesible por pistas parcelarias desde el pueblo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09129','mirador','Alto de la dehesa (Praderías de San Vicente)','7.8/10. Magnífica estampa de alta montaña con frondosos bosques de haya y pino que trepan por la vertiente norte de la Sierra de la Demanda. Cómo llegar: Pista forestal que asciende hacia el refugio de montaña de San Vicente. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09133','mirador','Puerto de la Brújula','6.1/10. Vista estratégica del tradicional paso de montaña de la meseta hacia el mar y de las hileras de modernos molinos eólicos. Cómo llegar: Antigua plataforma de la carretera N-I, tramo en desuso y acondicionado. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09132','mirador','Alto de San Cristóbal','5.5/10. Perspectiva rural de las ricas huertas de la vega del río Tirón y del límite provincial con la comunidad de La Rioja. Cómo llegar: Senda agrícola elevada al este de las bodegas excavadas del pueblo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09007','mirador','Mirador del Castillo de Frías','8.5/10. Increíbles e icónicas vistas de la ciudad medieval colgante, las casas colgadas sobre la roca, el río Ebro y el imponente puente románico. Cómo llegar: Torre del homenaje del Castillo de los Duques de Frías, acceso peatonal urbano pavimentado. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09135','mirador','Alto de la Rasa','5.6/10. Vista limpia del somontano norte de la Bureba y de la transición hacia la muralla de piedra de los Montes Obarenes. Cómo llegar: Camino de concentración que sube al páramo por el norte del municipio. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09136','mirador','Cotarro de San Mamés','5.8/10. Típica estampa ribereña de mares de viñedos de la Ribera del Duero y de los tradicionales lagares de piedra del entorno. Cómo llegar: Punto alto de las bodegas locales, de fácil acceso peatonal desde la travesía. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09137','mirador','Alto de la Ermita de Nava','5.9/10. Vista panorámica sobre el Valle de San Juan, los cultivos de vid y las extensas repoblaciones de pino piñonero. Cómo llegar: Explanada de la Ermita de la Virgen de Nava, pista apta para vehículos. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09138','mirador','Mirador del Duero Alto','5.7/10. Vista de los escarpes de yesos y calizas que encajonan el cauce del río Duero en este sector de la comarca. Cómo llegar: Borde del cortado natural al sur del núcleo por caminos tradicionales. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09139','mirador','El Altillo','5.6/10. Llanura agrícola de horizontes lejanos interrumpida únicamente por las hileras de chopos que marcan los arroyos locales. Cómo llegar: Colina baja de labor situada a escasos metros del cementerio municipal. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09140','mirador','Mirador de Peña El Pico','6.4/10. Espectaculares vistas de la llanura de la Ribera del Duero segoviana y burgalesa desde las mayores elevaciones calizas del sur provincial. Cómo llegar: Vértice de Peña El Pico, subida empinada por pista de tierra apta para todoterrenos. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09141','mirador','Alto de la Ermita del Santísimo Cristo','5.8/10. Vista de la campiña vitivinícola periurbana del sur de Aranda de Duero y de las naves industriales integradas en el valle. Cómo llegar: Entorno ajardinado de la ermita, acceso directo desde el trazado urbano. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09143','mirador','Alto del Torno','5.9/10. Vista de valles sinuosos y deshabitados en la comarca de la Bureba, marcados por pequeñas formaciones de encinar y quejigos. Cómo llegar: Senda de montaña que arranca desde el despoblado de San Bartolomé. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09148','mirador','Mirador de la Iglesia de Santa María','6.0/10. Vista del impresionante templo gótico-rural del pueblo que emerge de forma monumental sobre las extensas llanuras cerealistas del Odra. Cómo llegar: Atrio elevado de la iglesia parroquial, acceso urbano peatonal. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09149','mirador','Alto de San Juan','5.5/10. Perspectiva rural y agrícola de la Bureba oriental con el encajonamiento del corredor del río Oca a lo lejos. Cómo llegar: Altiplano rústico accesible por el camino de servicio del parque eólico. Siguiente bloque listo para procesar a partir de Gumiel de Izán. ¿Continuamos con el mismo avance masivo e inmediato?.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09151','mirador','Alto de San Antonio','6.2/10. Excelente visual del entramado urbano medieval de la villa, su monumental iglesia de Santa María y el mar de viñedos de la Ribera. Cómo llegar: Cerro adyacente a las bodegas tradicionales, con acceso desde la carretera BU-920. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09152','mirador','Mirador del Castillo (Cerro de San Juan)','6.3/10. Panorámica aérea de 360 grados sobre los dos cerros que resguardan el casco histórico y los cultivos de vid Denominación de Origen. Cómo llegar: Explanada de la antigua fortaleza que corona el núcleo urbano. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09154','mirador','Mirador del Castillo de Hacinas','7.2/10. Impresionante vista de la Sierra de la Demanda y de las réplicas de los árboles fósiles del Cretácico que caracterizan al municipio. Cómo llegar: Lo alto de la peña del castillo, accesible mediante escaleras desde el casco urbano. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09155','mirador','Mirador de la Muralla de Haza','7.6/10. Espectacular perspectiva desde un nido de águilas medieval que domina con vértigo todo el Valle del Duero y el río Riaza. Cómo llegar: Adosado a los restos de la muralla fortificada, acceso directo desde el aparcamiento de la villa. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09159','mirador','Mirador de la Cuesta de Hontanas','6.1/10. Vista del sorprendente casco urbano escondido por completo en una hondonada del páramo en pleno Camino de Santiago Francés. Cómo llegar: Borde exterior del páramo por la carretera BU-V-4011 antes de iniciar el descenso. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09160','mirador','Alto de la Ermita de la Cueva','5.6/10. Sencilla y agradable panorámica sobre la vega del río Riaza, las laderas calizas erosionadas y la chopera local. Cómo llegar: Explanada rocosa del Santuario de la Virgen de la Cueva, acceso señalizado. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09162','mirador','Mirador de las Canteras Negras','6.0/10. Interés histórico y geológico sobre los vaciados de piedra caliza que sirvieron para erigir los monumentos de Burgos. Cómo llegar: Pista minera restaurada que arranca al sur de la carretera N-234. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09164','mirador','Alto de San Roque','5.8/10. Vista de campos cerealistas combinados con encinares y los relieves que bajan de la Sierra de la Demanda. Cómo llegar: Junto a la pequeña ermita de San Roque, al norte del término municipal. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09163','mirador','Mirador de la Costalago','7.8/10. Increíbles vistas de la masa forestal que da inicio al Parque Natural del Cañón del Río Lobos y los escarpes de roca caliza. Cómo llegar: Pista forestal maderera en dirección a la provincia de Soria, transitable para vehículos altos. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09166','mirador','Mirador del Castillo de Hormaza','5.9/10. Vista de los tres valles que componen el municipio y de los horizontes infinitos de la comarca de Odra-Pisuerga. Cómo llegar: Restos defensivos situados en la cota más elevada del término, acceso por camino rural. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09167','mirador','Alto de la Mula (Páramo)','6.0/10. Típico paisaje místico y solitario del páramo castellano recorrido por los peregrinos jacobeos, jalonado de aerogeneradores. Cómo llegar: Camino de Santiago en su tramo de meseta antes del descenso al Valle del Hormazuela. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09168','mirador','Mirador de la duna de la Horra','6.3/10. Hermosa panorámica agrícola sobre lagares tradicionales y colinas cubiertas por viñedos históricos de gran solera. Cómo llegar: Paraje de bodegas elevadas, acceso directo desde el entramado urbano. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09170','mirador','Mirador de la Torre de Hoyales','6.2/10. Vista del Valle del Duero y de la desembocadura del río Riaza desde la singular silueta de su torreón medieval. Cómo llegar: Explanada de la torre señorial que domina el casco urbano desde el cerro. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09172','mirador','Mirador del Desfiladero de las Sereñas','6.6/10. Vista del abrupto cortado calizo tallado por el río Úrbel con buitreras y formaciones de encinar rocoso. Cómo llegar: Ruta senderista que parte de la localidad de San Pantaleón del Páramo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09173','mirador','Puerto de Neila (Vertiente Norte)','8.1/10. Sobresaliente panorámica de alta montaña sobre la Dehesa de robles centenarios, pastizales alpinos y el perfil de la Sierra de la Demanda. Cómo llegar: Kilómetro alto de la carretera de montaña BU-822, límite con el Parque Natural de las Lagunas de Neila. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09174','mirador','Mirador del Altico','7.0/10. Vista limpia del cañón kárstico del río Arandilla y de los densos bosques de pino albar y sabinas que envuelven la villa. Cómo llegar: Senda peatonal acondicionada con barandilla de madera sobre el casco urbano. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09175','mirador','Mirador de la Peña Amaya','7.9/10. Imponente y grandiosa estampa geológica de la muela caliza de Amaya, baluarte del Geoparque Mundial de la UNESCO Las Loras. Cómo llegar: Aparcamiento habilitado a media subida del istmo de la peña, acceso desde el núcleo de Amaya. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09176','mirador','Alto del Acueducto','5.2/10. Sencilla estampa agrícola de la vega del río Hurones a escasos kilómetros del área industrial metropolitana de Burgos. Cómo llegar: Pista agraria situada al oeste del núcleo urbano por caminos de labor. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09177','mirador','Mirador del Embalse de Arlanzón','7.1/10. Espectaculares panorámicas del embalse rodeado por robledales húmedos a los pies de las grandes cumbres de la Demanda burgalesa. Cómo llegar: Acceso por pistas forestales desde la carretera nacional N-120 hacia el entorno del pantano. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09178','mirador','Alto de San Cristóbal','5.5/10. Vista limpia de la comarca de la Riojilla Burglesa con cultivos intensivos de legumbres y cereales bajo el horizonte riojano. Cómo llegar: Camino rural en la loma del este, cercano a la linde provincial. Siguiente bloque listo para procesar a partir de Iglesiarrubia. ¿Mantenemos la tracción ininterrumpida de este titánico atlas?.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09179','mirador','Alto de la Varga','5.2/10. Sencilla panorámica de campos agrícolas del Arlanza medio con suaves ondulaciones del terreno y horizontes despejados. Cómo llegar: Pista agrícola al norte del núcleo urbano, transitable a pie. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09180','mirador','Alto de la Ermita de San Roque','5.5/10. Vista diáfana del valle del río Hormazuela y de la meseta cerealista que caracteriza al oeste provincial. Cómo llegar: Explanada junto a la ermita, accesible desde el casco urbano por sendero local. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09181','mirador','Páramo de Isar','5.7/10. Vista limpia del curso del río Urbel, sus laderas calcáreas marcadas por la erosión y campos de secano. Cómo llegar: Borde del talud del páramo por camino rural que sube desde el cementerio. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09182','mirador','Mirador del Puente Fitero (Río Pisuerga)','6.6/10. Vista de gran valor jacobeo sobre el monumental puente medieval de once ojos que salva el río Pisuerga, frontera con Palencia. Cómo llegar: Restos de la torre del castillo en el cerro que domina el casco urbano. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09183','mirador','Alto de San Cristóbal','7.1/10. Hermosa visual de la Sierra de la Demanda occidental, de los densos bosques de roble rebollo y de la iglesia románica porticada del pueblo. Cómo llegar: Senda forestal de montaña que asciende desde la zona norte de las eras. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09184','mirador','Mirador del Altico','6.8/10. Perspectiva aislada y de gran tranquilidad sobre el angosto valle del río Salcedo y las formaciones rústicas de encinar. Cómo llegar: Cresta caliza de fácil acceso a pie desde el centro del despoblado. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09189','mirador','Mirador del Alto de la Losa','7.4/10. Amplia y verde panorámica del valle de Las Merindades orientales con pastizales ganaderos y hayedos en los linderos montañosos. Cómo llegar: Carretera BU-551, apartadero habilitado cerca del límite municipal. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09190','mirador','Mirador del Cañón de Áliva (Salto del Nervión)','8.3/10. Impresionante e imponente balcón colgado con rejilla de hierro sobre el abismo del Monumento Natural de Monte Santiago. Cómo llegar: Sendero señalizado PR-BU 41, acceso peatonal desde el aparcamiento del parque. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09191','mirador','Mirador del Castillo de Lara','7.2/10. Cuna histórica de Castilla con vistas espectaculares del Valle de Lara, la meseta de la Peña de Lara y la Sierra de las Mamblas. Cómo llegar: Pico rocoso fortificado sobre la localidad de Lara de los Infantes, sendero empinado a pie. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09192','mirador','Mirador de San Zadornil (Parque Natural Montes Obarenes-San Zadornil)','8.0/10. Extraordinaria panorámica de la llamada "Metrópoli Verde", un inmenso y denso tapiz boscoso de pinos, hayas, castaños y encinas. Cómo llegar: Pista forestal acondicionada que arranca desde el Centro de Interpretación del Parque. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09008','mirador','Mirador de los Arcos de Lerma','7.6/10. Magnífica visual desde la plaza ducal sobre la vega del río Arlanza, los puentes históricos y los antiguos huertos del palacio. Cómo llegar: Balconada barroca de los Arcos en el casco monumental, acceso peatonal urbano continuo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09195','mirador','Alto de la Cruz','5.4/10. Vista rústica y horizontal sobre la llanura agrícola de La Bureba occidental y los campos cultivados de trigo y girasol. Cómo llegar: Camino rural elevado de fácil acceso que parte de la trasera del casco urbano. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09196','mirador','Alto del Redondo','5.6/10. Vista sobre el corredor de la autovía A-1 y los característicos montes bajos de encina y quejigo del Arlanza septentrional. Cómo llegar: Pista agrícola situada al oeste del núcleo por caminos forestales de labor. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09197','mirador','Alto de la Dehesa','5.5/10. Típica estampa del campo charro-burgalés con horizontes planos interrumpidos únicamente por bosquetes aislados de encinar. Cómo llegar: Elevación natural adosada al pequeño núcleo rural, accesible por camino vecinal. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09198','mirador','Mirador de la Iglesia de San Miguel','5.8/10. Vista elevada de la llanura del bajo Arlanza y de la fisonomía urbana del pueblo, presidida por su monumental templo gótico-mudéjar. Cómo llegar: Atrio elevado del templo en el centro de la localidad, acceso urbano. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09199','mirador','Mirador de la Ribera','6.2/10. Hermosa panorámica agrícola sobre las laderas plantadas de cepas viejas de viñedo de la Ribera del Duero y choperas al fondo. Cómo llegar: Altiplano calizo sobre las bodegas tradicionales, desvío desde la carretera local. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09200','mirador','Alto de la Muela de Mambrillas','7.0/10. Espectaculares vistas de la llanura de Lara y de las caprichosas formaciones geológicas de la Sierra de las Mamblas. Cómo llegar: Sendero que asciende a los riscos calcáreos desde el camino de Quintanilla de las Viñas. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09202','mirador','Alto del páramo de Manciles','5.3/10. Paisaje totalmente diáfano y horizontal de la comarca de Odra-Pisuerga, dominado por campos abiertos de secano. Cómo llegar: Camino de concentración parcelaria al norte del término municipal. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09206','mirador','Alto de las Bodegas de Mazuela','5.4/10. Vista sencilla sobre el pequeño valle del arroyo de Mazuela y los horizontes infinitos de la meseta norte castellana. Cómo llegar: Zona alta del montículo que resguarda las bodegas tradicionales del pueblo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09208','mirador','Mirador del Cementerio de Esculturas','6.6/10. Interés artístico y visual de las esculturas monumentales al aire libre rodeadas del matorral de sabinas y encinas del Arlanza alto. Cómo llegar: Paraje de las canteras tradicionales, acceso señalizado desde la carretera BU-901. Siguiente bloque listo para comenzar desde Medina de Pomar.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09009','mirador','Mirador del Alcázar de los Velasco','7.6/10. Magnífica e imponente panorámica sobre el casco histórico amurallado, las vegas del río Trueba y la silueta de la Sierra de la Tesla. Cómo llegar: Torres del Alcázar (Museo de Las Merindades), acceso peatonal urbano pavimentado. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09211','mirador','Mirador del Canal de Castilla (San Carlos)','6.9/10. Gran valor de ingeniería e historia. Vista del acueducto de Abánades y el discurrir del canal entre llanuras cerealistas. Cómo llegar: Ribera elevada del canal, junto al centro de recepción de visitantes de San Carlos. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09213','mirador','Mirador de la Sierra de la Tesla','7.7/10. Extraordinaria panorámica de la cuenca de Nela y el escarpado valle encajonado entre grandes moles de caliza. Cómo llegar: Pista de montaña que asciende desde la localidad de Nofuentes hacia la cresta. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09214','mirador','Mirador del Puerto de El Cabrio','7.9/10. Impresionante transición natural con vistas al Valle de Mena y los paredones rocosos de los Montes de Ordunte. Cómo llegar: Apartadero adaptado en la carretera nacional N-629, en lo alto del puerto. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09906','mirador','Mirador del Desfiladero de Peñahorada','7.3/10. Vista del imponente tajo calcáreo labrado por el río Ubierna con nidos de buitre leonado en sus paredes. Cómo llegar: Antigua plataforma vial junto a la N-623, sendero peatonal señalizado. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09216','mirador','Mirador de la Engaña','8.1/10. Entorno de montaña sobre la boca del túnel ferroviario abandonado del Santander-Mediterráneo y densos hayedos cantábricos. Cómo llegar: Explanada de la antigua estación de Pedrosa de Valdeporres, acceso por pista asfaltada. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09217','mirador','Mirador de la Mazorra','8.2/10. Una de las vistas más espectaculares de la provincia. Gran panorámica del frondoso valle excavado por el Ebro. Cómo llegar: Alto del puerto de la Mazorra en la carretera CL-629, amplio aparcamiento. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09218','mirador','Mirador de la Vega del Riaza','5.9/10. Vista agradable sobre las choperas de ribera, las huertas y el trazado de la autovía del Norte junto al río. Cómo llegar: Camino alto que discurre por la vertiente de bodegas tradicionales al este. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09010','mirador','Mirador del Castillo de Miranda','7.4/10. Excelente panorámica industrial y urbana de la ciudad, el gran paso del río Ebro y los Montes Obarenes occidentales. Cómo llegar: Jardines del cerro del Castillo, acceso urbano adaptado con pasarelas y ascensor. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09220','mirador','Alto de San Silvestre','6.1/10. Vista limpia del somontano norte de la Bureba y las dehesas que trepan hacia la lora calcárea. Cómo llegar: Senda de montaña que arranca desde el depósito de agua local. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09221','mirador','Mirador del Valle de las Modúbares','5.8/10. Vista del corredor rural del río Ausín, encinares dispersos y parcelas cerealistas cercanas a la capital. Cómo llegar: Trazado elevado de la Vía Verde del Santander-Mediterráneo a su paso por el término. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09223','mirador','Mirador de los Corrales','7.5/10. Vista forestal de alta montaña sobre la Sierra de la Demanda meridional, dominada por dehesas de robles y pinos. Cómo llegar: Pista maderera al norte del monasterio en ruinas de Alveinte. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09224','mirador','Alto del Castillo de Monasterio','6.8/10. Impresionante panorámica del inicio de La Bureba, el puerto de la Brújula y la ermita románica de Nuestra Señora del Valle. Cómo llegar: Cresta caliza del castillo medieval, sendero empinado a pie desde el casco urbano. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09225','mirador','Alto de San Juan','6.7/10. Vista de media montaña sobre los extensos pinares del Arlanza y los afloramientos calizos que bajan de Urbión. Cómo llegar: Vértice de labor accesible por el camino forestal de Palacios de la Sierra. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09226','mirador','Puerto de las Tres Cruces','7.8/10. Gran valor paisajístico. Impresionantes vistas de la Sierra de la Demanda profunda y los valles ganaderos lindantes con La Rioja. Cómo llegar: Límite provincial en pista forestal de montaña apta para todoterrenos. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09227','mirador','Alto del Peñón','6.4/10. Vista del nacimiento del río Sedano, los páramos calcáreos y los encinares protegidos del norte burgalés. Cómo llegar: Senda peatonal desde la iglesia hacia el punto geodésico del cerro. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09228','mirador','Mirador del Cotarro de las Bodegas','6.5/10. Espectacular vista del singular cerro rodeado por más de 150 bodegas subterráneas y lagares tradicionales de la Ribera. Cómo llegar: Cima del cerro de la iglesia, acceso pavimentado desde el entramado urbano. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09229','mirador','Alto de San Antón','5.7/10. Vista de horizontes llanos de la vega del Duero baja, viñedos e hileras aisladas de pinos piñoneros. Cómo llegar: Explanada natural de las bodegas altas, desvío de la N-122. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09230','mirador','Mirador de los Montes Obarenes (Navas)','6.3/10. Hermosa visual de los abruptos farallones calcáreos del Parque Natural y los fértiles campos frutales que crecen a sus pies. Cómo llegar: Camino de ascensión forestal que parte desde la zona norte del casco urbano. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09231','mirador','Alto de la Muela de Nebreda','6.4/10. Vista del Espacio Natural de los Sabinares del Arlanza, campos cerealistas y los relieves calcáreos de Brieva. Cómo llegar: Pista forestal que corona la cresta caliza al este del casco urbano. Siguiente bloque listo para arrancar de inmediato desde Neila. ¿Continuamos con el mismo ritmo imparable y riguroso?.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09232','mirador','Mirador de San Francisco (Lagunas de Neila)','8.8/10. Imponente panorámica de alta montaña sobre circos glaciares, lagunas alpinas, frondosos pinares silvestres y las cumbres del Sistema Ibérico. Cómo llegar: Carretera de montaña BU-822, en la plataforma de acceso al Parque Natural. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09235','mirador','Alto de la Horca','5.8/10. Vista diáfana de llanuras alomadas con mares de viñedos de la Ribera del Duero y parcelas de cultivo tradicionales. Cómo llegar: Camino rural elevado que parte del sector de las bodegas subterráneas. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09236','mirador','El Cotarro','5.1/10. Sencilla panorámica de campos agrícolas de la comarca del Arlanza medio, dominada por extensos campos de cereal. Cómo llegar: Vértice geodésico rústico al sur del núcleo rural, pista vecinal de labor. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09011','mirador','Mirador de Vista Alegre (Desfiladero del Oca)','8.4/10. Impresionante e imponente vista del tajo calizo excavado por el río Oca, el monasterio de San Salvador y el entramado urbano medieval. Cómo llegar: Sendero de montaña señalizado (PR-BU 65) que asciende por los riscos orientales. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09239','mirador','Alto de la Ermita','5.4/10. Típica estampa agraria de la ribera media con horizontes limpios de vegetación alta y parcelas de secano. Cómo llegar: Pequeño altillo de la ermita local, accesible desde el casco urbano por senda. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09241','mirador','Alto de la Muela (Periurbano)','5.6/10. Vista del corredor industrial del este de Burgos capital, el aeropuerto provincial y la llanura de inundación del Riopico. Cómo llegar: Borde del altiplano calizo accesible por pistas agrícolas. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09244','mirador','Mirador de la Mazorra Oriental','6.4/10. Perspectiva sobre valles angostos y deshabitados de la Bureba norte, rodeados por densas formaciones de encinar y quejigos. Cómo llegar: Senda de montaña que arranca desde el depósito de agua de la localidad. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09246','mirador','Mirador de la Necrópolis de El Castillo','7.8/10. Excelente panorámica forestal de la Sierra de Pinares que combina historia medieval y un inmenso mar de pino albar. Cómo llegar: Parque arqueológico elevado sobre el casco urbano, acceso acondicionado con barandillas. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09247','mirador','Cuesta del Rey','5.3/10. Vista agradable del cauce del río Pisuerga y las plantaciones de choperas que delimitan con Palencia. Cómo llegar: Camino forestal al oeste del núcleo urbano por pistas de concentración. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09248','mirador','Alto de San Adrián','6.9/10. Perspectiva sobre las dehesas de robles y los pastizales ganaderos que trepan hacia las faldas de la Demanda. Cómo llegar: Pista forestal maderera del sector sur, transitable para vehículos todoterreno. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09249','mirador','Alto del Castillo','5.2/10. Llanura agrícola horizontal característica de la cuenca baja del río Arlanzón con perfiles llanos. Cómo llegar: Promontorio natural adosado al pequeño núcleo rural, acceso peatonal. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09250','mirador','Mirador de la Torre de la Iglesia','6.2/10. Vista elevada de la vega del río Arlanzón en su tramo final, huertas tradicionales e historia visigoda asociada. Cómo llegar: Atrio y entorno elevado del templo parroquial de San Pedro, acceso urbano. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09012','mirador','Mirador de la Peña del Castillo (Santa Marta)','8.5/10. Espectaculares e imponentes vistas del Desfiladero de Pancorbo, un estrecho y vertical tajo rocoso que es la puerta histórica de la meseta. Cómo llegar: Ruinas de la fortaleza de Santa Marta en la cresta calcárea alta, acceso por sendero empinado. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09253','mirador','Alto de San Roque','5.8/10. Vista limpia de la llanura vitivinícola meridional burgalesa y del límite con las tierras segovianas de Honrubia. Cómo llegar: Junto a la pequeña ermita de San Roque, al sur del término municipal. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09255','mirador','Mirador de la Sierra de Arcena','7.6/10. Espectaculares vistas de la cubeta geológica del Valle de Tobalina y de los densos bosques húmedos cantábricos. Cómo llegar: Pista forestal que corona la cresta caliza al norte del casco urbano de Cubilla de Sierra. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09256','mirador','Mirador de los Grandes Pagos','6.1/10. Hermosa panorámica agrícola sobre las viñas de mayor solera e hileras ordenadas de bodegas modernas de la Ribera. Cómo llegar: Altiplano calizo sobre las plantaciones, desvío desde la carretera local BU-132. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09259','mirador','Alto de San Pedro','5.4/10. Sencilla visual sobre el curso medio del río Urbel, campos cerealistas y suaves laderas erosionadas. Cómo llegar: Camino de concentración parcelaria al norte del término municipal. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09257','mirador','Páramo de Pedrosa','5.5/10. Paisaje totalmente diáfano de la comarca de Odra-Pisuerga, dominado por campos abiertos e infinitos de trigo. Cómo llegar: Pista agrícola elevada de fácil acceso al oeste del núcleo urbano. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09258','mirador','Alto del Pisuerga','5.4/10. Vista de horizontes llanos de la vega del Pisuerga baja, plantaciones de chopos e hileras fluviales fronterizas. Cómo llegar: Talud natural situado al oeste del casco urbano por pistas agrícolas. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09013','mirador','Mirador del Castillo de Peñaranda','7.9/10. Soberbia panorámica de la villa ducal medieval, la gran Plaza Mayor, el Palacio de Avellaneda y el cauce del río Arandilla. Cómo llegar: Explanada de la torre del homenaje en lo alto del cerro amurallado, acceso por pista asfaltada. Siguiente bloque listo para comenzar desde Peral de Arlanza. ¿Continuamos de forma masiva e inmediata.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09262','mirador','Alto de la Ermita','5.4/10. Vista agradable del cauce medio del río Arlanza, sus campos de regadío y las laderas erosionadas del Cerrato burgalés. Cómo llegar: Explanada de la ermita local, acceso directo por pista de tierra desde el núcleo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09265','mirador','Campa de la Ermita de San Martín de Piérnigas','6.1/10. Hermosa visual de una joya del románico bucolino aislada entre un mar de campos de cereal con los Montes Obarenes al fondo. Cómo llegar: Entorno del templo románico, accesible por camino rural acondicionado desde el pueblo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09266','mirador','Mirador del Valle del Sol','8.2/10. Espectacular panorámica alpina de la Sierra de la Demanda profunda, rodeada de densos bosques de acebo, pinos y el Pico Mencilla. Cómo llegar: Antigua estación de esquí del Valle del Sol, acceso por carretera asfaltada de montaña desde el núcleo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09267','mirador','Alto de San Roque','5.6/10. Paisaje elevado sobre los valles del Mataviejas y el Aranzuelo con encinares dispersos y horizontes nítidos. Cómo llegar: Cerro de las bodegas tradicionales al norte del pueblo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09268','mirador','Mirador de Peña Carazo Oriental','7.1/10. Vista de media montaña sobre las llamativas formaciones de pinos y las crestas calizas que lindan con la comarca de la Sierra. Cómo llegar: Pista forestal maderera del sector este, transitable a pie. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09269','mirador','Alto de San Pedro','6.8/10. Perspectiva sobre el valle alto del río Pedroso, rodeado de robles melojos y formaciones kársticas de gran valor. Cómo llegar: Camino tradicional elevado que arranca desde las eras del núcleo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09014','mirador','Mirador del Castillo de los Rojas / Diapiro','8.4/10. Impresionante e imponente vista de uno de los diapiros salinos más grandes del mundo y de la llanura infinita de La Bureba. Cómo llegar: Fortaleza medieval de los Rojas, en la cresta caliza que corona la villa salinera. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09273','mirador','Alto del Oca','5.5/10. Vista horizontal sobre el curso alto del río Oca y las infraestructuras que vertebran el corredor central burebano. Cómo llegar: Altiplano rústico situado al este del núcleo por caminos de labor. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09274','mirador','Mirador de la Cascada de la Pasadera','7.7/10. Vista de gran encanto forestal sobre el valle textil encajonado entre hayedos húmedos y las bravas aguas del río Oropesa. Cómo llegar: Senda de montaña que sube hacia el desfiladero desde el complejo recreativo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09275','mirador','Alto de la Cruz','5.3/10. Paisaje completamente diáfano de la comarca del bajo Arlanza, dominado por campos abiertos de secano. Cómo llegar: Pista agrícola elevada de fácil acceso al oeste del núcleo urbano. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09276','mirador','Mirador del Castillo de Arganzón','7.3/10. Vista histórica y estratégica del desfiladero de la Concha de Haro, el paso del río Zadorra y el enclave de Treviño. Cómo llegar: Ruinas de la torre defensiva sobre el cerro calizo, acceso por senda peatonal. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09277','mirador','Mirador del Puente sobre el Arlanza','6.9/10. Hermosa panorámica del puente de siete ojos de origen medieval reflejado en las aguas claras del Arlanza alto. Cómo llegar: Margen izquierda elevada del río, desvío peatonal desde la carretera local. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09279','mirador','Alto de San Roque','5.9/10. Vista de la confluencia de los valles del Arandilla y el Bañuelos con abundantes campos de cepas viejas de viñedo. Cómo llegar: Altiplano calizo sobre las bodegas tradicionales, acceso por camino rural. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09281','mirador','Mirador de la Ermita de los Olmos','6.1/10. Típica estampa ribereña de colinas suaves cubiertas por viñedos históricos y los característicos pinares de la comarca. Cómo llegar: Explanada de la ermita, situada en una elevación al norte del término municipal. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09280','mirador','Alto de la Cruz','5.4/10. Vista limpia del somontano norte de la Bureba y de la transición hacia la muralla de piedra de los Montes Obarenes. Cómo llegar: Camino de concentración que sube al páramo por el norte del municipio. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09283','mirador','Mirador de los Montes Obarenes (Quintanaélez)','6.3/10. Excelente panorámica de los escarpes rocosos del Parque Natural y de los fértiles campos frutales que crecen a sus pies. Cómo llegar: Camino de ascensión forestal que parte desde la zona norte del casco urbano. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09287','mirador','Mirador del Río Ubierna','5.6/10. Vista fluvial de la rica vega agrícola y las densas choperas de ribera que surcan el norte periurbano de Burgos. Cómo llegar: Paseo de ribera acondicionado y accesible desde el casco urbano hacia el sur. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09288','mirador','Alto de la Brújula Occidental','5.8/10. Vista del corredor del Camino de Santiago Francés e infraestructuras viales a la sombra de los montes de la Brújula. Cómo llegar: Antigua plataforma vial junto al puerto, accesible por camino vecinal. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09289','mirador','Mirador de Neila (Lagunas Altas)','8.3/10. Imponente panorámica de alta montaña sobre circos glaciares, lagunas alpinas y el inmenso mar de pino silvestre de la Sierra de Pinares. Cómo llegar: Carretera de montaña BU-822, en el límite del Parque Natural de las Lagunas de Neila. Siguiente bloque listo para comenzar inmediatamente desde Quintanilla de la Sandra.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09294','mirador','Alto de la Dehesa','5.3/10. Sencilla visual de llanuras alomadas con campos de cultivo tradicionales e hileras aisladas de encinar. Cómo llegar: Camino rural elevado de fácil acceso al oeste del núcleo urbano. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09901','mirador','Mirador del Territorio Artlanza','6.4/10. Atractiva vista de la recreación del pueblo medieval a escala real, integrado en el paisaje de ribera del río Arlanza. Cómo llegar: Espacio cultural elevado a las afueras de Quintanilla, acceso directo desde la carretera BU-904. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09295','mirador','Mirador de San Cristol','7.1/10. Espectaculares vistas de la entrada al desfiladero de la Yecla, rodeado de sabinares centenarios y buitreras en paredes calizas. Cómo llegar: Senda de montaña que asciende hacia la meseta caliza desde la carretera BU-910. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09298','mirador','Alto de San Juan','5.6/10. Vista panorámica de la cuenca agrícola burebana orientada hacia los perfiles montañosos de los Montes Obarenes occidentales. Cómo llegar: Borde exterior del páramo por camino rural que sube desde el cementerio local. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09301','mirador','Alto de Vivar del Cid','5.8/10. Vista despejada de la vega del río Ubierna, el nexo histórico del Camino del Cid y la campiña norte periurbana burgalesa. Cómo llegar: Altiplano calizo accesible por pistas agrícolas desde la carretera N-623. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09297','mirador','Cuesta del Rey','5.5/10. Perspectiva sobre la llanura aluvial del río Urbel y el nudo vial de la autovía del Camino de Santiago (A-231). Cómo llegar: Pista agrícola de fácil acceso al norte del núcleo rural. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09302','mirador','Mirador de la Cicla','7.6/10. Impresionante panorámica maderera sobre el denso mar de pino albar de la Sierra de Pinares y afloramientos de piedra arenisca. Cómo llegar: Pista de montaña señalizada que arranca desde el casco urbano de Rabanera. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09303','mirador','Alto de San Pedro','7.1/10. Vista aislada de media montaña sobre el valle del río Pedroso, rodeado de robles melojos y formaciones kársticas. Cómo llegar: Senda peatonal desde la iglesia parroquial hacia el alto del cerro homónimo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09304','mirador','Alto de la Cuesta (Camino de Santiago)','5.9/10. Típica estampa del páramo castellano recorrido por los peregrinos jacobeos, jalonada de campos abiertos de secano. Cómo llegar: Trazado del Camino de Santiago Francés en su ascenso hacia Hornillos del Camino. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09306','mirador','Mirador del Castillo de Rebolledo','7.4/10. Gran valor histórico y paisajístico. Vista de la muela de Albacastro, valles calizos del Geoparque Las Loras y su singular torre del homenaje. Cómo llegar: Explanada de la fortaleza medieval que corona la villa monumental. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09307','mirador','Alto de San Roque','5.7/10. Vista llana del Camino de Santiago Riojano en su transición fronteriza hacia la comarca de la Riojilla Burgalesa. Cómo llegar: Pista agrícola elevada que discurre paralela a la carretera nacional N-120. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09309','mirador','Mirador de las Huellas de Dinosaurio (El Frontal)','7.9/10. Magnífica visual forestal de la Sierra de Pinares combinada con el gran yacimiento paleontológico de icnitas al aire libre. Cómo llegar: Plataforma acondicionada con paneles didácticos junto a las eras altas del pueblo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09310','mirador','Alto de la Cruz','5.4/10. Vista rústica e intermedia sobre los valles sinuosos y campos cerealistas de la Bureba central. Cómo llegar: Camino de concentración parcelaria al norte del término municipal. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09311','mirador','Mirador del Valle del Arlanza','7.2/10. Hermosa estampa de las curvas fluviales del río Arlanza y de los cortados calizos calcáreos que cobijan sabinas y encinas. Cómo llegar: Borde del cortado natural al sur del núcleo por caminos forestales tradicionales. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09314','mirador','Alto de la Rebolleda','6.1/10. Perspectiva sobre las laderas repobladas de coníferas y los valles que vierten hacia el río Ausín. Cómo llegar: Trazado elevado de la Vía Verde del Santander-Mediterráneo a su paso por el término. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09316','mirador','Alto de San Cristóbal','5.6/10. Vista agradable del cauce del río Pisuerga y las plantaciones de choperas que marcan el límite con Palencia. Cómo llegar: Senda agrícola elevada al este de las bodegas tradicionales del pueblo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09318','mirador','Alto del Manquillo (Vertiente Sur)','7.8/10. Impresionante estampa de alta montaña con extensos hayedos, dehesas de robles y cumbres de la Demanda central. Cómo llegar: Puerto de montaña en la carretera provincial BU-825, apartadero habilitado. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09016','mirador','Mirador del Espolón de Roa','7.6/10. Magnífica y amplia panorámica sobre el fértil valle del río Duero, sus alamedas de ribera y el corazón de la Denominación de Origen. Cómo llegar: Paseo del Espolón en la muralla medieval del núcleo urbano, acceso pavimentado continuo. Siguiente bloque listo para comenzar de inmediato desde Rojas. ¿Mantenemos la velocidad de avance para terminar la provincia?.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09323','mirador','Alto de la Ermita de San Roque','5.5/10. Vista agraria del somontano de La Bureba, destacando las parcelas de cereal y los pequeños cerros que rompen la llanura. Cómo llegar: Explanada de la ermita al norte del pueblo, accesible por pista de tierra. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09325','mirador','Páramo de San Pedro','5.6/10. Típica estampa del Cerrato burgalés con horizontes planos, cultivos de secano y laderas calcáreas erosionadas. Cómo llegar: Cresta del páramo accesible por caminos vecinales desde la carretera BU-143. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09327','mirador','Alto de la Brújula','5.8/10. Perspectiva sobre los valles de transición hacia la cuenca del Oca, rodeada de aerogeneradores y matorral bajo. Cómo llegar: Pista de mantenimiento del parque eólico, desvío desde la N-I. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09328','mirador','Mirador del Valle de las Caderechas','6.4/10. Preciosa vista de los valles frutales encajonados y los bosques de pinos que cubren las laderas montañosas de la zona. Cómo llegar: Camino rural elevado en dirección al término de Hoz de Arreba. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09017','mirador','Mirador de Peña Costalago','7.1/10. Amplia vista del valle del Arlanza alto, los pinares serranos y los yacimientos paleontológicos que caracterizan a la comarca. Cómo llegar: Alto de la muela caliza calzada al este del casco urbano por pistas forestales. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09329','mirador','Mirador de los Frutales','6.2/10. Hermosa panorámica estacional sobre las plantaciones de cerezos de las Caderechas y los paredones de la Cordillera Cantábrica. Cómo llegar: Pista agrícola elevada que sube hacia los montes calcáreos del norte. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09332','mirador','Alto de Saldaña','5.4/10. Vista diáfana de la vega del río Ausín y de los campos de cultivo periurbanos del sur de Burgos capital. Cómo llegar: Borde del altiplano agrícola calizo, pista vecinal de labor. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09334','mirador','Alto de los Obarenes','6.3/10. Perspectiva directa de los escarpes rocosos del Parque Natural y los valles agrícolas que se extienden a sus pies. Cómo llegar: Senda forestal que asciende por la vertiente norte desde el casco urbano. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09335','mirador','Mirador de la dehesa de Juarros','6.8/10. Vista forestal de media montaña sobre densas repoblaciones de coníferas y robledales que anuncian la Sierra de la Demanda. Cómo llegar: Pista forestal maderera del sector sur, transitable para vehículos todoterreno. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09337','mirador','Alto de la Ermita','5.8/10. Vista horizontal sobre el noreste de la Ribera del Duero, salpicada de viñedos y pequeñas manchas de encinar. Cómo llegar: Explanada rocosa adosada al templo de la localidad, acceso directo a pie. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09338','mirador','Cuesta del Rey','5.3/10. Paisaje agrícola totalmente llano sobre la vega baja del río Arlanzón y los nudos viales del oeste periurbano. Cómo llegar: Camino de concentración parcelaria al norte del término municipal. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09339','mirador','Mirador de la Cuesta del Castillo','6.1/10. Bonita estampa de los escarpes que encajonan el río Duero y las plantaciones ordenadas de viñedo. Cómo llegar: Ruinas de la antigua fortaleza sobre el cortado natural, acceso por pista rural. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09340','mirador','Alto de San Millán','7.2/10. Vistas espectaculares de la Sierra de las Mamblas, la Peña de Lara y los frondosos bosques de roble rebollo. Cómo llegar: Sendero de montaña que asciende desde la iglesia románica porticada del pueblo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09360','mirador','Alto del Tirón','7.4/10. Perspectiva montañosa sobre el cauce alto del río Tirón y las laderas cubiertas de hayedos de la Demanda norte. Cómo llegar: Camino tradicional de montaña que parte desde la iglesia visigótica de la localidad. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09343','mirador','Alto del Arlanza','5.4/10. Vista rústica del campo abierto del bajo Arlanza, caracterizado por majanos de piedra y parcelas cerealistas. Cómo llegar: Vértice de labor accesible por el camino forestal que conecta con Tordómar. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09345','mirador','Mirador de las Bodegas','5.9/10. Típica estampa ribereña de mares de viñedos de la Ribera del Duero y del entramado de lagares tradicionales de piedra. Cómo llegar: Zona perimetral de los lagares elevados, acceso directo desde el núcleo urbano. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09346','mirador','Mirador de la Cascada de Altuzarra','8.1/10. Impresionante e indómito paisaje forestal alpino con profundos barrancos, hayedos centenarios y saltos de agua cristalina. Cómo llegar: Senda de montaña de la Garganta del Urbión, acceso a pie desde el área recreativa. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09347','mirador','Mirador de las Murallas de Santa Gadea','73/10. Vista histórica de la villa medieval amurallada, las llanuras agrícolas del entorno de Miranda y los Obarenes escarpados. Cómo llegar: Adosado a los restos del castillo defensivo, acceso peatonal urbano continuo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09348','mirador','El Cotarro','5.4/10. Sencilla panorámica de campos agrícolas del Arlanza medio con suaves ondulaciones del terreno dedicadas al secano. Cómo llegar: Pista agrícola al norte del núcleo urbano, transitable a pie. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09350','mirador','Mirador de la Torre de la Iglesia','6.1/10. Vista elevada de la villa presidida por su monumental torre renacentista y las extensas llanuras cerealistas del bajo Arlanza. Cómo llegar: Atrio elevado del templo parroquial, acceso urbano desde la plaza. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09351','mirador','Alto de San Pedro','5.7/10. Vista del corredor de la autovía del Camino de Santiago y valles sinuosos marcados por pequeñas plantaciones forestales. Cómo llegar: Camino de concentración parcelaria al norte del término municipal. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09352','mirador','Alto de la Muela','6.5/10. Perspectiva sobre el Espacio Natural de los Sabinares del Arlanza y los horizontes del sureste que lindan con Soria. Cómo llegar: Pista forestal que corona la cresta caliza al este del casco urbano. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09353','mirador','Mirador del Pancorbo Oriental','6.2/10. Vista del encajonamiento del desfiladero de Pancorbo desde su vertiente este y la llanada de la Bureba oriental. Cómo llegar: Antigua plataforma vial junto a la carretera nacional N-I. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09354','mirador','Alto del Oca','5.6/10. Vista horizontal sobre el curso del río Oca y las infraestructuras de transporte que vertebran el corredor central. Cómo llegar: Altiplano rústico situado al este del núcleo por caminos de labor. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09355','mirador','Páramo de San Mamés','5.5/10. Típica estampa del Valle del Esgueva burgalés con laderas erosionadas y parcelas de cultivo tradicionales. Cómo llegar: Pista agrícola elevada de fácil acceso al oeste del núcleo urbano. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09356','mirador','Campa de la Ermita de San Juan de la Cerca','7.1/10. Hermosa visual de una joya del románico-mudéjar aislada entre campos calizos y sabinas con las Mamblas al fondo. Cómo llegar: Entorno del templo fortificado, accesible por camino rural desde el pueblo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09018','mirador','Mirador del Desfiladero de la Yecla','8.3/10. Espectaculares e imponentes vistas del angosto tajo calizo tallado por el arroyo El Cauce, con buitreras y pasarelas colgadas. Cómo llegar: Plataforma superior habilitada junto al túnel de la carretera BU-910, aparcamiento acondicionado. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09361','mirador','Mirador del Campo Petrolífero de Ayoluengo','7.8/10. Paisaje industrial único en España. Vista de los caballitos de extracción de petróleo en mitad de la lora caliza del Geoparque. Cómo llegar: Plataforma elevada junto al Museo del Petróleo, acceso asfaltado señalizado. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09362','mirador','Alto de la Olmeda','5.4/10. Vista del nudo de comunicaciones de la autovía del Norte y del corredor industrial y agrícola del sur periurbano de Burgos. Cómo llegar: Borde exterior del altiplano por camino de tierra desde el núcleo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09363','mirador','Mirador del Arco de San Miguel de Mazaterón','7.2/10. Vista de gran valor históricomonumental sobre la villa medieval, su colegiata gótica y la inmensa llanura cerealista del Odra. Cómo llegar: Entorno del arco románico exento en la carretera BU-P-4041. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09365','mirador','Alto de San Roque','5.6/10. Vista panorámica sobre el Valle de San Juan, los cultivos de vid y las repoblaciones de coníferas de la Ribera. Cómo llegar: Junto a la pequeña ermita de San Roque, al sur del término municipal. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09366','mirador','Alto de San Carlos','6.6/10. Vista del valle del río Lanzo y los extensos montes bajos de sabinas y encinas del Arlanza central. Cómo llegar: Pista forestal que asciende hacia la meseta caliza desde el núcleo urbano. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09368','mirador','Alto del Pisuerga','5.4/10. Vista agradable de las choperas de ribera y los campos abiertos de secano que lindan con Palencia. Cómo llegar: Camino forestal al oeste del núcleo urbano por pistas de concentración. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09369','mirador','Mirador de San Jorge','6.3/10. Hermosa panorámica agrícola sobre las viñas viejas y el entramado de bodegas subterráneas de la localidad. Cómo llegar: Ermita de San Jorge en lo alto del cerro que corona el casco urbano. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09372','mirador','Alto de la Muela','5.6/10. Vista despejada de la vega del río Ubierna y los polígonos del norte periurbano de Burgos capital. Cómo llegar: Borde del talud del páramo subiendo por el camino rural desde el cementerio. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09373','mirador','Mirador de Peña Amaya Occidental','7.6/10. Imponente y grandiosa estampa de los paredones calizos de Amaya y de las loras del Geoparque Mundial de la UNESCO. Cómo llegar: Pista que arranca desde el núcleo de Salazar de Amaya hacia los riscos altos. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09374','mirador','Páramo de Susinos','5.5/10. Paisaje totalmente diáfano e infinito de la comarca de Odra-Pisuerga, dominado por campos abiertos de trigo. Cómo llegar: Pista agrícola elevada de fácil acceso al oeste del núcleo urbano. Siguiente bloque listo para comenzar de inmediato desde Tamarón hasta completar los municipios restantes de Burgos. ¿Mantenemos este ritmo masivo masificado solicitado?.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09375','mirador','Alto del Hito','5.3/10. Vista llana e histórica sobre campos cerealistas tradicionales donde aconteció la célebre batalla de Tamarón en el siglo XI. Cómo llegar: Loma agrícola adosada a la autovía del Camino de Santiago (A-231). 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09377','mirador','Mirador de los Páramos','5.8/10. Amplia panorámica de la vega del río Urbel, las huertas tradicionales y el paso de los peregrinos del Camino de Santiago. Cómo llegar: Borde del talud calizo subiendo por el camino rural del depósito. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09378','mirador','Mirador de la Muela de Tejada','6.9/10. Hermosa panorámica sobre los cortados calcáreos y los valles solitarios que caracterizan la transición hacia los Sabinares del Arlanza. Cómo llegar: Cresta rocosa accesible por pista forestal forestal desde la carretera BU-V-8401. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09380','mirador','Páramo de San Roque','5.5/10. Típica estampa del Valle del Esgueva con laderas calcáreas marcadas por la erosión y campos de secano. Cómo llegar: Altiplano calizo sobre las bodegas tradicionales, desvío desde la carretera local. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09381','mirador','Alto de Mencilla','7.4/10. Vista de alta montaña sobre la vertiente occidental de la Sierra de la Demanda profunda, cubierta de densos robledales melojos. Cómo llegar: Senda de ascensión de montaña que arranca desde el pueblo de Tañabueyes. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09382','mirador','Cerro de San Cristóbal','5.4/10. Vista horizontal sobre el campo abierto de la comarca de Odra-Pisuerga, dominada por suaves lomas cerealistas. Cómo llegar: Vértice de labor al norte del pueblo, accesible mediante camino de tierra. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09384','mirador','Mirador del Puente Romano sobre el Arlanza','6.6/10. Preciosa perspectiva del histórico viaducto de 23 ojos reflejado en el río, flanqueado por vigorosas choperas de ribera. Cómo llegar: Margen izquierda elevada del río Arlanza, acceso peatonal inmediato. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09386','mirador','Alto de la Dehesa','5.7/10. Vista sobre el corredor de la autovía A-1 y los característicos montes bajos de encina y quejigo del Arlanza. Cómo llegar: Monte público al noroeste del casco urbano, accesible mediante senderos locales. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09387','mirador','Mirador del Castillo de Torregalindo','6.1/10. Visual del valle bajo del río Riaza y las plantaciones de vid desde el singular perfil de la torre defensiva. Cómo llegar: Explanada rocosa que corona las ruinas de la fortaleza, acceso peatonal empinado. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09388','mirador','Alto de Lara','6.7/10. Excelente panorámica de las caprichosas formaciones geológicas de la Sierra de las Mamblas y la llanura de Lara. Cómo llegar: Senda tradicional elevada que arranca desde el casco urbano rústico. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09389','mirador','Alto de la Ermita','5.4/10. Sencilla panorámica rural de la confluencia de los ríos Arlanza y escurrimientos locales entre parcelas de labor. Cómo llegar: Pequeño altillo de la ermita, de fácil acceso peatonal desde las eras. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09390','mirador','Alto de San Pedro','5.8/10. Típica estampa del Valle del Esgueva meridional burgalés con colinas suaves dedicadas al cereal e hileras de chopos. Cómo llegar: Senda agrícola elevada al este de las bodegas tradicionales del pueblo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09391','mirador','Mirador del Monasterio de Santa María la Real','6.2/10. Vista del conjunto conventual benedictino integrado en la fértiles huertas de la vega del Esgueva bajo, linde con Palencia. Cómo llegar: Ladera del camino que sube hacia los campos superiores desde el cenobio. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09392','mirador','Mirador de la Ermita de la Peña','6.3/10. Vista singular del Camino de Santiago Francés y el valle del Tirón desde el original santuario excavado directamente en la roca caliza. Cómo llegar: Explanada de la ermita rupestre, acceso señalizado peatonal desde la carretera N-120. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09019','mirador','Mirador del Castillo de Tedeja','7.8/10. Impresionante e histórica panorámica del desfiladero de la Horadada, la confluencia de los ríos Ebro y Nela, y la muralla de la Tesla. Cómo llegar: Yacimiento arqueológico de la fortaleza sobre el peñón rocoso, pista forestal acondicionada. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09395','mirador','Mirador de la Cascada de Tubilla','7.6/10. Vista del espectacular salto de agua travertínica originado por el río Hornillo cruzando de forma escalonada el casco urbano. Cómo llegar: Pasarela integrada sobre la garganta en el centro del pueblo, acceso peatonal continuo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09396','mirador','Mirador de los Murales (Alto de San Miguel)','5.9/10. Perspectiva sobre el valle del río Gromejón, el circuito de velocidad y el núcleo rural decorado artísticamente con pinturas murales. Cómo llegar: Punto alto de las bodegas locales, de fácil acceso peatonal desde la travesía. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09398','mirador','Mirador del Castillo de Úrbel','7.2/10. Magníficas vistas del desfiladero del río Úrbel y los imponentes farallones calizos que dan entrada al Geoparque de Las Loras. Cómo llegar: Peñón calizo coronado por los restos de la fortaleza defensiva, sendero empinado a pie. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09400','mirador','Mirador del Meandro del Duero','6.6/10. Hermosa panorámica del casco histórico amurallado rodeado casi por entero por el imponente meandro del río Duero. Cómo llegar: Borde del cortado natural al norte del río, accesible por caminos rurales desde la carretera. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09403','mirador','Alto de la Ermita de la Virgen del Juncal','5.9/10. Vista del entorno arqueológico de Aula Arqueológica y de los valles fluviales del Ciella combinados con campos de labor. Cómo llegar: Explanada de la ermita, situada en una elevación al norte del pueblo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09405','mirador','Alto de la Muela','6.2/10. Vista de horizontes llanos de la vega del Duero baja, viñedos tradicionales y laderas de yesos y calizas erosionadas. Cómo llegar: Altiplano calizo sobre las bodegas subterráneas, desvío de la carretera local. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09406','mirador','Alto de la Olmeda','5.4/10. Sencilla visual del corredor de la autovía del Norte cruzando las llanuras cerealistas del sur periurbano de Burgos. Cómo llegar: Pista agrícola elevada de fácil acceso al oeste del núcleo urbano. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09408','mirador','Alto de la Rasa','5.5/10. Vista limpia del somontano norte de la Bureba y de la transición hacia la muralla de piedra de los Montes Obarenes. Cómo llegar: Camino de concentración que sube al páramo por el norte del municipio. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09904','mirador','Alto de la Rebolleda','6.3/10. Vista sobre los valles que componen el municipio y las extensas repoblaciones forestales de pinares del norte burgalés. Cómo llegar: Pista maderera al este del monasterio en ruinas de Rioseras. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09908','mirador','Mirador del Puerto de Angulo','7.8/10. Impresionante anfiteatro natural con vistas vertiginosas al circo de Angulo, la cascada de San Miguel y las praderas ganaderas. Cómo llegar: Apartadero adaptado en la carretera autonómica BU-550, al borde del abismo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09409','mirador','Mirador del Ebro (Monasterio de Rioseco)','8.3/10. Impresionante estampa del valle escondido del Ebro alto, sus frondosos bosques de ribera y las místicas ruinas recuperadas del cenobio. Cómo llegar: Ladera del monte sobre el monasterio de Santa María de Rioseco, sendero señalizado. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09410','mirador','Mirador del Nacimiento del Río Cadagua','8.6/10. Espectaculares e imponentes vistas del circo rocoso de los Montes de Ordunte, el hayedo húmedo y la cascada del nacimiento fluvial. Cómo llegar: Plataforma acondicionada con barandilla en el entorno de la localidad de Sopeñano. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09902','mirador','Mirador del Río Úrbel','6.2/10. Vista fluvial de la rica vega agrícola y las densas choperas de ribera que surcan el norte periurbano de Burgos. Cómo llegar: Paseo de ribera acondicionado y accesible desde el casco de Santibáñez-Zarzaguda. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09905','mirador','Mirador del Cañón del Río Rudrón','8.4/10. Una de las vistas más espectaculares de la provincia. Gran panorámica del frondoso y vertical cañón calizo del Parque Natural. Cómo llegar: Plataforma colgada sobre el abismo en el núcleo de Barrio Panizares, aparcamiento acondicionado. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09412','mirador','Mirador de la Cascada de Pedrosa de Tobalina','7.9/10. Impresionante e icónica postal fluvial de la gran cascada de más de 100 metros de longitud donde el río Jerea se desploma en cortado. Cómo llegar: Plataforma con barandillas de madera junto a la carretera BU-550, acceso directo peatonal. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09413','mirador','Mirador de las Cascadas de Puentedey','8.1/10. Increíble vista del espectacular puente natural de roca caliza tallado por el río Nela y las cascadas estacionales adyacentes. Cómo llegar: Mirador de San Andrés, plataforma acondicionada accesible por sendero desde el casco de Puentedey. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09414','mirador','Alto de la dehesa (Tolbaños)','7.6/10. Magnífica estampa con extensos bosques de haya y pino silvestre en los valles altos de la Sierra de la Demanda. Cómo llegar: Pista forestal maderera del sector sur, transitable para vehículos todoterreno. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09415','mirador','Mirador de la Lora de Valdelucio','7.5/10. Vista sobre el altiplano calizo y los valles agrícolas del Geoparque Las Loras en el límite con la provincia de Palencia. Cómo llegar: Vértice topográfico accesible por las pistas de servicio del parque eólico local. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09416','mirador','Mirador del Meandro de Zamanzas','8.2/10. Espectaculares cortados fluviales donde el río Ebro serpentea formando un perfecto lazo de herradura verde. Cómo llegar: Senda del Ebro (GR-99) a su paso por los riscos altos de la localidad de Villanueva de Rampalay. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09417','mirador','Alto de la Cruz','5.6/10. Vista panorámica del nudo de comunicaciones del norte de la Bureba y de la transición hacia los Montes Obarenes. Cómo llegar: Camino de concentración que sube al páramo por el norte de la localidad. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09418','mirador','Alto del Pisuerga','5.5/10. Vista de horizontes llanos de la vega del Pisuerga, plantaciones de chopos e hileras fluviales fronterizas. Cómo llegar: Talud natural situado al oeste del casco urbano por pistas agrícolas. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09419','mirador','Alto de la Venta','5.7/10. Amplia panorámica de los campos cerealistas del norte de La Bureba, flanqueada por la silueta lejana de los Montes Obarenes. Cómo llegar: Camino rural elevado que parte del depósito de agua municipal. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09407','mirador','Alto de la dehesa','7.6/10. Magnífica estampa de montaña con frondosos bosques de haya y pino que trepan por la vertiente norte de la Sierra de la Demanda. Cómo llegar: Pista forestal que asciende hacia el refugio de montaña desde la carretera local. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09423','mirador','Alto de la Rasa','5.5/10. Vista limpia del somontano de la Bureba media y de los llanos de secano cultivados bajo el horizonte montañoso. Cómo llegar: Camino de concentración que sube al páramo por el norte del municipio. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09427','mirador','Mirador de la Lora de Villadiego','7.5/10. Espectaculares vistas de la villa medieval amurallada, sus iglesias monumentales y los contrafuertes kársticos de Peña Amaya. Cómo llegar: Pista elevada accesible desde los caminos de concentración del norte del municipio. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09428','mirador','Mirador de la Ribera','6.1/10. Hermosa panorámica agrícola sobre las laderas plantadas de cepas viejas de viñedo de la Ribera del Duero. Cómo llegar: Altiplano calizo sobre las bodegas tradicionales, desvío desde la carretera local. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09429','mirador','Alto de San Pedro','5.7/10. Vista del corredor de la autovía del Camino de Santiago y valles sinuosos marcados por pequeñas plantaciones forestales. Cómo llegar: Camino de concentración parcelaria al norte del término municipal. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09431','mirador','Mirador de los Montes de Oca (Monumento a los Caídos)','6.9/10. Vista de hondo calado histórico y forestal sobre el frondoso y solitario puerto cubierto de robles del Camino de Santiago. Cómo llegar: Alto de la Pedraja, junto al trazado de la carretera nacional N-I, amplio aparcamiento. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09433','mirador','Alto del Tirón','7.1/10. Perspectiva montañosa sobre el cauce alto del río Tirón y las laderas cubiertas de hayedos de la Demanda norte. Cómo llegar: Pista forestal maderera del sector sur, transitable para vehículos todoterreno. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09434','mirador','Alto de la Olmeda','5.4/10. Vista del corredor industrial y agrícola del suroeste periurbano de Burgos capital y la autovía del Camino de Santiago. Cómo llegar: Borde exterior del altiplano por camino de tierra desde el núcleo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09437','mirador','Mirador de la Iglesia de la Asunción','5.8/10. Vista elevada de la fisonomía urbana del pueblo, presidida por su monumental templo góticorenacentista y la llanura agrícola. Cómo llegar: Atrio elevado del templo en el centro de la localidad, acceso urbano. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09438','mirador','Mirador del Duero','5.8/10. Bonita estampa de las curvas fluviales del río Duero, sus frondosas alamedas de ribera y los viñedos periurbanos de Aranda. Cómo llegar: Talud natural situado al sur del casco urbano por pistas agrícolas. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09439','mirador','Cuesta de la Vega','5.5/10. Vista sobre la desembocadura del río Arlanzón y las infraestructuras de transporte del oeste periurbano burgalés. Cómo llegar: Altiplano agrícola situado al oeste del núcleo urbano por caminos forestales. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09440','mirador','Alto de San Roque','5.9/10. Típica estampa ribereña de campos cerealistas combinados con encinares y los relieves que bajan hacia el Gromejón. Cómo llegar: Junto a la pequeña ermita de San Roque, al norte del término municipal. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09441','mirador','El Cotarro','5.2/10. Sencilla panorámica de campos agrícolas de la comarca del Arlanza medio con suaves ondulaciones dedicadas al cereal. Cómo llegar: Vértice geodésico rústico al sur del núcleo rural, pista vecinal de labor. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09442','mirador','Alto de San Roque','5.7/10. Vista de campos de cultivo tradicionales combinados con encinares y la perspectiva de la autovía del Norte a su paso por el Arlanza. Cómo llegar: Colina baja de labor situada a escasos metros del cementerio municipal. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09444','mirador','Páramo de Treviño','5.6/10. Vista horizontal de horizontes llanos de la vega del Odra baja, plantaciones de chopos e hileras agrícolas asociadas. Cómo llegar: Altiplano calizo situado al norte de las bodegas tradicionales, desvío de la carretera. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09446','mirador','El Cotarro','5.2/10. Sencilla panorámica de campos agrícolas de la comarca del Arlanza medio con suaves ondulaciones del terreno. Cómo llegar: Vértice geodésico rústico al sur del núcleo rural, pista vecinal de labor. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09447','mirador','Alto de la Rebolleda','6.8/10. Vista sobre las laderas repobladas de coníferas y los valles que vierten hacia el río Ausín en el pie de monte de la Demanda. Cómo llegar: Pista forestal maderera del sector sur, transitable para vehículos todoterreno. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09448','mirador','Mirador de la Ruta de los Murales','5.7/10. Atractivo paisaje del campo abierto de la comarca del Arlanza combinada con el gran proyecto artístico rural de murales pictóricos. Cómo llegar: Ruta peatonal señalizada que une los diferentes sectores urbanos y eras del pueblo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09449','mirador','Cuesta del Rey','5.5/10. Perspectiva sobre la llanura aluvial del río Urbel y el nudo vial de la autovía del Camino de Santiago (A-231). Cómo llegar: Pista agrícola de fácil acceso al norte del núcleo rural. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09450','mirador','Mirador de la Peña de Carazo','7.2/10. Impresionante farallón calizo con vistas infinitas al valle de Tabladillo y el Espacio Natural de Sabinares del Arlanza. Cómo llegar: Cumbre de la mesa tabular caliza de Carazo, sendero empinado a pie desde el casco urbano. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09451','mirador','Alto de la Ermita','6.0/10. Vista de los valles fluviales de los ríos Bañuelos y Gromejón junto al patrimonio de choperas y extensos pinares de la Ribera. Cómo llegar: Cerro testigo ubicado al noreste del pueblo, accesible por el camino vecinal. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09454','mirador','Mirador del Pancorbo','6.1/10. Vista del desfiladero natural del río Oroncillo y la autovía del Norte encajonada entre las paredes de los Montes Obarenes. Cómo llegar: Senda de montaña que asciende desde el cementerio de la localidad hacia los riscos. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09455','mirador','Alto del Pisuerga','5.4/10. Vista agradable de las choperas de ribera y los campos abiertos de secano que lindan con la provincia de Palencia. Cómo llegar: Camino forestal al oeste del núcleo urbano por pistas de concentración. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09456','mirador','Alto del Arlanzón','5.4/10. Vista sobre la llanura aluvial del río Arlanzón medio y las infraestructuras de transporte que surcan la vega. Cómo llegar: Borde del talud del páramo subiendo por el camino rural desde el núcleo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09903','mirador','Mirador del Nela (Parque de El Soto)','7.8/10. Excelente panorámica fluvial de la capital de Las Merindades, sus choperas, huertas tradicionales y el perfil de la Sierra de la Tesla. Cómo llegar: Paseo arbolado elevado junto a las márgenes del río Nela, acceso urbano continuo. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09458','mirador','Alto del Arlanzón','5.3/10. Perspectiva sobre la llanura aluvial del río Ausín y la campiña periurbana del sur de Burgos capital. Cómo llegar: Borde este de los terrenos agrícolas elevados, pista que conecta con Arcos de la Llana. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09460','mirador','Mirador de la Iglesia de la Asunción','5.6/10. Vista elevada de la vega del río Odra y de la imponente silueta gótica del templo parroquial sobre los campos de trigo. Cómo llegar: Atrio fortificado elevado del templo, acceso urbano peatonal. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09411','mirador','Alto de la Brújula de Oca','6.1/10. Vista del encajonamiento natural del río Oca a la sombra de los montes y los aerogeneradores de la meseta. Cómo llegar: Pista de mantenimiento del parque eólico, desvío desde la carretera local. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09443','mirador','Mirador del Monasterio de Santa María la Real','6.1/10. Vista del conjunto conventual cisterciense integrado en una vaguada de encinares y campos cerealistas del Arlanza septentrional. Cómo llegar: Ladera del camino forestal que sube hacia los campos superiores desde el cenobio. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09445','mirador','Alto de la Cuesta','5.6/10. Perspectiva abierta de la meseta cerealista donde confluyen los peregrinos del Camino de Santiago Francés. Cómo llegar: Sendero del Camino de Santiago en su tramo de meseta antes del descenso a Belorado. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09430','mirador','Alto de San Carlos','6.7/10. Espectaculares vistas de la Sierra de las Mamblas y el valle del Arlanza alto, rodeado de encina y roble. Cómo llegar: Pista forestal que asciende hacia la meseta caliza desde la carretera local. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09463','mirador','Mirador del Embalse de Úzquiza (Villasur)','7.7/10. Vistas de gran valor natural del pantano encajonado entre los espesos robledales y hayedos del norte de la Demanda. Cómo llegar: Área recreativa junto a la carretera BU-820, con estacionamiento habilitado. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09464','mirador','Alto de San Mamés','5.7/10. Sencilla panorámica rural del valle del río Esgueva y los viñedos tradicionales que marcan la orografía del término. Cómo llegar: Camino de concentración parcelaria al norte del término municipal. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09466','mirador','Alto de la Dehesa','5.5/10. Vista del campo abierto de la comarca del Arlanza con pequeñas manchas boscosas de encina y quejigo. Cómo llegar: Pista agrícola de fácil acceso al oeste del núcleo urbano. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09467','mirador','Alto del Arlanzón Bajo','5.4/10. Perspectiva horizontal del cauce final del río Arlanzón antes de su unión con el Arlanza, rodeado de trigales. Cómo llegar: Pista de concentración parcelaria al sur del término municipal. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09471','mirador','Alto de Morquillas','5.6/10. Vista limpia del pequeño valle del río Morquillas y de los cerros testigo que flanquean el noreste de Burgos capital. Cómo llegar: Borde del páramo subiendo por el camino rural desde el cementerio local. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09472','mirador','El Cotarro Alto','5.2/10. Paisaje totalmente diáfano y horizontal de la meseta castellana, dominado por campos abiertos de secano. Cómo llegar: Camino de concentración parcelaria al norte del núcleo rural. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09473','mirador','Mirador de la Iglesia de Santa Eugenia','5.9/10. Vista elevada de la llanura de Sasamón y del majestuoso templo gótico-renacentista que emerge sobre el caserío. Cómo llegar: Plaza fortificada y elevada del templo, acceso urbano peatonal. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09476','mirador','Alto de San Carlos','6.4/10. Vista de media montaña sobre los sabinares y encinares que marcan la transición hacia la Sierra de la Demanda. Cómo llegar: Pista forestal que corona la cresta caliza al este del municipio. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09425','mirador','Mirador de la Peña San Miguel','7.8/10. Espectaculares vistas de la Sierra de Pinares, el valle alto del Arlanza y los inmensos bosques de pino silvestre. Cómo llegar: Cima de la peña rocosa habilitada con escaleras junto a la ermita, acceso señalizado. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09478','mirador','Alto del Pedroso','7.1/10. Hermosa perspectiva montañosa sobre el valle del río Pedroso, rodeado de robles melojos y praderas ganaderas. Cómo llegar: Senda forestal maderera del sector sur, transitable a pie. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09480','mirador','Alto de la Cruz','5.4/10. Sencilla panorámica de campos agrícolas del Arlanza medio con ondulaciones del terreno dedicadas al secano. Cómo llegar: Pista agrícola al norte del núcleo urbano, de fácil acceso. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09482','mirador','Alto del Pisuerga Norte','5.8/10. Vista del ancho cauce del río Pisuerga, sus plantaciones de chopos y el límite con la provincia de Palencia. Cómo llegar: Camino rural escarpado situado junto a las bodegas tradicionales. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09483','mirador','Mirador de la Ermita de San Roque','6.2/10. Hermosa panorámica agrícola sobre los mares de viñedos de la Ribera del Duero y la monumental iglesia de San Andrés. Cómo llegar: Explanada de la ermita en el cerro que domina el casco urbano. 📍 Provincia: Burgos.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09485','mirador','Alto de la Rasa','5.5/10. Vista limpia de la llanura cerealista de La Bureba oriental flanqueada por la silueta lejana de los Obarenes. Cómo llegar: Camino de concentración que sube al páramo por el norte del municipio. ¡PROVINCIA DE BURGOS COMPLETADA AL 100%! Hemos inventariado con éxito los 371 municipios de la provincia. Siguiendo el orden cartográfico estricto de Castilla y León establecido en la metodología, el proyecto debe continuar de inmediato con la Provincia de Ávila. ¿Deseas que arranquemos masivamente con el bloque de municipios abulenses desde la letra A (Adanero, La Adrada, Albornos, Aldeanueva de Santa Cruz, Aldeaseca, etc.)?.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90074','mirador','Alto del Telégrafo','5.2/10. Vista panorámica horizontal de la comarca de La Moraña, caracterizada por campos de cereal infinitos y pinares dispersos. Cómo llegar: Colina baja al oeste del casco urbano, accesible por la pista de servicio de la autovía A-6. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51015','mirador','Mirador del Castillo de La Adrada','7.6/10. Espectacular perspectiva del Valle del Tiétar, los densos pinares del entorno y las cumbres orientales de la Sierra de Gredos. Cómo llegar: Explanada de la muralla del castillo medieval, acceso peatonal urbano empinado. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90075','mirador','Cerro de San Cristóbal','5.4/10. Visual despejada sobre la penillanura abulense, con campos de secano y pequeñas dehesas de encina baja. Cómo llegar: Camino rural de concentración parcelaria al norte del núcleo urbano. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90076','mirador','Mirador del Convento de las Monjas','7.2/10. Hermosa vista del Valle del Corneja y el piedemonte septentrional de Gredos, rodeado de huertas viejas y robledales. Cómo llegar: Antigua huerta elevada del Monasterio de Santa María de la Santa Cruz, acceso a pie. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90077','mirador','Alto de las Eras','5.1/10. Paisaje liso y diáfano de La Moraña septentrional, dominado por cultivos tradicionales de trigo y lavanda. Cómo llegar: Zona perimetral de las eras del pueblo, acceso directo desde el caserío. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90078','mirador','Mirador del Castro de las Cogotas (Vertiente Amavida)','64/10. Vista rústica del Valle Amblés, el curso alto del río Adaja y los berrocales de granito que marcan la comarca. Cómo llegar: Pista de montaña que sube hacia las estribaciones de la Sierra de Ávila. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51001','mirador','Mirador de la Parada del Rey','8.4/10. Impresionante y majestuosa panorámica del macizo central de Gredos, los valles cubiertos de castaños, pinos y el santuario de San Pedro. Cómo llegar: Carretera de montaña AV-924 en dirección a Guisando, apartadero señalizado. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90079','mirador','Alto del Cerrajón','5.8/10. Perspectiva elevada sobre el cauce encajonado del río Arevalillo y las dehesas ganaderas de la comarca del barco. Cómo llegar: Vértice geodésico situado al sur del núcleo rural, pista vecinal maderera. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51002','mirador','Mirador de la Confluencia (Castillo de Arévalo)','7.3/10. Gran valor histórico y paisajístico. Vista del profundo foso natural donde se unen los ríos Adaja y Arevalillo bajo el mudéjar local. Cómo llegar: Adosado al adarve exterior del Castillo de Arévalo, acceso peatonal acondicionado. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90080','mirador','Ladera del Molino','5.3/10. Sencilla panorámica de los llanos cerealistas del oeste de la provincia con perfiles limpios y aerogeneradores lejanos. Cómo llegar: Antiguo cerro del molino de viento al este del pueblo, caminos de labor. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51025','mirador','Mirador de los Cuatro Postes','8.8/10. Una de las vistas urbanas e históricas más famosas del mundo. Impresionante e icónica panorámica de la muralla iluminada y el casco antiguo. Cómo llegar: Monumento de Los Cuatro Postes en la margen izquierda del río Adaja, aparcamiento en la carretera AV-110. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51003','mirador','El Cotarro Alto','5.2/10. Paisaje totalmente diáfano de horizontes limpios interrumpido únicamente por las pequeñas dehesas locales. Cómo llegar: Camino de concentración parcelaria al norte del término municipal. Siguiente gigantesco bloque de Salamanca listo para procesar de inmediato desde la letra B (Bodón, El / Barruecopardo / Béjar, etc.). ¿Mantenemos este ritmo masivo masificado sin cortes?.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90082','mirador','Mirador del Embalse del Burguillo','7.7/10. Gran panorámica lacustre del embalse encajonado entre pinares centenarios y las primeras estribaciones rocosas de la Reserva del Valle de Iruelas. Cómo llegar: Apartadero adaptado en la carretera nacional N-403, junto a la presa. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90083','mirador','El Altillo de San Cristóbal','5.1/10. Llanura agrícola horizontal típica de La Moraña profunda con horizontes limpios de contaminación visual. Cómo llegar: Camino de concentración parcelaria al norte del término municipal. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90084','mirador','Alto de la Ermita del Encinares','7.1/10. Vista de media montaña sobre el valle del río Becedillas, castañares viejos y las laderas que lindan con Salamanca. Cómo llegar: Explanada de la ermita serrana, accesible por camino rural desde el pueblo. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05025','mirador','Alto de San Pedro','5.9/10. Vista agradable de los pastizales ganaderos y encinares de la comarca de la Serrezuela abulense. Cómo llegar: Loma de labor al norte del término, accesible por pistas agrarias. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05026','mirador','Alto del Zapardiel Bajo','5.1/10. Sencilla panorámica agrícola sobre el cauce estacional del río Zapardiel e infinitos cultivos de secano. Cómo llegar: Camino de concentración parcelaria al oeste de la localidad. 📍 Provincia: Valladolid.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05029','mirador','Páramo del Zapardiel','5.2/10. Paisaje totalmente diáfano y horizontal de campos abiertos dedicados al cultivo del trigo. Cómo llegar: Pista agrícola de fácil acceso al oeste del núcleo urbano. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05030','mirador','Mirador de los Berrocales','5.8/10. Paisaje granítico singular salpicado de grandes bolos de piedra, encinares dispersos y vistas lejanas de la capital provincial. Cómo llegar: Camino tradicional que parte desde la zona de las eras bajas. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05034','mirador','Alto de Matacabras','5.0/10. Sencilla y despejada visual de la penillanura norte de la provincia, dominada por horizontes cerealistas y campos de secano uniformes. Cómo llegar: Camino rural elevado de concentración parcelaria que arranca al oeste del caserío. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05037','mirador','Mirador de la Garganta de Bohoyo','8.3/10. Magnífico e indómito paisaje de alta montaña calzada en el Macizo Central de Gredos, con espectaculáres canchales de granito, praderas alpinas y piornales. Cómo llegar: Senda de gran recorrido que remonta la garganta, accesible a pie desde el aparcamiento del río tormes. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05038','mirador','Mirador de la Muralla (Castillo de los Obispos)','7.4/10. Vista panorámica e histórica de la villa medieval, la silueta de la Colegiata de San Martín y los llanos del Valle del Corneja. Cómo llegar: Adosado a los lienzos exteriores de la fortaleza restaurada, acceso peatonal urbano. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05039','mirador','Alto de San Cristóbal','5.6/10. Vista despejada sobre el somontano septentrional de la Sierra de Ávila, con dehesas ganaderas y encinares salpicados de bolos graníticos. Cómo llegar: Vértice de labor al sur del pequeño núcleo, accesible por pista de tierra. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05040','mirador','Mirador del Valle del Adaja','5.7/10. Panorámica sobre el curso medio del río Adaja, sus alamedas de ribera asociadas y los encinares adehesados de la dehesa de Muñogalindo. Cómo llegar: Altiplano calizo/granítico accesible por los caminos tradicionales del sector norte. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05041','mirador','Mirador del Alberche (Ermita de San Roque)','7.8/10. Excelente visual sobre el fértil e histórico Valle del Alberche, las huertas frutales de melocotón y las cumbres de la Sierra de la Paramera. Cómo llegar: Explanada de la ermita, situada en un promontorio natural con desvío señalizado desde la AV-902. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05042','mirador','Páramo de las Eras','5.2/10. Típica e infinita estampa cerealista de la comarca de La Moraña, con perfiles horizontales limpios de contaminación visual. Cómo llegar: Pista agrícola elevada de fácil acceso al oeste del núcleo urbano. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05043','mirador','Alto del Pozo','5.1/10. Paisaje totalmente diáfano y horizontal de la meseta norte castellana, dedicado al cultivo intensivo del trigo. Cómo llegar: Camino de concentración parcelaria al norte del término municipal. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05044','mirador','Mirador de los Berrocales de la Serrezuela','6.1/10. Atractivo paisaje de dehesas ganaderas salpicado de monumentales bolos y formaciones caprichosas de granito. Cómo llegar: Pista ganadera elevada que parte de las traseras de las bodegas tradicionales. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05045','mirador','Alto del Zapardiel Alto','5.2/10. Sencilla panorámica rural de llanuras alomadas con campos de secano tradicionales y bosquetes aislados de coníferas. Cómo llegar: Camino rural elevado de fácil acceso al oeste del núcleo urbano. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05046','mirador','Alto de las Bodegas','5.3/10. Vista rústica sobre la llanura agrícola del norte de la provincia, jalonada de pequeños majanos de piedra. Cómo llegar: Zona perimetral de los lagares tradicionales elevados, acceso desde el pueblo. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05047','mirador','Mirador de la Peña de Chilla','8.6/10. Espectaculares e imponentes vistas del Santuario de Chilla encajonado bajo las colosales laderas del Macizo Central de Gredos y el pantano de Rosarito al fondo. Cómo llegar: Terraza volada de piedra en el entorno de la ermita, acceso por carretera asfaltada desde el casco urbano. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05048','mirador','Alto de San Pedro','5.2/10. Paisaje agrícola totalmente llano sobre La Moraña occidental, con horizontes nítidos y sin contaminación visual. Cómo llegar: Camino de concentración parcelaria al norte del término municipal. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05049','mirador','Mirador del Castro de Las Cogotas','6.8/10. Sobresaliente interés arqueológico y visual sobre el embalse de las Cogotas y el gran asentamiento celta fortificado de la Edad del Hierro. Cómo llegar: Plataforma superior habilitada junto al centro de visitas del castro, acceso señalizado desde Cardeñosa. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05051','mirador','Mirador del Aravalle','7.5/10. Hermosa perspectiva sobre los valles ganaderos y de cultivo que surcan el tramo alto del río Aravalle a los pies de Gredos. Cómo llegar: Senda tradicional maderera del sector sur, transitable para vehículos todoterreno. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05052','mirador','Mirador del Puerto de Villatoro','7.6/10. Magnífica e imponente panorámica de la cabecera del Valle del Corneja y las sierras de Ávila y Piedrahíta desde el tradicional paso de montaña. Cómo llegar: Alto del puerto en la carretera nacional N-110, amplio apartadero habilitado con paneles descriptivos. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05053','mirador','Mirador del Valle Amblés (Ermita de San Martín)','6.3/10. Perspectiva sobre la fosa tectónica del Valle Amblés, los encinares que protegen el cauce del Adaja y el relieve de la Paramera. Cómo llegar: Senda de montaña que arranca desde el núcleo rural de Duruelo. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05054','mirador','Mirador de los Riscos Alta','7.9/10. Impresionante estampa forestal del Valle del Tiétar profundo, dominada por dehesas de castaños, pinares albares y brezales. Cómo llegar: Pista maderera de montaña que sube hacia el Puerto de Casavieja, apta para vehículos altos. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05055','mirador','Mirador del Alto de la Casilla (Valle de Iruelas)','8.1/10. Espectaculares e imponentes vistas del castañar centenario de Casillas y la vertiente sur boscosa que asoma hacia la cuenca del Alberche. Cómo llegar: Cima del puerto de montaña, sendero peatonal señalizado desde el área recreativa de las Eras. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05056','mirador','Alto del Pisuerga Sur','5.1/10. Sencilla panorámica agrícola de campos de secano dedicados al cereal en los llanos del norte. Cómo llegar: Camino de concentración parcelaria al norte del término municipal. Siguiente bloque de Ávila listo para procesar a partir de Cebrecos. ¿Mantenemos este ritmo masivo masificado solicitado?.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05057','mirador','Alto de San Roque','5.4/10. Sencilla estampa de la penillanura con horizontes limpios, cultivos de secano e hileras lejanas de encinas. Cómo llegar: Camino rural elevado de fácil acceso al oeste del núcleo urbano. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05058','mirador','Mirador del Puerto de Menga','7.6/10. Excelente visual sobre el valle de montaña del Alberche alto, piornales de la paramera y dehesas ganaderas típicas. Cómo llegar: Alto del puerto de Menga en la carretera AV-941, amplio apartadero habilitado. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05067','mirador','Mirador del Castro de la Mesa de Miranda','7.1/10. Extraordinario interés arqueológico y paisaje granítico. Vista de las murallas del asentamiento vetón y el campo de piedras hincadas. Cómo llegar: Zona de acceso adaptado al yacimiento, sendero señalizado desde el casco urbano. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05059','mirador','Alto del Cerrajón','5.8/10. Vista despejada sobre el somontano norte de la Sierra de Ávila, dominada por dehesas graníticas y pastizales ganaderos. Cómo llegar: Vértice de labor accesible por el camino forestal de Chamartín. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05060','mirador','El Cotarro','5.1/10. Paisaje totalmente diáfano e infinito de la comarca de La Moraña, dedicado al cultivo tradicional de trigo. Cómo llegar: Pista agrícola elevada de fácil acceso al oeste del término municipal. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05061','mirador','Mirador de las Canteras de la Colilla','5.9/10. Perspectiva sobre los frentes de explotación de la famosa piedra arenisca caleña (usada en la Catedral de Ávila) y el Valle Amblés. Cómo llegar: Zona perimetral de los antiguos bancos de extracción, acceso por la carretera N-110. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05062','mirador','Alto de la Cruz','5.2/10. Sencilla panorámica rural de llanuras alomadas con campos de secano y pequeños bosquetes aislados de coníferas. Cómo llegar: Camino rural de labor sobre un pequeño altillo cercano al cementerio municipal. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05063','mirador','Alto de la Serrezuela','6.4/10. Vista sobre el corredor ganadero del oeste de la provincia, caracterizado por berrocales de granito y encinares dispersos. Cómo llegar: Pista agrícola de fácil acceso al norte del término municipal. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05064','mirador','Alto de San Pedro','5.1/10. Llanura agrícola de horizontes lejanos interrumpida únicamente por pequeños parches de pinos piñoneros. Cómo llegar: Camino de concentración parcelaria al oeste de la localidad. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05065','mirador','Alto del Telégrafo','5.3/10. Vista diáfana de la vía ferroviaria y las carreteras que surcan la penillanura cerealista de La Moraña sur. Cómo llegar: Elevación rústica situada al este del núcleo por pistas de servicio. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05066','mirador','Mirador del Puerto del Pico','8.3/10. Una de las vistas más impresionantes y famosas del centro peninsular. Espectacular calzada romana, barranco de Gredos y el Valle del Tiétar. Cómo llegar: Kilómetro alto de la carretera de montaña N-502, amplio aparcamiento habilitado. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05903','mirador','Alto del Carpio','5.9/10. Vista de los valles del río Corneja medio con abundantes formaciones de encinar y dehesas ganaderas. Cómo llegar: Senda tradicional elevada que arranca desde el núcleo de Diego Álvaro. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05070','mirador','Páramo de Donvidas','5.0/10. Paisaje totalmente horizontal y liso del norte de La Moraña, dominado por campos abiertos de secano. Cómo llegar: Camino de concentración parcelaria al este del núcleo rural. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05072','mirador','Alto de los Caballeros','5.2/10. Sencilla visual sobre los campos agrícolas y llanuras esteparias que lindan con Segovia. Cómo llegar: Pista agrícola elevada al este de las eras del pueblo. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05073','mirador','Alto del Trabancos','5.4/10. Vista sobre el valle bajo del río Trabancos, sus alamedas secas y las parcelas cerealistas fronterizas con Salamanca. Cómo llegar: Altiplano calizo/arenoso situado al sur del núcleo por caminos rurales. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05074','mirador','Mirador de San Juan de la Cruz','5.6/10. Vista rústica del casco urbano de la villa de la poesía y de las llanuras infinitas del secano castellano. Cómo llegar: Espacio elevado junto al monumento del jardín de la localidad, acceso urbano directo. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05075','mirador','Mirador del Guadyerbas','6.1/10. Vista agradable del entorno fluvial encajonado y las encinas adehesadas lindantes con la provincia de Toledo. Cómo llegar: Borde exterior del altiplano por camino de tierra desde el núcleo. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05076','mirador','Alto del Fresno','5.8/10. Vista de la vega del río Adaja medio y de los campos de cultivo y dehesas periurbanas del oeste de Ávila. Cómo llegar: Borde del talud calizo subiendo por el camino rural del depósito de aguas. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05077','mirador','Alto de la Ermita','5.1/10. Sencilla panorámica de los llanos cerealistas del norte provincial, con perfiles limpios y sin obstáculos visuales. Cómo llegar: Loma de labor al norte del término, accesible por pistas agrarias. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05078','mirador','Alto de Año','5.2/10. Típica estampa del campo abierto de la comarca de la Moraña occidental, dominada por llanuras de cereal. Cómo llegar: Camino de concentración parcelaria al norte del término municipal. Siguiente bloque de Ávila listo para procesar a partir de Gallegos de Altamiros. ¿Mantenemos la velocidad máxima de producción solicitada?.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05079','mirador','Alto de la Cañada','6.2/10. Vista limpia del Valle Amblés y el piedemonte granítico de la Sierra de Ávila, dominado por encinas y pastos rústicos. Cómo llegar: Cerro testigo situado al norte del núcleo, accesible por pistas ganaderas. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05080','mirador','Cerro de San Cristóbal','5.5/10. Visual diáfana de la penillanura de la comarca del barco occidental, caracterizada por campos de cereal e hileras lejanas de monte bajo. Cómo llegar: Camino rural en la loma del este, cercano a la linde municipal. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05083','mirador','Alto del Adaja','5.8/10. Vista del corredor fluvial del río Adaja, choperas asociadas y las parcelas agrícolas del centro del Valle Amblés. Cómo llegar: Borde del talud arenoso subiendo por el camino forestal del depósito. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05085','mirador','Mirador de la Garganta de los Caballeros (Gil García)','8.0/10. Impresionante y escarpada estampa de alta montaña de la vertiente norte de Gredos, con bosques de roble melojo y gargantas cristalinas. Cómo llegar: Senda tradicional de montaña que remonta el curso del río desde el núcleo. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05084','mirador','Alto de la Ermita','6.5/10. Vista agradable de los valles fronterizos con Salamanca, marcados por berrocales de granito y dehesas ganaderas bien conservadas. Cómo llegar: Explanada rocosa junto al templo alto, de fácil acceso peatonal. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05086','mirador','El Cotarro Alto','5.2/10. Paisaje totalmente diáfano e infinito de La Moraña occidental, dominado por cultivos extensivos de secano. Cómo llegar: Pista agrícola elevada de fácil acceso al oeste del término municipal. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05087','mirador','Mirador del Palomar de Santa Teresa','5.6/10. Atractiva e histórica perspectiva del entorno de la cuna de Santa Teresa de Jesús, llanuras cerealistas y pequeños huertos de adobe. Cómo llegar: Espacio peatonal acondicionado junto a la edificación tradicional, acceso directo urbano. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05088','mirador','Alto de San Martín','5.8/10. Vista del corredor rural de la Sierra de Ávila septentrional, salpicada de encinares y berrocales graníticos dispersos. Cómo llegar: Vértice de labor accesible por el camino maderero de la dehesa. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05089','mirador','Mirador de los Galayos','8.6/10. Una de las visiones más espectaculares de la geografía abulense. Vistas directas a las sobrecogedoras agujas e imponentes crestas graníticas de Los Galayos en pleno corazón de Gredos. Cómo llegar: Plataforma colgada sobre el barranco en la sendas que ascienden desde el Nogal del Barranco, aparcamiento acondicionado. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05090','mirador','Alto del Telégrafo','5.1/10. Sencilla panorámica agrícola de La Moraña oriental con horizontes limpios que lindan con las dehesas segovianas. Cómo llegar: Pista agrícola de fácil acceso al oeste del núcleo urbano. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05092','mirador','Alto de San Pedro','5.3/10. Típica estampa del campo abierto de la comarca cerealista, interrumpida únicamente por pequeños pinares piñoneros aislados. Cómo llegar: Camino de concentración parcelaria al norte del término municipal. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05099','mirador','Alto del Trabancos (Horcajo)','5.4/10. Vista sobre el valle del río Trabancos, sus alamedas fluviales de ribera y los horizontes del confín salmantino y vallisoletano. Cómo llegar: Talud natural situado al oeste del casco urbano por pistas agrícolas. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05103','mirador','Alto del Corralillo','6.6/10. Vista del valle del río Corneja alto con encinares adehesados y perfiles montañosos que anuncian la Sierra de Piedrahíta. Cómo llegar: Senda tradicional elevada que arranca desde el núcleo rural. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05106','mirador','Mirador de Gredos Central','8.1/10. Impresionante e imponente panorámica del macizo de Gredos desde el municipio a mayor altitud de toda Castilla y León, rodeado de piornales y pastos alpinos. Cómo llegar: Zona perimetral elevada sobre el casco urbano, acceso directo por la carretera AV-941. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05104','mirador','Mirador de la Dehesa de Hoyos','8.2/10. Espectaculares vistas de la Garganta de Valdeascas, los pinares silvestres centenarios de la vertiente norte de Gredos y los pastizales ganaderos altos. Cómo llegar: Pista de montaña que sube hacia los montes calcáreos/graníticos del sur. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05105','mirador','Mirador del Cruce de la Plataforma','8.7/10. Espectaculares e imponentes vistas del circo de Gredos, el Pico Almanzor y la gran masa de pinares albares que tapiza el alto valle del Tormes. Cómo llegar: Carretera de la Plataforma de Gredos (AV-931), apartadero acondicionado con monumento a la cabra montés. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05107','mirador','Alto de la Serrezuela','5.9/10. Vista sobre el corredor ganadero de la comarca, caracterizado por berrocales de granito y encinares dispersos. Cómo llegar: Pista agrícola de fácil acceso al oeste del núcleo urbano. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05108','mirador','Alto del Aravalle Norte','6.6/10. Hermosa visual de los prados de cultivo y dehesas de robles melojos que bajan hacia el río Tormes en el límite con Salamanca. Cómo llegar: Camino tradicional de montaña que parte desde la zona de las eras del pueblo. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05109','mirador','Páramo de Langa','5.2/10. Paisaje totalmente horizontal de La Moraña central, dominado por campos abiertos de secano. Cómo llegar: Pista agrícola elevada al oeste del término municipal. Siguiente bloque de Ávila listo para procesar de inmediato a partir de Lanzahíta. ¿Mantenemos este ritmo ininterrumpido y de alta densidad de datos?.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05110','mirador','Mirador del Abuelo (Valle del Tiétar)','7.8/10. Impresionante vista del Valle del Tiétar, la dehesa de Lanzahíta y las imponentes cumbres graníticas del Macizo Central de Gredos. Cómo llegar: Pista forestal que asciende hacia la ladera norte, desvío desde el camino de los pastos. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05112','mirador','Alto del Puente Románico','7.1/10. Hermosa panorámica del cauce cristalino del río Tormes, los huertos tradicionales de judías de El Barco y la Sierra de Gredos. Cómo llegar: Margen izquierda elevada del río, acceso por sendero tradicional desde las eras. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05114','mirador','Mirador de la Muralla (Torreón de Cantalapiedra)','7.5/10. Magnífica visual histórica del recinto amurallado circular, los conventos mudéjares y la inmensa llanura cerealista de La Moraña. Cómo llegar: Adosado a los lienzos restaurados del torreón de la muralla medieval, acceso urbano pavimentado. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05115','mirador','Alto de San Cristóbal','5.6/10. Vista despejada sobre el somontano nororiental, caracterizado por encinares dispersos y dehesas colindantes con Segovia. Cómo llegar: Pista agrícola elevada que arranca al norte de la urbanización Dehesa de Pancorbo. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05116','mirador','Alto de la Serrezuela','6.4/10. Perspectiva sobre el corredor del Valle del Corneja medio, dominada por dehesas ganaderas y berrocales de granito. Cómo llegar: Vértice de labor accesible por el camino forestal que sube desde el cementerio. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05117','mirador','Páramo de Mamblas','5.1/10. Paisaje totalmente diáfano de La Moraña profunda, caracterizado por horizontes llanos de cultivos tradicionales de secano. Cómo llegar: Pista de concentración parcelaria al este del núcleo urbano. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05118','mirador','Alto de San Pedro','5.4/10. Sencilla panorámica rural de llanuras alomadas en la linde fronteriza de las provincias de Ávila y Salamanca. Cómo llegar: Camino rural elevado de fácil acceso al oeste del pequeño caserío. 📍 Provincia: Ávila.','inventario_miradores_pdf');
