INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05121','mirador','Mirador del Berrocal','5.8/10. Vista despejada de las dehesas graníticas del Valle Amblés y de los perfiles monumentales del recinto amurallado de Ávila capital. Cómo llegar: Altiplano calizo/granítico accesible por la carretera local AV-110. 📍 Provincia: Ávila.','inventario_miradores_pdf');
