INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05136','mirador','Alto de San Cristóbal','5.7/10. Perspectiva elevada sobre las cuencas de los arroyos locales y campos de dehesa ganadera tradicional. Cómo llegar: Vértice de labor al norte del pueblo, accesible mediante camino vecinal de tierra. 📍 Provincia: Ávila.','inventario_miradores_pdf');
