INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05225','mirador','Mirador de los Pañeros','6.8/10. Vista panorámica de la villa textil tradicional, las dehesas ganaderas de granito y el Valle del Corneja bajo. Cómo llegar: Cerro sobre los lagares y telares tradicionales, desvío de la carretera local. 📍 Provincia: Ávila.','inventario_miradores_pdf');
