INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05228','mirador','Alto de la Serrezuela','7.1/10. Vista de media montaña sobre el valle del río Corneja alto, rodeado de robles melojos y formaciones graníticas. Cómo llegar: Senda peatonal desde la iglesia parroquial hacia el alto del cerro. 📍 Provincia: Ávila.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05904','mirador','Mirador de la Lastra (Gredos Occidental)','8.1/10. Espectaculares e imponentes vistas de los valles ganaderos altos del Tormes y las cumbres nevadas del Aravalle. Cómo llegar: Carretera de montaña AV-941, apartadero adaptado cerca de Lastra del Cano. 📍 Provincia: Ávila.','inventario_miradores_pdf');
