INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05237','mirador','Alto de la Serrezuela','5.9/10. Vista sobre el corredor ganadero del río Almar, caracterizado por berrocales de granito y encinares dispersos. Cómo llegar: Pista agrícola de fácil acceso al oeste del núcleo urbano. 📍 Provincia: Ávila.','inventario_miradores_pdf');
