INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37086','mirador','Alto de la dehesa de Azaba','6.1/10. Paisaje liso e intermedio cubierto por un espeso monte de encinas y pastizales ganaderos en la frontera salmantina. Cómo llegar: Camino de concentración que asciende al altiplano desde el núcleo rural. 📍 Provincia: Salamanca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37087','mirador','Mirador de Peñasolana','5.9/10. Visual diáfana del inicio de la comarca de Ledesma, campos de cultivo tradicionales y pequeñas urbanizaciones de la periferia. Cómo llegar: Punto alto de la urbanización homónima, de fácil acceso peatonal y rodado. 📍 Provincia: Salamanca.','inventario_miradores_pdf');
