INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37134','mirador','Alto de la Alhándiga','5.5/10. Vista de la vega del río Alhándiga, campos de secano e hileras aisladas de chopos en la comarca de Alba. Cómo llegar: Altiplano calizo/granítico accesible por los caminos tradicionales del norte. 📍 Provincia: Salamanca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37135','mirador','Mirador del Campo Charro (La Fuente)','6.1/10. Amplia panorámica de las grandes fincas de encinas dedicadas al toro bravo y del importante nudo ferroviario e histórico de la comarca. Cómo llegar: Pista agrícola elevada situada al oeste del casco urbano por pistas tradicionales. 📍 Provincia: Salamanca.','inventario_miradores_pdf');
