INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37144','mirador','Alto del Tormes Alto','5.4/10. Vista horizontal de la rica vega del río Tormes, plantaciones de chopos e islas fluviales cercanas a la presa de Santa Teresa. Cómo llegar: Talud natural situado al oeste del casco urbano por pistas agrícolas. 📍 Provincia: Salamanca.','inventario_miradores_pdf');
