INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37157','mirador','Alto de la dehesa de Agadones','6.1/10. Paisaje liso cubierto por un espeso monte de encinas y pastizales ganaderos en la comarca de Ciudad Rodrigo meridional. Cómo llegar: Camino de concentración que asciende al altiplano desde el núcleo rural. 📍 Provincia: Salamanca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37158','mirador','Mirador de la Haya de Herguijuela','8.1/10. Espectaculares e imponentes vistas del Valle de las Batuecas profundo, bancales de olivares, viñedos e imponentes formaciones de la Sierra de Francia. Cómo llegar: Senda peatonal de montaña acondicionada que arranca del caserío. 📍 Provincia: Salamanca.','inventario_miradores_pdf');
