INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37215','mirador','Páramo de Sotrobal','5.3/10. Paisaje liso y diáfano de la Tierra de Peñaranda, dominado por campos abiertos de secano. Cómo llegar: Camino de concentración parcelaria al este del pequeño núcleo. 📍 Provincia: Salamanca.','inventario_miradores_pdf');
