INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37216','mirador','Alto de la Ermita','5.5/10. Sencilla estampa agrícola del sur de la comarca de Alba, salpicada de parcelas cerealistas y encinas dispersas. Cómo llegar: Explanada junto a la ermita local, accesible desde el casco urbano por sendero. 📍 Provincia: Salamanca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37217','mirador','Alto de la Serrezuela','6.6/10. Vista de media montaña sobre el valle del río Sangusín, dehesas y berrocales de granito. Cómo llegar: Pista forestal maderera del sector sur, transitable a pie. 📍 Provincia: Salamanca.','inventario_miradores_pdf');
