INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37239','mirador','El Cotarro del Pedroso','5.3/10. Típica estampa horizontal de la comarca cerealista norteña, sin contaminación visual ni obstáculos geográficos. Cómo llegar: Pista agrícola elevada de fácil acceso al norte del casco urbano. 📍 Provincia: Salamanca.','inventario_miradores_pdf');
