INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40091','mirador','Mirador del Barranco de San Vicente','6.6/10. Vista del angosto valle del arroyo de San Vicente, ermita románica en ruinas integrada en las laderas calizas del páramo y vegetación. Cómo llegar: Senda rústica elevada al este del casco urbano por pistas agrícolas. 📍 Provincia: Segovia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40092','mirador','Mirador de la Muralla de Fuentidueña','7.8/10. Soberbia e histórica panorámica sobre el cauce del río Duratón, el puente monumental de piedra, la villa medieval amurallada y los restos de la iglesia románica de San Martín. Cómo llegar: Explanada de la torre del homenaje en lo alto del cerro amurallado, acceso por pista rural. 📍 Provincia: Segovia.','inventario_miradores_pdf');
